import {
  canRevertDetailActivity,
  type DetailActivity,
  type DetailRecord,
  type DetailRevertHandler,
  detailActivity,
  type RecordDetailsConfig,
} from "./record-details";

export interface TableActivityRecord {
  row: DetailRecord;
  activity: readonly DetailActivity[];
}

/** Reuse the record activity contract, including records no longer in the visible dataset. */
export function createActivityUndo(options: {
  rows: () => readonly DetailRecord[];
  config: () => RecordDetailsConfig | undefined;
  handler: () => DetailRevertHandler | undefined;
  onReverted: () => Promise<void>;
  onSuccess?: (entry: DetailActivity) => void;
  onError: (error?: string) => void;
  onUnavailable: () => void;
}): { undo: () => Promise<void> } {
  let pending = false;
  const completed = new Set<string>();
  return {
    undo: async () => {
      const config = options.config();
      const handler = options.handler();
      if (pending || !config || !handler) {
        return;
      }
      const records =
        config.history?.() ??
        options
          .rows()
          .map((row) => ({ row, activity: detailActivity(config, row) }));
      const candidates = activityCandidates(records, config, completed);
      const candidate = candidates.find((item) => item.allowed);
      if (!candidate) {
        options.onUnavailable();
        return;
      }
      const group = candidate.entry.transactionId
        ? candidates.filter(
            (item) =>
              item.entry.transactionId === candidate.entry.transactionId &&
              !item.reverted
          )
        : [candidate];
      if (group.some((item) => !item.allowed)) {
        options.onUnavailable();
        return;
      }
      pending = true;
      try {
        const changed = await revertGroup(
          group,
          handler,
          completed,
          options.onError
        );
        if (changed) {
          await options.onReverted();
        }
        if (changed === group.length) {
          options.onSuccess?.(candidate.entry);
        }
      } catch (error) {
        options.onError(errorMessage(error));
      } finally {
        pending = false;
      }
    },
  };
}

function errorMessage(error: unknown): string | undefined {
  return error instanceof Error ? error.message : undefined;
}

function activityCandidates(
  records: readonly TableActivityRecord[],
  config: RecordDetailsConfig,
  completed: Set<string>
) {
  return records
    .flatMap(({ row, activity }) => {
      const sorted = [...activity].sort(
        (a, b) => Date.parse(b.at) - Date.parse(a.at)
      );
      return sorted.map((entry) => ({
        row,
        entry,
        reverted:
          completed.has(entry.id) ||
          activity.some((item) => item.reverts === entry.id),
        allowed:
          !completed.has(entry.id) &&
          canRevertDetailActivity(entry, sorted) &&
          config.canRevert?.(entry, row) !== false,
      }));
    })
    .sort((a, b) => Date.parse(b.entry.at) - Date.parse(a.entry.at));
}

async function revertGroup(
  group: ReturnType<typeof activityCandidates>,
  handler: DetailRevertHandler,
  completed: Set<string>,
  onError: (error?: string) => void
): Promise<number> {
  let changed = 0;
  try {
    for (const item of group) {
      const result = await handler(item.row, item.entry);
      if (!result.success) {
        onError(result.error);
        break;
      }
      completed.add(item.entry.id);
      changed += 1;
    }
  } catch (error) {
    onError(errorMessage(error));
  }
  // Partial success must refresh before the remaining members can be retried.
  return changed;
}

const SCROLLABLE_OVERFLOW = /auto|scroll|hidden/;

/** Bound the numeric page size sent to both local and server-backed tables. */
export function fitPageSize(
  availableHeight: number,
  rowHeight: number
): number {
  if (
    !(Number.isFinite(availableHeight) && Number.isFinite(rowHeight)) ||
    rowHeight <= 0
  ) {
    return 1;
  }
  return Math.max(
    1,
    Math.min(500, Math.floor(Math.max(0, availableHeight) / rowHeight))
  );
}

/** Count measured rows in order, then estimate unseen rows using the smallest visible row. */
export function fitMeasuredPageSize(
  availableHeight: number,
  heights: number[]
): number {
  const measured = heights.filter(
    (height) => Number.isFinite(height) && height > 0
  );
  if (!measured.length) {
    return 1;
  }
  let remaining = Math.max(0, availableHeight);
  let count = 0;
  for (const height of measured) {
    if (height > remaining) {
      return Math.max(1, count);
    }
    remaining -= height;
    count += 1;
    if (count === 500) {
      return count;
    }
  }
  return Math.min(500, count + Math.floor(remaining / Math.min(...measured)));
}

export interface AutoPageMeasurement {
  pageSize: number;
  tableHeight: number;
  layoutKey: string;
}

/** Observe layout, not scroll position, so scrolling to the selector does not change the capacity. */
export function observeAutoPageSize(
  root: HTMLElement,
  onMeasure: (value: AutoPageMeasurement) => void
): () => void {
  const win = root.ownerDocument.defaultView;
  if (!win) {
    return () => undefined;
  }
  let disposed = false;
  let frame = 0;
  const ancestors: HTMLElement[] = [];
  for (
    let element = root.parentElement;
    element;
    element = element.parentElement
  ) {
    ancestors.push(element);
  }
  const measure = () => {
    frame = 0;
    if (disposed || !root.isConnected || !root.getClientRects().length) {
      return;
    }
    const table = root.querySelector("table");
    const body = table?.querySelector("tbody");
    if (!(table && body)) {
      return;
    }
    const rows = [...body.querySelectorAll("tr")].filter(
      (row) => row.querySelector("td")?.colSpan === 1
    );
    // Intrinsic table width can change between pages; only the container is a layout boundary.
    const width = root.getBoundingClientRect().width;
    const heights = rows
      .map((row) => row.getBoundingClientRect().height)
      .filter((height) => height > 0);
    if (!heights.length) {
      return;
    }
    const scroller = ancestors.find((element) => {
      const style = win.getComputedStyle(element);
      return (
        SCROLLABLE_OVERFLOW.test(style.overflowY) &&
        element.clientHeight < element.scrollHeight
      );
    });
    const viewportHeight =
      scroller?.clientHeight ?? win.visualViewport?.height ?? win.innerHeight;
    const origin = scroller
      ? scroller.getBoundingClientRect().top +
        scroller.clientTop -
        scroller.scrollTop
      : -win.scrollY;
    const tableTop = Math.max(0, table.getBoundingClientRect().top - origin);
    const bodyTop = Math.max(0, body.getBoundingClientRect().top - origin);
    const footer = root.querySelector<HTMLElement>("[data-yayaw-pagination]");
    const footerHeight = footer?.getBoundingClientRect().height ?? 48;
    const calculationsHeight =
      table.querySelector("tfoot")?.getBoundingClientRect().height ?? 0;
    const tableHeight = Math.max(
      80,
      viewportHeight - tableTop - footerHeight - 24
    );
    const available =
      viewportHeight - bodyTop - footerHeight - calculationsHeight - 24;
    onMeasure({
      pageSize: fitMeasuredPageSize(available, heights),
      tableHeight,
      // Header wrapping and footer content can vary between pages just like row heights.
      // They affect measured capacity, but must not raise the existing capacity ceiling.
      layoutKey: [viewportHeight, width].join(":"),
    });
  };
  const schedule = () => {
    if (!(disposed || frame)) {
      frame = win.requestAnimationFrame(measure);
    }
  };
  const resize =
    typeof win.ResizeObserver === "function"
      ? new win.ResizeObserver(schedule)
      : undefined;
  resize?.observe(root);
  for (const ancestor of ancestors) {
    resize?.observe(ancestor);
  }
  const mutation = new win.MutationObserver(schedule);
  mutation.observe(root, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["class", "style"],
  });
  win.addEventListener("resize", schedule);
  win.visualViewport?.addEventListener("resize", schedule);
  root.addEventListener("load", schedule, true);
  root.ownerDocument.fonts?.ready.then(schedule, schedule);
  schedule();
  return () => {
    disposed = true;
    win.cancelAnimationFrame(frame);
    resize?.disconnect();
    mutation.disconnect();
    win.removeEventListener("resize", schedule);
    win.visualViewport?.removeEventListener("resize", schedule);
    root.removeEventListener("load", schedule, true);
  };
}

import type { BulkActionResult, TableRecord } from "./types";

export interface ResolvedBulkActionResult {
  success: boolean;
  clearSelection: boolean;
  closeMenu: boolean;
  message?: string;
}

export const resolveBulkActionResult = (
  result: BulkActionResult | undefined,
  failureMessage: string,
  defaults = { clearSelection: false, closeMenu: true }
): ResolvedBulkActionResult => {
  const success = result?.success !== false;
  return {
    success,
    clearSelection:
      result?.clearSelection ??
      result?.closeMenu ??
      (success && defaults.clearSelection),
    closeMenu: result?.closeMenu ?? (success && defaults.closeMenu),
    message:
      result?.message?.trim() ||
      result?.error?.trim() ||
      (success ? undefined : failureMessage),
  };
};

export const parseBulkEditPatch = (input: string): TableRecord => {
  const patch: unknown = JSON.parse(input);
  if (patch === null || typeof patch !== "object" || Array.isArray(patch)) {
    throw new Error("Enter a valid JSON object.");
  }
  return patch as TableRecord;
};

import {
  type ConditionField,
  evaluateForm,
  type FormEvaluation,
  type FormRule,
  rulesReading,
} from "./form-conditions";

/** Shared copy and clear-value conventions for both independently installed registries. */
export const bulkEditorMessages = (locale = "en") =>
  locale.startsWith("fr")
    ? {
        titleOne: "Modifier 1 ligne",
        titleMany: "Modifier {count} lignes",
        applyOne: "Appliquer à 1 ligne",
        applyMany: "Appliquer à {count} lignes",
        description: "Les autres propriétés restent inchangées.",
        addField: "Ajouter un champ",
        searchFields: "Rechercher une propriété…",
        noFields: "Aucune propriété disponible",
        empty: "Ajoutez les propriétés à modifier.",
        removeField: "Retirer {field}",
        clearValue: "Effacer la valeur",
        cancel: "Annuler",
        close: "Fermer",
        saving: "Enregistrement…",
      }
    : {
        titleOne: "Edit 1 row",
        titleMany: "Edit {count} rows",
        applyOne: "Apply to 1 row",
        applyMany: "Apply to {count} rows",
        description: "Other properties stay unchanged.",
        addField: "Add a field",
        searchFields: "Search properties…",
        noFields: "No properties available",
        empty: "Add the properties you want to change.",
        removeField: "Remove {field}",
        clearValue: "Clear value",
        cancel: "Cancel",
        close: "Close",
        saving: "Saving…",
      };
export type BulkEditorMessages = ReturnType<typeof bulkEditorMessages>;

/** Required fields and boolean/custom editors never imply a clear operation. */
export function bulkClearCandidate(field: {
  type: string;
  required?: boolean;
}): { value: unknown } | undefined {
  if (field.required) {
    return;
  }
  switch (field.type) {
    case "text":
    case "string":
    case "textarea":
    case "url":
    case "image":
      return { value: "" };
    case "multiSelect":
    case "collection":
      return { value: [] };
    case "number":
    case "date":
    case "json":
    case "location":
    case "select":
    case "radio":
    case "select-with-add-new":
      return { value: null };
    default:
      return;
  }
}

/** Words of the bulk editor's condition notes. */
export const bulkConditionMessages = (locale = "en") =>
  locale.startsWith("fr")
    ? {
        mixedBlocked:
          "Dépend de {fields}, dont les valeurs diffèrent entre les lignes. Modifiez d’abord {fields}.",
        mixedNote:
          "Les valeurs de {fields} diffèrent entre les lignes : la condition est considérée comme non remplie.",
      }
    : {
        mixedBlocked:
          "Depends on {fields}, whose values differ across the selection. Set {fields} first.",
        mixedNote:
          "Values of {fields} differ across the selection: the condition is treated as not met.",
      };

const sameValue = (left: unknown, right: unknown) =>
  JSON.stringify(left) === JSON.stringify(right);

export interface BulkConditionInput {
  rules: readonly FormRule[];
  fields: readonly ConditionField[];
  /** The selected rows. */
  rows: readonly Record<string, unknown>[];
  /** Fields added to the bulk draft. */
  applied: readonly string[];
  /** The draft values. */
  values: Record<string, unknown>;
}

/**
 * Rules in a bulk editor: conditions read the edited values, or the value
 * shared by every selected row. A field whose value differs across the
 * selection (and is not set in the draft) is "mixed": conditions on it never
 * match.
 */
export function bulkConditionState(input: BulkConditionInput): {
  evaluation: FormEvaluation;
  mixed: string[];
} {
  const [first] = input.rows;
  const mixed = input.fields
    .map((field) => field.id)
    .filter(
      (id) =>
        !input.applied.includes(id) &&
        input.rows.some((row) => !sameValue(row[id], first?.[id]))
    );
  const values = Object.fromEntries(
    input.fields.map((field) => [
      field.id,
      input.applied.includes(field.id)
        ? input.values[field.id]
        : first?.[field.id],
    ])
  );
  return {
    evaluation: evaluateForm(input.rules, values, input.fields, { mixed }),
    mixed,
  };
}

/** Labels of the mixed fields the rules of `target` read. */
export function bulkMixedDependencies(
  input: Pick<BulkConditionInput, "fields" | "rules">,
  target: string,
  mixed: readonly string[]
): string[] {
  const labels = new Map(
    input.fields.map((field) => [field.id, field.label ?? field.id])
  );
  return rulesReading(input.rules, target, mixed).map(
    (id) => labels.get(id) ?? id
  );
}

import {
  bulkClearCandidate,
  bulkConditionState,
  bulkMixedDependencies,
} from "./bulk-editor";
import {
  cloneFormValue,
  fieldIsDisabled,
  fieldIsHidden,
  formRuleSet,
  formValuesEqual,
  validateForm,
} from "./form-runtime";
import type {
  FormConfig,
  FormFieldContext,
  FormFieldDefinition,
  TableRecord,
} from "./types";

const reservedFields = new Set([
  "id",
  "_id",
  "createdAt",
  "updatedAt",
  "created_at",
  "updated_at",
]);

/** Start with common values, never the first row's differing values. */
export const commonBulkValues = (rows: readonly TableRecord[]): TableRecord =>
  cloneFormValue(
    Object.fromEntries(
      Object.entries(rows[0] ?? {}).filter(([key, value]) =>
        rows.every((row) => formValuesEqual(row[key], value))
      )
    )
  );

/** A bulk context evaluating the config's declared rules on the shared values (mixed ones never match). */
export const bulkRuleContext = (
  config: FormConfig,
  context: FormFieldContext
): FormFieldContext => ({
  ...context,
  formRules: formRuleSet(config, { legacy: false }),
});

/** The declared rules of a bulk context, with the fields whose values differ across rows. */
export const bulkRuleState = (context: FormFieldContext) =>
  context.formRules && context.bulkEdit
    ? bulkConditionState({
        rules: context.formRules.rules,
        fields: context.formRules.fields,
        rows: context.bulkEdit.rows,
        applied: context.bulkEdit.fields,
        values: context.values ?? {},
      })
    : undefined;

/** Labels of the mixed fields a field's rules read, for the "mixed" note. */
export const bulkMixedFieldsOf = (
  field: FormFieldDefinition,
  context: FormFieldContext
): string[] => {
  const state = bulkRuleState(context);
  return state && context.formRules
    ? bulkMixedDependencies(context.formRules, field.name, state.mixed)
    : [];
};

/** Legacy predicates run per row, with the draft's changed dependencies. */
const editableInEveryRow = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean => {
  const patch = Object.fromEntries(
    (context.bulkEdit?.fields ?? []).map((name) => [name, context.values[name]])
  );
  return (context.bulkEdit?.rows ?? []).every((row) => {
    const rowContext = {
      ...context,
      formRules: undefined,
      row,
      values: { ...row, ...patch },
    };
    return !(
      fieldIsHidden(field, rowContext) || fieldIsDisabled(field, rowContext)
    );
  });
};

/**
 * Check conditional fields against every target, including explicitly
 * changed dependencies. Declared rules read the edited values or the value
 * shared by every row; a value that differs is treated as not matching.
 */
export const bulkFieldEditable = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean => {
  if (reservedFields.has(field.name) || field.bulkEdit === false) {
    return false;
  }
  if (!editableInEveryRow(field, context)) {
    return false;
  }
  return !bulkRuleState(context)?.evaluation.hidden.has(field.name);
};

/** Fields held back only by a rule reading mixed values, with those values' labels. */
export const bulkBlockedFields = (
  fields: readonly FormFieldDefinition[],
  context: FormFieldContext
): { field: FormFieldDefinition; mixed: string[] }[] =>
  fields.flatMap((field) => {
    if (
      reservedFields.has(field.name) ||
      field.bulkEdit === false ||
      bulkFieldEditable(field, context) ||
      !editableInEveryRow(field, context)
    ) {
      return [];
    }
    const mixed = bulkMixedFieldsOf(field, context);
    return mixed.length ? [{ field, mixed }] : [];
  });

/** Keep field validation, but not a full-row schema that requires untouched fields. */
export const bulkFormConfig = (
  config: FormConfig,
  context: FormFieldContext
): FormConfig => ({
  ...config,
  schema: undefined,
  submitMode: "full",
  fields: config.fields
    .filter(
      (field) =>
        context.bulkEdit?.fields.includes(field.name) &&
        bulkFieldEditable(field, context)
    )
    .sort(
      (left, right) =>
        (context.bulkEdit?.fields.indexOf(left.name) ?? 0) -
        (context.bulkEdit?.fields.indexOf(right.name) ?? 0)
    )
    .map((field) => ({ ...field, hidden: false, disabled: false })),
});

/** Strip untouched fields before validation and transforms, including undeclared row metadata. */
export const bulkFormValues = (
  config: FormConfig,
  values: TableRecord
): TableRecord =>
  cloneFormValue(
    Object.fromEntries(
      config.fields.map((field) => [field.name, values[field.name]])
    )
  );

/** Invalid completion reports must never clear unrelated rows or cause a silent success. */
export const bulkCompletion = (
  ids: string[],
  result: { success: boolean; failedIds?: string[] }
): { completed: string[]; remaining: string[] } => {
  if (result.success) {
    return { completed: [...ids], remaining: [] };
  }
  const failed = result.failedIds;
  if (!failed?.length || failed.some((id) => !ids.includes(id))) {
    return { completed: [], remaining: [...ids] };
  }
  return {
    completed: ids.filter((id) => !failed.includes(id)),
    remaining: ids.filter((id) => failed.includes(id)),
  };
};

/** Validate drafts without publishing them; reject unsupported clears through the field schema. */
export async function validateBulkDraft(
  config: FormConfig,
  context: FormFieldContext
) {
  const values = context.values ?? {};
  const [draft, candidates] = await Promise.all([
    validateForm(config, bulkFormValues(config, values), context),
    Promise.all(
      config.fields.map(async (field) => {
        const candidate = bulkClearCandidate(field);
        if (!candidate) {
          return;
        }
        const result = await validateForm(
          { ...config, schema: undefined, fields: [field] },
          { [field.name]: candidate.value },
          { ...context, values: { ...values, [field.name]: candidate.value } }
        );
        return Object.keys(result.errors).length
          ? undefined
          : ([field.name, candidate.value] as const);
      })
    ),
  ]);
  const clearValues: TableRecord = {};
  for (const candidate of candidates) {
    if (candidate) {
      clearValues[candidate[0]] = candidate[1];
    }
  }
  return {
    valid: config.fields.length > 0 && !Object.keys(draft.errors).length,
    clearValues,
  };
}

/**
 * Calendar view model shared by the React and Vue editions. It has no
 * calendar-library dependency: the optional calendar registry items render it.
 */
import { type DateRangeScope, localDayKey } from "./scoped-rows";
import { type FieldTextColumn, fieldText } from "./table-contracts";

type FieldTextColumnWithId = FieldTextColumn & { id: string };

export type CalendarLayout = "month" | "week" | "list";

export interface CalendarViewSettings {
  /** Column holding the start date, or the only date. */
  dateColumn?: string;
  /** Column holding an inclusive end date; one-day events without it. */
  endColumn?: string;
  /** Column used as the event title. */
  titleColumn?: string;
  /** Column whose tag color colors the event. */
  colorColumn?: string;
  layout?: CalendarLayout;
  /** First day of the week, 0 = Sunday … 6 = Saturday (default Monday). */
  weekStartsOn?: number;
  showWeekends?: boolean;
  /** Drag an event to another day (needs `actions.update`). */
  allowDragUpdate?: boolean;
  /** Stretch an event to change its end (needs an end column). */
  allowResize?: boolean;
  /** Click a day to create a record on it (needs `actions.create`). */
  allowCreate?: boolean;
}

export const CALENDAR_DEFAULTS = {
  layout: "month",
  weekStartsOn: 1,
  showWeekends: true,
  allowDragUpdate: true,
  allowResize: true,
  allowCreate: true,
} as const satisfies CalendarViewSettings;

type ResolvedCalendarSettings = CalendarViewSettings &
  Required<
    Pick<
      CalendarViewSettings,
      | "allowCreate"
      | "allowDragUpdate"
      | "allowResize"
      | "layout"
      | "showWeekends"
      | "weekStartsOn"
    >
  >;

const LAYOUTS = new Set<CalendarLayout>(["month", "week", "list"]);
const STRING_KEYS = [
  "dateColumn",
  "endColumn",
  "titleColumn",
  "colorColumn",
] as const;
const BOOLEAN_KEYS = [
  "showWeekends",
  "allowDragUpdate",
  "allowResize",
  "allowCreate",
] as const;
const DAYS_IN_WEEK = 7;
const DAY_MS = 86_400_000;
const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;

/** Keep only valid calendar settings; unknown or malformed values are dropped. */
export function normalizeCalendarViewConfig(
  value: unknown
): CalendarViewSettings | undefined {
  if (!value || typeof value !== "object") {
    return;
  }
  const input = value as Record<string, unknown>;
  const normalized: CalendarViewSettings = {};
  for (const key of STRING_KEYS) {
    const text = typeof input[key] === "string" ? input[key].trim() : "";
    if (text) {
      normalized[key] = text;
    }
  }
  for (const key of BOOLEAN_KEYS) {
    if (typeof input[key] === "boolean") {
      normalized[key] = input[key];
    }
  }
  if (LAYOUTS.has(input.layout as CalendarLayout)) {
    normalized.layout = input.layout as CalendarLayout;
  }
  const weekStart = Number(input.weekStartsOn);
  if (
    input.weekStartsOn !== undefined &&
    Number.isInteger(weekStart) &&
    weekStart >= 0 &&
    weekStart < DAYS_IN_WEEK
  ) {
    normalized.weekStartsOn = weekStart;
  }
  return Object.keys(normalized).length ? normalized : undefined;
}

interface CalendarColumn {
  id: string;
  type?: string;
}

/** Table defaults, then the view; the first date column when none is chosen. */
export function resolveCalendarSettings(
  columns: readonly CalendarColumn[],
  defaults: CalendarViewSettings | undefined,
  view: CalendarViewSettings | undefined
): ResolvedCalendarSettings {
  const merged = { ...CALENDAR_DEFAULTS, ...defaults, ...view };
  const dataColumns = columns.filter(
    (column) => column.id !== "select" && column.id !== "actions"
  );
  return {
    ...merged,
    dateColumn:
      merged.dateColumn ??
      dataColumns.find((column) => column.type === "date")?.id,
    titleColumn:
      merged.titleColumn ??
      dataColumns.find((column) => column.type !== "date")?.id,
  };
}

export interface CalendarEvent {
  id: string;
  title: string;
  /** Local calendar day (`YYYY-MM-DD`). */
  start: string;
  /** Exclusive end day, as calendar libraries expect for all-day events. */
  end: string;
  allDay: true;
  /** Value of the color column, for tag coloring. */
  colorValue?: string;
}

/** Year, month index and day of a `YYYY-MM-DD` string. */
function dayParts(day: string): [number, number, number] {
  const [year = 0, month = 1, date = 1] = day.split("-").map(Number);
  return [year, month - 1, date];
}

/** `YYYY-MM-DD` plus a number of days, in local calendar arithmetic. */
export function addDays(day: string, days: number): string {
  const [year, month, date] = dayParts(day);
  const shifted = new Date(year, month, date + days);
  return localDayKey(shifted) ?? day;
}

/** Whole days from one `YYYY-MM-DD` to another. */
export function daysBetween(from: string, to: string): number {
  const toTime = (day: string) => Date.UTC(...dayParts(day));
  return Math.round((toTime(to) - toTime(from)) / DAY_MS);
}

/**
 * Rows with a start date become all-day events; an end before the start is
 * ignored. With the columns and locale, titles read as the table shows the
 * title column (option labels, number and date formats).
 */
export function calendarEvents(
  rows: readonly Record<string, unknown>[],
  settings: CalendarViewSettings,
  getRowId: (row: Record<string, unknown>) => string,
  format: { columns?: readonly FieldTextColumnWithId[]; locale?: string } = {}
): CalendarEvent[] {
  if (!settings.dateColumn) {
    return [];
  }
  const titleColumn = format.columns?.find(
    (column) => column.id === settings.titleColumn
  );
  return rows.flatMap((row) => {
    const start = localDayKey(row[settings.dateColumn as string]);
    if (!start) {
      return [];
    }
    const lastDay =
      (settings.endColumn && localDayKey(row[settings.endColumn])) || start;
    const last = lastDay < start ? start : lastDay;
    const title = settings.titleColumn ? row[settings.titleColumn] : undefined;
    const color = settings.colorColumn ? row[settings.colorColumn] : undefined;
    return [
      {
        id: getRowId(row),
        title: fieldText(title, titleColumn, format.locale, row),
        start,
        end: addDays(last, 1),
        allDay: true as const,
        colorValue:
          color === null || color === undefined ? undefined : String(color),
      },
    ];
  });
}

/** The rows a visible calendar range needs, as a list scope. */
export function calendarScope(
  settings: CalendarViewSettings,
  visibleStart: Date,
  visibleEndExclusive: Date
): DateRangeScope | undefined {
  const from = localDayKey(visibleStart);
  const end = localDayKey(visibleEndExclusive);
  if (!(settings.dateColumn && from && end)) {
    return;
  }
  return {
    kind: "dateRange",
    field: settings.dateColumn,
    endField: settings.endColumn,
    from,
    to: addDays(end, -1),
  };
}

/** Write a day in the stored value's own format: date-only stays date-only. */
function formatLike(original: unknown, day: string): string {
  if (typeof original === "string" && !DATE_ONLY.test(original)) {
    const previous = new Date(original);
    if (Number.isFinite(previous.getTime())) {
      previous.setFullYear(...dayParts(day));
      return previous.toISOString();
    }
  }
  return day;
}

/**
 * The patch for an event moved or stretched to a new exclusive range. Without
 * an end column, only the start moves and stretching is not possible.
 */
export function calendarMovePatch(
  row: Record<string, unknown>,
  settings: CalendarViewSettings,
  start: string,
  endExclusive: string
): Record<string, unknown> {
  if (!settings.dateColumn) {
    return {};
  }
  const patch: Record<string, unknown> = {
    [settings.dateColumn]: formatLike(row[settings.dateColumn], start),
  };
  if (settings.endColumn) {
    const last = addDays(endExclusive, -1);
    patch[settings.endColumn] = formatLike(
      row[settings.endColumn],
      last < start ? start : last
    );
  }
  return patch;
}

/**
 * Chart view model shared by the React and Vue editions. It has no charting
 * library dependency: the optional chart registry items render what it builds.
 *
 * Server first: `actions.aggregate` receives `groupBy` and `metrics` beside the
 * usual query and answers `{ groups: [{ keys, values }] }`. Hosts that have not
 * implemented it, or tables without an aggregate action, are aggregated here
 * over every row matching the query (capped, with a `truncated` signal).
 */
import { loadScopedRows, type ScopedRowsRequest } from "./scoped-rows";
import {
  dataTypeFilter,
  dataTypeOptionLabel,
  normalizeFilterEnvelope,
  recordValue,
} from "./table-contracts";
import { tagAppearance } from "./tag-colors";
import {
  type ColumnValueFormat,
  formatColumnDay,
  formatColumnNumber,
  parseDateValue,
  resolveNumberFormat,
} from "./value-format";

export type ChartType =
  | "bar"
  | "horizontalBar"
  | "line"
  | "area"
  | "combo"
  | "donut"
  | "funnel"
  | "number";
export type ChartBucket = "day" | "week" | "month" | "quarter" | "year";
/** Area series on top of each other, as shares of each category (100 %), or overlapping. */
export type ChartStacking = "stacked" | "percent" | "none";
/** Lines and areas: smooth curves or straight segments. */
export type ChartCurve = "smooth" | "linear";
export type ChartMetricFn =
  | "count"
  | "sum"
  | "avg"
  | "min"
  | "max"
  | "countDistinct";
export type ChartSort =
  | "auto"
  | "keyAsc"
  | "keyDesc"
  | "valueAsc"
  | "valueDesc"
  | "manual";
export type ChartColors = "options" | "palette";

export interface ChartViewSettings {
  type?: ChartType;
  /** Column whose values (or date buckets) are the x axis, the slices of a donut. */
  xColumn?: string;
  /** Date bucket of a date x axis (default `month`). */
  bucket?: ChartBucket;
  /** What the y axis measures (default `count`). */
  metric?: ChartMetricFn;
  /** Column the metric reads; required by every metric but `count`. */
  metricColumn?: string;
  /** Optional second grouping: stacked or grouped bars, one line per value. */
  seriesColumn?: string;
  /** Stack the series of a bar chart (default) or show them side by side. */
  stacked?: boolean;
  sort?: ChartSort;
  /** Running totals along the x axis (bar and line charts). */
  cumulative?: boolean;
  /** Hide groups without a value and groups whose value is zero. */
  hideEmpty?: boolean;
  /** Keep the first N groups after sorting; the rest become "Other". */
  topN?: number;
  showDataLabels?: boolean;
  showLegend?: boolean;
  /** Color groups with their option colors (default) or the chart palette. */
  colors?: ChartColors;
  /** First day of week buckets, 0 = Sunday … 6 = Saturday (default Monday). */
  weekStartsOn?: number;
  /** Area charts with series: stacked (default), stacked to 100 % or overlapping. */
  stacking?: ChartStacking;
  /** Lines, areas and the line of combo charts: smooth (default) or straight. */
  curve?: ChartCurve;
  /** What the line of a combo chart measures (default `count`); bars use `metric`. */
  lineMetric?: ChartMetricFn;
  /** Column the line metric reads; required by every line metric but `count`. */
  lineMetricColumn?: string;
  /**
   * Funnel stages in order, as option values. Options left out follow in the
   * column's option order; without it the stages follow the option order.
   */
  stageOrder?: string[];
  /**
   * Fill the nearest size container (CSS `container-type: size`, e.g. a
   * dashboard widget) instead of a 320px tall chart: no title, table toggle
   * or hint; the legend moves beside or under the chart, or hides, and data
   * labels hide when the space is too small (`chartFillLayout`).
   */
  fill?: boolean;
}

export const CHART_DEFAULTS = {
  type: "bar",
  bucket: "month",
  metric: "count",
  stacked: true,
  sort: "auto",
  cumulative: false,
  hideEmpty: false,
  showDataLabels: false,
  showLegend: true,
  colors: "options",
  weekStartsOn: 1,
  stacking: "stacked",
  curve: "smooth",
  lineMetric: "count",
} as const satisfies ChartViewSettings;

export type ResolvedChartSettings = ChartViewSettings &
  Required<
    Pick<
      ChartViewSettings,
      | "bucket"
      | "colors"
      | "cumulative"
      | "curve"
      | "hideEmpty"
      | "lineMetric"
      | "metric"
      | "showDataLabels"
      | "showLegend"
      | "sort"
      | "stacked"
      | "stacking"
      | "type"
      | "weekStartsOn"
    >
  >;

export const CHART_TYPES: readonly ChartType[] = [
  "bar",
  "horizontalBar",
  "line",
  "area",
  "combo",
  "donut",
  "funnel",
  "number",
];
export const CHART_STACKINGS: readonly ChartStacking[] = [
  "stacked",
  "percent",
  "none",
];
export const CHART_CURVES: readonly ChartCurve[] = ["smooth", "linear"];
export const CHART_BUCKETS: readonly ChartBucket[] = [
  "day",
  "week",
  "month",
  "quarter",
  "year",
];
export const CHART_METRICS: readonly ChartMetricFn[] = [
  "count",
  "sum",
  "avg",
  "min",
  "max",
  "countDistinct",
];
export const CHART_SORTS: readonly ChartSort[] = [
  "auto",
  "keyAsc",
  "keyDesc",
  "valueAsc",
  "valueDesc",
  "manual",
];
export const MAX_CHART_TOP_N = 50;
/** Series beyond this many are folded into "Other" (or left out for non-additive metrics). */
export const MAX_CHART_SERIES = 10;
/** Gaps filled between the first and last date buckets, at most. */
const MAX_FILLED_BUCKETS = 500;
const DAYS_IN_WEEK = 7;
const MONTHS_IN_QUARTER = 3;
const DAY_MS = 86_400_000;
/** Funnel stages kept in a saved order, at most. */
const MAX_STAGE_ORDER = 200;
const STRING_KEYS = [
  "xColumn",
  "metricColumn",
  "seriesColumn",
  "lineMetricColumn",
] as const;
const BOOLEAN_KEYS = [
  "stacked",
  "cumulative",
  "hideEmpty",
  "showDataLabels",
  "showLegend",
  "fill",
] as const;
const DATE_ONLY = /^(\d{4})-(\d{2})-(\d{2})$/;
const MONTH_KEY = /^(\d{4})-(\d{2})$/;
const QUARTER_KEY = /^(\d{4})-Q([1-4])$/;
const YEAR_KEY = /^\d{4}$/;
const TEMPLATE_PARAM = /\{(\w+)\}/g;
const EMPTY_ID = "__empty";
export const OTHER_ID = "__other";
export const VALUE_SERIES_ID = "value";
/** Series ids of combo charts: the bars' metric and the line's. */
export const COMBO_BAR_ID = "bars";
export const COMBO_LINE_ID = "line";

const pad = (value: number, size = 2) => String(value).padStart(size, "0");
const oneOf = <T extends string>(list: readonly T[], value: unknown) =>
  list.includes(value as T) ? (value as T) : undefined;

// Settings ------------------------------------------------------------------

function normalizedTopN(value: unknown): number | undefined {
  const top = Number(value);
  return value !== undefined &&
    value !== null &&
    Number.isInteger(top) &&
    top > 0 &&
    top <= MAX_CHART_TOP_N
    ? top
    : undefined;
}

function normalizedWeekStart(value: unknown): number | undefined {
  const day = Number(value);
  return value !== undefined &&
    value !== null &&
    value !== "" &&
    Number.isInteger(day) &&
    day >= 0 &&
    day < DAYS_IN_WEEK
    ? day
    : undefined;
}

/** Distinct option values as text, in order; anything else is dropped. */
function normalizedStageOrder(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return;
  }
  const stages = [
    ...new Set(
      value.filter(
        (item): item is string => typeof item === "string" && item !== ""
      )
    ),
  ].slice(0, MAX_STAGE_ORDER);
  return stages.length ? stages : undefined;
}

/** Keep only valid chart settings; unknown or malformed values are dropped. */
export function normalizeChartViewConfig(
  value: unknown
): ChartViewSettings | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return;
  }
  const input = value as Record<string, unknown>;
  const normalized: ChartViewSettings = {};
  for (const key of STRING_KEYS) {
    const text = typeof input[key] === "string" ? input[key].trim() : "";
    if (text) {
      normalized[key] = text;
    }
  }
  for (const key of BOOLEAN_KEYS) {
    if (typeof input[key] === "boolean") {
      normalized[key] = input[key];
    }
  }
  const enums = {
    type: oneOf(CHART_TYPES, input.type),
    bucket: oneOf(CHART_BUCKETS, input.bucket),
    metric: oneOf(CHART_METRICS, input.metric),
    sort: oneOf(CHART_SORTS, input.sort),
    colors: oneOf(["options", "palette"] as const, input.colors),
    topN: normalizedTopN(input.topN),
    weekStartsOn: normalizedWeekStart(input.weekStartsOn),
    stacking: oneOf(CHART_STACKINGS, input.stacking),
    curve: oneOf(CHART_CURVES, input.curve),
    lineMetric: oneOf(CHART_METRICS, input.lineMetric),
    stageOrder: normalizedStageOrder(input.stageOrder),
  };
  for (const [key, item] of Object.entries(enums)) {
    if (item !== undefined) {
      Object.assign(normalized, { [key]: item });
    }
  }
  return Object.keys(normalized).length ? normalized : undefined;
}

/** A column as the chart reads it. */
/** Columns bring their formats: metrics, number groups and day buckets use them. */
export interface ChartColumn extends ColumnValueFormat {
  id: string;
  header?: string;
  type?: string;
  options?: unknown;
  coloredTags?: boolean;
  tagColorMap?: Record<string, string>;
}

const OPTION_TYPES = new Set(["select", "multiSelect"]);
const GROUPABLE_TYPES = new Set([
  "select",
  "multiSelect",
  "date",
  "text",
  "string",
  "boolean",
  "number",
  "email",
  "url",
]);

const isDataColumn = (column: ChartColumn) =>
  column.id !== "select" &&
  column.id !== "actions" &&
  column.type !== "actions";

/** Columns a chart can group by (x axis and series). */
export function chartGroupColumns<T extends ChartColumn>(
  columns: readonly T[]
): T[] {
  return columns.filter(
    (column) =>
      isDataColumn(column) && GROUPABLE_TYPES.has(column.type ?? "text")
  );
}

/** Number columns a metric other than a count can read. */
export function chartNumberColumns<T extends ChartColumn>(
  columns: readonly T[]
): T[] {
  return columns.filter(
    (column) => isDataColumn(column) && column.type === "number"
  );
}

function defaultXColumn(columns: readonly ChartColumn[]): string | undefined {
  const groupable = chartGroupColumns(columns);
  return (
    groupable.find((column) => OPTION_TYPES.has(column.type ?? "")) ??
    groupable.find((column) => column.type === "date") ??
    groupable.at(0)
  )?.id;
}

function resolvedMetric(
  columns: readonly ChartColumn[],
  metric: ChartMetricFn,
  metricColumn: string | undefined
): Pick<ChartViewSettings, "metric" | "metricColumn"> {
  if (metric === "count") {
    return { metric };
  }
  const column = columns.find((item) => item.id === metricColumn);
  if (metric === "countDistinct") {
    return column ? { metric, metricColumn } : { metric: "count" };
  }
  return column?.type === "number"
    ? { metric, metricColumn }
    : { metric: "count" };
}

/** Chart types that split their values by a series column. */
const SERIES_TYPES = new Set<ChartType>([
  "bar",
  "horizontalBar",
  "line",
  "area",
]);

/** Table defaults, then the view; sensible columns when none are chosen. */
export function resolveChartSettings(
  columns: readonly ChartColumn[],
  defaults: ChartViewSettings | undefined,
  view: ChartViewSettings | undefined
): ResolvedChartSettings {
  const merged = {
    ...CHART_DEFAULTS,
    ...normalizeChartViewConfig(defaults),
    ...normalizeChartViewConfig(view),
  };
  const known = (id: string | undefined) =>
    id && chartGroupColumns(columns).some((column) => column.id === id)
      ? id
      : undefined;
  const xColumn = known(merged.xColumn) ?? defaultXColumn(columns);
  const seriesColumn = known(merged.seriesColumn);
  const usesSeries = SERIES_TYPES.has(merged.type) && seriesColumn !== xColumn;
  const line = resolvedMetric(
    columns,
    merged.lineMetric,
    merged.lineMetricColumn
  );
  const resolved: ResolvedChartSettings = {
    ...merged,
    ...resolvedMetric(columns, merged.metric, merged.metricColumn),
    lineMetric: line.metric ?? "count",
    lineMetricColumn: line.metricColumn,
    xColumn,
    seriesColumn: usesSeries ? seriesColumn : undefined,
  };
  for (const key of ["metricColumn", "lineMetricColumn", "seriesColumn"]) {
    if (!resolved[key as keyof ResolvedChartSettings]) {
      Reflect.deleteProperty(resolved, key);
    }
  }
  return resolved;
}

// Aggregate contract ---------------------------------------------------------

/** One grouping level of `actions.aggregate`: a column, bucketed when it holds dates. */
export interface ChartGroupBy {
  columnId: string;
  bucket?: ChartBucket;
}

export interface ChartMetric {
  columnId?: string;
  fn: ChartMetricFn;
}

/**
 * One group of an aggregate answer. `keys` follow `groupBy` (empty values are
 * `null`; date buckets are `YYYY-MM-DD` days, the first day of `YYYY-MM-DD`
 * weeks, `YYYY-MM` months, `YYYY-Qn` quarters and `YYYY` years); `values`
 * follow `metrics`.
 */
export interface ChartAggregateGroup {
  keys: unknown[];
  values: number[];
}

export interface ChartAggregateResult {
  groups: ChartAggregateGroup[];
  /** The groups were computed over part of the records only. */
  truncated?: boolean;
}

/** What a chart asks `actions.aggregate` for, beside the query. */
export interface ChartAggregateRequest {
  /** At most two levels: the x axis, then the series. Empty for one total. */
  groupBy: ChartGroupBy[];
  metrics: ChartMetric[];
  /** IANA zone date buckets are computed in; the browser's zone when omitted. */
  timeZone?: string;
  /** First day of week buckets, 0 = Sunday … 6 = Saturday. */
  weekStartsOn: number;
}

const columnById = (columns: readonly ChartColumn[], id: string | undefined) =>
  id ? columns.find((column) => column.id === id) : undefined;

const groupByFor = (column: ChartColumn, bucket: ChartBucket): ChartGroupBy =>
  column.type === "date"
    ? { columnId: column.id, bucket }
    : { columnId: column.id };

const metricOf = (fn: ChartMetricFn, columnId: string | undefined) =>
  columnId ? { columnId, fn } : { fn };

/**
 * The aggregate request of a chart, or undefined while it has no x axis.
 * Combo charts ask for both metrics at once: the bars', then the line's.
 */
export function chartAggregateRequest(
  settings: ResolvedChartSettings,
  columns: readonly ChartColumn[]
): ChartAggregateRequest | undefined {
  const x = columnById(columns, settings.xColumn);
  const metrics: ChartMetric[] = [
    metricOf(settings.metric, settings.metricColumn),
  ];
  if (settings.type === "combo") {
    metrics.push(metricOf(settings.lineMetric, settings.lineMetricColumn));
  }
  const base = {
    metrics,
    weekStartsOn: settings.weekStartsOn,
    ...(x?.timeZone ? { timeZone: x.timeZone } : {}),
  };
  if (settings.type === "number") {
    return { ...base, groupBy: [] };
  }
  if (!x) {
    return;
  }
  const series = columnById(columns, settings.seriesColumn);
  return {
    ...base,
    groupBy: [
      groupByFor(x, settings.bucket),
      ...(series ? [groupByFor(series, settings.bucket)] : []),
    ],
  };
}

/** Parameters of `actions.aggregate` for a chart: the table's query plus the request. */
export function chartAggregateParams(
  listParams: Record<string, unknown>,
  request: ChartAggregateRequest,
  locale: string
): Record<string, unknown> {
  const envelope = normalizeFilterEnvelope(listParams.advancedFilters);
  return {
    filters: recordValue(listParams.filters),
    advancedFilters: envelope.filters.filter(
      (filter) => filter.isActive !== false
    ),
    advancedFilterJoin: envelope.joinOperator,
    search: String(listParams.search ?? ""),
    calculations: {},
    locale,
    groupBy: request.groupBy,
    metrics: request.metrics,
    weekStartsOn: request.weekStartsOn,
    ...(request.timeZone ? { timeZone: request.timeZone } : {}),
  };
}

const isFiniteNumber = (value: unknown): value is number =>
  typeof value === "number" && Number.isFinite(value);

/** A host's aggregate answer when it holds groups; otherwise undefined (fall back). */
export function normalizeChartAggregateResult(
  value: unknown
): ChartAggregateResult | undefined {
  const groups = recordValue(value).groups;
  if (!Array.isArray(groups)) {
    return;
  }
  return {
    groups: groups.flatMap((group) => {
      const record = recordValue(group);
      return Array.isArray(record.keys) && Array.isArray(record.values)
        ? [
            {
              keys: record.keys.map((key) => key ?? null),
              values: record.values.map((item) =>
                isFiniteNumber(Number(item)) ? Number(item) : 0
              ),
            },
          ]
        : [];
    }),
    ...(recordValue(value).truncated === true ? { truncated: true } : {}),
  };
}

// Date buckets ---------------------------------------------------------------

interface DayParts {
  year: number;
  month: number;
  day: number;
}

const zonedFormatters = new Map<string, Intl.DateTimeFormat>();

function zonedParts(date: Date, timeZone: string): DayParts | undefined {
  let formatter = zonedFormatters.get(timeZone);
  if (!formatter) {
    try {
      formatter = new Intl.DateTimeFormat("en-US", {
        day: "numeric",
        month: "numeric",
        year: "numeric",
        timeZone,
      });
    } catch {
      return;
    }
    zonedFormatters.set(timeZone, formatter);
  }
  const parts = formatter.formatToParts(date);
  const part = (type: string) =>
    Number(parts.find((item) => item.type === type)?.value);
  return { year: part("year"), month: part("month"), day: part("day") };
}

/** The calendar day of a value: date-only strings as they are, instants in the zone. */
function dayParts(value: unknown, timeZone?: string): DayParts | undefined {
  if (typeof value === "string") {
    const match = DATE_ONLY.exec(value);
    if (match) {
      return {
        year: Number(match[1]),
        month: Number(match[2]),
        day: Number(match[3]),
      };
    }
  }
  const date = parseDateValue(value);
  if (!date) {
    return;
  }
  if (timeZone) {
    const zoned = zonedParts(date, timeZone);
    if (zoned) {
      return zoned;
    }
  }
  return {
    year: date.getFullYear(),
    month: date.getMonth() + 1,
    day: date.getDate(),
  };
}

const utcDay = ({ year, month, day }: DayParts) =>
  new Date(Date.UTC(year, month - 1, day));
const dayKey = (date: Date) =>
  `${pad(date.getUTCFullYear(), 4)}-${pad(date.getUTCMonth() + 1)}-${pad(date.getUTCDate())}`;
const shiftDays = (date: Date, days: number) =>
  new Date(date.getTime() + days * DAY_MS);

function bucketOfDay(
  parts: DayParts,
  bucket: ChartBucket,
  weekStartsOn: number
): string {
  switch (bucket) {
    case "day":
      return dayKey(utcDay(parts));
    case "week": {
      const date = utcDay(parts);
      const offset =
        (date.getUTCDay() - weekStartsOn + DAYS_IN_WEEK) % DAYS_IN_WEEK;
      return dayKey(shiftDays(date, -offset));
    }
    case "month":
      return `${pad(parts.year, 4)}-${pad(parts.month)}`;
    case "quarter":
      return `${pad(parts.year, 4)}-Q${Math.ceil(parts.month / MONTHS_IN_QUARTER)}`;
    default:
      return pad(parts.year, 4);
  }
}

/** The bucket key of a date value, or null when it holds no date. */
export function chartBucketKey(
  value: unknown,
  bucket: ChartBucket,
  options: { timeZone?: string; weekStartsOn?: number } = {}
): string | null {
  const parts = dayParts(value, options.timeZone);
  return parts ? bucketOfDay(parts, bucket, options.weekStartsOn ?? 1) : null;
}

/** First and last day (`YYYY-MM-DD`, inclusive) of a bucket key. */
export function chartBucketRange(
  key: string,
  bucket: ChartBucket
): [string, string] | undefined {
  const first = bucketStart(key, bucket);
  if (!first) {
    return;
  }
  const next = nextBucketStart(first, bucket);
  return [dayKey(first), dayKey(shiftDays(next, -1))];
}

function bucketStart(key: string, bucket: ChartBucket): Date | undefined {
  if (bucket === "day" || bucket === "week") {
    const match = DATE_ONLY.exec(key);
    return match
      ? utcDay({
          year: Number(match[1]),
          month: Number(match[2]),
          day: Number(match[3]),
        })
      : undefined;
  }
  if (bucket === "month") {
    const match = MONTH_KEY.exec(key);
    return match
      ? new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, 1))
      : undefined;
  }
  if (bucket === "quarter") {
    const match = QUARTER_KEY.exec(key);
    return match
      ? new Date(
          Date.UTC(
            Number(match[1]),
            (Number(match[2]) - 1) * MONTHS_IN_QUARTER,
            1
          )
        )
      : undefined;
  }
  return YEAR_KEY.test(key) ? new Date(Date.UTC(Number(key), 0, 1)) : undefined;
}

function nextBucketStart(start: Date, bucket: ChartBucket): Date {
  const year = start.getUTCFullYear();
  const month = start.getUTCMonth();
  switch (bucket) {
    case "day":
      return shiftDays(start, 1);
    case "week":
      return shiftDays(start, DAYS_IN_WEEK);
    case "month":
      return new Date(Date.UTC(year, month + 1, 1));
    case "quarter":
      return new Date(Date.UTC(year, month + MONTHS_IN_QUARTER, 1));
    default:
      return new Date(Date.UTC(year + 1, 0, 1));
  }
}

/** The key of the bucket following `key`. */
export function nextChartBucketKey(
  key: string,
  bucket: ChartBucket
): string | undefined {
  const start = bucketStart(key, bucket);
  if (!start) {
    return;
  }
  const next = nextBucketStart(start, bucket);
  return bucketOfDay(
    {
      year: next.getUTCFullYear(),
      month: next.getUTCMonth() + 1,
      day: next.getUTCDate(),
    },
    bucket,
    next.getUTCDay()
  );
}

// Client aggregation ------------------------------------------------------------

const isEmptyValue = (value: unknown) =>
  value === null ||
  value === undefined ||
  value === "" ||
  (Array.isArray(value) && value.length === 0);

/** Group keys of one value: arrays count in each of their groups; empty values are null. */
function groupKeysOf(
  value: unknown,
  groupBy: ChartGroupBy,
  request: ChartAggregateRequest
): unknown[] {
  if (isEmptyValue(value)) {
    return [null];
  }
  const items = Array.isArray(value) ? value : [value];
  const keys = items.map((item) => {
    if (groupBy.bucket) {
      return chartBucketKey(item, groupBy.bucket, request);
    }
    return isEmptyValue(item) ? null : item;
  });
  return keys.filter(
    (key, index) => keys.findIndex((other) => Object.is(other, key)) === index
  );
}

interface MetricAccumulator {
  count: number;
  sum: number;
  numbers: number;
  min: number;
  max: number;
  distinct: Set<string>;
}

const newAccumulator = (): MetricAccumulator => ({
  count: 0,
  sum: 0,
  numbers: 0,
  min: Number.POSITIVE_INFINITY,
  max: Number.NEGATIVE_INFINITY,
  distinct: new Set(),
});

function accumulate(
  accumulator: MetricAccumulator,
  metric: ChartMetric,
  row: Record<string, unknown>
) {
  accumulator.count += 1;
  if (!metric.columnId) {
    return;
  }
  const value = row[metric.columnId];
  if (metric.fn === "countDistinct") {
    for (const item of Array.isArray(value) ? value : [value]) {
      if (!isEmptyValue(item)) {
        accumulator.distinct.add(JSON.stringify(item));
      }
    }
    return;
  }
  const numeric = typeof value === "number" ? value : Number(value);
  if (isEmptyValue(value) || !Number.isFinite(numeric)) {
    return;
  }
  accumulator.sum += numeric;
  accumulator.numbers += 1;
  accumulator.min = Math.min(accumulator.min, numeric);
  accumulator.max = Math.max(accumulator.max, numeric);
}

function metricValue(
  accumulator: MetricAccumulator,
  fn: ChartMetricFn
): number {
  switch (fn) {
    case "count":
      return accumulator.count;
    case "sum":
      return accumulator.sum;
    case "avg":
      return accumulator.numbers ? accumulator.sum / accumulator.numbers : 0;
    case "min":
      return accumulator.numbers ? accumulator.min : 0;
    case "max":
      return accumulator.numbers ? accumulator.max : 0;
    default:
      return accumulator.distinct.size;
  }
}

function keyCombinations(levels: unknown[][]): unknown[][] {
  let combinations: unknown[][] = [[]];
  for (const keys of levels) {
    combinations = combinations.flatMap((prefix) =>
      keys.map((key) => [...prefix, key])
    );
  }
  return combinations;
}

/**
 * The groups `actions.aggregate` would answer, computed over loaded rows.
 * Hosts can use it as their in-memory implementation of the contract.
 */
export function aggregateChartRows(
  rows: readonly unknown[],
  request: ChartAggregateRequest
): ChartAggregateResult {
  const groups = new Map<
    string,
    { keys: unknown[]; accumulators: MetricAccumulator[] }
  >();
  const levels = request.groupBy.slice(0, 2);
  for (const item of rows) {
    const row = recordValue(item);
    const combinations = keyCombinations(
      levels.map((level) => groupKeysOf(row[level.columnId], level, request))
    );
    for (const keys of combinations) {
      const id = JSON.stringify(keys);
      let group = groups.get(id);
      if (!group) {
        group = {
          keys,
          accumulators: request.metrics.map(() => newAccumulator()),
        };
        groups.set(id, group);
      }
      for (const [index, metric] of request.metrics.entries()) {
        const accumulator = group.accumulators[index];
        if (accumulator) {
          accumulate(accumulator, metric, row);
        }
      }
    }
  }
  if (!levels.length && groups.size === 0) {
    return {
      groups: [
        {
          keys: [],
          values: request.metrics.map((metric) =>
            metricValue(newAccumulator(), metric.fn)
          ),
        },
      ],
    };
  }
  return {
    groups: [...groups.values()].map((group) => ({
      keys: group.keys,
      values: group.accumulators.map((accumulator, index) =>
        metricValue(accumulator, request.metrics[index]?.fn ?? "count")
      ),
    })),
  };
}

// Loading ---------------------------------------------------------------------

export interface ChartDataRequest {
  /** `actions.aggregate`; answers with `groups` when the host supports `groupBy`. */
  aggregate?: (params: Record<string, unknown>) => unknown;
  list?: ScopedRowsRequest["list"];
  /** Rows matching the query, for tables without a list action. */
  rows?: readonly unknown[];
  /** The table's query as list parameters. */
  params: Record<string, unknown>;
  request: ChartAggregateRequest;
  locale: string;
  maxRows?: number;
  signal?: AbortSignal;
}

export interface ChartDataResult extends ChartAggregateResult {
  /** `server` when `actions.aggregate` answered the groups. */
  source: "client" | "server";
}

async function serverGroups(
  input: ChartDataRequest
): Promise<ChartAggregateResult | undefined> {
  if (!input.aggregate) {
    return;
  }
  try {
    const answer = normalizeChartAggregateResult(
      await input.aggregate(
        chartAggregateParams(input.params, input.request, input.locale)
      )
    );
    const metrics = input.request.metrics.length;
    // Hosts that answer fewer values than metrics (one metric only) fall back too.
    return answer?.groups.every((group) => group.values.length >= metrics)
      ? answer
      : undefined;
  } catch {
    // Hosts that reject grouped requests fall back to loaded rows.
    return;
  }
}

/** Server groups when the host answers them, otherwise groups over loaded rows. */
export async function loadChartData(
  input: ChartDataRequest
): Promise<ChartDataResult> {
  const server = await serverGroups(input);
  input.signal?.throwIfAborted();
  if (server) {
    return { ...server, source: "server" };
  }
  const loaded = await loadScopedRows({
    list: input.list,
    rows: input.rows,
    params: input.params,
    maxRows: input.maxRows,
    signal: input.signal,
  });
  return {
    ...aggregateChartRows(loaded.rows, input.request),
    ...(loaded.truncated ? { truncated: true } : {}),
    source: "client",
  };
}

