import { computed, onBeforeUnmount, ref } from "vue";
import { useTableContext } from "../context";
import {
  LIST_MOBILE_BREAKPOINT,
  resolveListSettings,
  visibleListProperties,
} from "../list-view";
import type { TableListViewConfig } from "../types";

const SYSTEM_COLUMNS = ["select", "actions"];

/** List settings mirror React: every non-title column is shown until the user picks. */
export function useListSettings() {
  const context = useTableContext();
  const translate = (key: string, fallback: string) =>
    String(context.translations.value[key] ?? fallback);
  const columns = computed(() =>
    context.config.columns.definitions.filter(
      (column) => !SYSTEM_COLUMNS.includes(column.id)
    )
  );
  const columnOptions = computed(() =>
    columns.value.map((column) => ({ value: column.id, label: column.header }))
  );
  const active = computed(() =>
    resolveListSettings(context.config.table.list, context.state.list.value)
  );
  const update = (patch: TableListViewConfig): void => {
    const next: TableListViewConfig = { ...context.state.list.value, ...patch };
    for (const key of Object.keys(patch) as (keyof TableListViewConfig)[]) {
      if (patch[key] === undefined) {
        Reflect.deleteProperty(next, key);
      }
    }
    context.state.list.value = next;
  };
  const query =
    typeof window !== "undefined" && typeof window.matchMedia === "function"
      ? window.matchMedia(`(max-width: ${LIST_MOBILE_BREAKPOINT - 1}px)`)
      : undefined;
  const isMobile = ref(query?.matches ?? false);
  const onMedia = (event: MediaQueryListEvent) => {
    isMobile.value = event.matches;
  };
  query?.addEventListener("change", onMedia);
  onBeforeUnmount(() => query?.removeEventListener("change", onMedia));
  const wrap = computed({
    get: () => active.value.wrap,
    set: (value: boolean) => update({ wrap: value }),
  });
  const showActions = computed({
    get: () => active.value.showActions,
    set: (value: boolean) => update({ showActions: value }),
  });
  const propertyAlign = computed({
    get: () => active.value.propertyAlign,
    set: (value: "end" | "start") => update({ propertyAlign: value }),
  });
  const maxProperties = computed({
    get: () => active.value.maxProperties,
    set: (value: number | undefined) => update({ maxProperties: value }),
  });
  const mobileMaxProperties = computed({
    get: () => active.value.mobileMaxProperties,
    set: (value: number | undefined) => update({ mobileMaxProperties: value }),
  });
  const titleColumn = computed({
    get: () => active.value.titleColumn || (columns.value[0]?.id ?? "id"),
    set: (value: string) => update({ titleColumn: value }),
  });
  const propertyIds = computed({
    get: () =>
      active.value.cardColumnIds ??
      columns.value
        .map((column) => column.id)
        .filter((id) => id !== titleColumn.value),
    set: (value: string[]) => update({ cardColumnIds: value }),
  });
  const showLabels = computed({
    get: () => active.value.showCardLabels === true,
    set: (value: boolean) => update({ showCardLabels: value }),
  });
  const reset = (): void => {
    context.state.list.value = {};
  };

  const visibleProperties = (ids: string[]): string[] =>
    visibleListProperties(ids, active.value, isMobile.value);

  return {
    context,
    wrap,
    showActions,
    propertyAlign,
    maxProperties,
    mobileMaxProperties,
    visibleProperties,
    translate,
    columns,
    columnOptions,
    titleColumn,
    propertyIds,
    showLabels,
    reset,
  };
}

import { type ComputedRef, computed } from "vue";
import { type TableContextValue, useTableContext } from "../context";
import type { DisplayModeSettingsContext } from "../display-mode-renderer";
import { GENERIC_MODE_CONFIG_KEYS, modeDefaultsOf } from "../display-modes";
import { formCreateFields } from "../form-view";

/** Fields of the table's create form, when the host declares one (`getFormConfig`). */
function createFormFields(
  context: TableContextValue
): readonly string[] | undefined {
  const tableType = context.tableType ?? context.config.id;
  const formType =
    context.config.form?.createFormType ?? context.formType ?? tableType;
  try {
    return formCreateFields(
      context.getFormConfig?.(formType, {
        formType,
        locale: context.locale,
        mode: "create",
        tableId: context.config.id,
        tableType,
        values: {},
      })?.fields
    );
  } catch {
    // A host form that cannot be built without a record limits nothing.
    return;
  }
}

/** Settings of the active mode, saved in the view and URL like built-in modes. */
export const useModeSettingsContext =
  (): ComputedRef<DisplayModeSettingsContext> => {
    const context = useTableContext();
    const translate = (key: string, fallback: string): string => {
      const value = context.translations.value[key];
      return typeof value === "string" ? value : fallback;
    };
    // The Form mode asks what the create form offers, when the host declares it.
    const formFields = computed(() => createFormFields(context));
    return computed(() => {
      const mode = context.state.displayMode.value;
      const key = GENERIC_MODE_CONFIG_KEYS.find((item) => item === mode);
      const table = context.config.table as unknown as Record<string, unknown>;
      return {
        tableId: context.config.id,
        locale: context.locale,
        columns: context.config.columns.definitions,
        defaults: modeDefaultsOf(table, mode),
        settings: (key && context.state.modeConfigs.value[key]) || {},
        updateSettings: (settings) => {
          if (!key) {
            return;
          }
          const next = { ...context.state.modeConfigs.value };
          if (settings && Object.keys(settings).length > 0) {
            next[key] = settings;
          } else {
            Reflect.deleteProperty(next, key);
          }
          context.state.modeConfigs.value = next;
        },
        translate,
        formFields: formFields.value,
      };
    });
  };

import { type Ref, ref } from "vue";

/** Portaled controls retain the table's theme and typography outside its DOM subtree. */
export function useOverlayTheme(anchor: Readonly<Ref<HTMLElement | null>>) {
  const overlayStyle = ref<Record<string, string>>({});
  const updateOpen = (open: boolean): void => {
    if (!(open && anchor.value)) {
      return;
    }
    const style = getComputedStyle(anchor.value);
    const tokens: Record<string, string> = { font: style.font };
    for (const name of [
      "background",
      "foreground",
      "muted",
      "muted-foreground",
      "border",
      "primary",
      "primary-foreground",
      "danger",
      "radius",
      "shadow",
    ]) {
      const property = `--yayaw-${name}`;
      tokens[property] = style.getPropertyValue(property);
    }
    overlayStyle.value = tokens;
  };
  return { overlayStyle, updateOpen };
}

import { computed, nextTick, onMounted, onScopeDispose, ref, watch } from "vue";
import { useTableContext } from "../context";
import {
  createLocalTableViewActions,
  readLocalTableViewOrder,
  storeLocalTableViewOrder,
} from "../core";
import { cloneFormValue, formValuesEqual } from "../form-runtime";
import { resolveInitialTableView } from "../table-view-favorite";
import type {
  TableDisplayMode,
  TableView,
  TableViewActionResult,
  TableViewConfig,
} from "../types";
import { areViewSettingsEqual } from "../view-menu";
import {
  formatViewMove,
  listedViewOrder,
  moveViewInOrder,
  orderViews,
  parseViewOrder,
  type ViewMoveDirection,
  viewMoves,
  viewPosition,
} from "../view-order";

/** Keep persistence and asynchronous state separate from menu/dialog presentation. */
export function useSavedViews(
  initialViews: () => TableView[],
  enabled: () => boolean = () => true
) {
  const context = useTableContext();
  const fallback = createLocalTableViewActions();
  const actions = computed(() => ({
    getFavorite:
      context.actions.value?.views?.getFavorite ?? fallback.getFavorite,
    setFavorite:
      context.actions.value?.views?.setFavorite ?? fallback.setFavorite,
    list: context.actions.value?.views?.list ?? fallback.list,
    create: context.actions.value?.views?.create ?? fallback.create,
    update: context.actions.value?.views?.update ?? fallback.update,
    delete: context.actions.value?.views?.delete ?? fallback.delete,
    // No local action: without the host's, this browser keeps the order.
    setOrder: context.actions.value?.views?.setOrder,
  }));
  const actionContext = {
    tableId: context.config.id,
    tableType: context.tableType,
  };
  // The host keeps the user's order with `setOrder` (and `list` answers
  // with it); otherwise this browser keeps it.
  const hostKeepsOrder = computed(
    () => typeof actions.value.setOrder === "function"
  );
  const views = ref<TableView[]>(cloneFormValue(initialViews()));
  const localOrder = ref<string[]>();
  /** The views in the user's order: tabs, "More views" and the view menu. */
  const orderedViews = computed(() =>
    orderViews(views.value, hostKeepsOrder.value ? undefined : localOrder.value)
  );
  const active = computed(() =>
    views.value.find((view) => view.id === context.state.activeViewId.value)
  );
  const dirty = computed(() =>
    Boolean(
      active.value &&
        !areViewSettingsEqual(
          context.state.resolveView(context.state.snapshot.value),
          context.state.resolveView(active.value.config)
        )
    )
  );
  const editable = computed(() =>
    Boolean(
      active.value &&
        !active.value.isSystem &&
        active.value.canEdit !== false &&
        context.config.table.allowViewSave
    )
  );
  const deletable = computed(() =>
    Boolean(
      active.value &&
        !active.value.isSystem &&
        active.value.canDelete !== false &&
        context.config.table.allowViewSave
    )
  );
  const busy = ref(false);
  const loading = ref(true);
  const loadError = ref("");
  const error = ref("");
  const dialogError = ref("");
  const dialogOpen = ref(false);
  const name = ref("");
  const shared = ref(false);
  /** Layout of the view being created; a tab's "+" may pick another one. */
  const newViewMode = ref<TableDisplayMode>();
  const favoriteViewId = ref<string | null>(null);
  const effectiveFavoriteViewId = computed(
    () =>
      views.value.find((view) => view.id === favoriteViewId.value)?.id ?? null
  );
  const favorite = computed(
    () =>
      (context.state.activeViewId.value ?? null) ===
      effectiveFavoriteViewId.value
  );
  /** Where the current view can move; undefined when it keeps its place. */
  const moves = computed(() => viewMoves(orderedViews.value, active.value?.id));
  /** Announced after a move, while the focus stays on the action. */
  const moveAnnouncement = ref("");
  let disposed = false;
  let hasInitialized = false;
  let initialSnapshot: TableViewConfig | undefined;
  onScopeDispose(() => {
    disposed = true;
  });
  const label = (reactKey: string, vueKey: string): string =>
    String(
      context.translations.value[reactKey] ??
        context.translations.value[vueKey] ??
        vueKey
    );
  const resultData = <T>(
    result: TableViewActionResult<T>,
    fallbackMessage: string
  ): T | undefined => {
    if (result.success === false || result.error) {
      throw new Error(result.error || fallbackMessage);
    }
    return result.data;
  };
  const select = (view?: TableView): void => {
    if (busy.value) {
      return;
    }
    error.value = "";
    hasInitialized = true;
    if (view) {
      context.state.applyView(view.config, view.id);
    } else {
      context.state.reset();
    }
  };
  const initialize = (): void => {
    if (
      !(hasInitialized || context.state.hasInitialTableUrlState) &&
      context.state.initialViewId === context.state.activeViewId.value &&
      formValuesEqual(initialSnapshot, context.state.snapshot.value)
    ) {
      const initial = resolveInitialTableView(
        views.value,
        context.state.initialViewId,
        favoriteViewId.value
      );
      if (initial) {
        select(initial);
      }
    }
  };
  const loadFavorite = async (): Promise<void> => {
    try {
      const data = resultData(
        await actions.value.getFavorite(actionContext),
        label("views.favoriteError", "favoriteViewError")
      );
      if (!disposed) {
        favoriteViewId.value = data?.viewId ?? null;
      }
    } catch (cause) {
      if (!disposed) {
        loadError.value =
          cause instanceof Error
            ? cause.message
            : label("views.favoriteError", "favoriteViewError");
      }
    }
  };
  /** The order this browser keeps, when the host does not (no `setOrder`). */
  const loadLocalOrder = (): void => {
    localOrder.value = hostKeepsOrder.value
      ? undefined
      : readLocalTableViewOrder(actionContext);
  };
  /** The saved views; false when the manager was disposed meanwhile. */
  const loadViews = async (): Promise<boolean> => {
    const response = await actions.value.list(actionContext);
    const loaded = Array.isArray(response)
      ? response
      : (resultData(
          response,
          label("views.notifications.error.load", "viewLoadError")
        ) ?? []);
    if (disposed) {
      return false;
    }
    // Persisted records supersede initial seeds, including their renamed/configured values.
    const merged = cloneFormValue([
      ...new Map(
        [...initialViews(), ...loaded].map((view) => [view.id, view])
      ).values(),
    ]);
    const order = listedViewOrder(response, hostKeepsOrder.value);
    views.value = order ? orderViews(merged, order) : merged;
    return true;
  };
  const load = async (): Promise<void> => {
    if (!enabled()) {
      loading.value = false;
      return;
    }
    loading.value = true;
    loadError.value = "";
    loadLocalOrder();
    // Parent URL hydration finishes before testing whether the user has edited the table.
    await nextTick();
    initialSnapshot ??= cloneFormValue(context.state.snapshot.value);
    // A view the link or the host names does not depend on the favorite: it
    // applies once the views are loaded (persisted records win over seeds).
    const explicit = context.state.initialViewId !== undefined;
    const favoriteLoaded = loadFavorite();
    try {
      if (!(await loadViews())) {
        return;
      }
      if (explicit) {
        initialize();
      }
      await favoriteLoaded;
      if (disposed) {
        return;
      }
      initialize();
      hasInitialized = true;
    } catch (cause) {
      if (!disposed) {
        loadError.value =
          cause instanceof Error
            ? cause.message
            : label("views.notifications.error.load", "viewLoadError");
      }
    } finally {
      if (!disposed) {
        loading.value = false;
      }
    }
  };
  const openSave = (): void => {
    if (busy.value || loading.value || !context.config.table.allowViewSave) {
      return;
    }
    name.value = "";
    shared.value = false;
    newViewMode.value = context.state.displayMode.value;
    dialogError.value = "";
    dialogOpen.value = true;
  };
  const closeSave = (): void => {
    if (!busy.value) {
      dialogOpen.value = false;
    }
  };
  const run = async (
    operation: () => Promise<void>,
    target: typeof error,
    fallbackMessage: string
  ): Promise<void> => {
    if (busy.value) {
      return;
    }
    busy.value = true;
    target.value = "";
    try {
      await operation();
    } catch (cause) {
      if (!disposed) {
        target.value = cause instanceof Error ? cause.message : fallbackMessage;
      }
    } finally {
      if (!disposed) {
        busy.value = false;
      }
    }
  };
  const upsert = (view: TableView): void => {
    const index = views.value.findIndex((item) => item.id === view.id);
    if (index < 0) {
      views.value.push(cloneFormValue(view));
    } else {
      views.value[index] = cloneFormValue(view);
    }
  };
  const notify = (reactKey: string, vueKey: string): void => {
    context.status.value = {
      type: "success",
      message: label(reactKey, vueKey),
    };
  };
  const toggleFavorite = async (): Promise<void> => {
    const view = active.value;
    if ((!view && context.state.activeViewId.value) || loading.value) {
      return;
    }
    const viewId = view && !favorite.value ? view.id : null;
    // The built-in default represents no personal override; its filled star is stable.
    if (!view && effectiveFavoriteViewId.value === null && !loadError.value) {
      return;
    }
    const failure = label("views.favoriteError", "favoriteViewError");
    await run(
      async () => {
        const result = resultData(
          await actions.value.setFavorite(viewId, actionContext),
          failure
        );
        if (!disposed) {
          favoriteViewId.value = result ? result.viewId : viewId;
        }
      },
      error,
      failure
    );
  };
  /** Keeps a new order with the host's `setOrder`, else in this browser. */
  const persistOrder = async (
    viewIds: string[],
    failure: string
  ): Promise<string[]> => {
    const setOrder = actions.value.setOrder;
    if (!setOrder) {
      if (!storeLocalTableViewOrder(actionContext, viewIds)) {
        throw new Error(failure);
      }
      localOrder.value = viewIds;
      return viewIds;
    }
    const saved = resultData(
      await setOrder({ ...actionContext, viewIds }),
      failure
    );
    const order = parseViewOrder(saved?.viewIds) ?? viewIds;
    if (!disposed) {
      views.value = orderViews(views.value, order);
    }
    return order;
  };
  /** Moves the current view one step, keeps the new order and announces it. */
  const move = async (direction: ViewMoveDirection): Promise<void> => {
    const view = active.value;
    const viewIds =
      view && moveViewInOrder(orderedViews.value, view.id, direction);
    if (!(view && viewIds) || busy.value) {
      return;
    }
    const failure = label("views.orderError", "viewOrderError");
    await run(
      async () => {
        const order = await persistOrder(viewIds, failure);
        const place = viewPosition(
          orderViews(orderedViews.value, order),
          view.id
        );
        if (place && !disposed) {
          moveAnnouncement.value = formatViewMove(
            label("views.moved", "viewMoved"),
            { name: view.name, ...place }
          );
        }
      },
      error,
      failure
    );
  };
  const save = async (): Promise<void> => {
    if (!context.config.table.allowViewSave) {
      return;
    }
    if (!name.value.trim()) {
      dialogError.value = label(
        "views.dialog.save.namePlaceholder",
        "viewNamePlaceholder"
      );
      return;
    }
    const current = cloneFormValue(context.state.snapshot.value);
    const config = {
      ...current,
      displayMode: newViewMode.value ?? current.displayMode,
    };
    const failure = label(
      "views.notifications.error.create",
      "viewCreateError"
    );
    await run(
      async () => {
        const result = await actions.value.create({
          ...actionContext,
          name: name.value.trim(),
          config,
          isGlobal: context.config.table.allowViewSharing && shared.value,
        });
        const view = resultData(result, failure);
        if (!view) {
          throw new Error(failure);
        }
        if (disposed) {
          return;
        }
        upsert(view);
        // Preserve table edits made while persistence was pending.
        if (
          config.displayMode !== current.displayMode ||
          formValuesEqual(current, context.state.snapshot.value)
        ) {
          context.state.applyView(view.config, view.id);
        } else {
          context.state.activeViewId.value = view.id;
        }
        dialogOpen.value = false;
        notify("views.notifications.created", "viewCreated");
      },
      dialogError,
      failure
    );
  };
  const update = async (): Promise<void> => {
    const view = active.value;
    if (!(view && editable.value && dirty.value)) {
      return;
    }
    const config = cloneFormValue(context.state.snapshot.value);
    const failure = label(
      "views.notifications.error.update",
      "viewUpdateError"
    );
    await run(
      async () => {
        const result = await actions.value.update(view.id, {
          ...actionContext,
          name: view.name,
          config,
        });
        const saved = resultData(result, failure) ?? { ...view, config };
        if (disposed) {
          return;
        }
        upsert(saved);
        if (
          context.state.activeViewId.value === view.id &&
          formValuesEqual(config, context.state.snapshot.value)
        ) {
          context.state.applyView(saved.config, saved.id);
        }
        notify("views.notifications.updated", "viewUpdated");
      },
      error,
      failure
    );
  };
  const remove = async (): Promise<void> => {
    const view = active.value;
    if (!(view && deletable.value)) {
      return;
    }
    const before = cloneFormValue(context.state.snapshot.value);
    const failure = label(
      "views.notifications.error.delete",
      "viewDeleteError"
    );
    await run(
      async () => {
        resultData(await actions.value.delete(view.id, actionContext), failure);
        if (disposed) {
          return;
        }
        views.value = views.value.filter((item) => item.id !== view.id);
        if (context.state.activeViewId.value === view.id) {
          if (formValuesEqual(before, context.state.snapshot.value)) {
            context.state.reset();
          } else {
            context.state.activeViewId.value = undefined;
          }
        }
        notify("views.notifications.deleted", "viewDeleted");
      },
      error,
      failure
    );
  };
  onMounted(load);
  watch(enabled, (isEnabled) => {
    if (isEnabled) {
      load();
    }
  });
  return {
    context,
    views,
    orderedViews,
    moves,
    move,
    moveAnnouncement,
    active,
    dirty,
    editable,
    deletable,
    busy,
    loading,
    loadError,
    error,
    dialogError,
    dialogOpen,
    name,
    shared,
    newViewMode,
    favorite,
    favoriteViewId: effectiveFavoriteViewId,
    toggleFavorite,
    label,
    select,
    load,
    openSave,
    closeSave,
    save,
    update,
    remove,
  };
}

import type { QueryClient } from "@tanstack/vue-query";
import {
  type ComputedRef,
  computed,
  onScopeDispose,
  type Ref,
  ref,
  watch,
} from "vue";
import { withManualOrderView } from "../manual-order";
import { compatibleListParams } from "../table-contracts";
import type {
  AdvancedFiltersState,
  ColumnFiltersState,
  PaginationState,
  SortingState,
  TableActions,
  TableListParams,
  TableRecord,
} from "../types";

export interface TableDataResult<TData extends TableRecord> {
  rows: Ref<TData[]>;
  rowCount: Ref<number>;
  pageCount: Ref<number>;
  isLoading: Ref<boolean>;
  error: Ref<Error | undefined>;
  isServer: ComputedRef<boolean>;
  refresh: () => Promise<void>;
}

export const useTableData = <TData extends TableRecord>({
  actions,
  inputData,
  search,
  filters,
  advancedFilters,
  sorting,
  grouping,
  pagination,
  initialRowCount,
  initialPageCount,
  initialRowsCurrent = false,
  queryClient,
  tableId,
  searchDebounceMs,
  viewId,
}: {
  actions: ComputedRef<TableActions<TData> | undefined>;
  inputData: ComputedRef<TData[]>;
  search: Ref<string>;
  filters: Ref<ColumnFiltersState>;
  advancedFilters: Ref<AdvancedFiltersState>;
  sorting: Ref<SortingState>;
  grouping: Ref<string[]>;
  pagination: Ref<PaginationState>;
  initialRowCount?: number;
  initialPageCount?: number;
  /**
   * The rows passed in are the starting state's first page, produced in its
   * sort (see `initial-rows.ts`): keep them until the state changes instead
   * of loading that page again on mount.
   */
  initialRowsCurrent?: boolean;
  queryClient: QueryClient;
  tableId: string;
  searchDebounceMs?: Readonly<Ref<number>>;
  /** Active saved view; sent with the manual-order sort so the host applies that view's order. */
  viewId?: Readonly<Ref<string | undefined>>;
}): TableDataResult<TData> => {
  const rows = ref<TData[]>([...inputData.value]) as Ref<TData[]>;
  const rowCount = ref(initialRowCount ?? inputData.value.length);
  const pageCount = ref(
    initialPageCount ?? Math.ceil(rowCount.value / pagination.value.pageSize)
  );
  const isLoading = ref(false);
  const error = ref<Error>();
  const isServer = computed(() => typeof actions.value?.list === "function");
  let requestId = 0;
  let activeQueryKey = "";
  let searchTimer: ReturnType<typeof setTimeout> | undefined;
  const cancelSearch = (): void => {
    clearTimeout(searchTimer);
    searchTimer = undefined;
  };
  onScopeDispose(() => {
    cancelSearch();
    requestId += 1;
  });

  const listParams = () =>
    withManualOrderView(
      {
        page: pagination.value.pageIndex + 1,
        pageSize: pagination.value.pageSize,
        search: search.value,
        filters: Object.fromEntries(
          filters.value.map((filter) => [filter.id, filter.value])
        ),
        advancedFilters: advancedFilters.value.filters,
        advancedFilterJoin: advancedFilters.value.joinOperator,
        sorting: sorting.value,
        grouping: grouping.value,
      },
      sorting.value,
      viewId?.value
    );
  const listQueryKey = (params: ReturnType<typeof listParams>) => [
    "yayaw-table",
    tableId,
    params,
  ];

  const loadRows = async (): Promise<void> => {
    cancelSearch();
    if (!actions.value?.list) {
      rows.value = [...inputData.value];
      rowCount.value = inputData.value.length;
      pageCount.value = Math.ceil(rowCount.value / pagination.value.pageSize);
      return;
    }
    const currentRequest = ++requestId;
    isLoading.value = true;
    error.value = undefined;
    try {
      const params = listParams();
      const list = actions.value.list;
      activeQueryKey = JSON.stringify(listQueryKey(params));
      const result = await queryClient.fetchQuery({
        queryKey: listQueryKey(params),
        queryFn: () =>
          list(compatibleListParams(params) as unknown as TableListParams),
        staleTime: 0,
      });
      if (currentRequest !== requestId) {
        return;
      }
      rowCount.value = result.meta?.totalCount ?? result.data.length;
      pageCount.value =
        result.meta?.pageCount ??
        Math.ceil(rowCount.value / pagination.value.pageSize);
      const lastPage = Math.max(0, pageCount.value - 1);
      if (pagination.value.pageIndex > lastPage) {
        // A deletion can remove the last page. Let the pagination watcher load its predecessor.
        pagination.value = { ...pagination.value, pageIndex: lastPage };
        return;
      }
      rows.value = result.data;
    } catch (cause) {
      if (currentRequest === requestId) {
        error.value = cause instanceof Error ? cause : new Error(String(cause));
      }
    } finally {
      if (currentRequest === requestId) {
        isLoading.value = false;
      }
    }
  };

  const refresh = async (): Promise<void> => {
    // A mutation must not reuse a pending list response captured before the write.
    requestId += 1;
    await queryClient.cancelQueries({
      queryKey: ["yayaw-table", tableId],
      predicate: (query) => JSON.stringify(query.queryKey) === activeQueryKey,
    });
    await loadRows();
  };

  const unsubscribe = queryClient.getQueryCache().subscribe(async (event) => {
    const key = event.query.queryKey;
    if (
      key[0] === "yayaw-table" &&
      key[1] === tableId &&
      JSON.stringify(key) === activeQueryKey &&
      event.type === "updated" &&
      event.action.type === "invalidate"
    ) {
      await refresh();
    }
  });
  onScopeDispose(unsubscribe);

  // Current rows stand for the starting state's first page, cached as its
  // response so an invalidation still reloads them, until the state or the
  // actions change (reading the URL on mount may set equal values again).
  let currentRowsKey = "";
  if (initialRowsCurrent && isServer.value) {
    const params = listParams();
    currentRowsKey = JSON.stringify(listQueryKey(params));
    activeQueryKey = currentRowsKey;
    queryClient.setQueryData(listQueryKey(params), {
      data: [...inputData.value],
      meta: { pageCount: pageCount.value, totalCount: rowCount.value },
    });
  }
  const keepsCurrentRows = (
    current: unknown[],
    previous: unknown[]
  ): boolean => {
    if (!currentRowsKey) {
      return false;
    }
    const sameActions = previous.length === 0 || current[0] === previous[0];
    if (
      sameActions &&
      JSON.stringify(listQueryKey(listParams())) === currentRowsKey
    ) {
      return true;
    }
    currentRowsKey = "";
    return false;
  };

  watch(
    inputData,
    async () => {
      if (!isServer.value) {
        await loadRows();
      }
    },
    { deep: true }
  );
  watch(
    [
      actions,
      search,
      filters,
      advancedFilters,
      sorting,
      grouping,
      pagination,
      () => viewId?.value,
    ],
    async (current, previous) => {
      if (keepsCurrentRows(current, previous)) {
        return;
      }
      cancelSearch();
      // Invalidate in-flight results before the debounce window starts.
      requestId += 1;
      const delay = Math.max(0, searchDebounceMs?.value ?? 0);
      if (
        previous.length &&
        current[1] !== previous[1] &&
        delay &&
        isServer.value
      ) {
        searchTimer = setTimeout(loadRows, delay);
      } else {
        await loadRows();
      }
    },
    { deep: true, immediate: true }
  );

  return { rows, rowCount, pageCount, isLoading, error, isServer, refresh };
};

import {
  computed,
  onBeforeUnmount,
  onMounted,
  type Ref,
  ref,
  watch,
} from "vue";
import {
  lockedColumnOrder,
  lockedColumnPinning,
  lockedColumnVisibility,
} from "../column-locks";
import { createTableViewSnapshot } from "../core";
import { normalizeDateFilterRules } from "../date-filter-days";
import {
  GENERIC_MODE_CONFIG_KEYS,
  pickGenericModeSettings,
  resolveDisplayMode,
  resolveDisplayModes,
} from "../display-modes";
import { cloneFormValue } from "../form-runtime";
import { normalizeGanttView } from "../planning/engine";
import type { TableGanttViewConfig } from "../planning/types";
import {
  isTableDensity,
  normalizeColumnSizing,
  normalizeFilterEnvelope,
  normalizeViewAliases,
  positiveInteger,
} from "../table-contracts";
import type {
  AdvancedFiltersState,
  ColumnFiltersState,
  ColumnPinningState,
  ColumnVisibilityState,
  PaginationState,
  SortingState,
  TableConfig,
  TableDensity,
  TableDisplayMode,
  TableGalleryViewConfig,
  TableKanbanViewConfig,
  TableListViewConfig,
  TableRecord,
  TableViewConfig,
} from "../types";

const emptyAdvancedFilters = (): AdvancedFiltersState => ({
  filters: [],
  joinOperator: "and",
});
const emptyPinning = (): ColumnPinningState => ({
  left: ["select"],
  right: ["actions"],
});

const parseJson = <T>(value: string | null, fallback: T): T => {
  if (!value) {
    return fallback;
  }
  try {
    return JSON.parse(value) as T;
  } catch {
    try {
      return JSON.parse(decodeURIComponent(value)) as T;
    } catch {
      return fallback;
    }
  }
};

const serialize = (value: unknown): string => JSON.stringify(value);
const serializeEncoded = (value: unknown): string =>
  encodeURIComponent(JSON.stringify(value));

export interface TableStateRefs {
  search: Ref<string>;
  filters: Ref<ColumnFiltersState>;
  advancedFilters: Ref<AdvancedFiltersState>;
  sorting: Ref<SortingState>;
  visibility: Ref<ColumnVisibilityState>;
  order: Ref<string[]>;
  sizing: Ref<Record<string, number>>;
  grouping: Ref<string[]>;
  pinning: Ref<ColumnPinningState>;
  pagination: Ref<PaginationState>;
  displayMode: Ref<TableDisplayMode>;
  /** Modes this table offers (configured, with their renderer or planning session). */
  offeredDisplayModes: readonly TableDisplayMode[];
  density: Ref<TableDensity>;
  footerCalculationsVisible: Ref<boolean>;
  kanban: Ref<TableKanbanViewConfig>;
  gantt: Ref<TableGanttViewConfig>;
  gallery: Ref<TableGalleryViewConfig>;
  list: Ref<TableListViewConfig>;
  /** Settings of the modes the registry handles generically, keyed by config key. */
  modeConfigs: Ref<Record<string, Record<string, unknown>>>;
  columnDragEnabled: Ref<boolean>;
  activeViewId: Ref<string | undefined>;
  initialViewId?: string;
  hasInitialTableUrlState: boolean;
  resolveView: (config: TableViewConfig) => TableViewConfig;
  snapshot: Readonly<Ref<TableViewConfig>>;
  applyView: (config: TableViewConfig, viewId?: string) => void;
  reset: () => void;
  resetFilters: () => void;
  shareableUrl: () => string;
}

export const useTableState = <TData extends TableRecord>({
  config,
  syncUrl,
  initialActiveViewId,
  instanceId,
  planning = false,
  renderers,
}: {
  config: TableConfig<TData>;
  syncUrl: boolean;
  initialActiveViewId?: string;
  /** Scopes the URL keys: `<instanceId>-view`, `<instanceId>-…`. */
  instanceId?: string;
  /** Whether a planning session exists; without one, links asking for Gantt fall back. */
  planning?: boolean;
  /** Modes with an optional renderer installed, such as `calendar`. */
  renderers?: readonly string[];
}): TableStateRefs => {
  const tableId = config.id;
  const columnDragStorageKey = `${tableId}-column-drag-enabled`;
  // A scoped instance prefixes every URL key, `view` included, with its id.
  const urlPrefix = instanceId || tableId;
  const viewKey = instanceId ? `${instanceId}-view` : "view";
  const columnDndFeatureEnabled = config.table.enableColumnDnd !== false;
  const initialColumnDragEnabled = (): boolean => {
    if (!columnDndFeatureEnabled) {
      return false;
    }
    if (typeof window === "undefined") {
      return config.table.enableColumnDragDropByDefault;
    }
    const storedPreference = window.localStorage.getItem(columnDragStorageKey);
    return storedPreference === null
      ? config.table.enableColumnDragDropByDefault
      : storedPreference === "true";
  };
  const search = ref("");
  const filters = ref<ColumnFiltersState>([]);
  const advancedFilters = ref<AdvancedFiltersState>(emptyAdvancedFilters());
  const sorting = ref<SortingState>(config.columns.sort ?? []);
  const visibility = ref<ColumnVisibilityState>(
    Object.fromEntries(
      config.columns.definitions.map((column) => [
        column.id,
        config.columns.visible.includes(column.id),
      ])
    )
  );
  const order = ref([...config.columns.order]);
  const sizing = ref<Record<string, number>>({});
  const grouping = ref<string[]>([]);
  const pinning = ref<ColumnPinningState>(emptyPinning());
  const columnIds = config.columns.definitions.map((column) => column.id);
  watch(
    [visibility, order, pinning],
    () => {
      const nextVisibility = lockedColumnVisibility(
        visibility.value,
        config.columns.mandatory
      );
      const nextOrder = lockedColumnOrder(order.value, columnIds);
      const nextPinning = lockedColumnPinning(
        pinning.value,
        columnIds,
        config.table.enableColumnPinning
      );
      if (serialize(visibility.value) !== serialize(nextVisibility)) {
        visibility.value = nextVisibility;
      }
      if (serialize(order.value) !== serialize(nextOrder)) {
        order.value = nextOrder;
      }
      if (serialize(pinning.value) !== serialize(nextPinning)) {
        pinning.value = nextPinning;
      }
    },
    { deep: true, immediate: true, flush: "sync" }
  );
  const pagination = ref<PaginationState>({
    pageIndex: 0,
    pageSize: config.table.defaultPageSize,
  });
  // Keep toolbar choices local to this instance without mutating shared configuration.
  const densityOverride = ref<TableDensity>();
  const footerCalculationsVisible = ref(true);
  const density = computed({
    get: () => densityOverride.value ?? config.table.density,
    set: (value: TableDensity) => {
      densityOverride.value = value;
    },
  });
  const displayMode = ref<TableDisplayMode>(
    config.table.defaultDisplayMode ?? "table"
  );
  const kanban = ref<TableKanbanViewConfig>({
    groupBy: config.table.kanban?.groupBy,
    titleColumn: config.table.kanban?.titleColumn,
    cardColumnIds: config.table.kanban?.cardColumnIds,
    showCardLabels: config.table.kanban?.showCardLabels,
  });
  const gantt = ref<TableGanttViewConfig>(
    normalizeGanttView(config.table.gantt)
  );
  const gallery = ref<TableGalleryViewConfig>({ ...config.table.gallery });
  // Settings of the modes the registry handles generically (`list`, …).
  const modeConfigs = ref<Record<string, Record<string, unknown>>>({
    ...pickGenericModeSettings(config.table),
  } as Record<string, Record<string, unknown>>);
  const list = computed<TableListViewConfig>({
    get: () => (modeConfigs.value.list ?? {}) as TableListViewConfig,
    set: (value) => {
      modeConfigs.value = {
        ...modeConfigs.value,
        list: value as Record<string, unknown>,
      };
    },
  });
  const columnDragEnabled = ref(initialColumnDragEnabled());
  watch(
    columnDragEnabled,
    (enabled) => {
      const effectiveValue = columnDndFeatureEnabled && enabled;
      if (enabled !== effectiveValue) {
        columnDragEnabled.value = effectiveValue;
        return;
      }
      if (typeof window !== "undefined") {
        window.localStorage.setItem(
          columnDragStorageKey,
          String(effectiveValue)
        );
      }
    },
    { immediate: true }
  );
  // Capture the incoming URL before this table starts writing its own state.
  const initialParams = new URLSearchParams(
    syncUrl && typeof window !== "undefined" ? window.location.search : ""
  );
  const hasInitialTableUrlState = [...initialParams.keys()].some((key) =>
    key.startsWith(`${urlPrefix}-`)
  );
  const initialViewId =
    initialParams.get(viewKey) ??
    (hasInitialTableUrlState ? undefined : initialActiveViewId);
  const activeViewId = ref<string | undefined>(initialViewId);
  let hydrating = true;
  let urlTimer: ReturnType<typeof setTimeout> | undefined;
  const enabledFilters = (value: ColumnFiltersState): ColumnFiltersState =>
    config.table.enableColumnFilters ? value : [];
  const dateColumnIds = new Set(
    config.columns.definitions
      .filter((column) => column.type === "date")
      .map((column) => column.id)
  );
  // Date rules name calendar days: older links and views saved instants,
  // which read as the viewer's days.
  const enabledAdvancedFilters = (
    value: AdvancedFiltersState
  ): AdvancedFiltersState =>
    config.table.enableColumnFilters
      ? (normalizeDateFilterRules(normalizeFilterEnvelope(value), {
          isDateColumn: (columnId) => dateColumnIds.has(columnId),
        }) as unknown as AdvancedFiltersState)
      : emptyAdvancedFilters();
  const enabledGrouping = (value: string[]): string[] =>
    config.table.enableGrouping ? value : [];
  const enabledPinning = (value: ColumnPinningState): ColumnPinningState =>
    config.table.enableColumnPinning ? value : emptyPinning();
  const enabledSizing = (value: unknown): Record<string, number> =>
    config.table.enableColumnResizing
      ? normalizeColumnSizing(value, columnIds)
      : {};
  const offeredDisplayModes = resolveDisplayModes(config.table.displayModes, {
    planning,
    renderers,
  });
  const enabledDisplayMode = (requested?: TableDisplayMode): TableDisplayMode =>
    resolveDisplayMode({
      allowed: offeredDisplayModes,
      fallback: config.table.defaultDisplayMode,
      requested,
    });

  const snapshot = computed<TableViewConfig>(() => ({
    ...createTableViewSnapshot({
      density: density.value,
      footerCalculationsVisible: footerCalculationsVisible.value,
      globalSearch: search.value,
      columnFilters: enabledFilters(filters.value),
      columnPinning: enabledPinning(pinning.value),
      search: search.value,
      filters: enabledFilters(filters.value),
      advancedFilters: enabledAdvancedFilters(advancedFilters.value),
      sorting: sorting.value,
      columnVisibility: visibility.value,
      columnOrder: order.value,
      columnSizing: enabledSizing(sizing.value),
      displayMode: displayMode.value,
      kanban: kanban.value,
      gantt: gantt.value,
      gallery: gallery.value,
      ...modeConfigs.value,
      grouping: enabledGrouping(grouping.value),
      pinning: enabledPinning(pinning.value),
      pageSize: pagination.value.pageSize,
    }),
    // Empty grouping is intentional, even when a Kanban lane is configured.
    grouping: enabledGrouping(grouping.value),
  }));

  /** Per-mode settings without their own URL migrations. */
  const readModeSettings = (
    params: URLSearchParams,
    defaults: TableViewConfig
  ): void => {
    gantt.value = normalizeGanttView(
      parseJson(params.get(`${urlPrefix}-gantt`), defaults.gantt ?? {})
    );
    modeConfigs.value = Object.fromEntries(
      GENERIC_MODE_CONFIG_KEYS.map((key) => [
        key,
        parseJson(
          params.get(`${urlPrefix}-${key}`),
          (defaults[key] ?? {}) as Record<string, unknown>
        ),
      ])
    );
    gallery.value = parseJson(
      params.get(`${urlPrefix}-gallery`),
      defaults.gallery ?? {}
    );
  };

  const fromUrl = (): void => {
    if (!syncUrl || typeof window === "undefined") {
      hydrating = false;
      return;
    }
    const params = new URLSearchParams(window.location.search);
    const defaults = resolveView({});
    search.value = params.get(`${urlPrefix}-q`) ?? "";
    filters.value = enabledFilters(
      parseJson(params.get(`${urlPrefix}-filters`), [])
    );
    advancedFilters.value = enabledAdvancedFilters(
      parseJson(
        params.get(`${urlPrefix}-advancedFilters`),
        emptyAdvancedFilters()
      )
    );
    sorting.value = parseJson(
      params.get(`${urlPrefix}-sort`),
      config.columns.sort ?? []
    );
    visibility.value = parseJson(
      params.get(`${urlPrefix}-visibility`),
      defaults.columnVisibility ?? {}
    );
    order.value = parseJson(
      params.get(`${urlPrefix}-order`),
      config.columns.order
    );
    sizing.value = enabledSizing(
      parseJson(params.get(`${urlPrefix}-sizing`), {})
    );
    grouping.value = enabledGrouping(
      parseJson(params.get(`${urlPrefix}-grouping`), [])
    );
    pinning.value = enabledPinning(
      parseJson(params.get(`${urlPrefix}-pinning`), emptyPinning())
    );
    pagination.value = {
      pageIndex: Math.max(
        0,
        positiveInteger(params.get(`${urlPrefix}-page`), 0)
      ),
      pageSize: positiveInteger(
        params.get(`${urlPrefix}-pageSize`),
        config.table.defaultPageSize
      ),
    };
    const requestedMode = params.get(
      `${urlPrefix}-display`
    ) as TableDisplayMode | null;
    displayMode.value = enabledDisplayMode(requestedMode ?? undefined);
    kanban.value = parseJson(
      params.get(`${urlPrefix}-kanban`),
      defaults.kanban ?? {}
    );
    if (!kanban.value.groupBy) {
      kanban.value = {
        ...kanban.value,
        groupBy:
          params.get(`${urlPrefix}-kanbanGroupBy`) ??
          config.table.kanban?.groupBy,
      };
    }
    if (
      displayMode.value === "kanban" &&
      !params.has(`${urlPrefix}-grouping`) &&
      (params.has(`${urlPrefix}-kanban`) ||
        params.has(`${urlPrefix}-kanbanGroupBy`)) &&
      kanban.value.groupBy
    ) {
      grouping.value = enabledGrouping([kanban.value.groupBy]);
    }
    readModeSettings(params, defaults);
    activeViewId.value =
      params.get(viewKey) ?? (hydrating ? initialViewId : undefined);
    hydrating = false;
  };

  const serializedGrouping = computed(() =>
    grouping.value.length || kanban.value.groupBy
      ? serialize(grouping.value)
      : undefined
  );
  const serializePresent = (value: object): string | undefined =>
    Object.keys(value).length ? serialize(value) : undefined;
  const commitUrl = (): void => {
    const url = new URL(window.location.href);
    const set = (key: string, value: string | undefined): void =>
      value ? url.searchParams.set(key, value) : url.searchParams.delete(key);
    set(`${urlPrefix}-q`, search.value || undefined);
    set(
      `${urlPrefix}-filters`,
      filters.value.length ? serialize(filters.value) : undefined
    );
    set(
      `${urlPrefix}-advancedFilters`,
      advancedFilters.value.filters.length
        ? serialize(advancedFilters.value)
        : undefined
    );
    set(
      `${urlPrefix}-sort`,
      sorting.value.length ? serialize(sorting.value) : undefined
    );
    set(`${urlPrefix}-visibility`, serialize(visibility.value));
    set(`${urlPrefix}-order`, serialize(order.value));
    set(
      `${urlPrefix}-sizing`,
      Object.keys(sizing.value).length ? serialize(sizing.value) : undefined
    );
    set(`${urlPrefix}-grouping`, serializedGrouping.value);
    set(`${urlPrefix}-pinning`, serializeEncoded(pinning.value));
    set(
      `${urlPrefix}-page`,
      pagination.value.pageIndex
        ? String(pagination.value.pageIndex)
        : undefined
    );
    set(
      `${urlPrefix}-pageSize`,
      pagination.value.pageSize !== config.table.defaultPageSize
        ? String(pagination.value.pageSize)
        : undefined
    );
    set(
      `${urlPrefix}-display`,
      displayMode.value !== (config.table.defaultDisplayMode ?? "table")
        ? displayMode.value
        : undefined
    );
    set(`${urlPrefix}-kanban`, serializePresent(kanban.value));
    set(`${urlPrefix}-gantt`, serializePresent(gantt.value));
    set(`${urlPrefix}-gallery`, serializePresent(gallery.value));
    for (const key of GENERIC_MODE_CONFIG_KEYS) {
      set(
        `${urlPrefix}-${key}`,
        serializePresent(modeConfigs.value[key] ?? {})
      );
    }
    set(viewKey, activeViewId.value);
    window.history.replaceState(window.history.state, "", url);
  };

  const writeUrl = (): void => {
    if (!syncUrl || hydrating || typeof window === "undefined") {
      return;
    }
    if (urlTimer) {
      clearTimeout(urlTimer);
    }
    urlTimer = setTimeout(commitUrl, 40);
  };

  /** Resolve partial saved views against catalogue defaults, never the previously selected view. */
  const resolveView = (input: TableViewConfig): TableViewConfig => {
    const aliases = normalizeViewAliases(input);
    const globalSearch = String(aliases.globalSearch ?? "");
    const columnFilters = enabledFilters(
      aliases.columnFilters as ColumnFiltersState
    );
    const columnPinning = lockedColumnPinning(
      enabledPinning(aliases.columnPinning as ColumnPinningState),
      columnIds,
      config.table.enableColumnPinning
    );
    return cloneFormValue(
      createTableViewSnapshot({
        footerCalculationsVisible: input.footerCalculationsVisible ?? true,
        density: isTableDensity(input.density)
          ? input.density
          : config.table.density,
        globalSearch,
        search: globalSearch,
        columnFilters,
        filters: columnFilters,
        columnPinning,
        pinning: columnPinning,
        advancedFilters: enabledAdvancedFilters(
          normalizeFilterEnvelope(
            input.advancedFilters
          ) as unknown as AdvancedFiltersState
        ),
        sorting: input.sorting ?? config.columns.sort ?? [],
        columnVisibility: lockedColumnVisibility(
          input.columnVisibility ??
            Object.fromEntries(
              config.columns.definitions.map((column) => [
                column.id,
                config.columns.visible.includes(column.id),
              ])
            ),
          config.columns.mandatory
        ),
        columnOrder: lockedColumnOrder(
          input.columnOrder ?? config.columns.order,
          columnIds
        ),
        columnSizing: enabledSizing(input.columnSizing),
        displayMode: enabledDisplayMode(input.displayMode),
        kanban: input.kanban ?? {
          groupBy: config.table.kanban?.groupBy,
          titleColumn: config.table.kanban?.titleColumn,
          cardColumnIds: config.table.kanban?.cardColumnIds,
          showCardLabels: config.table.kanban?.showCardLabels,
        },
        gantt: normalizeGanttView(input.gantt ?? config.table.gantt),
        gallery: input.gallery ?? { ...config.table.gallery },
        ...Object.fromEntries(
          GENERIC_MODE_CONFIG_KEYS.map((key) => [
            key,
            input[key] ?? {
              ...(
                pickGenericModeSettings(config.table) as Record<
                  string,
                  object | undefined
                >
              )[key],
            },
          ])
        ),
        grouping: enabledGrouping(
          input.grouping ??
            (enabledDisplayMode(input.displayMode) === "kanban"
              ? (aliases.grouping as string[])
              : [])
        ),
        pageSize: positiveInteger(input.pageSize, config.table.defaultPageSize),
      })
    );
  };

  const applyView = (input: TableViewConfig, viewId?: string): void => {
    const view = resolveView(input);
    densityOverride.value = view.density;
    footerCalculationsVisible.value = view.footerCalculationsVisible ?? true;
    search.value = view.search ?? "";
    filters.value = view.filters ?? [];
    advancedFilters.value = enabledAdvancedFilters(
      normalizeFilterEnvelope(
        view.advancedFilters
      ) as unknown as AdvancedFiltersState
    );
    sorting.value = view.sorting ?? [];
    visibility.value = view.columnVisibility ?? {};
    order.value = view.columnOrder ?? [];
    sizing.value = enabledSizing(view.columnSizing);
    displayMode.value = view.displayMode ?? "table";
    kanban.value = view.kanban ?? {};
    gantt.value = normalizeGanttView(view.gantt);
    gallery.value = view.gallery ?? {};
    modeConfigs.value = Object.fromEntries(
      GENERIC_MODE_CONFIG_KEYS.map((key) => [
        key,
        (view[key] ?? {}) as Record<string, unknown>,
      ])
    );
    grouping.value = view.grouping ?? [];
    pinning.value = view.pinning ?? emptyPinning();
    pagination.value = {
      pageIndex: 0,
      pageSize: view.pageSize ?? config.table.defaultPageSize,
    };
    activeViewId.value = viewId;
  };

  const resetFilters = (): void => {
    search.value = "";
    filters.value = [];
    advancedFilters.value = emptyAdvancedFilters();
    pagination.value = { ...pagination.value, pageIndex: 0 };
  };

  const reset = (): void => {
    applyView({
      sorting: config.columns.sort ?? [],
      columnVisibility: Object.fromEntries(
        config.columns.definitions.map((column) => [
          column.id,
          config.columns.visible.includes(column.id),
        ])
      ),
      columnOrder: config.columns.order,
      columnSizing: {},
      displayMode: config.table.defaultDisplayMode,
      pageSize: config.table.defaultPageSize,
    });
  };

  const shareableUrl = (): string =>
    typeof window === "undefined" ? "" : window.location.href;

  watch(
    [
      search,
      filters,
      advancedFilters,
      sorting,
      visibility,
      order,
      sizing,
      grouping,
      pinning,
      pagination,
      displayMode,
      kanban,
      gantt,
      gallery,
      modeConfigs,
      activeViewId,
    ],
    writeUrl,
    { deep: true }
  );
  watch(
    [search, filters, advancedFilters, sorting],
    () => {
      if (!hydrating && pagination.value.pageIndex !== 0) {
        pagination.value = { ...pagination.value, pageIndex: 0 };
      }
    },
    { deep: true }
  );
  onMounted(() => {
    fromUrl();
    window.addEventListener("popstate", fromUrl);
  });
  onBeforeUnmount(() => {
    if (urlTimer) {
      clearTimeout(urlTimer);
    }
    if (typeof window !== "undefined") {
      window.removeEventListener("popstate", fromUrl);
    }
  });

  return {
    search,
    filters,
    advancedFilters,
    sorting,
    visibility,
    order,
    sizing,
    grouping,
    pinning,
    pagination,
    displayMode,
    offeredDisplayModes,
    density,
    footerCalculationsVisible,
    kanban,
    gantt,
    gallery,
    list,
    modeConfigs,
    columnDragEnabled,
    activeViewId,
    initialViewId,
    hasInitialTableUrlState,
    resolveView,
    snapshot,
    applyView,
    reset,
    resetFilters,
    shareableUrl,
  };
};

import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  useTemplateRef,
