/** The builder's panels on phones, one at a time. */
export type FormBuilderTab = "outline" | "preview" | "properties";

/** Key of the form's own settings (title, layout, languages, messages). */
export const FORM_BUILDER_FORM = "form";
const ITEM = "item:";
const COLUMN = "column:";

/** Key of a question, section, consent or hidden field in the builder. */
export const formBuilderItemKey = (id: string): string => `${ITEM}${id}`;

/** Key of a column the form does not ask. */
export const formBuilderColumnKey = (columnId: string): string =>
  `${COLUMN}${columnId}`;

interface EntryBase {
  /** `item:<id>` or `column:<id>`: what the outline selects. */
  key: string;
  id: string;
  /** How the outline names it, in the language being edited. */
  name: string;
}

export interface FormBuilderQuestionEntry extends EntryBase {
  kind: "question";
  /** Place among the ordered items (questions, sections and consents). */
  index: number;
  column: FormColumn;
  question: FormQuestion;
  required: boolean;
  /** Rules show, hide or require it. */
  conditional: boolean;
  missing: boolean;
}

export interface FormBuilderSectionEntry extends EntryBase {
  kind: "section";
  index: number;
  section: FormSectionBreak;
  conditional: boolean;
  missing: boolean;
}

export interface FormBuilderConsentEntry extends EntryBase {
  kind: "consent";
  index: number;
  consent: FormConsentQuestion;
  missing: boolean;
}

export interface FormBuilderHiddenEntry extends EntryBase {
  kind: "hidden";
  field: FormHiddenField;
  /** Where the value is saved: a column's name, or "Response details". */
  target: string;
}

export interface FormBuilderColumnEntry extends EntryBase {
  kind: "column";
  column: FormColumn;
  /** The fixed value saved with every response, as shown. */
  fixed?: string;
}

/** An item the form shows, in order. */
export type FormBuilderOrderedEntry =
  | FormBuilderQuestionEntry
  | FormBuilderSectionEntry
  | FormBuilderConsentEntry;

export type FormBuilderEntry =
  | FormBuilderOrderedEntry
  | FormBuilderHiddenEntry
  | FormBuilderColumnEntry;

/**
 * A group of the outline: the form's items in order, its hidden fields, and
 * the columns it does not ask. A form writing several tables can add a group
 * of its tables the same way.
 */
export interface FormBuilderGroup {
  id: "columns" | "hidden" | "items";
  title: string;
  entries: FormBuilderEntry[];
}

/** What the conditions of the selected question need. */
export interface FormBuilderRules {
  list: FormRule[];
  /** Questions its conditions may read (every other question). */
  fields: ConditionField[];
  issues: RuleIssue[];
  questions: ResolvedFormQuestion[];
  summaries: string[];
}

/** The selected entry, with what its properties need. */
export type FormBuilderSelection =
  | { kind: "form" }
  | {
      kind: "question";
      entry: FormBuilderQuestionEntry;
      rules: FormBuilderRules;
      /** Number of ordered items, for "Move up" and "Move down". */
      count: number;
    }
  | { kind: "section"; entry: FormBuilderSectionEntry; count: number }
  | { kind: "consent"; entry: FormBuilderConsentEntry; count: number }
  | {
      kind: "hidden";
      entry: FormBuilderHiddenEntry;
      /** Columns the field may write. */
      columns: FormColumn[];
    }
  | {
      kind: "column";
      entry: FormBuilderColumnEntry;
      /** Options of a fixed value chosen in a list; typed otherwise. */
      choices?: { value: string; label: string }[];
      value?: FormHiddenValue;
    };

/** An item being dragged, and the place it would drop at. */
export interface FormBuilderDrag {
  key: string;
  from: number;
  to: number;
}

export interface FormBuilderState {
  /** The view's own form settings, as edited. */
  draft: FormViewSettings;
  /** The form they make with the table's settings (what the preview shows). */
  form: FormViewSettings;
  /** The draft differs from what is saved in the view. */
  dirty: boolean;
  /** The draft was just saved; cleared by the next change. */
  saved: boolean;
  /** The form's title in the language being edited. */
  title: string;
  selected: string;
  selection: FormBuilderSelection;
  groups: FormBuilderGroup[];
  ordered: FormBuilderOrderedEntry[];
  /** Columns "Add" offers as questions. */
  addable: FormColumn[];
  /** Columns a form cannot ask (computed or custom values). */
  excluded: FormColumn[];
  languages: string[];
  addableLocales: string[];
  defaultLocale: string;
  /** The language texts are written in, and the preview shows. */
  locale: string;
  layout: FormLayout;
  tab: FormBuilderTab;
  /** Phones and narrow windows: one panel at a time, in tabs. */
  compact: boolean;
  /** "Discard your changes?" is asked. */
  confirming: boolean;
  drag?: FormBuilderDrag;
  /** An entry to focus after the outline renders (it moved), with a counter. */
  focus?: { key: string; count: number };
  /** What a live region reads: moves, additions, removals, saving. */
  announcement: string;
}

export interface FormBuilderOptions {
  columns: readonly FormColumn[];
  /** The table's form settings (`table.form`), under the view's. */
  defaults: unknown;
  /** The view's own form settings when the builder opens. */
  settings: unknown;
  /** The table's language: labels, and the default language of forms without one. */
  locale: string;
  translate?: FormTranslate;
  /** Save the draft in the view (`undefined`: back to the table's settings). */
  onSave: (settings: FormViewSettings | undefined) => void;
  onClose: () => void;
}

type LabelParams = Record<string, number | string>;

const sortKeys = (value: unknown): unknown => {
  if (Array.isArray(value)) {
    return value.map(sortKeys);
  }
  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return Object.fromEntries(
      Object.keys(record)
        .sort()
        .map((key) => [key, sortKeys(record[key])])
    );
  }
  return value;
};

/** Whether two form settings are the same once normalized, key order aside. */
export function sameFormSettings(left: unknown, right: unknown): boolean {
  const text = (value: unknown) =>
    JSON.stringify(sortKeys(normalizeFormViewConfig(value) ?? {}));
  return text(left) === text(right);
}

/** Alt + ↑ / ↓ on an outline entry moves it one place; other keys do not. */
export function formBuilderKeyMove(event: {
  key: string;
  altKey: boolean;
}): -1 | 1 | undefined {
  if (!event.altKey) {
    return;
  }
  if (event.key === "ArrowUp") {
    return -1;
  }
  return event.key === "ArrowDown" ? 1 : undefined;
}

interface TextLanguage {
  locale: string;
  defaultLocale: string;
}

/** A consent's statement as the form reads it, its link text in place. */
function consentName(consent: FormConsentQuestion, texts: TextLanguage) {
  const { defaultLocale, locale } = texts;
  const statement =
    resolveFormText(consent.text, locale, defaultLocale) ??
    formLabel(consent.link ? "consentTextLink" : "consentText", locale);
  const link =
    resolveFormText(consent.link?.label, locale, defaultLocale) ??
    formLabel("consentLinkLabel", locale);
  return statement.replaceAll("{link}", link);
}

/** A fixed value as the outline shows it: an option's label, or the value. */
function fixedText(
  column: FormColumn,
  value: FormHiddenValue | undefined
): string | undefined {
  if (value === undefined) {
    return;
  }
  const choice = formHiddenChoices(column)?.find(
    (option) => option.value === String(value)
  );
  return choice?.label ?? (formHiddenValueText(value) || undefined);
}

interface OutlineInput {
  columns: readonly FormColumn[];
  form: FormViewSettings;
  items: FormItem[];
  texts: TextLanguage;
  label: (key: FormLabelKey, params?: LabelParams) => string;
}

function orderedEntries({
  columns,
  form,
  items,
  label,
  texts,
}: OutlineInput): FormBuilderOrderedEntry[] {
  const { defaultLocale, locale } = texts;
  const byId = new Map(columns.map((column) => [column.id, column]));
  const rules = form.rules ?? [];
  const conditional = (id: string) => formRulesFor(rules, id).length > 0;
  const entries: FormBuilderOrderedEntry[] = [];
  for (const item of formOrderedItems(items)) {
    const index = entries.length;
    const base = { key: formBuilderItemKey(item.id), id: item.id, index };
    if (isFormSection(item)) {
      entries.push({
        ...base,
        kind: "section",
        name:
          resolveFormText(item.title, locale, defaultLocale) ??
          label("untitledSection"),
        section: item,
        conditional: conditional(item.id),
        missing: formItemMissingTranslation(item, locale, defaultLocale),
      });
    } else if (isFormConsent(item)) {
      entries.push({
        ...base,
        kind: "consent",
        name: consentName(item, texts),
        consent: item,
        missing: formItemMissingTranslation(item, locale, defaultLocale),
      });
    } else if (isFormQuestion(item)) {
      const column = byId.get(item.columnId);
      if (column) {
        entries.push({
          ...base,
          kind: "question",
          name:
            resolveFormText(item.label, locale, defaultLocale) ?? column.header,
          column,
          question: item,
          required: item.required === true,
          conditional: conditional(item.id),
          missing: formItemMissingTranslation(
            item,
            locale,
            defaultLocale,
            column
          ),
        });
      }
    }
  }
  return entries;
}

function hiddenEntries({
  columns,
  items,
  label,
}: OutlineInput): FormBuilderHiddenEntry[] {
  return items.filter(isFormHiddenField).map((field) => ({
    key: formBuilderItemKey(field.id),
    id: field.id,
    kind: "hidden",
    name:
      field.source.type === "urlParam"
        ? field.source.name
        : label(FORM_HIDDEN_SOURCE_LABELS[field.source.type]),
    field,
    target:
      columns.find((column) => column.id === field.columnId)?.header ??
      label("responseDetails"),
  }));
}

function columnEntries(
  eligible: readonly FormColumn[],
  { form, items }: OutlineInput
): FormBuilderColumnEntry[] {
  const asked = new Set(
    items.filter(isFormQuestion).map((question) => question.columnId)
  );
  const fixed = form.hiddenValues ?? {};
  return eligible
    .filter((column) => !asked.has(column.id))
    .map((column) => ({
      key: formBuilderColumnKey(column.id),
      id: column.id,
      kind: "column",
      name: column.header,
      column,
      fixed: fixedText(column, fixed[column.id]),
    }));
}

/** The rules acting on a question, and what editing them needs. */
function questionRules(
  columns: readonly FormColumn[],
  form: FormViewSettings,
  questionId: string,
  locale: string,
  translate?: FormTranslate
): FormBuilderRules {
  const list = formRulesFor(form.rules, questionId);
  const ids = new Set(list.map((rule) => rule.id));
  const { questions } = resolveFormSettings(
    columns,
    undefined,
    { ...form, rules: [] },
    locale
  );
  return {
    list,
    fields: formRuleFields(columns, form, locale).filter(
      (field) => field.id !== questionId
    ),
    issues: formRuleIssues(columns, form).filter((issue) =>
      ids.has(issue.ruleId)
    ),
    questions,
    summaries: list.map((rule) =>
      formRuleSummary(rule, questions, locale, translate)
    ),
  };
}

/** The outline's entries by group, and the columns a form cannot ask. */
interface Outline {
  ordered: FormBuilderOrderedEntry[];
  hidden: FormBuilderHiddenEntry[];
  columns: FormBuilderColumnEntry[];
  excluded: FormColumn[];
}

type FormItemPatch = Parameters<typeof updateFormQuestion>[2];

/** The item after (else before) `key` among `keys`, for the selection after a removal. */
function neighbour(keys: readonly string[], key: string): string | undefined {
  const index = keys.indexOf(key);
  return index < 0 ? undefined : (keys[index + 1] ?? keys[index - 1]);
}

/**
 * The form builder's state and edits. It holds a draft of the view's form
 * settings: the table is changed only by `save`, and closing with unsaved
 * changes asks first.
 */
export class FormBuilderController {
  private options: FormBuilderOptions;
  private readonly listeners = new Set<() => void>();
  private savedSettings: FormViewSettings;
  private draft: FormViewSettings;
  private selected: string;
  private localeChoice: string | undefined;
  private tab: FormBuilderTab = "outline";
  private compact = false;
  private confirming = false;
  private justSaved = false;
  private drag: FormBuilderDrag | undefined;
  private focus: { key: string; count: number } | undefined;
  private focusCount = 0;
  private announcement = "";
  private snapshot: FormBuilderState | undefined;

  constructor(options: FormBuilderOptions) {
    this.options = options;
    this.savedSettings = normalizeFormViewConfig(options.settings) ?? {};
    this.draft = this.savedSettings;
    this.selected = this.firstKey();
  }

  // ------------------------------------------------------------ subscription

  subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  };

  getState = (): FormBuilderState => {
    if (!this.snapshot) {
      this.snapshot = this.buildState();
    }
    return this.snapshot;
  };

  private emit(): void {
    this.snapshot = undefined;
    for (const listener of this.listeners) {
      listener();
    }
  }

  /**
   * New columns, table settings, language or callbacks; the draft is kept.
   * The state changes only when what it shows does.
   */
  setOptions(options: FormBuilderOptions): void {
    const previous = this.options;
    this.options = options;
    const changed =
      previous.columns !== options.columns ||
      previous.defaults !== options.defaults ||
      previous.locale !== options.locale ||
      previous.translate !== options.translate;
    if (changed) {
      this.emit();
    }
  }

  // ------------------------------------------------------------ labels

  private readonly label = (key: FormLabelKey, params?: LabelParams): string =>
    formLabel(key, this.options.locale, this.options.translate, params);

  // ------------------------------------------------------------ derived

  private form(): FormViewSettings {
    return mergeFormSettings(this.options.defaults, this.draft);
  }

  private items(form = this.form()): FormItem[] {
    return formQuestionList(this.options.columns, form);
  }

  private languages(form = this.form()) {
    const fallback = formLanguage(this.options.locale) || "en";
    const pinned = formDefaultLocale(form);
    const defaultLocale = pinned ?? fallback;
    const languages = formViewLocales(
      this.options.defaults,
      this.draft,
      fallback
    );
    const locale =
      this.localeChoice && languages.includes(this.localeChoice)
        ? this.localeChoice
        : defaultLocale;
    return { defaultLocale, languages, locale, pinned };
  }

  private outline(form = this.form()): Outline {
    const { eligible, excluded } = formColumns(this.options.columns);
    const { defaultLocale, locale } = this.languages(form);
    const input: OutlineInput = {
      columns: this.options.columns,
      form,
      items: this.items(form),
      texts: { defaultLocale, locale },
      label: this.label,
    };
    return {
      ordered: orderedEntries(input),
      hidden: hiddenEntries(input),
      columns: columnEntries(eligible, input),
      excluded,
    };
  }

  private firstKey(): string {
    return this.outline().ordered[0]?.key ?? FORM_BUILDER_FORM;
  }

  private entry(key: string): FormBuilderEntry | undefined {
    const { columns, hidden, ordered } = this.outline();
    return [...ordered, ...hidden, ...columns].find(
      (entry) => entry.key === key
    );
  }

  private buildSelection(
    outline: Outline,
    form: FormViewSettings
  ): FormBuilderSelection {
    const { columns, hidden, ordered } = outline;
    const count = ordered.length;
    const entry = [...ordered, ...hidden, ...columns].find(
      (item) => item.key === this.selected
    );
    switch (entry?.kind) {
      case "question":
        return {
          kind: "question",
          entry,
          count,
          rules: questionRules(
            this.options.columns,
            form,
            entry.id,
            this.options.locale,
            this.options.translate
          ),
        };
      case "section":
        return { kind: "section", entry, count };
      case "consent":
        return { kind: "consent", entry, count };
      case "hidden":
        return {
          kind: "hidden",
          entry,
          columns: formHiddenFieldColumns(
            this.options.columns,
            this.items(form),
            entry.id
          ),
        };
      case "column":
        return {
          kind: "column",
          entry,
          choices: formHiddenChoices(entry.column),
          value: form.hiddenValues?.[entry.id],
        };
      default:
        return { kind: "form" };
    }
  }

  private buildState(): FormBuilderState {
    const form = this.form();
    const outline = this.outline(form);
    const { defaultLocale, languages, locale } = this.languages(form);
    const selection = this.buildSelection(outline, form);
    const selected =
      selection.kind === "form" ? FORM_BUILDER_FORM : selection.entry.key;
    return {
      draft: this.draft,
      form,
      dirty: !sameFormSettings(this.savedSettings, this.draft),
      saved: this.justSaved,
      title:
        resolveFormText(form.title, locale, defaultLocale) ??
        this.label("untitledForm"),
      selected,
      selection,
      groups: [
        {
          id: "items",
          title: this.label("questions"),
          entries: outline.ordered,
        },
        {
          id: "hidden",
          title: this.label("hiddenFields"),
          entries: outline.hidden,
        },
        {
          id: "columns",
          title: this.label("notInForm"),
          entries: outline.columns,
        },
      ],
      ordered: outline.ordered,
      addable: outline.columns.map((entry) => entry.column),
      excluded: outline.excluded,
      languages,
      addableLocales: formAddableLocales(this.options.defaults, languages),
      defaultLocale,
      locale,
      layout: form.layout ?? "page",
      tab: this.tab,
      compact: this.compact,
      confirming: this.confirming,
      drag: this.drag,
      focus: this.focus,
      announcement: this.announcement,
    };
  }

  // ------------------------------------------------------------ edits

  /** Settings that are not texts: layout, review, fixed values, rules… */
  update(patch: FormViewSettings): void {
    this.draft = normalizeFormViewConfig({ ...this.draft, ...patch }) ?? {};
    this.justSaved = false;
    this.emit();
  }

  /**
   * Texts written in the language being edited. Writing in another language
   * pins the default one, so plain texts keep theirs.
   */
  write(patch: FormViewSettings): void {
    const { defaultLocale, locale, pinned } = this.languages();
    this.update(
      locale === defaultLocale || pinned ? patch : { ...patch, defaultLocale }
    );
  }

  private setItems(items: FormItem[]): void {
    this.write({ questions: items });
  }

  private say(announcement: string): void {
    this.announcement = announcement;
  }

  select(key: string): void {
    if (key !== FORM_BUILDER_FORM && !this.entry(key)) {
      return;
    }
    this.selected = key;
    if (this.compact) {
      this.tab = "properties";
    }
    this.emit();
  }

  setTab(tab: FormBuilderTab): void {
    if (tab !== this.tab) {
      this.tab = tab;
      this.emit();
    }
  }

  setCompact(compact: boolean): void {
    if (compact !== this.compact) {
      this.compact = compact;
      this.emit();
    }
  }

  // Languages ---------------------------------------------------------

  setLocale(locale: string): void {
    this.localeChoice = locale;
    this.emit();
  }

  addLanguage(added: string): void {
    const { defaultLocale, languages } = this.languages();
    this.localeChoice = added;
    this.update({
      locales: uniqueFormLocales([...languages, added]),
      defaultLocale,
    });
  }

  setDefaultLocale(defaultLocale: string): void {
    this.update({ defaultLocale });
  }

  setLayout(layout: FormLayout): void {
    this.update({ layout });
  }

  // Items -------------------------------------------------------------

  /** Change a question, section or consent. */
  changeItem(id: string, patch: FormItemPatch): void {
    this.setItems(updateFormQuestion(this.items(), id, patch));
  }

  /** Change a hidden field's source or column; its key follows its new id. */
  changeHidden(
    id: string,
    patch: { source?: FormHiddenSource; columnId?: string }
  ): void {
    const next = updateFormHiddenField(this.items(), id, patch);
    if (this.selected === formBuilderItemKey(id)) {
      this.selected = formBuilderItemKey(next.id);
    }
    this.update({ questions: next.questions });
  }

  /** The selected ordered item, after which new items go. */
  private selectedItemId(): string | undefined {
    const entry = this.entry(this.selected);
    return entry && entry.kind !== "hidden" && entry.kind !== "column"
      ? entry.id
      : undefined;
  }

  private added(id: string): void {
    this.selected = formBuilderItemKey(id);
    const entry = this.entry(this.selected);
    this.say(this.label("builderAdded", { label: entry?.name ?? id }));
    if (this.compact) {
      this.tab = "properties";
    }
    this.emit();
  }

  /** Ask a column, after the selected item (else at the end). */
  ask(columnId: string): void {
    const items = toggleFormQuestion(
      this.items(),
      columnId,
      true,
      this.selectedItemId()
    );
    const question = items.find(
      (item) => isFormQuestion(item) && item.columnId === columnId
    );
    this.setItems(items);
    if (question) {
      this.added(question.id);
    }
  }

  addSection(): void {
    const next = addFormSection(this.items(), this.selectedItemId());
    this.setItems(next.questions);
    this.added(next.id);
  }

  addConsent(): void {
    const next = addFormConsent(this.items(), this.selectedItemId());
    this.setItems(next.questions);
    this.added(next.id);
  }

  addHiddenField(): void {
    const next = addFormHiddenField(this.items());
    this.update({ questions: next.questions });
    this.added(next.id);
  }

  /**
   * Remove a question (its column is then not asked), a section, a consent or
   * a hidden field, and the rules left without a target. A question's column
   * gets selected, so it can be asked again.
   */
  remove(id: string): void {
    const key = formBuilderItemKey(id);
    const entry = this.entry(key);
    if (!entry) {
      return;
    }
    const outline = this.outline();
    const group = entry.kind === "hidden" ? outline.hidden : outline.ordered;
    const next = neighbour(
      group.map((item) => item.key),
      key
    );
    const form = this.form();
    this.update(removeFormItem({ ...form, questions: this.items(form) }, id));
    this.selected =
      entry.kind === "question"
        ? formBuilderColumnKey(entry.column.id)
        : (next ?? FORM_BUILDER_FORM);
    this.say(this.label("builderRemoved", { label: entry.name }));
    this.emit();
  }

  private moved(id: string): void {
    const key = formBuilderItemKey(id);
    const { ordered } = this.outline();
    const entry = ordered.find((item) => item.key === key);
    if (entry) {
      this.say(
        this.label("builderMoved", {
          label: entry.name,
          position: entry.index + 1,
          count: ordered.length,
        })
      );
    }
  }

  /** Move an item one place (Alt + ↑ / ↓, or "Move up"); the entry keeps the focus. */
  move(id: string, offset: -1 | 1): void {
    const items = this.items();
    const next = moveFormQuestion(items, id, offset);
    if (sameFormSettings({ questions: items }, { questions: next })) {
      return;
    }
    this.setItems(next);
    this.moved(id);
    this.focusCount += 1;
    this.focus = { key: formBuilderItemKey(id), count: this.focusCount };
    this.emit();
  }

  /** Move an item to `index` among the ordered items. */
  moveTo(id: string, index: number): void {
    this.setItems(moveFormItemTo(this.items(), id, index));
    this.moved(id);
    this.emit();
  }

  // Dragging ----------------------------------------------------------

  startDrag(key: string): void {
    const entry = this.outline().ordered.find((item) => item.key === key);
    if (entry) {
      this.drag = { key, from: entry.index, to: entry.index };
      this.emit();
    }
  }

  /** The place the dragged item would drop at, among the ordered items. */
  dragTo(index: number): void {
    const drag = this.drag;
    if (!drag) {
      return;
    }
    const last = Math.max(0, this.outline().ordered.length - 1);
    const to = Math.max(0, Math.min(Math.trunc(index), last));
    if (to !== drag.to) {
      this.drag = { ...drag, to };
      this.emit();
    }
  }

  /** Drop the dragged item where it is (`drop`), or cancel the drag. */
  endDrag(drop: boolean): void {
    const drag = this.drag;
    this.drag = undefined;
    const entry = drag && this.entry(drag.key);
    if (drop && drag && entry && drag.to !== drag.from) {
      this.moveTo(entry.id, drag.to);
      return;
    }
    this.emit();
  }

  // Rules -------------------------------------------------------------

  addRule(questionId: string): void {
    const rules = this.form().rules ?? [];
    this.update({
      rules: upsertFormRule(rules, createFormRule(rules, questionId)),
    });
  }

  changeRule(rule: FormRule): void {
    this.update({ rules: upsertFormRule(this.form().rules, rule) });
  }

  removeRule(ruleId: string): void {
    this.update({ rules: removeFormRule(this.form().rules, ruleId) });
  }

  // Fixed values ------------------------------------------------------

  /** The value saved with every response for a column not asked (`undefined`: none). */
  setFixedValue(columnId: string, value: FormHiddenValue | undefined): void {
    const next = { ...this.form().hiddenValues };
    if (value === undefined) {
      Reflect.deleteProperty(next, columnId);
    } else {
      next[columnId] = value;
    }
    this.update({ hiddenValues: next });
  }

  /** Back to the table's form settings (the view keeps none once saved). */
  reset(): void {
    this.draft = {};
    this.justSaved = false;
    if (!this.entry(this.selected)) {
      this.selected = this.firstKey();
    }
    this.emit();
  }

  // Saving and closing ------------------------------------------------

  /** Save the draft in the view; the builder stays open. */
  save(): void {
    const settings = normalizeFormViewConfig(this.draft);
    this.options.onSave(settings);
    this.savedSettings = settings ?? {};
    this.justSaved = true;
    this.say(this.label("builderSaved"));
    this.emit();
  }

  /** Close, or ask first when the draft has unsaved changes. */
  requestClose(): void {
    if (sameFormSettings(this.savedSettings, this.draft)) {
      this.options.onClose();
      return;
    }
    this.confirming = true;
    this.emit();
  }

  keepEditing(): void {
    this.confirming = false;
    this.emit();
  }

  discard(): void {
    this.confirming = false;
    this.emit();
    this.options.onClose();
  }

  saveAndClose(): void {
    this.confirming = false;
    this.save();
    this.options.onClose();
  }
}

// Summary -------------------------------------------------------------------

/** What the View settings say about a view's form, above "Edit form". */
export interface FormBuilderSummary {
  title?: string;
  questions: number;
  sections: number;
  consents: number;
  hiddenFields: number;
  layout: FormLayout;
  review: boolean;
  languages: string[];
}

export function formBuilderSummary(
  columns: readonly FormColumn[],
  defaults: unknown,
  view: unknown,
  locale: string
): FormBuilderSummary {
  const form = mergeFormSettings(defaults, view);
  const items = formQuestionList(columns, form);
  const fallback = formLanguage(locale) || "en";
  const defaultLocale = formDefaultLocale(form) ?? fallback;
  return {
    title: resolveFormText(form.title, locale, defaultLocale),
    questions: items.filter(isFormQuestion).length,
    sections: items.filter(isFormSection).length,
    consents: items.filter(isFormConsent).length,
    hiddenFields: items.filter(isFormHiddenField).length,
    layout: form.layout ?? "page",
    review: form.layout === "steps" && form.review === true,
    languages: formLocales(form, fallback),
  };
}

/** The summary's lines: counts, layout and languages, in the table's language. */
export function formBuilderSummaryLines(
  summary: FormBuilderSummary,
  locale: string,
  translate?: FormTranslate
): string[] {
  const label = (key: FormLabelKey, params?: LabelParams) =>
    formLabel(key, locale, translate, params);
  const counts: [FormLabelKey, number][] = [
    ["summarySections", summary.sections],
    ["summaryConsents", summary.consents],
    ["summaryHiddenFields", summary.hiddenFields],
  ];
  const items = [
    label("summaryQuestions", { count: summary.questions }),
    ...counts.flatMap(([key, count]) => (count ? [label(key, { count })] : [])),
  ];
  const layout =
    summary.layout === "steps"
      ? [label("layoutSteps"), summary.review ? label("summaryReview") : ""]
          .filter(Boolean)
          .join(", ")
      : label("layoutPage");
  return [
    items.join(" · "),
    layout,
    summary.languages.map((language) => formLanguageName(language)).join(", "),
  ];
}

// Dragging in the outline ---------------------------------------------------

const ROW = "[data-form-builder-row]";
const GRIP = "[data-form-builder-grip]";
const SCROLLER = "[data-form-builder-scroll]";
/** Distance from the outline's edges where dragging scrolls it. */
const EDGE = 32;
const EDGE_STEP = 8;

/** Rows above `y` (the dragged one aside): where the dragged row would drop. */
function dropIndex(list: HTMLElement, key: string, y: number): number {
  let index = 0;
  for (const row of list.querySelectorAll<HTMLElement>(ROW)) {
    if (row.dataset.key !== key) {
      const rect = row.getBoundingClientRect();
      if (y > rect.top + rect.height / 2) {
        index += 1;
      }
    }
  }
  return index;
}

function scrollNear(scroller: HTMLElement | null, y: number): void {
  if (!scroller) {
    return;
  }
  const rect = scroller.getBoundingClientRect();
  if (y < rect.top + EDGE) {
    scroller.scrollTop -= EDGE_STEP;
  } else if (y > rect.bottom - EDGE) {
    scroller.scrollTop += EDGE_STEP;
  }
}

/**
 * Reorder the outline's items by dragging their grip (mouse, pen or touch):
 * moving shows where the item would drop, releasing drops it, Escape
 * cancels. Keyboard users move items with Alt + ↑ / ↓. Returns a cleanup.
 */
export function attachFormOutlineDrag(
  list: HTMLElement,
  controller: Pick<FormBuilderController, "dragTo" | "endDrag" | "startDrag">
): () => void {
  let active: { grip: HTMLElement; key: string; pointerId: number } | undefined;

  const onMove = (event: PointerEvent) => {
    if (active && event.pointerId === active.pointerId) {
      scrollNear(list.closest<HTMLElement>(SCROLLER), event.clientY);
      controller.dragTo(dropIndex(list, active.key, event.clientY));
    }
  };
  const finish = (drop: boolean) => {
    const current = active;
    if (!current) {
      return;
    }
    active = undefined;
    current.grip.removeEventListener("pointermove", onMove);
    current.grip.removeEventListener("pointerup", onUp);
    current.grip.removeEventListener("pointercancel", onCancel);
    window.removeEventListener("keydown", onKey, true);
    if (current.grip.hasPointerCapture?.(current.pointerId)) {
      current.grip.releasePointerCapture(current.pointerId);
    }
    controller.endDrag(drop);
  };
  const onUp = (event: PointerEvent) => {
    if (event.pointerId === active?.pointerId) {
      finish(true);
    }
  };
  const onCancel = () => finish(false);
  const onKey = (event: KeyboardEvent) => {
    if (event.key === "Escape" && active) {
      event.preventDefault();
      event.stopPropagation();
      finish(false);
    }
  };
  const onDown = (event: PointerEvent) => {
    const grip = (event.target as Element | null)?.closest<HTMLElement>(GRIP);
    const key = grip?.closest<HTMLElement>(ROW)?.dataset.key;
    if (!(grip && key && event.button === 0 && list.contains(grip))) {
      return;
    }
    event.preventDefault();
    finish(false);
    active = { grip, key, pointerId: event.pointerId };
    grip.setPointerCapture?.(event.pointerId);
    grip.addEventListener("pointermove", onMove);
    grip.addEventListener("pointerup", onUp);
    grip.addEventListener("pointercancel", onCancel);
    window.addEventListener("keydown", onKey, true);
    controller.startDrag(key);
  };
  list.addEventListener("pointerdown", onDown);
  return () => {
    finish(false);
    list.removeEventListener("pointerdown", onDown);
  };
}

/**
 * Conditions engine shared by every form of the React and Vue editions (Form
 * view, record create/edit forms and bulk edit). Rules show, hide, require or
 * set questions when their conditions match the current answers. It is pure
 * and has no UI dependency, so hosts can run it on their server too.
 *
 * ```ts
 * const rules: FormRule[] = [{
 *   id: "hardware",
 *   when: { join: "and", items: [{ fieldId: "category", operator: "is", value: "Hardware" }] },
 *   then: { action: "show", questionIds: ["serial"] },
 * }];
 * evaluateForm(rules, { category: "Hardware" }, fields).visible.has("serial"); // true
 * ```
 */

/** The value family a condition compares, derived from a column or field type. */
export type ConditionFieldType =
  | "checkbox"
  | "date"
  | "multiSelect"
  | "number"
  | "select"
  | "text";

export type ConditionOperator =
  // text
  | "is"
  | "isNot"
  | "contains"
  | "notContains"
  | "startsWith"
  // number
  | "eq"
  | "neq"
  | "lt"
  | "lte"
  | "gt"
  | "gte"
  // number and date
  | "between"
  // date
  | "on"
  | "before"
  | "after"
  | "inLast"
  | "inNext"
  // select
  | "isAnyOf"
  | "isNoneOf"
  // multi-select
  | "containsAny"
  | "containsAll"
  | "containsNone"
  // checkbox
  | "isChecked"
  | "isUnchecked"
  // every type but checkbox
  | "isEmpty"
  | "isNotEmpty";

export type ConditionScalar = boolean | number | string;
/** A scalar, a list, or `[from, to]` (an open end is `null`). */
export type ConditionValue =
  | ConditionScalar
  | (ConditionScalar | null)[]
  | null;

/** One comparison: the answer of `fieldId` against `value`. */
export interface Condition {
  fieldId: string;
  operator: ConditionOperator;
  /** A scalar, `[from, to]` for `between`, a list for `isAnyOf`…, days for `inLast`/`inNext`. */
  value?: ConditionValue;
}

/**
 * A code-only condition (not serializable): the legacy `hidden` predicate of
 * record form fields is converted to one when a form loads. It reads the
 * answers as given (hidden ones included), as the predicate always did.
 */
export interface CustomCondition {
  fieldId?: string;
  operator: "custom";
  test: (values: Record<string, unknown>, context?: unknown) => boolean;
}

export type ConditionItem = Condition | ConditionGroup | CustomCondition;

/** Conditions joined by AND or OR; items may be nested groups. */
export interface ConditionGroup {
  join: "and" | "or";
  items: ConditionItem[];
}

export type FormRuleAction = "hide" | "require" | "set" | "show";

export interface FormRuleEffect {
  action: FormRuleAction;
  /** Form view questions (or sections) the rule acts on. */
  questionIds?: string[];
  /** Record form fields the rule acts on. */
  fieldIds?: string[];
  /** The value written by `set`. */
  value?: ConditionValue;
}

export interface FormRule {
  id: string;
  when: ConditionGroup;
  then: FormRuleEffect;
}

/** What the engine needs to know about a question or field. */
export interface ConditionField {
  id: string;
  type: ConditionFieldType;
  label?: string;
  options?: readonly { value: unknown; label: string }[];
  /** Required without any rule. */
  required?: boolean;
}

export interface FormEvaluation {
  visible: Set<string>;
  hidden: Set<string>;
  /** Visible and required, by the field itself or a matching `require` rule. */
  required: Set<string>;
  /** Values written by matching `set` rules, for visible targets. */
  setValues: Record<string, unknown>;
  /** Rule ids whose conditions match. */
  matched: Set<string>;
}

export interface EvaluateOptions {
  /** "Today" for relative dates (defaults to now). */
  now?: Date;
  /** Fields whose value differs across a bulk selection: conditions on them never match. */
  mixed?: Iterable<string>;
  /** Children hidden with their parent, e.g. the questions of a section. */
  groups?: Record<string, readonly string[]>;
  /** Passed to custom conditions. */
  context?: unknown;
}

type ValueKind = "days" | "list" | "none" | "range" | "single";

export const CONDITION_OPERATORS: Record<
  ConditionFieldType,
  readonly ConditionOperator[]
> = {
  text: [
    "is",
    "isNot",
    "contains",
    "notContains",
    "startsWith",
    "isEmpty",
    "isNotEmpty",
  ],
  number: [
    "eq",
    "neq",
    "lt",
    "lte",
    "gt",
    "gte",
    "between",
    "isEmpty",
    "isNotEmpty",
  ],
  date: [
    "on",
    "before",
    "after",
    "between",
    "inLast",
    "inNext",
    "isEmpty",
    "isNotEmpty",
  ],
  select: ["is", "isNot", "isAnyOf", "isNoneOf", "isEmpty", "isNotEmpty"],
  multiSelect: [
    "containsAny",
    "containsAll",
    "containsNone",
    "isEmpty",
    "isNotEmpty",
  ],
  checkbox: ["isChecked", "isUnchecked"],
};

const NO_VALUE = new Set<ConditionOperator>([
  "isEmpty",
  "isNotEmpty",
  "isChecked",
  "isUnchecked",
]);
const LIST_VALUE = new Set<ConditionOperator>([
  "isAnyOf",
  "isNoneOf",
  "containsAny",
  "containsAll",
  "containsNone",
]);
const ACTIONS = new Set<FormRuleAction>(["hide", "require", "set", "show"]);
const ALL_OPERATORS = new Set<string>(
  Object.values(CONDITION_OPERATORS).flat()
);
const DAY_MS = 86_400_000;
const DATE_PREFIX = /^(\d{4})-(\d{2})-(\d{2})/;

/** The kind of value an operator takes: none, one, `[from, to]`, a list or a number of days. */
export function operatorValueKind(operator: ConditionOperator): ValueKind {
  if (NO_VALUE.has(operator)) {
    return "none";
  }
  if (LIST_VALUE.has(operator)) {
    return "list";
  }
  if (operator === "between") {
    return "range";
  }
  return operator === "inLast" || operator === "inNext" ? "days" : "single";
}

/** The condition type of a column, question editor or record form field type. */
export function conditionFieldType(
  type: string | undefined
): ConditionFieldType {
  switch (type) {
    case "number":
    case "currency":
    case "percent":
      return "number";
    case "date":
    case "datetime":
      return "date";
    case "select":
    case "radio":
    case "select-with-add-new":
    case "tag":
      return "select";
    case "multiSelect":
    case "tags":
      return "multiSelect";
    case "boolean":
    case "checkbox":
    case "switch":
      return "checkbox";
    default:
      return "text";
  }
}

// Values -----------------------------------------------------------------

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === "object" && !Array.isArray(value);

export const isConditionGroup = (item: unknown): item is ConditionGroup =>
  isRecord(item) && Array.isArray(item.items);

export const isCustomCondition = (item: unknown): item is CustomCondition =>
  isRecord(item) &&
  item.operator === "custom" &&
  typeof item.test === "function";

function isEmptyValue(value: unknown): boolean {
  if (value === undefined || value === null) {
    return true;
  }
  if (Array.isArray(value)) {
    return value.length === 0;
  }
  return typeof value === "string" && value.trim() === "";
}

const toText = (value: unknown): string =>
  isEmptyValue(value) ? "" : String(value).trim().toLocaleLowerCase();

function toNumber(value: unknown): number {
  if (typeof value === "number") {
    return value;
  }
  if (typeof value !== "string" || value.trim() === "") {
    return Number.NaN;
  }
  return Number(value.trim().replace(",", "."));
}

/** A day number (days since 1970-01-01) for `YYYY-MM-DD…` strings and dates. */
function toDay(value: unknown): number {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime())
      ? Number.NaN
      : Date.UTC(value.getFullYear(), value.getMonth(), value.getDate()) /
          DAY_MS;
  }
  const match = typeof value === "string" ? DATE_PREFIX.exec(value) : null;
  if (!match) {
    return Number.NaN;
  }
  return (
    Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3])) / DAY_MS
  );
}

const toList = (value: unknown): string[] => {
  if (Array.isArray(value)) {
    return value.filter((item) => !isEmptyValue(item)).map(String);
  }
  return isEmptyValue(value) ? [] : [String(value)];
};

const pair = (value: unknown): [unknown, unknown] =>
  Array.isArray(value) ? [value[0], value[1]] : [undefined, undefined];

const isChecked = (value: unknown): boolean =>
  value === true || value === "true";

// Comparisons --------------------------------------------------------------

function compareText(
  operator: ConditionOperator,
  actual: unknown,
  expected: unknown
): boolean {
  const left = toText(actual);
  const right = toText(expected);
  switch (operator) {
    case "is":
      return left === right;
    case "isNot":
      return left !== right;
    case "contains":
      return right !== "" && left.includes(right);
    case "notContains":
      return right === "" || !left.includes(right);
    case "startsWith":
      return right !== "" && left.startsWith(right);
    default:
      return false;
  }
}

function inRange(value: number, [from, to]: [number, number]): boolean {
  const low = Number.isNaN(from) ? Number.NEGATIVE_INFINITY : from;
  const high = Number.isNaN(to) ? Number.POSITIVE_INFINITY : to;
  return !Number.isNaN(value) && value >= low && value <= high;
}

function compareOrdered(
  operator: ConditionOperator,
  left: number,
  right: number
): boolean {
  if (Number.isNaN(left) || Number.isNaN(right)) {
    return operator === "neq" && !Number.isNaN(right);
  }
  switch (operator) {
    case "eq":
    case "on":
      return left === right;
    case "neq":
      return left !== right;
    case "lt":
    case "before":
      return left < right;
    case "lte":
      return left <= right;
    case "gt":
    case "after":
      return left > right;
    case "gte":
      return left >= right;
    default:
      return false;
  }
}

function compareNumber(
  operator: ConditionOperator,
  actual: unknown,
  expected: unknown
): boolean {
  const value = toNumber(actual);
  if (operator === "between") {
    const [from, to] = pair(expected);
    return inRange(value, [toNumber(from), toNumber(to)]);
  }
  return compareOrdered(operator, value, toNumber(expected));
}

function compareDate(
  operator: ConditionOperator,
  actual: unknown,
  expected: unknown,
  now: Date
): boolean {
  const day = toDay(actual);
  if (operator === "between") {
    const [from, to] = pair(expected);
    return inRange(day, [toDay(from), toDay(to)]);
  }
  if (operator === "inLast" || operator === "inNext") {
    const today = toDay(now);
    const days = Math.max(0, toNumber(expected));
    if (Number.isNaN(days)) {
      return false;
    }
    return operator === "inLast"
      ? inRange(day, [today - days, today])
      : inRange(day, [today, today + days]);
  }
  return compareOrdered(operator, day, toDay(expected));
}

function compareSelect(
  operator: ConditionOperator,
  actual: unknown,
  expected: unknown
): boolean {
  const value = isEmptyValue(actual) ? undefined : String(actual);
  switch (operator) {
    case "is":
      return value !== undefined && value === String(expected);
    case "isNot":
      return value !== String(expected);
    case "isAnyOf":
      return value !== undefined && toList(expected).includes(value);
    case "isNoneOf":
      return value === undefined || !toList(expected).includes(value);
    default:
      return false;
  }
}

function compareMulti(
  operator: ConditionOperator,
  actual: unknown,
  expected: unknown
): boolean {
  const values = toList(actual);
  const wanted = toList(expected);
  switch (operator) {
    case "containsAny":
      return wanted.some((item) => values.includes(item));
    case "containsAll":
      return wanted.length > 0 && wanted.every((item) => values.includes(item));
    case "containsNone":
      return !wanted.some((item) => values.includes(item));
    default:
      return false;
  }
}

/** Whether one answer satisfies a condition, for a field of the given type. */
export function matchCondition(
  type: ConditionFieldType,
  condition: Pick<Condition, "operator" | "value">,
  actual: unknown,
  now: Date = new Date()
): boolean {
  const { operator, value } = condition;
  if (operator === "isEmpty") {
    return isEmptyValue(actual);
  }
  if (operator === "isNotEmpty") {
    return !isEmptyValue(actual);
  }
  switch (type) {
    case "checkbox":
      return operator === "isChecked" ? isChecked(actual) : !isChecked(actual);
    case "number":
      return compareNumber(operator, actual, value);
    case "date":
      return compareDate(operator, actual, value, now);
    case "select":
      return compareSelect(operator, actual, value);
    case "multiSelect":
      return compareMulti(operator, actual, value);
    default:
      return compareText(operator, actual, value);
  }
}

// Evaluation ---------------------------------------------------------------

interface MatchScope {
  types: Map<string, ConditionFieldType>;
  values: Record<string, unknown>;
  /** The answers as given: custom (legacy) conditions read them unchanged. */
  input: Record<string, unknown>;
  mixed: Set<string>;
  now: Date;
  context: unknown;
}

function matchItem(item: ConditionItem, scope: MatchScope): boolean {
  if (isConditionGroup(item)) {
    return matchGroup(item, scope);
  }
  if (isCustomCondition(item)) {
    return item.test(scope.input, scope.context);
  }
  const type = scope.types.get(item.fieldId);
  if (!type || scope.mixed.has(item.fieldId)) {
    return false;
  }
  return matchCondition(type, item, scope.values[item.fieldId], scope.now);
}

/** An empty group matches nothing, so an unfinished rule never acts. */
function matchGroup(group: ConditionGroup, scope: MatchScope): boolean {
  if (group.items.length === 0) {
    return false;
  }
  return group.join === "or"
    ? group.items.some((item) => matchItem(item, scope))
    : group.items.every((item) => matchItem(item, scope));
}

/** Question or field ids a rule acts on. */
export const ruleTargets = (rule: Pick<FormRule, "then">): string[] => [
  ...(rule.then.questionIds ?? []),
  ...(rule.then.fieldIds ?? []),
];

/** Field ids a condition group reads (custom conditions read none). */
export function conditionFieldIds(group: ConditionGroup): string[] {
  const ids: string[] = [];
  const walk = (item: ConditionItem) => {
    if (isConditionGroup(item)) {
      for (const child of item.items) {
        walk(child);
      }
    } else if (!isCustomCondition(item) && item.fieldId) {
      ids.push(item.fieldId);
    }
  };
  walk(group);
  return [...new Set(ids)];
}

function hiddenTargets(
  rules: readonly FormRule[],
  matched: Set<string>
): Set<string> {
  const showable = new Set<string>();
  const shown = new Set<string>();
  const hidden = new Set<string>();
  for (const rule of rules) {
    const hit = matched.has(rule.id);
    for (const target of ruleTargets(rule)) {
      if (rule.then.action === "show") {
        showable.add(target);
        if (hit) {
          shown.add(target);
        }
      } else if (rule.then.action === "hide" && hit) {
        hidden.add(target);
      }
    }
  }
  for (const target of showable) {
    if (!shown.has(target)) {
      hidden.add(target);
    }
  }
  return hidden;
}

function withGroups(
  hidden: Set<string>,
  groups: Record<string, readonly string[]> | undefined
): Set<string> {
  for (const [parent, children] of Object.entries(groups ?? {})) {
    if (hidden.has(parent)) {
      for (const child of children) {
        hidden.add(child);
      }
    }
  }
  return hidden;
}

function setValuesOf(
  rules: readonly FormRule[],
  matched: Set<string>,
  hidden: Set<string>
): Record<string, unknown> {
  const values: Record<string, unknown> = {};
  for (const rule of rules) {
    if (rule.then.action !== "set" || !matched.has(rule.id)) {
      continue;
    }
    for (const target of ruleTargets(rule)) {
      if (!hidden.has(target)) {
        values[target] = rule.then.value ?? null;
      }
    }
  }
  return values;
}

const sameSet = (left: Set<string>, right: Set<string>) =>
  left.size === right.size && [...left].every((item) => right.has(item));

/** Answers as rules read them: set values applied, hidden answers cleared. */
function effectiveValues(
  values: Record<string, unknown>,
  setValues: Record<string, unknown>,
  hidden: Set<string>
): Record<string, unknown> {
  const effective = { ...values, ...setValues };
  for (const id of hidden) {
    effective[id] = undefined;
  }
  return effective;
}

function requiredIds(
  rules: readonly FormRule[],
  fields: readonly ConditionField[],
  matched: Set<string>,
  visible: Set<string>
): Set<string> {
  const required = new Set(
    fields.filter((field) => field.required).map((field) => field.id)
  );
  for (const rule of rules) {
    if (rule.then.action === "require" && matched.has(rule.id)) {
      for (const target of ruleTargets(rule)) {
        required.add(target);
      }
    }
  }
  return new Set([...required].filter((id) => visible.has(id)));
}

/**
 * Which questions are visible and required, and the values `set` rules write.
 * Hidden answers never satisfy another condition, so chains (A shows B, B
 * shows C) settle; the loop is bounded so malformed cycles cannot hang.
 */
export function evaluateForm(
  rules: readonly FormRule[],
  values: Record<string, unknown>,
  fields: readonly ConditionField[],
  options: EvaluateOptions = {}
): FormEvaluation {
  const scope: MatchScope = {
    types: new Map(fields.map((field) => [field.id, field.type])),
    values,
    input: values,
    mixed: new Set(options.mixed ?? []),
    now: options.now ?? new Date(),
    context: options.context,
  };
  let hidden = new Set<string>();
  let setValues: Record<string, unknown> = {};
  let matched = new Set<string>();
  const limit = fields.length + rules.length + 2;
  for (let round = 0; round < limit; round += 1) {
    scope.values = effectiveValues(values, setValues, hidden);
    matched = new Set(
      rules
        .filter((rule) => matchGroup(rule.when, scope))
        .map((rule) => rule.id)
    );
    const nextHidden = withGroups(
      hiddenTargets(rules, matched),
      options.groups
    );
    const nextSet = setValuesOf(rules, matched, nextHidden);
    const stable =
      sameSet(hidden, nextHidden) &&
      JSON.stringify(setValues) === JSON.stringify(nextSet);
    hidden = nextHidden;
    setValues = nextSet;
    if (stable) {
      break;
    }
  }
  const ids = new Set([
    ...fields.map((field) => field.id),
    ...rules.flatMap(ruleTargets),
    ...Object.values(options.groups ?? {}).flat(),
  ]);
  const visible = new Set([...ids].filter((id) => !hidden.has(id)));
  return {
    visible,
    hidden,
    required: requiredIds(rules, fields, matched, visible),
    setValues,
    matched,
  };
}

/** Answers to submit: hidden ones removed, `set` values applied. */
export function applyFormEvaluation(
  values: Record<string, unknown>,
  evaluation: Pick<FormEvaluation, "hidden" | "setValues">
): Record<string, unknown> {
  const output: Record<string, unknown> = {
    ...values,
    ...evaluation.setValues,
  };
  for (const id of evaluation.hidden) {
    Reflect.deleteProperty(output, id);
  }
  return output;
}

/** Fields whose rules read one of `ids` (e.g. the mixed values of a bulk selection). */
export function rulesReading(
  rules: readonly FormRule[],
  target: string,
  ids: Iterable<string>
): string[] {
  const wanted = new Set(ids);
  return [
    ...new Set(
      rules
        .filter((rule) => ruleTargets(rule).includes(target))
        .flatMap((rule) => conditionFieldIds(rule.when))
        .filter((id) => wanted.has(id))
    ),
  ];
}

// Structure and validation -------------------------------------------------

const isScalar = (value: unknown): value is ConditionScalar =>
  typeof value === "string" ||
  typeof value === "boolean" ||
  (typeof value === "number" && Number.isFinite(value));

function sanitizeValue(value: unknown): ConditionValue | undefined {
  if (value === null || isScalar(value)) {
    return value;
  }
  if (Array.isArray(value)) {
    return value.filter((item) => item === null || isScalar(item));
  }
}

const idList = (value: unknown): string[] | undefined =>
  Array.isArray(value)
    ? [
        ...new Set(
          value.filter(
            (item): item is string =>
              typeof item === "string" && item.trim() !== ""
          )
        ),
      ]
    : undefined;

function sanitizeCondition(
  value: Record<string, unknown>
): Condition | undefined {
  if (
    typeof value.operator !== "string" ||
    !ALL_OPERATORS.has(value.operator)
  ) {
    return;
  }
  const condition: Condition = {
    fieldId: typeof value.fieldId === "string" ? value.fieldId : "",
    operator: value.operator as ConditionOperator,
  };
  const sanitized = sanitizeValue(value.value);
  if (sanitized !== undefined) {
    condition.value = sanitized;
  }
  return condition;
}

function sanitizeGroup(
  value: unknown,
  depth: number
): ConditionGroup | undefined {
  if (!isConditionGroup(value) || depth > 8) {
    return;
  }
  const items = (value.items as unknown[]).flatMap((item) => {
    if (!isRecord(item)) {
      return [];
    }
    const child = isConditionGroup(item)
      ? sanitizeGroup(item, depth + 1)
      : sanitizeCondition(item);
    return child ? [child] : [];
  });
  return { join: value.join === "or" ? "or" : "and", items };
}

function sanitizeEffect(value: unknown): FormRuleEffect | undefined {
  if (!(isRecord(value) && ACTIONS.has(value.action as FormRuleAction))) {
    return;
  }
  const effect: FormRuleEffect = { action: value.action as FormRuleAction };
  const questionIds = idList(value.questionIds);
  const fieldIds = idList(value.fieldIds);
  if (questionIds) {
    effect.questionIds = questionIds;
  }
  if (fieldIds) {
    effect.fieldIds = fieldIds;
  }
  const setValue = sanitizeValue(value.value);
  if (effect.action === "set" && setValue !== undefined) {
    effect.value = setValue;
  }
  return effect;
}

function sanitizeRule(
  item: unknown,
  index: number,
  ids: Set<string>
): FormRule | undefined {
  if (!isRecord(item)) {
    return;
  }
  const when = sanitizeGroup(item.when, 0);
  const then = sanitizeEffect(item.then);
  if (!(when && then)) {
    return;
  }
  let id =
    typeof item.id === "string" && item.id.trim()
      ? item.id.trim()
      : `rule-${index + 1}`;
  while (ids.has(id)) {
    id = `${id}-${index + 1}`;
  }
  ids.add(id);
  return { id, when, then };
}

/**
 * Keep the structure of saved rules (JSON-safe, unique ids), even unfinished
 * ones a settings editor is still building. `normalizeRules` decides which
 * rules can act.
 */
export function sanitizeRules(value: unknown): FormRule[] {
  if (!Array.isArray(value)) {
    return [];
  }
  const ids = new Set<string>();
  return value.flatMap((item, index) => {
    const rule = sanitizeRule(item, index, ids);
    return rule ? [rule] : [];
  });
}

export type RuleIssueCode =
  | "cycle"
  | "emptyGroup"
  | "laterQuestion"
  | "missingField"
  | "missingValue"
  | "noTargets"
  | "operator"
  | "selfReference"
  | "unknownField"
  | "unknownOption"
  | "unknownTarget";

export interface RuleIssue {
  ruleId: string;
  code: RuleIssueCode;
  /** Indexes from the rule's group down to the condition, e.g. `[1, 0]`. */
  path?: number[];
  fieldId?: string;
}

export interface ValidateRulesOptions {
  /** Ids a rule may act on besides fields, e.g. Form view sections. */
  targets?: readonly string[];
  /** Question order; with `layout: "steps"`, `require` and `set` may not read a later question. */
  order?: readonly string[];
  layout?: "page" | "steps";
}

function valueIssue(
  field: ConditionField,
  condition: Condition
): RuleIssueCode | undefined {
  const kind = operatorValueKind(condition.operator);
  const { value } = condition;
  if (kind === "none") {
    return;
  }
  if (kind === "range") {
    const [from, to] = pair(value);
    return isEmptyValue(from) && isEmptyValue(to) ? "missingValue" : undefined;
  }
  if (kind === "list") {
    return toList(value).length
      ? optionIssue(field, toList(value))
      : "missingValue";
  }
  if (isEmptyValue(value)) {
    return "missingValue";
  }
  return field.type === "select"
    ? optionIssue(field, [String(value)])
    : undefined;
}

function optionIssue(
  field: ConditionField,
  values: string[]
): RuleIssueCode | undefined {
  if (!field.options?.length) {
    return;
  }
  const known = new Set(field.options.map((option) => String(option.value)));
  return values.every((value) => known.has(value))
    ? undefined
    : "unknownOption";
}

function conditionIssue(
  condition: Condition,
  fields: Map<string, ConditionField>
): RuleIssueCode | undefined {
  if (!condition.fieldId) {
    return "missingField";
  }
  const field = fields.get(condition.fieldId);
  if (!field) {
    return "unknownField";
  }
  if (!CONDITION_OPERATORS[field.type].includes(condition.operator)) {
    return "operator";
  }
  return valueIssue(field, condition);
}

function groupIssues(
  group: ConditionGroup,
  fields: Map<string, ConditionField>,
  path: number[]
): Omit<RuleIssue, "ruleId">[] {
  if (group.items.length === 0) {
    return [{ code: "emptyGroup", path }];
  }
  return group.items.flatMap((item, index) => {
    const at = [...path, index];
    if (isConditionGroup(item)) {
      return groupIssues(item, fields, at);
    }
    if (isCustomCondition(item)) {
      return [];
    }
    const code = conditionIssue(item, fields);
    return code ? [{ code, path: at, fieldId: item.fieldId }] : [];
  });
}

function targetIssues(
  rule: FormRule,
  fields: Map<string, ConditionField>,
  options: ValidateRulesOptions
): RuleIssue[] {
  const targets = ruleTargets(rule);
  if (targets.length === 0) {
    return [{ ruleId: rule.id, code: "noTargets" }];
  }
  const extra = new Set(options.targets ?? []);
  const reads = new Set(conditionFieldIds(rule.when));
  return targets.flatMap((target): RuleIssue[] => {
    if (!(fields.has(target) || extra.has(target))) {
      return [{ ruleId: rule.id, code: "unknownTarget", fieldId: target }];
    }
    return reads.has(target)
      ? [{ ruleId: rule.id, code: "selfReference", fieldId: target }]
      : [];
  });
}

/** In steps, a `require` or `set` rule cannot depend on a later question. */
function orderIssues(
  rule: FormRule,
  options: ValidateRulesOptions
): RuleIssue[] {
  if (
    options.layout !== "steps" ||
    !options.order ||
    rule.then.action === "show" ||
    rule.then.action === "hide"
  ) {
    return [];
  }
  const position = new Map(options.order.map((id, index) => [id, index]));
  const first = Math.min(
    ...ruleTargets(rule).map(
      (id) => position.get(id) ?? Number.POSITIVE_INFINITY
    )
  );
  return conditionFieldIds(rule.when)
    .filter((id) => (position.get(id) ?? -1) > first)
    .map((fieldId) => ({ ruleId: rule.id, code: "laterQuestion", fieldId }));
}

/** Directed edges: a condition field influences each target of its rule. */
function ruleEdges(rules: readonly FormRule[]): Map<string, Set<string>> {
  const edges = new Map<string, Set<string>>();
  for (const rule of rules) {
    for (const from of conditionFieldIds(rule.when)) {
      const next = edges.get(from) ?? new Set<string>();
      for (const target of ruleTargets(rule)) {
        next.add(target);
      }
      edges.set(from, next);
    }
  }
  return edges;
}

function reaches(
  edges: Map<string, Set<string>>,
  from: string,
  to: string
): boolean {
  const seen = new Set<string>();
  const stack = [from];
  while (stack.length) {
    const current = stack.pop() as string;
    if (current === to) {
      return true;
    }
    if (!seen.has(current)) {
      seen.add(current);
      stack.push(...(edges.get(current) ?? []));
    }
  }
  return false;
}

/** Whether a rule closes a loop with the others: a target that reads itself back. */
function closesCycle(rule: FormRule, others: readonly FormRule[]): boolean {
  const edges = ruleEdges(others);
  return ruleTargets(rule).some((target) =>
    conditionFieldIds(rule.when).some(
      (from) => from === target || reaches(edges, target, from)
    )
  );
}

/** Rule ids that close a loop, in rule order (the earlier rules are kept). */
export function detectRuleCycles(rules: readonly FormRule[]): string[] {
  const kept: FormRule[] = [];
  const cyclic: string[] = [];
  for (const rule of rules) {
    if (closesCycle(rule, kept)) {
      cyclic.push(rule.id);
    } else {
      kept.push(rule);
    }
  }
  return cyclic;
}

/** Every problem of a rule set: unknown fields, operator/type mismatches, missing values, cycles. */
export function validateRules(
  rules: readonly FormRule[],
  fields: readonly ConditionField[],
  options: ValidateRulesOptions = {}
): RuleIssue[] {
  const byId = new Map(fields.map((field) => [field.id, field]));
  const issues = rules.flatMap((rule) => [
    ...groupIssues(rule.when, byId, []).map((issue) => ({
      ...issue,
      ruleId: rule.id,
    })),
    ...targetIssues(rule, byId, options),
    ...orderIssues(rule, options),
  ]);
  const cycles = detectRuleCycles(rules).map(
    (ruleId): RuleIssue => ({ ruleId, code: "cycle" })
  );
  return [...issues, ...cycles];
}

export interface DroppedRule {
  id: string;
  reason: RuleIssueCode | "invalid";
}

/**
 * Rules that can act: structurally valid, every condition complete and
 * matching its field's type, known targets and no cycle. Broken rules are
 * dropped with their reason instead of throwing.
 */
export function normalizeRules(
  value: unknown,
  fields: readonly ConditionField[],
  options: ValidateRulesOptions = {}
): { rules: FormRule[]; dropped: DroppedRule[] } {
  const input = Array.isArray(value) ? value : [];
  const dropped: DroppedRule[] = [];
  const ids = new Set<string>();
  const sanitized: FormRule[] = [];
  for (const [index, item] of input.entries()) {
    const rule = sanitizeRule(item, index, ids);
    if (rule) {
      sanitized.push(rule);
    } else {
      const id = isRecord(item) && typeof item.id === "string" ? item.id : "";
      dropped.push({ id: id || `rule-${index + 1}`, reason: "invalid" });
    }
  }
  const issues = validateRules(sanitized, fields, options).filter(
    (issue) => issue.code !== "cycle"
  );
  const broken = new Map(issues.map((issue) => [issue.ruleId, issue.code]));
  const candidates = sanitized.filter((rule) => {
    const reason = broken.get(rule.id);
    if (reason) {
      dropped.push({ id: rule.id, reason });
    }
    return !reason;
  });
  const cyclic = new Set(detectRuleCycles(candidates));
  for (const id of cyclic) {
    dropped.push({ id, reason: "cycle" });
  }
  return {
    rules: candidates.filter((rule) => !cyclic.has(rule.id)),
    dropped,
  };
}

/**
 * A rule from a code predicate: how the legacy `hidden: (context) => boolean`
 * of record form fields joins the engine (`action: "hide"`).
 */
export function predicateRule(
  id: string,
  targetId: string,
  test: CustomCondition["test"],
  action: FormRuleAction = "hide"
): FormRule {
  const when: ConditionGroup = {
    join: "and",
    items: [{ fieldId: targetId, operator: "custom", test }],
  };
  const then: FormRuleEffect = { action, fieldIds: [targetId] };
  return { id, when, then };
}

// Summaries ----------------------------------------------------------------

/** Words of a summary; `form-view.ts` provides English and French. */
export type ConditionWords = (
  key: string,
  params?: Record<string, number | string>
) => string;

function valueText(field: ConditionField | undefined, value: unknown): string {
  const label = (item: unknown) =>
    field?.options?.find((option) => String(option.value) === String(item))
      ?.label ?? String(item);
  if (Array.isArray(value)) {
    return value.map(label).join(", ");
  }
  return isEmptyValue(value) ? "…" : label(value);
}

function describeCondition(
  condition: Condition,
  fields: Map<string, ConditionField>,
  words: ConditionWords
): string {
  const field = fields.get(condition.fieldId);
  const name = field?.label ?? (condition.fieldId || "…");
  const kind = operatorValueKind(condition.operator);
  const [from, to] = pair(condition.value);
  return words(`op.${condition.operator}`, {
    field: name,
    value: kind === "range" ? "" : valueText(field, condition.value),
    from: valueText(field, from),
    to: valueText(field, to),
  });
}

function describeGroup(
  group: ConditionGroup,
  fields: Map<string, ConditionField>,
  words: ConditionWords,
  nested: boolean
): string {
  const parts = group.items.map((item) => {
    if (isConditionGroup(item)) {
      return describeGroup(item, fields, words, true);
    }
    return isCustomCondition(item)
      ? words("custom")
      : describeCondition(item, fields, words);
  });
  const text = parts.join(` ${words(group.join)} `);
  return nested && parts.length > 1 ? `(${text})` : text;
}

/** "Shown when Category is Hardware and Budget > 1000". */
export function describeRule(
  rule: FormRule,
  fields: readonly ConditionField[],
  words: ConditionWords
): string {
  const byId = new Map(fields.map((field) => [field.id, field]));
  const condition = describeGroup(rule.when, byId, words, false);
  const target = byId.get(ruleTargets(rule)[0] ?? "");
  return words(`then.${rule.then.action}`, {
    condition,
    value: valueText(target, rule.then.value),
  });
}

// Editing ------------------------------------------------------------------

/** The first operator of a type: what a new condition on that field starts with. */
export const defaultOperator = (type: ConditionFieldType): ConditionOperator =>
  CONDITION_OPERATORS[type][0] ?? "isNotEmpty";

/** The item at `path` (indexes from the root group). */
export function conditionAt(
  group: ConditionGroup,
  path: readonly number[]
): ConditionItem | undefined {
  let item: ConditionItem | undefined = group;
  for (const index of path) {
    item = isConditionGroup(item) ? item.items[index] : undefined;
  }
  return item;
}

/** Replace (or remove, with `undefined`) the item at `path`; other items are kept. */
export function updateConditionAt(
  group: ConditionGroup,
  path: readonly number[],
  update: (item: ConditionItem) => ConditionItem | undefined
): ConditionGroup {
  const [index, ...rest] = path;
  if (index === undefined) {
    return group;
  }
  const items = group.items.flatMap((item, position) => {
    if (position !== index) {
      return [item];
    }
    const next =
      rest.length && isConditionGroup(item)
        ? updateConditionAt(item, rest, update)
        : update(item);
    return next ? [next] : [];
  });
  return { ...group, items };
}

/**
 * A condition pointed at another field: the operator is kept when that
 * field's type offers it, the value is cleared.
 */
export function retargetCondition(
  condition: Condition,
  field: ConditionField | undefined
): Condition {
  if (!field) {
    return { fieldId: "", operator: condition.operator };
  }
  const operators = CONDITION_OPERATORS[field.type];
  return {
    fieldId: field.id,
    operator: operators.includes(condition.operator)
      ? condition.operator
      : defaultOperator(field.type),
  };
}

/** A condition with another operator; the value is kept while it still fits. */
export function withOperator(
  condition: Condition,
  operator: ConditionOperator
): Condition {
  const same =
    operatorValueKind(operator) === operatorValueKind(condition.operator);
  return same && operatorValueKind(operator) !== "none"
    ? { ...condition, operator }
    : { fieldId: condition.fieldId, operator };
}

/** Framework-neutral layout contracts; each registry ships its own copy. */
export interface FormLayoutRuntime {
  disabled: boolean;
  isSubmitting: boolean;
  isValidating: boolean;
  setFieldValue: (name: string, value: unknown) => void;
  submit: () => Promise<void>;
  validate: () => Promise<boolean>;
}

export interface FormLayoutAction<TContext> {
  id: string;
  label: string;
  labelKey?: string;
  disabled?: boolean | ((context: TContext) => boolean);
  hidden?: boolean | ((context: TContext) => boolean);
  /** Validate the form before running this action, without submitting it. */
  validate?: boolean;
  variant?: "default" | "outline" | "secondary" | "destructive";
  onClick: (context: TContext, signal: AbortSignal) => void | Promise<void>;
}

export type FormBlockSpan = 1 | 2 | 3 | "full";

interface BlockBase {
  id: string;
  span?: FormBlockSpan;
}

export type FormLayoutBlock<TContext, TContent> =
  | {
      type: "field";
      name: string;
      id?: string;
      span?: FormBlockSpan;
    }
  | (BlockBase & {
      type: "section";
      title?: string;
      titleKey?: string;
      description?: string;
      descriptionKey?: string;
      columns?: 1 | 2 | 3;
      blocks: FormLayoutBlock<TContext, TContent>[];
    })
  | (BlockBase & {
      type: "content";
      title?: string;
      titleKey?: string;
      text: string;
      textKey?: string;
      tone?: "default" | "info" | "warning";
    })
  | (BlockBase & {
      type: "actions";
      actions: FormLayoutAction<TContext>[];
    })
  | (BlockBase & {
      type: "custom";
      /** React/Vue render callback. Vue also supports the form-{id} slot. */
      render?: (context: TContext) => TContent;
    });

/** Render each declared field once and retain fields omitted from the layout. */
export function resolveFormBlocks<TContext, TContent>(
  blocks: FormLayoutBlock<TContext, TContent>[],
  fieldNames: readonly string[]
): FormLayoutBlock<TContext, TContent>[] {
  const remaining = new Set(fieldNames);
  const visit = (
    items: FormLayoutBlock<TContext, TContent>[]
  ): FormLayoutBlock<TContext, TContent>[] => {
    const result: FormLayoutBlock<TContext, TContent>[] = [];
    for (const block of items) {
      if (block.type === "field") {
        if (remaining.delete(block.name)) {
          result.push(block);
        }
      } else if (block.type === "section") {
        result.push({ ...block, blocks: visit(block.blocks) });
      } else {
        result.push(block);
      }
    }
    return result;
  };
  return [
    ...visit(blocks),
    ...Array.from(remaining, (name) => ({ type: "field" as const, name })),
  ];
}

export function formBlockId<TContext, TContent>(
  block: FormLayoutBlock<TContext, TContent>
): string {
  return block.type === "field"
    ? (block.id ?? `field-${block.name}`)
    : block.id;
}

export function formBlockSpan(
  span: FormBlockSpan | undefined,
  columns: number
): number | "full" {
  return span === "full" ? "full" : Math.min(span ?? 1, columns);
}

export function formActionFlag<TContext>(
  flag: boolean | ((context: TContext) => boolean) | undefined,
  context: TContext
): boolean {
  return typeof flag === "function" ? flag(context) : flag === true;
}

/** Resolve form-local translations while retaining unresolved provider keys. */
export function translateFormBlocks<TContext, TContent>(
  blocks: FormLayoutBlock<TContext, TContent>[],
  keys: Record<string, string>
): FormLayoutBlock<TContext, TContent>[] {
  const translated = (value: string | undefined, key: string | undefined) => ({
    value: key ? (keys[key] ?? value) : value,
    key: key && keys[key] !== undefined ? undefined : key,
  });
  return blocks.map((block) => {
    if (block.type === "section" || block.type === "content") {
      const title = translated(block.title, block.titleKey);
      if (block.type === "section") {
        const description = translated(block.description, block.descriptionKey);
        return {
          ...block,
          title: title.value,
          titleKey: title.key,
          description: description.value,
          descriptionKey: description.key,
          blocks: translateFormBlocks(block.blocks, keys),
        };
      }
      const text = translated(block.text, block.textKey);
      return {
        ...block,
        title: title.value,
        titleKey: title.key,
        text: text.value ?? block.text,
        textKey: text.key,
      };
    }
    if (block.type === "actions") {
      return {
        ...block,
        actions: block.actions.map((action) => {
          const label = translated(action.label, action.labelKey);
          return {
            ...action,
            label: label.value ?? action.label,
            labelKey: label.key,
          };
        }),
      };
    }
    return block;
  });
}

import { toRaw } from "vue";
import { bulkConditionState } from "./bulk-editor";
import {
  type ConditionField,
  conditionFieldType,
  evaluateForm,
  type FormEvaluation,
  type FormRule,
  normalizeRules,
  predicateRule,
} from "./form-conditions";
import { translateFormBlocks } from "./form-layout";
import {
  dataTypeValueError,
  isJsonFormDraft,
  jsonFormDraft,
  parseJsonFormValue,
} from "./table-contracts";
import type {
  FormConfig,
  FormFieldContext,
  FormFieldDefinition,
  FormRuleSet,
  FormSectionDefinition,
  TableRecord,
} from "./types";

/** Clone editable data without sharing nested values with a row or configuration. */
export const cloneFormValue = <T>(value: T): T => {
  if (isJsonFormDraft(value)) {
    return jsonFormDraft(value.text) as T;
  }
  if (value instanceof Date) {
    return new Date(value.getTime()) as T;
  }
  if (Array.isArray(value)) {
    return value.map(cloneFormValue) as T;
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [key, cloneFormValue(item)])
    ) as T;
  }
  return value;
};

export const formValuesEqual = (left: unknown, right: unknown): boolean => {
  if (isJsonFormDraft(left) || isJsonFormDraft(right)) {
    return (
      isJsonFormDraft(left) &&
      isJsonFormDraft(right) &&
      left.text === right.text
    );
  }
  if (Object.is(left, right)) {
    return true;
  }
  if (left instanceof Date || right instanceof Date) {
    return (
      left instanceof Date &&
      right instanceof Date &&
      left.getTime() === right.getTime()
    );
  }
  if (
    !(left && right) ||
    typeof left !== "object" ||
    typeof right !== "object"
  ) {
    return false;
  }
  if (Array.isArray(left) !== Array.isArray(right)) {
    return false;
  }
  const a = Object.entries(left);
  const b = Object.entries(right);
  return (
    a.length === b.length &&
    a.every(
      ([key, value]) =>
        Object.hasOwn(right, key) &&
        formValuesEqual(value, (right as TableRecord)[key])
    )
  );
};

/** The field's own `hidden` flag or predicate, without rules. */
export const fieldHiddenByPredicate = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean =>
  Boolean(
    typeof field.hidden === "function" ? field.hidden(context) : field.hidden
  );

/** Fields as the conditions engine sees them: name, type, label, options. */
export const formRuleFields = (
  fields: readonly FormFieldDefinition[]
): ConditionField[] =>
  fields.map((field) => ({
    id: field.name,
    type: conditionFieldType(field.type),
    label: field.label,
    options: Array.isArray(field.options) ? field.options : undefined,
    required: field.required,
  }));

/**
 * The legacy `hidden` flag or predicate of each field as a rule, so one
 * engine decides visibility. Predicates still receive the full context.
 */
export const legacyHiddenRules = (
  fields: readonly FormFieldDefinition[]
): FormRule[] =>
  fields.flatMap((field) =>
    field.hidden === undefined || field.hidden === false
      ? []
      : [
          predicateRule(
            `legacy-hidden:${field.name}`,
            field.name,
            (values, context) =>
              fieldHiddenByPredicate(field, {
                ...(context as FormFieldContext),
                values,
              })
          ),
        ]
  );

const ruleSets = new WeakMap<FormConfig, FormRuleSet>();

/**
 * The rules of a form config: `config.rules` that can act (broken or cyclic
 * ones are dropped) and, unless `legacy: false`, the fields' `hidden`
 * predicates converted at load.
 */
export function formRuleSet(
  config: FormConfig,
  options: { legacy?: boolean } = {}
): FormRuleSet {
  const legacy = options.legacy !== false;
  const source = toRaw(config);
  const cached = legacy ? ruleSets.get(source) : undefined;
  if (cached) {
    return cached;
  }
  const fields = formRuleFields(source.fields);
  const declared = normalizeRules(source.rules ?? [], fields).rules;
  const set = {
    fields,
    rules: legacy
      ? [...legacyHiddenRules(source.fields), ...declared]
      : declared,
  };
  if (legacy) {
    ruleSets.set(source, set);
  }
  return set;
}

/** The rules of a context evaluated against its values (bulk editors use the shared values). */
export function formConditions(
  context: FormFieldContext
): FormEvaluation | undefined {
  const set = context.formRules;
  if (!set) {
    return;
  }
  const values = context.values ?? {};
  return context.bulkEdit
    ? bulkConditionState({
        rules: set.rules,
        fields: set.fields,
        rows: context.bulkEdit.rows,
        applied: context.bulkEdit.fields,
        values,
      }).evaluation
    : evaluateForm(set.rules, values, set.fields, { context });
}

/** A context that evaluates the config's rules (kept when one is already set). */
export const withFormRules = (
  config: FormConfig,
  context: FormFieldContext
): FormFieldContext =>
  context.formRules ? context : { ...context, formRules: formRuleSet(config) };

/** Hidden by its `hidden` predicate or by the form's rules. */
export const fieldIsHidden = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean => {
  const conditions = formConditions(context);
  return conditions
    ? conditions.hidden.has(field.name)
    : fieldHiddenByPredicate(field, context);
};

/** Required by the field itself or by a matching `require` rule. */
export const fieldIsRequired = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean => {
  const conditions = formConditions(context);
  return conditions
    ? conditions.required.has(field.name)
    : Boolean(field.required);
};

export const fieldIsDisabled = (
  field: FormFieldDefinition,
  context: FormFieldContext
): boolean =>
  Boolean(
    typeof field.disabled === "function"
      ? field.disabled(context)
      : field.disabled
  );

export const defaultFieldValue = (field: FormFieldDefinition): unknown => {
  if (field.defaultValue !== undefined) {
    return cloneFormValue(field.defaultValue);
  }
  if (["number", "date", "select", "json"].includes(field.type)) {
    return null;
  }
  if (field.type === "collection" || field.type === "multiSelect") {
    return [];
  }
  if (field.type === "switch" || field.type === "checkbox") {
    return false;
  }
  return "";
};

export const initialFormValues = (
  config: FormConfig,
  row?: TableRecord
): TableRecord =>
  cloneFormValue({
    ...Object.fromEntries(
      config.fields.map((field) => [field.name, defaultFieldValue(field)])
    ),
    ...config.defaultValues,
    ...row,
  });

export const resolveFormSections = (
  config: FormConfig
): FormSectionDefinition[] => {
  const remaining = new Set(config.fields.map((field) => field.name));
  const sections: FormSectionDefinition[] = [];
  for (const section of config.sections ?? []) {
    const fields = section.fields.filter((name) => remaining.delete(name));
    if (fields.length) {
      sections.push({ ...section, fields });
    }
  }
  if (remaining.size) {
    let id = "__ungrouped";
    while (sections.some((section) => section.id === id)) {
      id += "_";
    }
    sections.push({ id, fields: [...remaining] });
  }
  return sections;
};

export const translateFormConfig = (config: FormConfig): FormConfig => {
  const keys = config.translations?.keys ?? {};
  const translate = (key: string | undefined, fallback: string | undefined) =>
    key ? (keys[key] ?? fallback) : fallback;
  const field = (value: FormFieldDefinition): FormFieldDefinition => ({
    ...value,
    label: translate(value.labelKey, value.label) ?? value.name,
    description: translate(value.descriptionKey, value.description),
    placeholder: translate(value.placeholderKey, value.placeholder),
    itemFields: value.itemFields?.map(field),
    options: Array.isArray(value.options)
      ? value.options.map((option, index) => ({
          ...option,
          label:
            translate(value.optionKeys?.[index], option.label) ?? option.label,
        }))
      : value.options,
  });
  return {
    ...config,
    fields: config.fields.map(field),
    blocks: config.blocks
      ? translateFormBlocks(config.blocks, keys)
      : undefined,
    sections: config.sections?.map((section) => ({
      ...section,
      title: translate(section.titleKey, section.title),
      description: translate(section.descriptionKey, section.description),
    })),
  };
};

export interface FormValidationResult {
  values: TableRecord;
  errors: Record<string, string>;
}

const missing = (value: unknown): boolean =>
  value === "" ||
  value === null ||
  value === undefined ||
  (Array.isArray(value) && value.length === 0);

export const dynamicFieldType = (
  field: FormFieldDefinition,
  context: FormFieldContext
): "boolean" | "json" | "number" | "string" => {
  if (!["dynamic-value", "dynamicValue", "value-type"].includes(field.type)) {
    return "string";
  }
  const raw =
    field.type === "value-type"
      ? context.values[field.valueTypeField ?? ""]
      : field.dependsOn?.transform(context.values[field.dependsOn.field]);
  const candidate = String(raw ?? "string") as
    | "boolean"
    | "json"
    | "number"
    | "string";
  return (
    field.supportedTypes ?? ["boolean", "json", "number", "string"]
  ).includes(candidate)
    ? candidate
    : "string";
};

const validateScalar = (
  field: FormFieldDefinition,
  value: unknown,
  context: FormFieldContext
): string | undefined => {
  if (fieldIsRequired(field, context) && missing(value)) {
    return `${field.label} is required`;
  }
  const typeError = dataTypeValueError(
    ["dynamic-value", "dynamicValue", "value-type"].includes(field.type)
      ? dynamicFieldType(field, context)
      : field.type,
    value
  );
  if (typeError) {
    return `${field.label}: ${typeError}`;
  }
  const numeric =
    field.type === "number" || dynamicFieldType(field, context) === "number";
  if (
    numeric &&
    !missing(value) &&
    (typeof value !== "number" || !Number.isFinite(value))
  ) {
    return `Invalid ${field.label}`;
  }
  if (numeric && typeof value === "number") {
    if (field.min !== undefined && value < field.min) {
      return `${field.label} must be at least ${field.min}`;
    }
    if (field.max !== undefined && value > field.max) {
      return `${field.label} must be at most ${field.max}`;
    }
  }
  return undefined;
};

const validateCollection = async (
  field: FormFieldDefinition,
  value: unknown[],
  context: FormFieldContext
): Promise<FormValidationResult> => {
  const items: TableRecord[] = [];
  const errors: Record<string, string> = {};
  for (const [index, item] of value.entries()) {
    const path = `${field.name}.${index}`;
    if (!item || typeof item !== "object" || Array.isArray(item)) {
      errors[path] = "Invalid item";
      continue;
    }
    const child = await validateFormFields(
      field.itemFields ?? [],
      item as TableRecord,
      { ...context, formRules: undefined, values: item as TableRecord }
    );
    items.push(child.values);
    for (const [name, message] of Object.entries(child.errors)) {
      errors[`${path}.${name}`] = message;
    }
    const issues = field.validateItem?.(child.values, index) ?? [];
    if (issues.length) {
      errors[path] = issues.join("; ");
    }
  }
  const issues = field.validateItems?.(items) ?? [];
  if (issues.length) {
    errors[field.name] = issues.join("; ");
  }
  return { values: { [field.name]: items }, errors };
};

const validateField = async (
  field: FormFieldDefinition,
  value: unknown,
  context: FormFieldContext
): Promise<FormValidationResult> => {
  const values = { [field.name]: value };
  if ((field.type === "number" || field.type === "date") && value === "") {
    values[field.name] = null;
  }
  if (field.type === "json" || dynamicFieldType(field, context) === "json") {
    try {
      values[field.name] = parseJsonFormValue(value);
    } catch {
      return {
        values,
        errors: { [field.name]: `Invalid ${field.label}: expected valid JSON` },
      };
    }
  }
  const errors: Record<string, string> = {};
  const scalarError = validateScalar(field, values[field.name], context);
  if (scalarError) {
    return { values, errors: { [field.name]: scalarError } };
  }
  if (field.type === "collection" && Array.isArray(value)) {
    const result = await validateCollection(field, value, context);
    Object.assign(values, result.values);
    Object.assign(errors, result.errors);
  }
  if (field.schema) {
    // Zod schemas contain non-configurable properties and must not run through Vue proxies.
    const result = await toRaw(field.schema).safeParseAsync(values[field.name]);
    if (result.success) {
      values[field.name] = result.data;
    } else {
      for (const issue of result.error.issues) {
        errors[[field.name, ...issue.path].join(".")] = issue.message;
      }
    }
  }
  return { values, errors };
};

export const validateFormFields = async (
  fields: FormFieldDefinition[],
  values: TableRecord,
  context: FormFieldContext
): Promise<FormValidationResult> => {
  const output = cloneFormValue(values);
  const errors: Record<string, string> = {};
  for (const field of fields) {
    if (fieldIsHidden(field, context) || fieldIsDisabled(field, context)) {
      continue;
    }
    const result = await validateField(field, output[field.name], context);
    Object.assign(output, result.values);
    Object.assign(errors, result.errors);
  }
  return { values: output, errors };
};

export const validateForm = async (
  config: FormConfig,
  input: TableRecord,
  baseContext: FormFieldContext
): Promise<FormValidationResult> => {
  const ruled = withFormRules(config, { ...baseContext, values: input });
  // `set` rules write their values before validation.
  const values = { ...input, ...formConditions(ruled)?.setValues };
  const context = { ...ruled, values };
  const result = await validateFormFields(config.fields, values, context);
  if (!Object.keys(result.errors).length && config.schema) {
    const parsed = await toRaw(config.schema).safeParseAsync(result.values);
    if (parsed.success) {
      if (
        parsed.data &&
        typeof parsed.data === "object" &&
        !Array.isArray(parsed.data)
      ) {
        result.values = parsed.data as TableRecord;
      } else {
        result.errors.form = "The form schema must return an object";
      }
    } else {
      for (const issue of parsed.error.issues) {
        result.errors[issue.path.join(".") || "form"] = issue.message;
      }
    }
  }
  return result;
};

export const formSubmissionValues = (
  config: FormConfig,
  values: TableRecord,
  initial: TableRecord,
  baseContext: FormFieldContext
): TableRecord => {
  const context = withFormRules(config, { ...baseContext, values });
  const output =
    config.submitMode === "patch" && context.mode === "edit"
      ? Object.fromEntries(
          config.fields
            .filter(
              (field) =>
                !formValuesEqual(values[field.name], initial[field.name])
            )
            .map((field) => [field.name, values[field.name]])
        )
      : cloneFormValue(values);
  for (const field of config.fields) {
    if (fieldIsHidden(field, context) || fieldIsDisabled(field, context)) {
      delete output[field.name];
    }
  }
  return output;
};

/**
 * Localized texts of forms, shared by the React and Vue editions. A text is a
 * plain string (as before) or one string per locale:
 *
 * ```ts
 * resolveFormText({ en: "Name", fr: "Nom" }, "fr-CA"); // "Nom"
 * resolveFormText("Name", "fr"); // "Name": a plain text is every language's
 * ```
 *
 * Pure and dependency-free, so a host can resolve texts on its server.
 */

/** A form text: one string, or one per locale (`{ en: "Name", fr: "Nom" }`). */
export type FormText = string | Readonly<Record<string, string>>;

const LOCALE_TAG = /^[a-z]{2,3}(?:-[a-z\d]{2,8})*$/i;
const UNDERSCORES = /_/g;
const LETTERS = /^[a-z]+$/i;
const SUBTAG_SEPARATOR = /[-_]/;
const MAX_LOCALE_LENGTH = 35;
const SCRIPT_LENGTH = 4;
const REGION_LENGTH = 2;

/**
 * Languages offered by "Add language" when the host lists none
 * (`table.form.locales`).
 */
export const FORM_COMMON_LOCALES = [
  "en",
  "fr",
  "de",
  "es",
  "it",
  "nl",
  "pt",
  "pl",
  "sv",
  "da",
  "fi",
  "nb",
  "cs",
  "ro",
  "el",
  "tr",
  "ru",
  "uk",
  "ar",
  "he",
  "ja",
  "ko",
  "zh",
] as const;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === "object" && !Array.isArray(value);

const casePart = (part: string, index: number): string => {
  if (index === 0) {
    return part.toLowerCase();
  }
  if (part.length === SCRIPT_LENGTH && LETTERS.test(part)) {
    return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
  }
  return part.length === REGION_LENGTH
    ? part.toUpperCase()
    : part.toLowerCase();
};

/**
 * A language tag as forms store it ("fr", "fr-CA", "zh-Hant"), or `undefined`
 * when the value is not one. Underscores are read as hyphens ("fr_CA").
 */
export function formLocaleTag(value: unknown): string | undefined {
  if (typeof value !== "string") {
    return;
  }
  const tag = value.trim().replace(UNDERSCORES, "-");
  if (!tag || tag.length > MAX_LOCALE_LENGTH || !LOCALE_TAG.test(tag)) {
    return;
  }
  return tag.split("-").map(casePart).join("-");
}

/** The language of a locale: "fr" for "fr-CA". */
export const formLanguage = (locale: string): string =>
  (locale.split(SUBTAG_SEPARATOR)[0] ?? "").toLowerCase();

/** Languages in order, each once (by tag), malformed ones left out. */
export function uniqueFormLocales(values: Iterable<unknown>): string[] {
  const seen = new Set<string>();
  const locales: string[] = [];
  for (const value of values) {
    const tag = formLocaleTag(value);
    if (tag && !seen.has(tag.toLowerCase())) {
      seen.add(tag.toLowerCase());
      locales.push(tag);
    }
  }
  return locales;
}

/**
 * Keep a valid text: a non-empty string, or non-empty strings under valid
 * language tags. Anything else is `undefined`, so plain strings saved before
 * localized texts existed stay as they are.
 */
export function normalizeFormText(value: unknown): FormText | undefined {
  if (typeof value === "string") {
    return value.trim() || undefined;
  }
  if (!isRecord(value)) {
    return;
  }
  const entries: [string, string][] = [];
  const seen = new Set<string>();
  for (const [key, text] of Object.entries(value)) {
    const locale = formLocaleTag(key);
    const content = typeof text === "string" ? text.trim() : "";
    if (locale && content && !seen.has(locale.toLowerCase())) {
      seen.add(locale.toLowerCase());
      entries.push([locale, content]);
    }
  }
  return entries.length ? Object.fromEntries(entries) : undefined;
}

const textEntries = (text: Readonly<Record<string, string>>) =>
  Object.entries(text).filter(
    (entry): entry is [string, string] =>
      typeof entry[1] === "string" && entry[1].trim() !== ""
  );

/**
 * The language among `locales` that serves `locale`: its exact tag, else its
 * language ("fr" for "fr-CA"), else another variant of it ("fr-FR").
 */
export function formLocaleMatch(
  locales: readonly string[],
  locale: string | undefined
): string | undefined {
  const tag = formLocaleTag(locale);
  if (!tag) {
    return;
  }
  const lower = tag.toLowerCase();
  const language = formLanguage(tag);
  return (
    locales.find((key) => key.toLowerCase() === lower) ??
    locales.find((key) => key.toLowerCase() === language) ??
    locales.find((key) => formLanguage(key) === language)
  );
}

/** A text in one language, and that language when it is known. */
export interface FormTextVersion {
  text: string;
  locale?: string;
}

/**
 * The version of a text for `locale`, with its language: the exact locale,
 * then its language, then the form's default locale. A plain string is the
 * default locale's. `undefined` when none of them has a text, so callers can
 * use their own default (a column name, a built-in label).
 */
export function formTextVersion(
  text: FormText | undefined,
  locale?: string,
  defaultLocale?: string
): FormTextVersion | undefined {
  if (text === undefined) {
    return;
  }
  if (typeof text === "string") {
    const content = text.trim();
    return content ? { text: content, locale: defaultLocale } : undefined;
  }
  const entries = textEntries(text);
  const keys = entries.map(([key]) => key);
  const key =
    formLocaleMatch(keys, locale) ?? formLocaleMatch(keys, defaultLocale);
  const found = entries.find(([entry]) => entry === key);
  return found ? { text: found[1], locale: found[0] } : undefined;
}

/**
 * A text in `locale`: the exact locale, then its language, then the form's
 * default locale, then the first version available. Plain strings are the
 * same in every language. Texts with a default of their own (a question's
 * column name, a built-in label) use `formTextVersion` instead.
 */
export function resolveFormText(
  text: FormText | undefined,
  locale?: string,
  defaultLocale?: string
): string | undefined {
  const version = formTextVersion(text, locale, defaultLocale);
  if (version || !text || typeof text === "string") {
    return version?.text;
  }
  return textEntries(text)[0]?.[1];
}

const sameLocale = (left: string, right: string) =>
  left.toLowerCase() === right.toLowerCase();

/**
 * The text written for exactly `locale`, as a settings input shows it: a plain
 * text belongs to the default locale; other locales read "" until translated.
 */
export function formTextIn(
  text: FormText | undefined,
  locale: string,
  defaultLocale: string
): string {
  if (text === undefined) {
    return "";
  }
  if (typeof text === "string") {
    return sameLocale(locale, defaultLocale) ? text : "";
  }
  return textEntries(text).find(([key]) => sameLocale(key, locale))?.[1] ?? "";
}

/**
 * A text with the version of `locale` replaced, or removed when `value` is
 * empty. A text only written in the default locale stays a plain string, so
 * forms that are not translated keep their saved shape.
 */
export function setFormText(
  text: FormText | undefined,
  locale: string,
  value: string,
  defaultLocale: string
): FormText | undefined {
  const content = value.trim();
  const entries: [string, string][] =
    typeof text === "string"
      ? [[defaultLocale, text]]
      : textEntries(text ?? {});
  const others = entries.filter(([key]) => !sameLocale(key, locale));
  const next = content
    ? [...others, [locale, content] as [string, string]]
    : others;
  if (next.length === 0) {
    return;
  }
  const [only] = next;
  if (next.length === 1 && only && sameLocale(only[0], defaultLocale)) {
    return only[1];
  }
  return Object.fromEntries(next);
}

/** Locales a text is written in (a plain text is written in none in particular). */
export const formTextLocales = (text: FormText | undefined): string[] =>
  text && typeof text !== "string"
    ? uniqueFormLocales(textEntries(text).map(([key]) => key))
    : [];

/**
 * Whether `locale` still needs a translation: another language (or `source`,
 * such as the column name a question shows by default) has a text and this
 * locale has none. The default locale only misses a text that other
 * languages have.
 */
export function formTextMissing(
  text: FormText | undefined,
  locale: string,
  defaultLocale: string,
  source?: string
): boolean {
  if (formTextIn(text, locale, defaultLocale)) {
    return false;
  }
  if (sameLocale(locale, defaultLocale)) {
    return formTextLocales(text).length > 0;
  }
  return resolveFormText(text, defaultLocale) !== undefined || Boolean(source);
}

/**
 * A language's name: in itself by default ("English", "Français", "Deutsch"),
 * as a language switcher shows it, or in `inLocale` for a sentence ("anglais").
 */
export function formLanguageName(locale: string, inLocale?: string): string {
  try {
    const name = new Intl.DisplayNames([inLocale ?? locale], {
      type: "language",
    }).of(locale);
    if (name && name.toLowerCase() !== locale.toLowerCase()) {
      return inLocale
        ? name
        : name.charAt(0).toLocaleUpperCase(locale) + name.slice(1);
    }
  } catch {
    // Unknown tags keep their code below.
  }
  return locale.toUpperCase();
}

/**
 * Form view model shared by the React and Vue editions: settings, questions,
 * validation, submissions, labels and the public-link contract. It has no UI
 * or state-library dependency, so a host can also run it on its server.
 */
import {
  type ConditionField,
  type ConditionFieldType,
  type ConditionGroup,
  type ConditionOperator,
  type ConditionValue,
  type ConditionWords,
  describeRule,
  evaluateForm,
  type FormEvaluation,
  type FormRule,
  type FormRuleAction,
  normalizeRules,
  type RuleIssue,
  type RuleIssueCode,
  sanitizeRules,
  validateRules,
} from "./form-conditions";
import {
  FORM_COMMON_LOCALES,
  type FormText,
  type FormTextVersion,
  formLocaleTag,
  formTextLocales,
  formTextMissing,
  formTextVersion,
  normalizeFormText,
  resolveFormText,
  uniqueFormLocales,
} from "./form-text";
import { formatLocation, parseLocation } from "./location-model";
import { resolveDataType, TABLE_DATA_TYPES } from "./table-contracts";
import {
  type ColumnValueFormat,
  type DateDisplayPreset,
  formatColumnDay,
  formatNumberValue,
  type NumberFormatConfig,
} from "./value-format";

/** The input a question renders, derived from its column type. */
export type FormEditor =
  | "boolean"
  | "date"
  | "location"
  | "multiSelect"
  | "number"
  | "select"
  | "text"
  | "textarea"
  | "url";

/** What the form needs from a table column. */
export interface FormColumn {
  id: string;
  header: string;
  type?: string;
  options?: unknown;
  accessorKey?: unknown;
  accessorFn?: unknown;
  /** `"tag"` shows the options as tags, like the table cells. */
  displayVariant?: string;
  /** Colored tags (default true); the Form view passes the table's setting. */
  coloredTags?: boolean;
  /** How the table shows numbers, e.g. `{ currency: "EUR" }`. */
  numberFormat?: unknown;
  /**
   * `false`: forms never ask the column (nor write it); `true`: they may,
   * whatever its other flags.
   */
  form?: boolean;
  /** Read-only columns (`readonly`, `readOnly` or `editable: false`) are never asked. */
  readonly?: boolean;
  readOnly?: boolean;
  editable?: boolean;
  /** Values the host computes: never asked. */
  computed?: boolean;
  /** System or metadata columns (record ids, created and updated stamps…): never asked. */
  system?: boolean;
  /** Columns people never see: never asked. */
  hidden?: boolean;
  /** How the table shows dates; answers are days, shown with the date part. */
  dateDisplayPreset?: unknown;
  dateFormat?: unknown;
}

export type { FormText } from "./form-text";

/**
 * One question of the form. `id` is stable (it defaults to the column id) so
 * later features, such as conditions, can point at a question. Texts are one
 * string or one per locale (`{ en: "Name", fr: "Nom" }`).
 */
export interface FormQuestion {
  id: string;
  /** Column that receives the answer. */
  columnId: string;
  /** Replaces the column name. */
  label?: FormText;
  /** Shown under the label. */
  help?: FormText;
  placeholder?: FormText;
  required?: boolean;
  /** Option labels replacing the column's, by option value (e.g. to translate them). */
  optionLabels?: Record<string, FormText>;
}

/**
 * A section break: starts a titled group of questions. In the steps layout,
 * each section is one step. Rules may show or hide a section (and its
 * questions) by its id.
 */
export interface FormSectionBreak {
  id: string;
  kind: "section";
  title?: FormText;
  description?: FormText;
}

/** The link of a consent statement, such as the privacy policy. */
export interface FormConsentLink {
  /** The link's text; unset reads "privacy policy". */
  label?: FormText;
  /** `https://…` or a path of the site (`/privacy`); without it the text shows unlinked. */
  href?: FormText;
}

/**
 * A consent checkbox (GDPR), bound to no column: always required, never hidden
 * by rules. `{link}` in its text marks where the link goes. Accepted consents
 * reach the host as `metadata.consents` of the response, never as a column.
 */
export interface FormConsentQuestion {
  id: string;
  kind: "consent";
  /** The statement; unset reads "I agree to the processing of my answers." */
  text?: FormText;
  link?: FormConsentLink;
  /** Version of the terms agreed to, recorded with each response (default "1"). */
  version?: string;
}

/** Where a hidden field takes its value from. */
export type FormHiddenSource =
  | { type: "urlParam"; name: string }
  | { type: "pageUrl" }
  | { type: "referrer" }
  | { type: "locale" }
  | { type: "static"; value: string };

export type FormHiddenSourceType = FormHiddenSource["type"];

/**
 * A hidden (context) field: never shown, it takes its value from the page
 * (a URL parameter such as `utm_source`, the page address, the referrer, the
 * language) or a fixed text. Bound to a column, the value is written like an
 * answer; otherwise it is kept in `metadata.context`. Browser values are
 * untrusted: the server accepts only the snapshot's sources, as capped text.
 */
export interface FormHiddenField {
  id: string;
  kind: "hidden";
  source: FormHiddenSource;
  /** Column written with the value (a column the form does not ask). */
  columnId?: string;
}

/** A question, a section break, a consent or a hidden field, in form order. */
export type FormItem =
  | FormQuestion
  | FormSectionBreak
  | FormConsentQuestion
  | FormHiddenField;

/** `page` shows every question at once; `steps` one question (or section) at a time. */
export type FormLayout = "page" | "steps";

export interface FormViewSettings {
  title?: FormText;
  description?: FormText;
  /**
   * Language of plain texts, and the fallback of missing translations (before
   * the first version available). Defaults to the first of `locales`.
   */
  defaultLocale?: string;
  /**
   * Languages the form is written in, shown by the settings' language
   * switcher and the Form view's preview. At table level
   * (`table.form.locales`), the host's languages: every form has them.
   */
  locales?: string[];
  /** Questions, section breaks, consents and hidden fields in order; unset asks every column that has an editor. */
  questions?: FormItem[];
  /**
   * Show, hide or require questions from earlier answers. Conditions point
   * at question ids (`fieldId`), effects at question or section ids
   * (`then.questionIds`). See `utils/form-conditions.ts`.
   */
  rules?: FormRule[];
  /** `page` (default) or `steps`. */
  layout?: FormLayout;
  /** In steps, end with a review of the answers before sending. */
  review?: boolean;
  /** Fixed values saved with every response, for columns not asked (e.g. `{ status: "New" }`). */
  hiddenValues?: Record<string, FormHiddenValue>;
  submitLabel?: FormText;
  successMessage?: FormText;
  /** Shown instead of the questions while the form is closed. */
  closedMessage?: FormText;
  /** Offer "Submit another response" after a success (default true). */
  allowAnotherResponse?: boolean;
  /** Where the host may send people after a success; the host decides whether to follow it. */
  redirectUrl?: string;
  /**
   * Show "Edit form" above the form in the Form view (default true). The
   * form stays editable from View settings.
   */
  editButton?: boolean;
}

export type FormHiddenValue = boolean | number | string | (number | string)[];

export interface FormOption {
  value: unknown;
  label: string;
}

export interface ResolvedFormQuestion {
  id: string;
  columnId: string;
  editor: FormEditor;
  /** Column name or the label override. */
  label: string;
  help?: string;
  placeholder?: string;
  required: boolean;
  options: FormOption[];
  /** Options shown as tags, as the column displays them. */
  tags: boolean;
  /** Tags get their automatic color. */
  coloredTags: boolean;
  /** Number display of the column, used once the answer is typed. */
  numberFormat?: NumberFormatConfig;
  /** Date display of the column, used once the day is picked. */
  dateFormat?: Pick<ColumnValueFormat, "dateDisplayPreset" | "dateFormat">;
}

export interface ResolvedFormSection {
  id: string;
  kind: "section";
  title?: string;
  description?: string;
}

/** A consent as the form shows it, in the form's language. */
export interface ResolvedFormConsent {
  id: string;
  /** The statement; `{link}` marks where the link goes. */
  text: string;
  /** The link, when the consent has one; without `href` its text shows unlinked. */
  link?: { label: string; href?: string };
  version: string;
  /** The language the statement is written in, when it is known. */
  locale?: string;
}

/** A hidden field with how its column takes the value, when it is bound to one. */
export interface ResolvedFormHiddenField extends FormHiddenField {
  /** The bound column's editor, for checking the value like an answer. */
  editor?: FormEditor;
  options?: FormOption[];
}

/** Questions, sections and consents in form order. */
export type ResolvedFormItem =
  | { kind: "question"; question: ResolvedFormQuestion }
  | { kind: "section"; section: ResolvedFormSection }
  | { kind: "consent"; consent: ResolvedFormConsent };

export interface ResolvedFormSettings {
  title?: string;
  description?: string;
  /** The asked questions, without sections. */
  questions: ResolvedFormQuestion[];
  /** Questions, section breaks and consents in order. */
  items: ResolvedFormItem[];
  /** Consent checkboxes, in form order: always required, never hidden. */
  consents: ResolvedFormConsent[];
  /** Hidden fields; a binding only stays on a column the form can write and does not ask. */
  hiddenFields: ResolvedFormHiddenField[];
  /** Rules that can act (broken or cyclic ones are dropped). */
  rules: FormRule[];
  layout: FormLayout;
  review: boolean;
  hiddenValues: Record<string, FormHiddenValue>;
  submitLabel?: string;
  successMessage?: string;
  closedMessage?: string;
  allowAnotherResponse: boolean;
  redirectUrl?: string;
  /** The language the texts were resolved in, when one was asked. */
  locale?: string;
  /** The form's default language, when it has one. */
  defaultLocale?: string;
}

/** Raw answers as the inputs hold them, keyed by column id. */
export type FormDraft = Record<string, boolean | string | string[]>;

/** What `onSubmit` resolves: success, or errors keyed by column id and a message. */
export type FormSubmitResult =
  | { ok: true }
  | { ok?: false; errors?: Record<string, string>; message?: string };

export const FORM_VIEW_DEFAULTS = {
  allowAnotherResponse: true,
} as const satisfies FormViewSettings;

/** Settings texts that may be localized. */
const TEXT_KEYS = [
  "title",
  "description",
  "submitLabel",
  "successMessage",
  "closedMessage",
] as const;
const QUESTION_TEXT_KEYS = ["label", "help", "placeholder"] as const;
const SECTION_TEXT_KEYS = ["title", "description"] as const;
const SAFE_URL = /^(https?:\/\/|\/(?!\/))/i;
const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;
/** URL parameter names a hidden field may read: `utm_source`, `ref`, `gclid`… */
const PARAM_NAME = /^[\w.[\]-]{1,100}$/;
const EXCLUDED_IDS = new Set(["select", "actions"]);
const EDITORS: Partial<Record<string, FormEditor>> = {
  date: "date",
  location: "location",
  multiSelect: "multiSelect",
  number: "number",
  select: "select",
  switch: "boolean",
  text: "text",
  textarea: "textarea",
  url: "url",
};
/** Editors a hidden field can write: text that converts to the column's type. */
const HIDDEN_FIELD_EDITORS = new Set<FormEditor>([
  "boolean",
  "date",
  "number",
  "select",
  "text",
  "textarea",
  "url",
]);
const HIDDEN_SOURCE_TYPES = new Set<FormHiddenSourceType>([
  "locale",
  "pageUrl",
  "referrer",
  "static",
  "urlParam",
]);
/** Longest hidden text kept (URL parameters, fixed texts); longer ones are cut. */
export const FORM_HIDDEN_TEXT_MAX = 500;
/** Longest page or referrer address kept; longer ones are dropped, not cut. */
export const FORM_HIDDEN_URL_MAX = 2048;
const DEFAULT_CONSENT_VERSION = "1";

const text = (value: unknown): string | undefined => {
  const trimmed = typeof value === "string" ? value.trim() : "";
  return trimmed || undefined;
};

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === "object" && !Array.isArray(value);

const isHiddenScalar = (value: unknown): value is number | string =>
  typeof value === "string" ||
  (typeof value === "number" && Number.isFinite(value));

function normalizeHiddenValue(value: unknown): FormHiddenValue | undefined {
  if (typeof value === "boolean" || isHiddenScalar(value)) {
    return value === "" ? undefined : value;
  }
  if (Array.isArray(value) && value.every(isHiddenScalar)) {
    return value.length ? [...value] : undefined;
  }
}

/** Whether a form item is a section break rather than a question. */
export const isFormSection = (item: unknown): item is FormSectionBreak =>
  isRecord(item) && item.kind === "section";

/** Whether a form item is a consent checkbox. */
export const isFormConsent = (item: unknown): item is FormConsentQuestion =>
  isRecord(item) && item.kind === "consent";

/** Whether a form item is a hidden (context) field. */
export const isFormHiddenField = (item: unknown): item is FormHiddenField =>
  isRecord(item) && item.kind === "hidden";

/** Whether a form item is a question, bound to a column. */
export const isFormQuestion = (item: unknown): item is FormQuestion =>
  isRecord(item) &&
  typeof item.columnId === "string" &&
  !(isFormSection(item) || isFormConsent(item) || isFormHiddenField(item));

/** Copy the localized texts of `keys` that are valid. */
function textsOf<K extends string>(
  value: Record<string, unknown>,
  keys: readonly K[]
): Partial<Record<K, FormText>> {
  const texts: Partial<Record<K, FormText>> = {};
  for (const key of keys) {
    const content = normalizeFormText(value[key]);
    if (content !== undefined) {
      texts[key] = content;
    }
  }
  return texts;
}

function normalizeSection(
  value: Record<string, unknown>
): FormSectionBreak | undefined {
  const id = text(value.id);
  return id
    ? { id, kind: "section", ...textsOf(value, SECTION_TEXT_KEYS) }
    : undefined;
}

/** Addresses that are `https://…`, `http://…` or a path of the site, per locale. */
function safeHref(value: unknown): FormText | undefined {
  const href = normalizeFormText(value);
  if (typeof href === "string" || href === undefined) {
    return href && SAFE_URL.test(href) ? href : undefined;
  }
  const entries = Object.entries(href).filter(([, item]) =>
    SAFE_URL.test(item)
  );
  return entries.length ? Object.fromEntries(entries) : undefined;
}

/** A link, when it has a text or a safe address. */
function normalizeConsentLink(value: unknown): FormConsentLink | undefined {
  if (!isRecord(value)) {
    return;
  }
  const link: FormConsentLink = {};
  const label = normalizeFormText(value.label);
  const href = safeHref(value.href);
  if (label !== undefined) {
    link.label = label;
  }
  if (href !== undefined) {
    link.href = href;
  }
  return Object.keys(link).length ? link : undefined;
}

function normalizeConsent(
  value: Record<string, unknown>
): FormConsentQuestion | undefined {
  const id = text(value.id);
  if (!id) {
    return;
  }
  const consent: FormConsentQuestion = { id, kind: "consent" };
  const statement = normalizeFormText(value.text);
  const link = normalizeConsentLink(value.link);
  const version = text(value.version);
  if (statement !== undefined) {
    consent.text = statement;
  }
  if (link) {
    consent.link = link;
  }
  if (version) {
    consent.version = version.slice(0, FORM_HIDDEN_TEXT_MAX);
  }
  return consent;
}

/** A hidden field's source; `"pageUrl"`, `"referrer"` and `"locale"` may be given as strings. */
export function normalizeFormHiddenSource(
  value: unknown
): FormHiddenSource | undefined {
  const source = typeof value === "string" ? { type: value } : value;
  if (
    !(
      isRecord(source) &&
      HIDDEN_SOURCE_TYPES.has(source.type as FormHiddenSourceType)
    )
  ) {
    return;
  }
  switch (source.type as FormHiddenSourceType) {
    case "urlParam": {
      const name = text(source.name);
      return name && PARAM_NAME.test(name)
        ? { type: "urlParam", name }
        : undefined;
    }
    case "static": {
      const content = text(source.value);
      return content
        ? { type: "static", value: content.slice(0, FORM_HIDDEN_TEXT_MAX) }
        : undefined;
    }
    case "pageUrl":
      return { type: "pageUrl" };
    case "referrer":
      return { type: "referrer" };
    default:
      return { type: "locale" };
  }
}

/** A hidden field; without `columnId` its value goes to `metadata.context`. */
const hiddenFieldOf = (
  id: string,
  source: FormHiddenSource,
  columnId?: string
): FormHiddenField =>
  columnId
    ? { id, kind: "hidden", source, columnId }
    : { id, kind: "hidden", source };

function normalizeHiddenField(
  value: Record<string, unknown>
): FormHiddenField | undefined {
  const id = text(value.id);
  const source = normalizeFormHiddenSource(value.source);
  return id && source
    ? hiddenFieldOf(id, source, text(value.columnId))
    : undefined;
}

function normalizeOptionLabels(
  value: unknown
): Record<string, FormText> | undefined {
  if (!isRecord(value)) {
    return;
  }
  const entries = Object.entries(value).flatMap(([key, label]) => {
    const content = normalizeFormText(label);
    return content === undefined ? [] : [[key, content] as const];
  });
  return entries.length ? Object.fromEntries(entries) : undefined;
}

function normalizeItem(value: unknown): FormItem | undefined {
  if (!isRecord(value)) {
    return;
  }
  if (isFormSection(value)) {
    return normalizeSection(value);
  }
  if (isFormConsent(value)) {
    return normalizeConsent(value);
  }
  return isFormHiddenField(value)
    ? normalizeHiddenField(value)
    : normalizeQuestion(value);
}

function normalizeQuestion(value: unknown): FormQuestion | undefined {
  if (!isRecord(value)) {
    return;
  }
  const columnId = text(value.columnId) ?? text(value.id);
  if (!columnId) {
    return;
  }
  const question: FormQuestion = {
    id: text(value.id) ?? columnId,
    columnId,
    ...textsOf(value, QUESTION_TEXT_KEYS),
  };
  if (typeof value.required === "boolean") {
    question.required = value.required;
  }
  const optionLabels = normalizeOptionLabels(value.optionLabels);
  if (optionLabels) {
    question.optionLabels = optionLabels;
  }
  return question;
}

/** A hidden field bound to an asked column (or to a column bound before) keeps its value in the metadata only. */
function unbindTaken(items: FormItem[], asked: Set<string>): FormItem[] {
  const bound = new Set<string>();
  return items.map((item) => {
    if (!(isFormHiddenField(item) && item.columnId)) {
      return item;
    }
    if (asked.has(item.columnId) || bound.has(item.columnId)) {
      return hiddenFieldOf(item.id, item.source);
    }
    bound.add(item.columnId);
    return item;
  });
}

/**
 * A consent keeps its answer under its id, next to the answers kept under
 * column ids: one sharing an asked column's id gets another id.
 */
function apartFromColumns(
  entries: readonly FormItem[],
  asked: ReadonlySet<string>
): FormItem[] {
  const taken = new Set([...asked, ...entries.map((item) => item.id)]);
  return entries.map((item) => {
    if (!(isFormConsent(item) && asked.has(item.id))) {
      return item;
    }
    const id = freeId(`${item.id}-consent`, taken);
    taken.add(id);
    return { ...item, id };
  });
}

/**
 * Questions, sections, consents and hidden fields in order, each column and
 * id at most once. A consent never shares its id with an asked column.
 */
export function normalizeFormQuestions(value: unknown): FormItem[] {
  if (!Array.isArray(value)) {
    return [];
  }
  const entries = value.flatMap((entry) => {
    const item = normalizeItem(entry);
    return item ? [item] : [];
  });
  const asked = new Set(
    entries.filter(isFormQuestion).map((question) => question.columnId)
  );
  const ids = new Set<string>();
  const columns = new Set<string>();
  const items: FormItem[] = [];
  for (const item of apartFromColumns(entries, asked)) {
    const column = isFormQuestion(item) ? item.columnId : undefined;
    if (!(ids.has(item.id) || (column && columns.has(column)))) {
      ids.add(item.id);
      if (column) {
        columns.add(column);
      }
      items.push(item);
    }
  }
  return unbindTaken(items, asked);
}

function normalizeHiddenValues(
  value: unknown
): Record<string, FormHiddenValue> | undefined {
  if (!isRecord(value)) {
    return;
  }
  const entries = Object.entries(value).flatMap(([key, item]) => {
    const normalized = normalizeHiddenValue(item);
    return key.trim() && normalized !== undefined ? [[key, normalized]] : [];
  });
  return entries.length ? Object.fromEntries(entries) : undefined;
}

function normalizeLocales(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return;
  }
  const locales = uniqueFormLocales(value);
  return locales.length ? locales : undefined;
}

/** Keep only valid form settings; unknown or malformed values are dropped. */
export function normalizeFormViewConfig(
  value: unknown
): FormViewSettings | undefined {
  if (!isRecord(value)) {
    return;
  }
  const normalized: FormViewSettings = textsOf(value, TEXT_KEYS);
  const defaultLocale = formLocaleTag(value.defaultLocale);
  const locales = normalizeLocales(value.locales);
  if (defaultLocale) {
    normalized.defaultLocale = defaultLocale;
  }
  if (locales) {
    normalized.locales = locales;
  }
  if (Array.isArray(value.questions)) {
    normalized.questions = normalizeFormQuestions(value.questions);
  }
  const hiddenValues = normalizeHiddenValues(value.hiddenValues);
  if (hiddenValues) {
    normalized.hiddenValues = hiddenValues;
  }
  if (typeof value.allowAnotherResponse === "boolean") {
    normalized.allowAnotherResponse = value.allowAnotherResponse;
  }
  if (Array.isArray(value.rules)) {
    normalized.rules = sanitizeRules(value.rules);
  }
  if (value.layout === "steps" || value.layout === "page") {
    normalized.layout = value.layout;
  }
  if (typeof value.review === "boolean") {
    normalized.review = value.review;
  }
  if (typeof value.editButton === "boolean") {
    normalized.editButton = value.editButton;
  }
  const redirectUrl = text(value.redirectUrl);
  if (redirectUrl && SAFE_URL.test(redirectUrl)) {
    normalized.redirectUrl = redirectUrl;
  }
  return Object.keys(normalized).length ? normalized : undefined;
}

/** The editor a column gets in a form, or none for computed and custom values. */
export function formColumnEditor(column: FormColumn): FormEditor | undefined {
  if (EXCLUDED_IDS.has(column.id) || column.accessorFn) {
    return;
  }
  if (column.type === "dynamicType" || column.type === "custom") {
    return;
  }
  const kind = TABLE_DATA_TYPES[resolveDataType(column.type)].form;
  if (column.type === "code") {
    return "textarea";
  }
  return kind ? EDITORS[kind] : undefined;
}

/**
 * Ids of the metadata columns tables commonly carry (record ids, creation and
 * update stamps): forms never ask them unless the column says `form: true`.
 */
const SYSTEM_COLUMN_IDS = new Set([
  "_id",
  "id",
  "uuid",
  "createdAt",
  "created_at",
  "createdBy",
  "created_by",
  "updatedAt",
  "updated_at",
  "updatedBy",
  "updated_by",
  "deletedAt",
  "deleted_at",
]);

/**
 * Whether forms may write a column, from its flags: columns with `form:
 * false`, `readonly`, `readOnly`, `editable: false`, `computed`, `system` or
 * `hidden`, and metadata ids (`id`, `createdAt`…), are never asked. `form:
 * true` opts a column in.
 */
export function formColumnWritable(column: FormColumn): boolean {
  if (column.form === true) {
    return true;
  }
  return !(
    column.form === false ||
    column.readonly === true ||
    column.readOnly === true ||
    column.editable === false ||
    column.computed === true ||
    column.system === true ||
    column.hidden === true ||
    SYSTEM_COLUMN_IDS.has(column.id)
  );
}

/**
 * Columns a form can ask (a form editor, and writable: see
 * `formColumnWritable`), and the others (listed with a note in the builder).
 */
export function formColumns<T extends FormColumn>(
  columns: readonly T[]
): { eligible: T[]; excluded: T[] } {
  const eligible: T[] = [];
  const excluded: T[] = [];
  for (const column of columns) {
    if (EXCLUDED_IDS.has(column.id) || column.type === "actions") {
      continue;
    }
    const askable = formColumnWritable(column) && formColumnEditor(column);
    (askable ? eligible : excluded).push(column);
  }
  return { eligible, excluded };
}

/**
 * The fields a host's create form declares (`getFormConfig` for the create
 * form type), without those it hides or disables; `undefined` when it
 * declares none.
 */
export function formCreateFields(fields: unknown): string[] | undefined {
  if (!Array.isArray(fields)) {
    return;
  }
  const names = fields.flatMap((field) =>
    isRecord(field) &&
    typeof field.name === "string" &&
    field.hidden !== true &&
    field.disabled !== true
      ? [field.name]
      : []
  );
  return names.length ? names : undefined;
}

/**
 * Columns as forms see them when the table's create form declares its fields
 * (`formFields`): the others get `form: false`, unless they opt in with
 * `form: true`. A Form view creates records like the create form does.
 */
export function withFormFields<T extends FormColumn>(
  columns: readonly T[],
  formFields: readonly string[] | undefined
): T[] {
  if (!formFields?.length) {
    return [...columns];
  }
  const names = new Set(formFields);
  return columns.map((column) =>
    column.form === true ||
    names.has(column.id) ||
    (typeof column.accessorKey === "string" && names.has(column.accessorKey))
      ? column
      : { ...column, form: false }
  );
}

/** `[{ value, label }]` or plain values, as columns declare options. */
export function formOptions(options: unknown): FormOption[] {
  if (!Array.isArray(options)) {
    return [];
  }
  return options.flatMap((option) => {
    if (isRecord(option) && "value" in option) {
      return [
        {
          value: option.value,
          label: String(option.label ?? option.value ?? ""),
        },
      ];
    }
    return isHiddenScalar(option)
      ? [{ value: option, label: String(option) }]
      : [];
  });
}

/** Settings of a form: its defaults, then the table's, then the view's. */
export function mergeFormSettings(
  defaults: unknown,
  view: unknown
): FormViewSettings {
  return {
    ...FORM_VIEW_DEFAULTS,
    ...normalizeFormViewConfig(defaults),
    ...normalizeFormViewConfig(view),
  };
}

/** The language of a form's plain texts: `defaultLocale`, else the first of `locales`. */
export const formDefaultLocale = (
  settings: Pick<FormViewSettings, "defaultLocale" | "locales">
): string | undefined => settings.defaultLocale ?? settings.locales?.[0];

const isNumberFormat = (value: unknown): value is NumberFormatConfig =>
  typeof value === "string" || isRecord(value);

/** How a form reads its texts, in the reader's language. */
interface TextReader {
  /** A text with no default of its own: its version, else the first available. */
  text: (value: FormText | undefined) => string | undefined;
  /** A text with a default of its own (a column name, a built-in label): its version, else the default. */
  own: (value: FormText | undefined) => FormTextVersion | undefined;
  /** A built-in label (host overrides applied), with its language. */
  builtIn: (key: FormLabelKey) => FormTextVersion;
}

/** The language of the built-in labels shown for `locale`: French for `fr*`, else English. */
const builtInLocale = (locale: string): string =>
  locale.toLowerCase().startsWith("fr") ? "fr" : "en";

function textReader(
  locale: string | undefined,
  defaultLocale: string | undefined,
  translate: FormTranslate | undefined
): TextReader {
  const labels = locale ?? defaultLocale ?? "en";
  return {
    text: (value) => resolveFormText(value, locale, defaultLocale),
    own: (value) => formTextVersion(value, locale, defaultLocale),
    builtIn: (key) => {
      const text = formLabel(key, labels, translate);
      // A host override is written in the reader's language.
      return text === formLabel(key, labels)
        ? { text, locale: builtInLocale(labels) }
        : { text, locale: labels };
    },
  };
}

function resolveQuestion(
  question: FormQuestion,
  column: FormColumn,
  editor: FormEditor,
  read: TextReader
): ResolvedFormQuestion {
  const options = formOptions(column.options).map((option) => {
    const label = read.own(question.optionLabels?.[String(option.value)]);
    return label ? { ...option, label: label.text } : option;
  });
  return {
    id: question.id,
    columnId: column.id,
    editor,
    label: read.own(question.label)?.text ?? column.header,
    help: read.text(question.help),
    placeholder: read.text(question.placeholder),
    required: question.required === true,
    options,
    tags: column.displayVariant === "tag",
    coloredTags: column.coloredTags !== false,
    numberFormat: isNumberFormat(column.numberFormat)
      ? column.numberFormat
      : undefined,
    dateFormat: questionDateFormat(column),
  };
}

function resolveSection(
  section: FormSectionBreak,
  read: TextReader
): ResolvedFormSection {
  const resolved: ResolvedFormSection = { id: section.id, kind: "section" };
  const title = read.text(section.title);
  const description = read.text(section.description);
  if (title) {
    resolved.title = title;
  }
  if (description) {
    resolved.description = description;
  }
  return resolved;
}

/**
 * A consent in the reader's language; the built-in statement and link text
 * fill what is unset. `locale` records the language the statement is in.
 */
function resolveConsent(
  consent: FormConsentQuestion,
  read: TextReader
): ResolvedFormConsent {
  const statement =
    read.own(consent.text) ??
    read.builtIn(consent.link ? "consentTextLink" : "consentText");
  const resolved: ResolvedFormConsent = {
    id: consent.id,
    text: statement.text,
    version: consent.version ?? DEFAULT_CONSENT_VERSION,
  };
  if (statement.locale) {
    resolved.locale = statement.locale;
  }
  if (consent.link) {
    const label = (
      read.own(consent.link.label) ?? read.builtIn("consentLinkLabel")
    ).text;
    const href = read.text(consent.link.href);
    resolved.link = href ? { label, href } : { label };
  }
  return resolved;
}

/** A hidden field keeps its column only when the form can write it and does not ask it. */
function resolveHiddenField(
  field: FormHiddenField,
  byId: ReadonlyMap<string, FormColumn>,
  asked: ReadonlySet<string>
): ResolvedFormHiddenField {
  const column = field.columnId ? byId.get(field.columnId) : undefined;
  const editor = column && formColumnEditor(column);
  if (
    !(column && editor && HIDDEN_FIELD_EDITORS.has(editor)) ||
    asked.has(column.id)
  ) {
    return hiddenFieldOf(field.id, field.source);
  }
  return { ...field, editor, options: formOptions(column.options) };
}

/** The column's date preset and pattern, when it sets them. */
function questionDateFormat(
  column: FormColumn
): ResolvedFormQuestion["dateFormat"] {
  const preset =
    typeof column.dateDisplayPreset === "string"
      ? (column.dateDisplayPreset as DateDisplayPreset)
      : undefined;
  const pattern =
    typeof column.dateFormat === "string" ? column.dateFormat : undefined;
  return preset || pattern
    ? { dateDisplayPreset: preset, dateFormat: pattern }
    : undefined;
}

const defaultItems = (eligible: readonly FormColumn[]): FormItem[] =>
  eligible.map((column) => ({ id: column.id, columnId: column.id }));

function resolveItems(
  items: readonly FormItem[],
  byId: Map<string, FormColumn>,
  read: TextReader
): ResolvedFormItem[] {
  return items.flatMap((item): ResolvedFormItem[] => {
    if (isFormSection(item)) {
      return [{ kind: "section", section: resolveSection(item, read) }];
    }
    if (isFormConsent(item)) {
      return [{ kind: "consent", consent: resolveConsent(item, read) }];
    }
    if (!isFormQuestion(item)) {
      return [];
    }
    const column = byId.get(item.columnId);
    const editor = column && formColumnEditor(column);
    return column && editor
      ? [
          {
            kind: "question",
            question: resolveQuestion(item, column, editor, read),
          },
        ]
      : [];
  });
}

const EDITOR_CONDITION: Record<FormEditor, ConditionFieldType> = {
  boolean: "checkbox",
  date: "date",
  // A place is kept as its JSON text in the draft: "is empty" and "is not empty" apply.
  location: "text",
  multiSelect: "multiSelect",
  number: "number",
  select: "select",
  text: "text",
  textarea: "text",
  url: "text",
};

/** Questions as the conditions engine sees them (id, type, label, options). */
export function formConditionFields(
  questions: readonly ResolvedFormQuestion[]
): ConditionField[] {
  return questions.map((question) => ({
    id: question.id,
    type: EDITOR_CONDITION[question.editor],
    label: question.label,
    options: question.options,
    required: question.required,
  }));
}

/** The id of a resolved question, section or consent. */
export const formItemId = (item: ResolvedFormItem): string => {
  if (item.kind === "section") {
    return item.section.id;
  }
  return item.kind === "consent" ? item.consent.id : item.question.id;
};

const itemIds = (items: readonly ResolvedFormItem[]) => items.map(formItemId);

const sectionIds = (items: readonly ResolvedFormItem[]) =>
  items.flatMap((item) => (item.kind === "section" ? [item.section.id] : []));

/**
 * Everything a form renders, with questions limited to columns it can edit.
 * Texts are resolved in `locale`: its exact version, else its language, else
 * the form's default locale; then a text's own default (the column name, a
 * built-in label, with the host's `translate` overrides), else the first
 * version available.
 */
export function resolveFormSettings(
  columns: readonly FormColumn[],
  defaults: unknown,
  view: unknown,
  locale?: string,
  translate?: FormTranslate
): ResolvedFormSettings {
  const settings = mergeFormSettings(defaults, view);
  const defaultLocale = formDefaultLocale(settings);
  const readerLocale = formLocaleTag(locale);
  const read = textReader(readerLocale, defaultLocale, translate);
  const { eligible } = formColumns(columns);
  const byId = new Map(eligible.map((column) => [column.id, column]));
  const saved = settings.questions ?? defaultItems(eligible);
  const items = resolveItems(saved, byId, read);
  const questions = items.flatMap((item) =>
    item.kind === "question" ? [item.question] : []
  );
  const consents = items.flatMap((item) =>
    item.kind === "consent" ? [item.consent] : []
  );
  const asked = new Set(questions.map((question) => question.columnId));
  const hiddenFields = saved
    .filter(isFormHiddenField)
    .map((field) => resolveHiddenField(field, byId, asked));
  const hiddenValues = Object.fromEntries(
    Object.entries(settings.hiddenValues ?? {}).filter(
      ([columnId]) => byId.has(columnId) && !asked.has(columnId)
    )
  );
  const layout = settings.layout ?? "page";
  const { rules } = normalizeRules(
    settings.rules ?? [],
    formConditionFields(questions),
    { targets: sectionIds(items), order: itemIds(items), layout }
  );
  return {
    title: read.text(settings.title),
    description: read.text(settings.description),
    questions,
    items,
    consents,
    hiddenFields,
    rules,
    layout,
    review: settings.review === true,
    hiddenValues,
    // The built-in labels apply when the reader's language has no text.
    submitLabel: read.own(settings.submitLabel)?.text,
    successMessage: read.own(settings.successMessage)?.text,
    closedMessage: read.own(settings.closedMessage)?.text,
    allowAnotherResponse: settings.allowAnotherResponse !== false,
    redirectUrl: settings.redirectUrl,
    ...(readerLocale ? { locale: readerLocale } : {}),
    ...(defaultLocale ? { defaultLocale } : {}),
  };
}

/** The items a settings panel edits: the view's, or one question per editable column. */
export function formQuestionList(
  columns: readonly FormColumn[],
  settings: FormViewSettings
): FormItem[] {
  const { eligible } = formColumns(columns);
  const known = new Set(eligible.map((column) => column.id));
  return (settings.questions ?? defaultItems(eligible)).filter(
    (item) => !isFormQuestion(item) || known.has(item.columnId)
  );
}

/**
 * Move a question, section or consent one place up (-1) or down (+1); other
 * positions are kept. Hidden fields are not shown, so moves pass over them.
 */
export function moveFormQuestion<T extends FormItem>(
  questions: readonly T[],
  id: string,
  offset: -1 | 1
): T[] {
  const index = questions.findIndex((question) => question.id === id);
  let target = index + offset;
  while (isFormHiddenField(questions[target])) {
    target += offset;
  }
  if (index < 0 || target < 0 || target >= questions.length) {
    return [...questions];
  }
  const next = [...questions];
  const [moved] = next.splice(index, 1);
  if (moved) {
    next.splice(target, 0, moved);
  }
  return next;
}

/** Items a settings panel orders (every item but hidden fields). */
export const formOrderedItems = <T extends FormItem>(
  items: readonly T[]
): T[] => items.filter((item) => !isFormHiddenField(item));

/** Ids and asked columns already used by items, for picking a new id. */
const takenIds = (items: readonly FormItem[]) =>
  new Set(
    items.flatMap((item) =>
      isFormQuestion(item) ? [item.id, item.columnId] : [item.id]
    )
  );

/** `base`, else `base-2`, `base-3`… whichever is free. */
function freeId(base: string, taken: ReadonlySet<string>): string {
  let id = base;
  let count = 2;
  while (taken.has(id)) {
    id = `${base}-${count}`;
    count += 1;
  }
  return id;
}

/**
 * Ask a column (after `afterId`, else at the end) or stop asking it; a hidden
 * field writing that column stops writing it.
 */
export function toggleFormQuestion(
  questions: readonly FormItem[],
  columnId: string,
  asked: boolean,
  afterId?: string
): FormItem[] {
  const rest = questions.filter(
    (question) => !isFormQuestion(question) || question.columnId !== columnId
  );
  if (!asked) {
    return rest;
  }
  const kept = rest.map(
    (item): FormItem =>
      isFormHiddenField(item) && item.columnId === columnId
        ? hiddenFieldOf(item.id, item.source)
        : item
  );
  const id = freeId(columnId, takenIds(kept));
  return insertItem(kept, { id, columnId }, afterId);
}

/**
 * Move a question, section or consent to `index` among the ordered items
 * (every item but hidden fields, which keep their places).
 */
export function moveFormItemTo<T extends FormItem>(
  questions: readonly T[],
  id: string,
  index: number
): T[] {
  const ordered = formOrderedItems(questions);
  const from = ordered.findIndex((item) => item.id === id);
  const moved = ordered[from];
  if (!moved) {
    return [...questions];
  }
  const rest = ordered.filter((item) => item !== moved);
  const target = Math.max(0, Math.min(Math.trunc(index), rest.length));
  rest.splice(target, 0, moved);
  let next = 0;
  return questions.map((item) => {
    if (isFormHiddenField(item)) {
      return item;
    }
    const placed = rest[next] ?? item;
    next += 1;
    return placed;
  });
}

type FormItemPatch = Partial<
  Omit<FormQuestion, "columnId" | "id"> &
    Omit<FormSectionBreak, "id" | "kind"> &
    Omit<FormConsentQuestion, "id" | "kind">
>;

/** Change one question, section or consent; empty texts and `required: false` are removed. */
export function updateFormQuestion(
  questions: readonly FormItem[],
  id: string,
  patch: FormItemPatch
): FormItem[] {
  return questions.map((item) => {
    if (item.id !== id) {
      return item;
    }
    if (isFormQuestion(item)) {
      return (
        normalizeQuestion({
          ...item,
          ...patch,
          required: patch.required ?? item.required,
        }) ?? item
      );
    }
    return normalizeItem({ ...item, ...patch, kind: item.kind }) ?? item;
  });
}

/** Insert an item after `afterId`, or at the end. */
function insertItem(
  questions: readonly FormItem[],
  item: FormItem,
  afterId?: string
): FormItem[] {
  const after = afterId
    ? questions.findIndex((entry) => entry.id === afterId) + 1
    : 0;
  const index = after > 0 ? after : questions.length;
  const next: FormItem[] = [...questions];
  next.splice(index, 0, item);
  return next;
}

/** `prefix-N`, from one more than the items of that kind, whichever is free. */
function numberedId(
  prefix: string,
  questions: readonly FormItem[],
  kind: "consent" | "section"
): string {
  const taken = takenIds(questions);
  let count =
    questions.filter((item) => "kind" in item && item.kind === kind).length + 1;
  while (taken.has(`${prefix}-${count}`)) {
    count += 1;
  }
  return `${prefix}-${count}`;
}

/** Add an empty section break after `afterId` (or at the end); returns the items and its id. */
export function addFormSection(
  questions: readonly FormItem[],
  afterId?: string
): { questions: FormItem[]; id: string } {
  const id = numberedId("section", questions, "section");
  return {
    questions: insertItem(questions, { id, kind: "section" }, afterId),
    id,
  };
}

/**
 * Add a consent after `afterId`, or at the end: the steps layout then shows
 * it on the last step (the review, when there is one). It reads the built-in
 * statement in English and French until a text is written.
 */
export function addFormConsent(
  questions: readonly FormItem[],
  afterId?: string
): { questions: FormItem[]; id: string } {
  const id = numberedId("consent", questions, "consent");
  return {
    questions: insertItem(questions, { id, kind: "consent" }, afterId),
    id,
  };
}

/** Labels of the hidden field sources. */
export const FORM_HIDDEN_SOURCE_LABELS: Record<
  FormHiddenSourceType,
  FormLabelKey
> = {
  urlParam: "sourceUrlParam",
  pageUrl: "sourcePageUrl",
  referrer: "sourceReferrer",
  locale: "sourceLocale",
  static: "sourceStatic",
};

const UTM_PARAMS = [
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
];

/** The key a hidden field's value has in `metadata.context` by default: its parameter, or its source. */
export function formHiddenFieldKey(source: FormHiddenSource): string {
  switch (source.type) {
    case "urlParam":
      return source.name;
    case "static":
      return "value";
    default:
      return source.type;
  }
}

/** Add a hidden field (the next free `utm_*` URL parameter); returns the items and its id. */
export function addFormHiddenField(questions: readonly FormItem[]): {
  questions: FormItem[];
  id: string;
} {
  const read = new Set(
    questions.flatMap((item) =>
      isFormHiddenField(item) && item.source.type === "urlParam"
        ? [item.source.name]
        : []
    )
  );
  const name = UTM_PARAMS.find((param) => !read.has(param)) ?? "ref";
  const source: FormHiddenSource = { type: "urlParam", name };
  const id = freeId(formHiddenFieldKey(source), takenIds(questions));
  return { questions: [...questions, { id, kind: "hidden", source }], id };
}

/**
 * Change a hidden field's source or column (`columnId: undefined` keeps the
 * value in the metadata). Its id, the value's key in `metadata.context`,
 * follows the source unless it was chosen otherwise; returns the new id.
 */
export function updateFormHiddenField(
  questions: readonly FormItem[],
  id: string,
  patch: { source?: FormHiddenSource; columnId?: string }
): { questions: FormItem[]; id: string } {
  const field = questions.find(
    (item): item is FormHiddenField => isFormHiddenField(item) && item.id === id
  );
  if (!field) {
    return { questions: [...questions], id };
  }
  const source =
    (patch.source && normalizeFormHiddenSource(patch.source)) ?? field.source;
  const columnId = "columnId" in patch ? patch.columnId : field.columnId;
  const key = formHiddenFieldKey(field.source);
  const follows = id === key || id.startsWith(`${key}-`);
  const others = takenIds(questions.filter((item) => item !== field));
  const nextId =
    follows && source !== field.source
      ? freeId(formHiddenFieldKey(source), others)
      : id;
  const next = hiddenFieldOf(nextId, source, columnId);
  return {
    questions: questions.map((item) => (item === field ? next : item)),
    id: nextId,
  };
}

/** Remove an item (a section's questions stay) and the rules left without a target. */
export function removeFormItem(
  settings: Pick<FormViewSettings, "questions" | "rules">,
  id: string
): Pick<FormViewSettings, "questions" | "rules"> {
  return {
    questions: (settings.questions ?? []).filter((item) => item.id !== id),
    rules: settings.rules
      ?.map((rule) => {
        const then = {
          ...rule.then,
          questionIds: rule.then.questionIds?.filter((target) => target !== id),
        };
        return { ...rule, then };
      })
      .filter((rule) => rule.then.questionIds?.length),
  };
}

/** Remove a section break (its questions stay) and the rules left without a target. */
export const removeFormSection = removeFormItem;

/** Columns a hidden field may write: editable text, number, date, URL, option or yes/no columns not asked nor written by another hidden field. */
export function formHiddenFieldColumns<T extends FormColumn>(
  columns: readonly T[],
  items: readonly FormItem[],
  fieldId?: string
): T[] {
  const asked = new Set(
    items.filter(isFormQuestion).map((question) => question.columnId)
  );
  const bound = new Set(
    items.flatMap((item) =>
      isFormHiddenField(item) && item.id !== fieldId && item.columnId
        ? [item.columnId]
        : []
    )
  );
  return formColumns(columns).eligible.filter((column) => {
    const editor = formColumnEditor(column);
    return (
      editor !== undefined &&
      HIDDEN_FIELD_EDITORS.has(editor) &&
      !asked.has(column.id) &&
      !bound.has(column.id)
    );
  });
}

const emptyAnswer = (editor: FormEditor): boolean | string | string[] => {
  if (editor === "boolean") {
    return false;
  }
  return editor === "multiSelect" ? [] : "";
};

/** Blank answers for every question, and unchecked consents (kept under their ids). */
export function initialFormDraft(
  questions: readonly ResolvedFormQuestion[],
  consents: readonly Pick<ResolvedFormConsent, "id">[] = []
): FormDraft {
  return Object.fromEntries([
    ...questions.map((question) => [
      question.columnId,
      emptyAnswer(question.editor),
    ]),
    ...consents.map((consent) => [consent.id, false]),
  ]);
}

const optionFor = (question: ResolvedFormQuestion, raw: string) =>
  question.options.find((option) => String(option.value) === raw);

function coerceAnswer(
  question: ResolvedFormQuestion,
  raw: FormDraft[string] | undefined
): unknown {
  if (question.editor === "boolean") {
    return raw === true;
  }
  if (question.editor === "multiSelect") {
    const values = Array.isArray(raw) ? raw : [];
    return values.map((item) => optionFor(question, item)?.value ?? item);
  }
  const value = typeof raw === "string" ? raw.trim() : "";
  if (!value) {
    return;
  }
  if (question.editor === "number") {
    const number = Number(value.replace(",", "."));
    return Number.isFinite(number) ? number : value;
  }
  if (question.editor === "select") {
    return optionFor(question, value)?.value ?? value;
  }
  if (question.editor === "location") {
    return parseLocation(value) ?? value;
  }
  return value;
}

/** Typed answers keyed by column id; empty answers are left out. */
export function formDraftValues(
  questions: readonly ResolvedFormQuestion[],
  draft: FormDraft
): Record<string, unknown> {
  const values: Record<string, unknown> = {};
  for (const question of questions) {
    const value = coerceAnswer(question, draft[question.columnId]);
    const empty = Array.isArray(value) && value.length === 0;
    if (value !== undefined && !empty) {
      values[question.columnId] = value;
    }
  }
  return values;
}

export type FormErrorCode =
  | "errorConsent"
  | "errorDate"
  | "errorNumber"
  | "errorOption"
  | "errorRequired"
  | "errorUrl"
  | "errorLocation";

const isBlank = (value: unknown, editor: FormEditor): boolean => {
  if (editor === "boolean") {
    return value !== true;
  }
  if (Array.isArray(value)) {
    return value.length === 0;
  }
  return value === undefined || value === null || value === "";
};

const validDate = (value: unknown): boolean => {
  if (typeof value !== "string" || !DATE_ONLY.test(value)) {
    return false;
  }
  const date = new Date(`${value}T00:00:00Z`);
  return (
    Number.isFinite(date.getTime()) && date.toISOString().startsWith(value)
  );
};

const validUrl = (value: unknown): boolean => {
  try {
    const url = new URL(String(value));
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
};

/** A typed number as its column shows it, or undefined while it is not a number. */
export function formNumberDisplay(
  raw: string,
  format: NumberFormatConfig | undefined,
  locale: string
): string | undefined {
  const value = raw.trim();
  const number = Number(value.replace(",", "."));
  if (!(value && Number.isFinite(number))) {
    return;
  }
  return formatNumberValue(number, format, locale);
}

/**
 * A date answer (`YYYY-MM-DD`) in the reader's language, e.g. "Sep 30, 2026";
 * with the column's date format, the day as the table shows it.
 */
export function formDateDisplay(
  raw: string,
  locale: string,
  format?: ResolvedFormQuestion["dateFormat"]
): string | undefined {
  return validDate(raw)
    ? formatColumnDay(
        raw,
        format ?? { dateDisplayPreset: "localized-medium" },
        locale
      )
    : undefined;
}

/** The answer of a picked calendar day, as `YYYY-MM-DD`. */
export function formDateAnswer(date: Date): string {
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

/**
 * An answer as the review step shows it: option labels, the column's number
 * format, dates in the form's language; `undefined` when unanswered.
 */
export function formAnswerText(
  question: ResolvedFormQuestion,
  raw: FormDraft[string] | undefined,
  locale: string,
  words: { yes: string; no: string }
): string | undefined {
  if (question.editor === "boolean") {
    return raw === true ? words.yes : words.no;
  }
  if (Array.isArray(raw)) {
    return raw.length
      ? raw.map((item) => optionFor(question, item)?.label ?? item).join(", ")
      : undefined;
  }
  const value = typeof raw === "string" ? raw.trim() : "";
  if (!value) {
    return;
  }
  switch (question.editor) {
    case "select":
      return optionFor(question, value)?.label ?? value;
    case "number":
      return formNumberDisplay(value, question.numberFormat, locale) ?? value;
    case "date":
      return formDateDisplay(value, locale, question.dateFormat) ?? value;
    case "location":
      return formatLocation(value) || value;
    default:
      return value;
  }
}

interface WeekInfoLocale {
  getWeekInfo?: () => { firstDay: number };
  weekInfo?: { firstDay: number };
}

/** First day of the week in a locale's calendar: 0 Sunday, 1 Monday, 6 Saturday. */
export function formWeekStart(locale: string): number {
  try {
    const info = new Intl.Locale(locale) as Intl.Locale & WeekInfoLocale;
    const firstDay = (info.getWeekInfo?.() ?? info.weekInfo)?.firstDay;
    if (firstDay) {
      return firstDay % 7;
    }
  } catch {
    // An unknown locale falls back below.
  }
  return locale.toLowerCase().startsWith("en-us") || locale === "en" ? 0 : 1;
}

const knownOption = (question: ResolvedFormQuestion, value: unknown) =>
  question.options.length === 0 ||
  question.options.some((option) => Object.is(option.value, value));

function typeError(
  question: ResolvedFormQuestion,
  value: unknown
): FormErrorCode | undefined {
  switch (question.editor) {
    case "number":
      return typeof value === "number" && Number.isFinite(value)
        ? undefined
        : "errorNumber";
    case "date":
      return validDate(value) ? undefined : "errorDate";
    case "url":
      return validUrl(value) ? undefined : "errorUrl";
    case "location":
      return parseLocation(value) ? undefined : "errorLocation";
    case "select":
      return knownOption(question, value) ? undefined : "errorOption";
    case "multiSelect":
      return Array.isArray(value) &&
        value.every((item) => knownOption(question, item))
        ? undefined
        : "errorOption";
    case "boolean":
      return typeof value === "boolean" ? undefined : "errorOption";
    default:
      return typeof value === "string" ? undefined : "errorRequired";
  }
}

/**
 * Error codes keyed by column id, for typed answers. Runs in the browser and,
 * for public forms, again on the host's server. With an `evaluation` (see
 * `evaluateFormView`), hidden questions are skipped and "required" follows
 * the rules.
 */
export function validateFormValues(
  questions: readonly ResolvedFormQuestion[],
  values: Record<string, unknown>,
  evaluation?: Pick<FormEvaluation, "hidden" | "required">
): Record<string, FormErrorCode> {
  const errors: Record<string, FormErrorCode> = {};
  for (const question of questions) {
    if (evaluation?.hidden.has(question.id)) {
      continue;
    }
    const value = values[question.columnId];
    const required = evaluation
      ? evaluation.required.has(question.id)
      : question.required;
    if (isBlank(value, question.editor)) {
      if (required) {
        errors[question.columnId] = "errorRequired";
      }
      continue;
    }
    const error = typeError(question, value);
    if (error) {
      errors[question.columnId] = error;
    }
  }
  return errors;
}

/**
 * `errorConsent` for each consent not checked, by consent id: `answers` are
 * the draft in the browser, the response's `consents` on the server (`true`
 * for an accepted consent).
 */
export function validateFormConsents(
  consents: readonly Pick<ResolvedFormConsent, "id">[],
  answers: unknown
): Record<string, FormErrorCode> {
  const given = isRecord(answers) ? answers : {};
  return Object.fromEntries(
    consents.flatMap((consent) =>
      Object.hasOwn(given, consent.id) && given[consent.id] === true
        ? []
        : [[consent.id, "errorConsent" as const]]
    )
  );
}

/** Section ids with the questions that follow them, until the next section. Consents stay out: rules never hide them. */
export function formSectionGroups(
  items: readonly ResolvedFormItem[]
): Record<string, string[]> {
  const groups: Record<string, string[]> = {};
  let current: string[] | undefined;
  for (const item of items) {
    if (item.kind === "section") {
      current = [];
      groups[item.section.id] = current;
    } else if (item.kind === "question") {
      current?.push(item.question.id);
    }
  }
  return groups;
}

/**
 * Which questions and sections show, which are required and what `set`
 * rules write, for typed answers keyed by column id.
 */
export function evaluateFormView(
  settings: Pick<ResolvedFormSettings, "items" | "questions" | "rules">,
  values: Record<string, unknown>,
  options: { now?: Date } = {}
): FormEvaluation {
  const answers = Object.fromEntries(
    settings.questions.map((question) => [
      question.id,
      values[question.columnId],
    ])
  );
  return evaluateForm(
    settings.rules,
    answers,
    formConditionFields(settings.questions),
    { now: options.now, groups: formSectionGroups(settings.items) }
  );
}

/** Answers keyed by column id without hidden questions, with `set` values applied. */
export function formVisibleValues(
  settings: Pick<ResolvedFormSettings, "items" | "questions" | "rules">,
  values: Record<string, unknown>,
  evaluation: FormEvaluation = evaluateFormView(settings, values)
): Record<string, unknown> {
  const output = { ...values };
  for (const question of settings.questions) {
    if (evaluation.hidden.has(question.id)) {
      Reflect.deleteProperty(output, question.columnId);
    } else if (Object.hasOwn(evaluation.setValues, question.id)) {
      output[question.columnId] = evaluation.setValues[question.id];
    }
  }
  return output;
}

// Hidden fields and consents -------------------------------------------------

/** What hidden fields read from the page: its address, referrer and the form's language. */
export interface FormPageContext {
  url?: string;
  referrer?: string;
  locale?: string;
}

/** The page the form is shown on, in a browser; empty on a server. */
export function formPageContext(locale?: string): FormPageContext {
  const page = typeof window === "undefined" ? undefined : window;
  const url = page?.location.href;
  const referrer = page?.document.referrer;
  return {
    ...(url ? { url } : {}),
    ...(referrer ? { referrer } : {}),
    ...(locale ? { locale } : {}),
  };
}

const FIRST_PRINTABLE = 32;
const DELETE = 127;

const withoutControls = (value: string): string =>
  Array.from(value)
    .filter((char) => {
      const code = char.codePointAt(0) ?? 0;
      return code >= FIRST_PRINTABLE && code !== DELETE;
    })
    .join("");

/** Text only, without control characters, cut at `max`. */
function hiddenText(value: unknown, max: number): string | undefined {
  if (typeof value !== "string") {
    return;
  }
  const content = withoutControls(value).trim();
  return content ? content.slice(0, max) : undefined;
}

/**
 * A page or referrer address: http(s) only, dropped when too long, kept
 * without its query and fragment, which may hold tokens or personal data
 * (campaign parameters are read with `urlParam` fields).
 */
function hiddenAddress(value: unknown): string | undefined {
  const address =
    typeof value === "string" ? withoutControls(value).trim() : "";
  if (address.length > FORM_HIDDEN_URL_MAX || !validUrl(address)) {
    return;
  }
  const url = new URL(address);
  return `${url.origin}${url.pathname}`;
}

/** A hidden value as the server keeps it: from the field's own source, as capped text. */
function acceptHiddenValue(
  field: FormHiddenField,
  raw: unknown
): string | undefined {
  switch (field.source.type) {
    case "static":
      return field.source.value.slice(0, FORM_HIDDEN_TEXT_MAX);
    case "locale":
      return formLocaleTag(hiddenText(raw, FORM_HIDDEN_TEXT_MAX));
    case "pageUrl":
    case "referrer":
      return hiddenAddress(raw);
    default:
      return hiddenText(raw, FORM_HIDDEN_TEXT_MAX);
  }
}

/** The value a bound column takes from a hidden text, checked like an answer. */
function hiddenColumnValue(
  field: ResolvedFormHiddenField,
  value: string
): unknown {
  switch (field.editor) {
    case "number": {
      const number = Number(value.replace(",", "."));
      return Number.isFinite(number) ? number : undefined;
    }
    case "date":
      return validDate(value) ? value : undefined;
    case "url":
      return validUrl(value) ? value : undefined;
    case "select":
      return (field.options ?? []).find(
        (option) => String(option.value) === value
      )?.value;
    case "boolean":
      if (value === "true" || value === "false") {
        return value === "true";
      }
      return;
    case "text":
    case "textarea":
      return value;
    default:
      return;
  }
}

/**
 * Hidden field values, checked as a server does: each field reads only its
 * own source from `input` (untrusted, by field id), as capped text; fixed
 * texts come from the settings, never from `input`. Bound fields give column
 * `values`, checked like answers (a value that does not fit is dropped); the
 * others give `context`, kept in the response's metadata.
 */
export function acceptFormHiddenFields(
  fields: readonly ResolvedFormHiddenField[],
  input: unknown
): { values: Record<string, unknown>; context: Record<string, string> } {
  const given = isRecord(input) ? input : {};
  const values: Record<string, unknown> = {};
  const context: Record<string, string> = {};
  for (const field of fields) {
    const raw = Object.hasOwn(given, field.id) ? given[field.id] : undefined;
    const value = acceptHiddenValue(field, raw);
    const typed =
      value !== undefined && field.columnId && field.editor
        ? hiddenColumnValue(field, value)
        : undefined;
    if (field.columnId && field.editor) {
      if (typed !== undefined) {
        values[field.columnId] = typed;
      }
    } else if (value !== undefined) {
      context[field.id] = value;
    }
  }
  return { values, context };
}

const pageParams = (url: string | undefined): URLSearchParams | undefined => {
  try {
    return url ? new URL(url).searchParams : undefined;
  } catch {
    return;
  }
};

function pageValue(
  source: FormHiddenSource,
  page: FormPageContext,
  params: URLSearchParams | undefined
): string | undefined {
  switch (source.type) {
    case "urlParam":
      return params?.get(source.name) ?? undefined;
    case "pageUrl":
      return page.url;
    case "referrer":
      return page.referrer;
    case "locale":
      return page.locale;
    default:
      // Fixed texts come from the settings, or the server's snapshot.
      return;
  }
}

/**
 * Hidden field values read from the page, by field id, for `onSubmit`'s
 * `meta.fields`. Hosts send them on; the server checks them again with
 * `acceptPublicFormResponse`.
 */
export function collectFormHiddenFields(
  fields: readonly FormHiddenField[],
  page: FormPageContext
): Record<string, string> {
  const params = pageParams(page.url);
  const values: Record<string, string> = {};
  for (const field of fields) {
    const raw = pageValue(field.source, page, params);
    const value =
      field.source.type === "static"
        ? undefined
        : acceptHiddenValue(field, raw);
    if (value !== undefined) {
      values[field.id] = value;
    }
  }
  return values;
}

const LINK_TOKEN = "{link}";

/** A consent statement around its link: `{link}` marks its place, else the link follows in parentheses. */
export function formConsentParts(consent: ResolvedFormConsent): {
  before: string;
  link?: { label: string; href?: string };
  after: string;
} {
  const index = consent.text.indexOf(LINK_TOKEN);
  if (!consent.link) {
    return { before: consent.text.replaceAll(LINK_TOKEN, ""), after: "" };
  }
  if (index < 0) {
    return { before: `${consent.text} (`, link: consent.link, after: ")" };
  }
  return {
    before: consent.text.slice(0, index),
    link: consent.link,
    after: consent.text.slice(index + LINK_TOKEN.length),
  };
}

/** The statement as read, the link's text in place: "I agree to the processing… in the privacy policy." */
export function formConsentStatement(consent: ResolvedFormConsent): string {
  const { before, link, after } = formConsentParts(consent);
  return `${before}${link?.label ?? ""}${after}`.trim();
}

/** A consent accepted with a response, as `metadata.consents` records it. */
export interface FormConsentRecord {
  id: string;
  version: string;
  /** The statement as shown, in the response's language, the link's text in place. */
  text: string;
  /** The link's address, when the statement has one. */
  href?: string;
  /** The language the statement is written in, when it is known. */
  locale?: string;
  /** When the host's server received the response (`acceptedAt`). */
  acceptedAt?: string;
}

/** A value of what the host's server knows about a response. */
export type FormServerContextValue = boolean | number | string;

/** What a response carries besides its column values; never written to a column. */
export interface FormResponseMetadata {
  /** The consents accepted, with their version and statement. */
  consents: FormConsentRecord[];
  /** Hidden fields not bound to a column, by field id (page values, checked). */
  context: Record<string, string>;
  /** What the host's server adds (`withFormServerContext`): page, revision, form token… */
  server?: Record<string, FormServerContextValue>;
}

/**
 * The metadata of a response: its consents (all accepted), each with the
 * statement as shown and the language it is written in, and the hidden
 * fields kept out of columns.
 */
export function formResponseMetadata(
  settings: Pick<ResolvedFormSettings, "consents">,
  context: Record<string, string>,
  acceptedAt?: string
): FormResponseMetadata {
  return {
    consents: settings.consents.map((consent) => ({
      id: consent.id,
      version: consent.version,
      text: formConsentStatement(consent),
      ...(consent.link?.href ? { href: consent.link.href } : {}),
      ...(consent.locale ? { locale: consent.locale } : {}),
      ...(acceptedAt ? { acceptedAt } : {}),
    })),
    context,
  };
}

/**
 * What `YayawTableForm` gives `onSubmit` besides the record. A public form's
 * host sends `consents`, `fields` and `locale` to its server with the answers,
 * where `acceptPublicFormResponse` checks them again.
 */
export interface FormSubmitMeta {
  /** The host's `context`, unchanged. */
  context?: Record<string, unknown>;
  /** Consents checked, by consent id. */
  consents: Record<string, true>;
  /** Hidden field values read from the page, by field id (untrusted). */
  fields: Record<string, string>;
  /** The language the form was shown in. */
  locale: string;
  /** The response's metadata as the browser sees it; servers rebuild it with `acceptPublicFormResponse`. */
  metadata: FormResponseMetadata;
}

/** The first question or consent with an error, in form order (errors are keyed by column id or consent id). */
export function formFirstError(
  items: readonly ResolvedFormItem[],
  errors: Record<string, unknown>
): { kind: "consent" | "question"; id: string } | undefined {
  for (const item of items) {
    if (item.kind === "question" && errors[item.question.columnId]) {
      return { kind: "question", id: item.question.id };
    }
    if (item.kind === "consent" && errors[item.consent.id]) {
      return { kind: "consent", id: item.consent.id };
    }
  }
}

/** `onSubmit`'s meta for a response whose consents are all checked (it was validated). */
export function formSubmitMeta(
  settings: Pick<ResolvedFormSettings, "consents" | "hiddenFields" | "locale">,
  fields: Record<string, string>,
  locale: string,
  context?: Record<string, unknown>
): FormSubmitMeta {
  const hidden = acceptFormHiddenFields(settings.hiddenFields, fields);
  return {
    context,
    consents: Object.fromEntries(
      settings.consents.map((consent) => [consent.id, true as const])
    ),
    fields,
    locale: settings.locale ?? locale,
    metadata: formResponseMetadata(settings, hidden.context),
  };
}

/**
 * The record a response creates: fixed values, then the hidden fields bound
 * to a column (`fields`: their values read from the page, by field id), then
 * the visible answers.
 */
export function formSubmission(
  settings: ResolvedFormSettings,
  values: Record<string, unknown>,
  fields?: Record<string, unknown>
): Record<string, unknown> {
  const hidden = acceptFormHiddenFields(settings.hiddenFields ?? [], fields);
  return {
    ...settings.hiddenValues,
    ...hidden.values,
    ...formVisibleValues(settings, values),
  };
}

/** One screen of the steps layout: a question, or a section and its questions. */
export interface FormStep {
  id: string;
  section?: ResolvedFormSection;
  questions: ResolvedFormQuestion[];
  /** Consents shown on this step, after its questions. */
  consents?: ResolvedFormConsent[];
}

const stepsBySection = (
  items: readonly ResolvedFormItem[],
  visible: (id: string) => boolean
): FormStep[] => {
  const steps: FormStep[] = [];
  let current: FormStep = { id: "start", questions: [] };
  for (const item of items) {
    if (item.kind === "section") {
      steps.push(current);
      current = { id: item.section.id, section: item.section, questions: [] };
    } else if (item.kind === "question" && visible(item.question.id)) {
      current.questions.push(item.question);
    }
  }
  steps.push(current);
  return steps.filter(
    (step) =>
      step.questions.length > 0 && (!step.section || visible(step.section.id))
  );
};

type StepSettings = Pick<ResolvedFormSettings, "items"> & { review?: boolean };

/** What placing consents needs to know about the steps. */
interface StepScan {
  items: readonly ResolvedFormItem[];
  /** Step of each visible question. */
  stepOf: Map<string, string>;
  shown: Set<string>;
  sectioned: boolean;
  review: boolean;
  last?: string;
}

/** The step of the first visible question after `index`. */
function stepAfter(scan: StepScan, index: number): string | undefined {
  const question = scan.items
    .slice(index + 1)
    .find(
      (entry) => entry.kind === "question" && scan.stepOf.has(entry.question.id)
    );
  return question?.kind === "question"
    ? scan.stepOf.get(question.question.id)
    : undefined;
}

/** The step a consent at `index` shows on, or `undefined` for the review. */
function consentStep(
  scan: StepScan,
  index: number,
  section: string,
  previous: string | undefined
): string | undefined {
  const next = stepAfter(scan, index);
  if (!next) {
    return scan.review ? undefined : scan.last;
  }
  if (scan.sectioned) {
    return scan.shown.has(section) ? section : next;
  }
  return previous ?? next;
}

/**
 * Where each consent shows in the steps layout: on the step it is placed in
 * (its section, or the question before it); after the last visible question,
 * or when its step is skipped, on the last step, the review when there is one.
 */
function consentPlaces(
  settings: StepSettings,
  steps: readonly FormStep[]
): {
  byStep: Map<string, ResolvedFormConsent[]>;
  review: ResolvedFormConsent[];
} {
  const scan: StepScan = {
    items: settings.items,
    stepOf: new Map(
      steps.flatMap((step) =>
        step.questions.map((question) => [question.id, step.id] as const)
      )
    ),
    shown: new Set(steps.map((step) => step.id)),
    sectioned: settings.items.some((item) => item.kind === "section"),
    review: settings.review === true,
    last: steps.at(-1)?.id,
  };
  const byStep = new Map<string, ResolvedFormConsent[]>();
  const review: ResolvedFormConsent[] = [];
  let section = "start";
  let previous: string | undefined;
  for (const [index, item] of settings.items.entries()) {
    if (item.kind === "section") {
      section = item.section.id;
    } else if (item.kind === "question") {
      previous = scan.stepOf.get(item.question.id) ?? previous;
    } else {
      const place = consentStep(scan, index, section, previous);
      if (place) {
        byStep.set(place, [...(byStep.get(place) ?? []), item.consent]);
      } else {
        review.push(item.consent);
      }
    }
  }
  return { byStep, review };
}

function plainSteps(
  settings: StepSettings,
  visible: (id: string) => boolean
): FormStep[] {
  if (settings.items.some((item) => item.kind === "section")) {
    return stepsBySection(settings.items, visible);
  }
  return settings.items.flatMap((item) =>
    item.kind === "question" && visible(item.question.id)
      ? [{ id: item.question.id, questions: [item.question] }]
      : []
  );
}

/** Id of the step holding the consents of a form whose questions are all hidden. */
export const CONSENT_STEP = "consents";

/** The steps of the steps layout and the consents of its review step. */
export interface FormStepPlan {
  steps: FormStep[];
  /** Consents shown on the review step (with `review`). */
  reviewConsents: ResolvedFormConsent[];
}

/**
 * Steps of the steps layout, skipping what the rules hide: one per question,
 * or one per section when the form has section breaks. Consents show on the
 * step they are placed in; those placed last show on the last step, the
 * review when the form has one. When the rules hide every question, the
 * consents still get a step of their own.
 */
export function formStepPlan(
  settings: StepSettings,
  evaluation?: Pick<FormEvaluation, "hidden">
): FormStepPlan {
  const visible = (id: string) => !evaluation?.hidden.has(id);
  const plain = plainSteps(settings, visible);
  const { byStep, review } = consentPlaces(settings, plain);
  const steps = plain.map((step) => ({
    ...step,
    consents: byStep.get(step.id) ?? [],
  }));
  if (settings.review || !review.length) {
    return { steps, reviewConsents: settings.review ? review : [] };
  }
  return {
    steps: [...steps, { id: CONSENT_STEP, questions: [], consents: review }],
    reviewConsents: [],
  };
}

/** The steps of `formStepPlan`. */
export const formSteps = (
  settings: StepSettings,
  evaluation?: Pick<FormEvaluation, "hidden">
): FormStep[] => formStepPlan(settings, evaluation).steps;

/** The review step's consents of `formStepPlan`: those placed after the last visible question. */
export const formReviewConsents = (
  settings: StepSettings,
  evaluation?: Pick<FormEvaluation, "hidden">
): ResolvedFormConsent[] => formStepPlan(settings, evaluation).reviewConsents;

/** Whether a step may be skipped: none of its visible questions is required, and it asks no consent. */
export const formStepOptional = (
  step: FormStep,
  evaluation: Pick<FormEvaluation, "required">
): boolean =>
  !(
    step.questions.some((question) => evaluation.required.has(question.id)) ||
    step.consents?.length
  );

