  overflow-y: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--yayaw-border);
  border-radius: 6px;
  padding: 4px;
  color: var(--yayaw-foreground);
  background: var(--yayaw-background);
  box-shadow: var(--yayaw-shadow);
  font:
    14px / 1.4 ui-sans-serif,
    system-ui,
    sans-serif;
}
.yayaw-inline-option {
  position: relative;
  display: flex;
  align-items: center;
  border-radius: 4px;
  padding: 6px 32px 6px 8px;
  outline: none;
  cursor: default;
  user-select: none;
}
.yayaw-inline-option[data-highlighted] {
  background: var(--yayaw-muted);
}
.yayaw-inline-option[data-disabled] {
  pointer-events: none;
  opacity: 0.5;
}
.yayaw-inline-check {
  position: absolute;
  right: 8px;
  display: flex;
}
.yayaw-inline-empty {
  padding: 8px;
  text-align: center;
  color: var(--yayaw-muted-foreground);
}
.yayaw-inline-progress {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 2px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--yayaw-muted);
}
.yayaw-inline-progress-bar {
  height: 100%;
  background: var(--yayaw-primary);
  transition: width 75ms;
}
.yayaw-inline-progress.is-saving .yayaw-inline-progress-bar {
  animation: yayaw-inline-pulse 1.5s ease-in-out infinite;
}
@keyframes yayaw-inline-pulse {
  50% {
    opacity: 0.5;
  }
}
@media (prefers-reduced-motion: reduce) {
  .yayaw-inline-progress-bar {
    transition: none;
    animation: none;
  }
}
.yayaw-inline-error,
.yayaw-field-error {
  display: block;
  margin-top: 4px;
  color: var(--yayaw-danger);
  font-size: 12px;
}
.yayaw-code,
.yayaw-json {
  margin: 0;
  border-radius: 4px;
  background: var(--yayaw-muted);
  padding: 2px 5px;
  font-family: ui-monospace, monospace;
  font-size: 12px;
}
.yayaw-json {
  max-width: 360px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-number {
  display: block;
  text-align: right;
}
.yayaw-cell-image {
  width: 38px;
  height: 38px;
  border-radius: 6px;
  object-fit: cover;
}
.yayaw-link {
  color: #2563eb;
  text-decoration: none;
}
.yayaw-tags {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
}
.yayaw-tag {
  display: inline-flex;
  border: 1px solid transparent;
  border-radius: 0.35rem;
  background: var(--yayaw-muted);
  padding: 2px 8px;
  font-size: 12px;
}
/* A checkbox-style mark, as in React: filled with a check for true, empty for false. */
.yayaw-boolean {
  display: inline-flex;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  box-sizing: border-box;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--yayaw-input);
  border-radius: 4px;
  background: transparent;
  box-shadow: var(--yayaw-shadow-xs);
  vertical-align: middle;
}
.yayaw-boolean[data-value="true"] {
  border-color: var(--yayaw-primary);
  background: var(--yayaw-primary);
  color: var(--yayaw-primary-foreground);
}
.yayaw-empty {
  text-align: center;
}
/* Shadcn Empty layout, shared by the table and card displays. */
.yayaw-empty-root {
  box-sizing: border-box;
  display: flex;
  width: 100%;
  min-width: 0;
  min-height: 160px;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  border-radius: var(--yayaw-radius);
  padding: 40px 16px;
  color: var(--yayaw-foreground);
  text-align: center;
  text-wrap: balance;
  white-space: normal;
}
.yayaw-card-empty {
  border: 1px solid var(--yayaw-border);
}
.yayaw-empty-header {
  display: flex;
  max-width: 384px;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.yayaw-empty-media {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  margin-bottom: 8px;
}
.yayaw-empty-media[data-variant="icon"] {
  width: 40px;
  height: 40px;
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-muted);
  color: var(--yayaw-foreground);
}
.yayaw-empty-media svg {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  pointer-events: none;
}
.yayaw-empty-title {
  font-size: 18px;
  font-weight: 500;
  letter-spacing: -0.025em;
}
.yayaw-empty-description {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
  line-height: 1.625;
}
.yayaw-empty-description > a {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.yayaw-empty-description > a:hover {
  color: var(--yayaw-primary);
}
.yayaw-empty-content {
  display: flex;
  width: 100%;
  max-width: 384px;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  font-size: 14px;
}
.yayaw-empty-reset:focus-visible {
  outline: 2px solid var(--yayaw-primary);
  outline-offset: 2px;
}
.yayaw-calculation small,
.yayaw-calculation strong {
  display: block;
}
.yayaw-calculation small {
  color: var(--yayaw-muted-foreground);
  font-size: 10px;
  text-transform: uppercase;
}
.yayaw-calculation-trigger {
  display: block;
  width: 100%;
  max-width: 100%;
  padding: 2px 4px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: inherit;
  cursor: pointer;
}
.yayaw-calculation-trigger:hover,
.yayaw-calculation-trigger[data-state="open"] {
  background: var(--yayaw-muted);
}
.yayaw-calculation-trigger:focus-visible {
  outline: 2px solid var(--yayaw-primary);
  outline-offset: 2px;
}
.yayaw-calculation-empty {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-calculation-menu {
  max-height: var(--reka-dropdown-menu-content-available-height);
  overflow-y: auto;
}
.yayaw-calculation-option {
  justify-content: space-between;
}
.yayaw-pagination {
  justify-content: flex-end;
  min-height: 54px;
  padding: 8px 12px;
}
.yayaw-pagination > span:first-child {
  margin-right: auto;
  color: var(--yayaw-muted-foreground);
}
.yayaw-loading-overlay {
  position: absolute;
  z-index: 20;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: var(--yayaw-radius);
  background: color-mix(in srgb, var(--yayaw-background) 72%, transparent);
  backdrop-filter: blur(1px);
}
.yayaw-row-actions {
  justify-content: center;
}
.yayaw-row-actions > .yayaw-icon-button {
  width: 32px;
  min-width: 32px;
  height: var(--yayaw-density-control, 32px);
  min-height: var(--yayaw-density-control, 32px);
  padding: 0;
}
.yayaw-row-actions-menu {
  z-index: 90;
  display: grid;
  min-width: 128px;
  gap: 0;
  border: 0;
  border-radius: 6px;
  background: var(--yayaw-background);
  box-shadow:
    0 0 0 1px var(--yayaw-border),
    var(--yayaw-shadow);
  padding: 4px;
  color: var(--yayaw-foreground);
  font:
    14px / 1.4 ui-sans-serif,
    system-ui,
    sans-serif;
}
.yayaw-row-actions-menu,
.yayaw-row-actions-menu * {
  box-sizing: border-box;
}
.yayaw-row-action-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  border: 0;
  min-height: 32px;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  padding: 6px 8px;
  text-align: left;
  cursor: pointer;
}
.yayaw-row-action-item:hover,
.yayaw-row-action-item:focus-visible,
.yayaw-row-action-item[data-highlighted] {
  background: var(--yayaw-muted);
  outline: none;
}
.yayaw-row-action-item:disabled,
.yayaw-row-action-item[data-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}
.yayaw-row-action-danger {
  color: var(--yayaw-danger);
}
.yayaw-row-actions-divider {
  height: 1px;
  margin: 4px -4px;
  background: var(--yayaw-border);
}
.yayaw-bulk-menu-wrapper {
  z-index: 50;
  display: flex;
  width: 100%;
  justify-content: center;
  pointer-events: none;
  animation: yayaw-bulk-enter 0.3s ease-out;
}
.yayaw-bulk-menu-wrapper[data-position="fixed"] {
  position: fixed;
  right: 0;
  bottom: 24px;
  left: 0;
  padding-inline: 16px;
}
.yayaw-bulk-menu-wrapper[data-position="anchored"] {
  position: relative;
  padding-inline: 0;
}
.yayaw-bulk-anchor {
  width: 100%;
  height: 0;
}
@keyframes yayaw-bulk-enter {
  from {
    transform: translateY(8px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}
.yayaw-bulk-bar {
  display: flex;
  width: fit-content;
  max-width: 100%;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--yayaw-border);
  border-radius: 16px;
  background: color-mix(in srgb, var(--yayaw-muted) 95%, transparent);
  box-shadow:
    0 20px 25px -5px rgba(0, 0, 0, 0.1),
    0 8px 10px -6px rgba(0, 0, 0, 0.1);
  padding: 4px;
  backdrop-filter: blur(10px);
  pointer-events: auto;
}
.yayaw-bulk-count {
  display: flex;
  flex: none;
  align-items: center;
  gap: 8px;
  padding-inline: 12px;
  color: var(--yayaw-foreground);
  font-size: 14px;
  white-space: nowrap;
}
.yayaw-bulk-count strong {
  font-weight: 500;
}
.yayaw-bulk-count-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--yayaw-primary);
  animation: yayaw-pulse 2s ease-in-out infinite;
}
@keyframes yayaw-pulse {
  50% {
    opacity: 0.5;
  }
}
.yayaw-bulk-action-tab {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  gap: 0;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: var(--yayaw-muted-foreground);
  padding: 8px;
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition:
    gap 0.6s cubic-bezier(0.22, 1, 0.36, 1) 0.1s,
    padding 0.6s cubic-bezier(0.22, 1, 0.36, 1) 0.1s,
    background 0.3s ease,
    color 0.3s ease;
}
.yayaw-bulk-action-tab:hover,
.yayaw-bulk-action-tab:focus-visible {
  gap: 8px;
  background: color-mix(in srgb, var(--yayaw-background) 80%, transparent);
  color: var(--yayaw-foreground);
  padding-inline: 16px;
  outline: none;
}
.yayaw-bulk-action-tab:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}
.yayaw-bulk-action-label {
  max-width: 0;
  overflow: hidden;
  opacity: 0;
  white-space: nowrap;
  transition:
    max-width 0.6s cubic-bezier(0.22, 1, 0.36, 1) 0.1s,
    opacity 0.6s cubic-bezier(0.22, 1, 0.36, 1) 0.1s;
}
.yayaw-bulk-action-tab:hover .yayaw-bulk-action-label,
.yayaw-bulk-action-tab:focus-visible .yayaw-bulk-action-label {
  max-width: 160px;
  opacity: 1;
}
.yayaw-bulk-action-danger {
  color: var(--yayaw-danger);
}
.yayaw-bulk-action-fallback {
  font-size: 11px;
  font-weight: 700;
}
.yayaw-bulk-divider {
  width: 1.2px;
  height: 24px;
  flex: none;
  margin-inline: 4px;
  background: var(--yayaw-border);
}
.yayaw-bulk-divider + .yayaw-bulk-action-tab {
  width: 32px;
  height: 32px;
  padding: 0;
}
.yayaw-bulk-divider + .yayaw-bulk-action-tab:hover,
.yayaw-bulk-divider + .yayaw-bulk-action-tab:focus-visible {
  padding: 0;
}
.yayaw-status,
.yayaw-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
  border: 1px solid #fecaca;
  border-radius: var(--yayaw-radius);
  background: #fef2f2;
  color: #991b1b;
  padding: 9px 12px;
}
.yayaw-status[data-type="success"] {
  border-color: #bbf7d0;
  background: #f0fdf4;
  color: #166534;
}
.yayaw-status button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.yayaw-card-view-shell {
  display: grid;
  gap: 12px;
}
.yayaw-card-controls {
  flex-wrap: wrap;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  padding: 8px;
}
/* Shadcn Vue controls share Reka focus, selection, and portal behavior. */
.yayaw-control-field {
  display: inline-flex;
  min-width: 0;
  max-width: 100%;
  align-items: center;
  gap: 8px;
}
.yayaw-control-field > label {
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  white-space: nowrap;
}
.yayaw-select-trigger,
.yayaw-card-control-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  height: 32px;
  min-height: 32px;
  padding: 6px 10px;
  border: 1px solid var(--yayaw-border);
  border-radius: 6px;
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  font: inherit;
  font-size: 13px;
  font-weight: 400;
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.04);
  cursor: pointer;
}
.yayaw-select-trigger {
  min-width: 96px;
  max-width: 220px;
}
.yayaw-select-trigger > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-select-trigger > svg {
  flex-shrink: 0;
  color: var(--yayaw-muted-foreground);
}
.yayaw-select-trigger:hover,
.yayaw-card-control-button:hover,
.yayaw-card-control-button[data-state="open"] {
  background: var(--yayaw-muted);
}
.yayaw-select-trigger:focus-visible,
.yayaw-card-control-button:focus-visible,
.yayaw-checkbox:focus-visible,
.yayaw-kanban-move-actions button:focus-visible {
  outline: 2px solid var(--yayaw-primary);
  outline-offset: 2px;
}
.yayaw-select-trigger[data-disabled],
.yayaw-checkbox[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}
.yayaw-select-content {
  /* Above modal dialogs, e.g. the layout choice when saving a view. */
  z-index: 120;
  min-width: var(--reka-select-trigger-width);
  max-width: min(320px, calc(100vw - 16px));
  max-height: min(320px, var(--reka-select-content-available-height));
  overflow: hidden;
}
.yayaw-select-viewport {
  max-height: inherit;
}
.yayaw-select-item,
.yayaw-control-check-item {
  position: relative;
  padding-right: 32px;
  border-radius: 4px;
  user-select: none;
}
.yayaw-control-indicator {
  position: absolute;
  right: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.yayaw-select-scroll {
  display: flex;
  justify-content: center;
  padding: 4px;
}
.yayaw-card-properties-menu {
  width: 224px;
  max-width: calc(100vw - 16px);
  max-height: var(--reka-dropdown-menu-content-available-height);
  overflow-y: auto;
}
.yayaw-control-menu-label {
  padding: 6px 8px;
  font-size: 12px;
  font-weight: 500;
  color: var(--yayaw-muted-foreground);
}
.yayaw-checkbox {
  box-sizing: border-box;
  display: inline-flex;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid var(--yayaw-input);
  border-radius: 4px;
  background: transparent;
  color: var(--yayaw-primary-foreground);
  box-shadow: var(--yayaw-shadow-xs);
  cursor: pointer;
}
.yayaw-checkbox[data-state="checked"] {
  border-color: var(--yayaw-primary);
  background: var(--yayaw-primary);
}
.yayaw-checkbox-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
}
.yayaw-kanban {
  display: grid;
  grid-auto-columns: 18rem;
  grid-auto-flow: column;
  gap: 12px;
  overflow-x: auto;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  padding: 12px;
}
.yayaw-kanban-lane {
  min-height: 28rem;
  overflow: hidden;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: color-mix(
    in oklab,
    var(--yayaw-muted) 20%,
    var(--yayaw-background)
  );
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.05);
}
.yayaw-kanban-lane > header {
  display: flex;
  height: 44px;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--yayaw-border);
  padding: 0 12px;
  font-weight: 500;
}
.yayaw-kanban-lane > header .yayaw-count {
  border-radius: 999px;
  background: var(--yayaw-background);
  padding: 2px 8px;
}
.yayaw-kanban-cards {
  display: grid;
  gap: 8px;
  padding: 8px;
}
.yayaw-card {
  overflow: hidden;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
  transition:
    box-shadow 0.15s,
    transform 0.15s;
}
.yayaw-card:hover,
.yayaw-card:focus {
  border-color: color-mix(
    in oklab,
    var(--yayaw-primary) 40%,
    var(--yayaw-border)
  );
  background: color-mix(
    in oklab,
    var(--yayaw-muted) 20%,
    var(--yayaw-background)
  );
  outline: none;
}
.yayaw-kanban-card {
  padding: 8px;
}
.yayaw-card.pending {
  opacity: 0.55;
}
.yayaw-card-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.yayaw-card-header strong {
  min-width: 0;
  flex: 1;
  font-size: 14px;
  font-weight: 500;
}
.yayaw-kanban-move-actions {
  display: inline-flex;
  gap: 2px;
}
.yayaw-card-select {
  display: inline-flex;
  align-items: center;
  padding-top: 2px;
  cursor: pointer;
}
.yayaw-card-properties {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin: 8px 0 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-card-properties:not(.labeled) dd[data-type="number"],
.yayaw-card-properties:not(.labeled) dd[data-type="date"] {
  border-radius: 999px;
  background: color-mix(in oklab, var(--yayaw-muted) 70%, transparent);
  padding: 2px 8px;
  font-size: 11px;
}
.yayaw-card-properties:not(.labeled) dd[data-type="date"] {
  color: var(--yayaw-muted-foreground);
}
.yayaw-card-properties.labeled {
  display: grid;
  grid-template-columns: 5.5rem minmax(0, 1fr);
  gap: 8px;
}
.yayaw-card-properties dt {
  color: var(--yayaw-muted-foreground);
}
.yayaw-card-properties dd {
  min-width: 0;
  overflow: hidden;
  margin: 0;
  color: var(--yayaw-foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-gallery-section {
  display: grid;
  gap: 8px;
}
.yayaw-gallery-section > h3 {
  margin: 12px 0 0;
  font-size: 14px;
}
.yayaw-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 16rem), 1fr));
  gap: 12px;
}
.yayaw-gallery[data-size="small"] {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 12rem), 1fr));
}
.yayaw-gallery[data-size="large"] {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 22rem), 1fr));
}
.yayaw-gallery-media {
  position: relative;
  display: grid;
