  background: #3b82f6;
}

/* View panels use compact Shadcn menu rows; only constrained content scrolls. */
.yayaw-toolbar-menu-header {
  padding: 4px 8px;
}
.yayaw-toolbar-menu .yayaw-options-list {
  gap: 0;
  padding: 4px;
}
.yayaw-toolbar-menu .yayaw-options-item {
  min-height: 32px;
  padding: 6px 8px;
  gap: 8px;
  border-radius: 4px;
}
.yayaw-toolbar-menu .yayaw-options-item-icon {
  width: 16px;
  height: 16px;
}
.yayaw-toolbar-menu .yayaw-options-item-count {
  min-width: 16px;
  width: auto;
  height: auto;
  background: transparent;
  color: var(--yayaw-muted-foreground);
  font-variant-numeric: tabular-nums;
}
.yayaw-toolbar-menu .yayaw-options-item-end {
  width: auto;
  min-width: 16px;
  font-size: 12px;
}
.yayaw-toolbar-menu :is(.yayaw-view-selection, .yayaw-view-write-actions) {
  padding: 4px;
}
.yayaw-toolbar-menu .yayaw-view-menu-item {
  min-height: 32px;
  padding: 6px 8px;
  border-radius: 4px;
  gap: 8px;
}
/* On phones the views, and their actions (Move up, Move down…), are touch targets, as in React. */
.yayaw-toolbar-menu[data-compact="true"] .yayaw-view-menu-item {
  min-height: 44px;
}

/* Bulk edits use flat property rows and a footer outside the scrolling body. */
.yayaw-form-surface[data-bulk-editor] {
  display: flex;
  flex-direction: column;
  width: min(32rem, calc(100vw - 2rem));
  max-height: 85dvh;
  overflow: clip;
}
.yayaw-form-surface[data-bulk-editor] .yayaw-form-header {
  position: static;
  flex-shrink: 0;
  padding: 20px 24px 16px;
  border-bottom: 0;
}
.yayaw-bulk-form {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: 0;
  padding: 0;
}
.yayaw-bulk-body {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 24px 20px;
}
.yayaw-bulk-fields {
  display: grid;
  gap: 20px;
}
.yayaw-bulk-fields > .yayaw-button {
  justify-self: start;
}
.yayaw-bulk-field {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 4px 8px;
  min-width: 0;
}
.yayaw-bulk-remove {
  margin-top: 24px;
}
.yayaw-bulk-empty {
  padding-block: 12px;
  margin: 0;
}
.yayaw-bulk-clear {
  grid-column: 1;
  justify-self: start;
  padding: 0;
  min-height: 32px;
  border: 0;
  background: transparent;
  color: var(--yayaw-muted-foreground);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}
.yayaw-bulk-clear:hover {
  text-decoration: underline;
}
.yayaw-bulk-clear:disabled {
  opacity: 0.5;
  cursor: default;
}
.yayaw-bulk-form .yayaw-form-footer {
  position: static;
  flex-shrink: 0;
  flex-wrap: wrap;
  padding: 16px 24px max(16px, env(safe-area-inset-bottom));
}
.yayaw-bulk-picker {
  z-index: 110;
  width: min(18rem, calc(100vw - 2rem));
  border: 1px solid var(--yayaw-border);
  border-radius: 8px;
  padding: 4px;
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  box-shadow: var(--yayaw-shadow);
}
.yayaw-bulk-picker-list {
  max-height: min(16rem, 40dvh);
  overflow-y: auto;
}
.yayaw-bulk-picker-option {
  padding: 8px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
}
.yayaw-bulk-picker-option[data-highlighted] {
  background: var(--yayaw-muted);
}
@media (max-width: 767px) {
  .yayaw-form-surface[data-bulk-editor] {
    width: 100%;
    max-height: 90dvh;
    margin: auto 0 0;
    border-radius: 16px 16px 0 0;
  }
  .yayaw-form-surface[data-bulk-editor] :is(button, input, select),
  .yayaw-bulk-picker-option {
    min-height: 44px;
  }
  .yayaw-form-surface[data-bulk-editor] button {
    min-width: 44px;
  }
}

/* Settings use the toolbar's single scroll region, including mobile choice screens. */
.yayaw-settings-choices {
  display: grid;
  gap: 4px;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.yayaw-settings-choice {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  min-height: 36px;
  padding: 0 8px;
  border-radius: 6px;
  cursor: pointer;
}
.yayaw-settings-choice > span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.yayaw-settings-choice:hover {
  background: var(--yayaw-muted);
}
.yayaw-settings-labels {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--yayaw-border);
}
.yayaw-settings-radio {
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
  min-width: 16px;
  min-height: 16px;
  flex-shrink: 0;
  border: 1px solid var(--yayaw-border);
  border-radius: 50%;
  padding: 0;
  background: transparent;
}
.yayaw-settings-radio-indicator {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--primary, var(--yayaw-primary));
}
.yayaw-settings-properties {
  width: 100%;
  gap: 8px;
  font-weight: 400;
}
.yayaw-settings-properties > span {
  flex: 1;
  text-align: left;
}
.yayaw-settings-back {
  justify-content: flex-start;
  gap: 8px;
  font-weight: 400;
}
.yayaw-toolbar-menu[data-compact="true"] .yayaw-settings-choice {
  min-height: 44px;
}
.yayaw-toolbar-menu[data-compact="true"]
  :is(.yayaw-settings-radio, .yayaw-checkbox) {
  min-height: 16px;
  min-width: 16px;
}
.yayaw-card-settings .yayaw-control-field,
.yayaw-display-mode-select .yayaw-control-field {
  display: grid;
  gap: 6px;
  min-width: 0;
}
.yayaw-card-settings .yayaw-control-field > label,
.yayaw-display-mode-select .yayaw-control-field > label {
  font-size: 14px;
  white-space: normal;
}
.yayaw-card-settings .yayaw-select-trigger,
.yayaw-display-mode-select .yayaw-select-trigger {
  width: 100%;
  min-width: 0;
  max-width: none;
  height: 36px;
  font-size: 14px;
}

/* Shared record geometry applies equally to create, edit, and bulk forms. */
.yayaw-form.yayaw-record-content {
  /* The record surface lays the body and footer out as a column; the
     generic form grid would split the height evenly between them. */
  display: flex;
  flex-direction: column;
  padding: 0;
  gap: 0;
  overflow: hidden;
}
.yayaw-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Gallery interaction and compact properties share the React defaults. */
.yayaw-gallery-native-media {
  width: 100%;
  height: 100%;
}
.yayaw-gallery-card.selected {
  border-color: var(--yayaw-primary);
  box-shadow: 0 0 0 1px var(--yayaw-primary);
}
.yayaw-gallery-card .yayaw-card-select {
  top: 12px;
  left: 12px;
  width: auto;
  height: auto;
  padding: 0;
  background: transparent;
  opacity: 0;
  transition: opacity 0.15s;
}
.yayaw-gallery-card:hover .yayaw-card-select,
.yayaw-gallery-card:focus-within .yayaw-card-select,
.yayaw-gallery-card.selected .yayaw-card-select {
  opacity: 1;
}
.yayaw-gallery-card .yayaw-card-select .yayaw-checkbox {
  width: 20px;
  height: 20px;
  background: var(--yayaw-background);
  box-shadow: 0 1px 4px #0002;
}
.yayaw-gallery-card .yayaw-card-select .yayaw-checkbox[data-state="checked"] {
  background: var(--yayaw-primary);
}
@media (hover: none) {
  .yayaw-gallery-card .yayaw-card-select {
    opacity: 1;
  }
}
.yayaw-card-properties:not(.labeled) {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.yayaw-card-properties:not(.labeled) > dd {
  max-width: 100%;
}
.yayaw-row-actions-menu {
  width: max-content;
  min-width: min(11rem, var(--reka-dropdown-menu-content-available-width));
  max-width: min(
    var(--reka-dropdown-menu-content-available-width),
    calc(100vw - 1rem)
  );
}
.yayaw-row-action-item {
  white-space: normal;
  overflow-wrap: anywhere;
}
.yayaw-row-action-item svg {
  flex-shrink: 0;
}

/* Gantt timeline. Geometry comes from the shared planning/timeline model. */
.yayaw-gantt-message {
  color: var(--yayaw-muted-foreground);
  font-size: 0.875rem;
}
.yayaw-gantt-error {
  color: var(--yayaw-danger);
  font-size: 0.875rem;
}
.yayaw-gantt-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.5rem 0;
}
.yayaw-gantt-toolbar h3 {
  margin: 0;
  font-size: 1rem;
  font-weight: 500;
}
.yayaw-gantt-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}
.yayaw-gantt-viewport {
  position: relative;
  overflow: auto;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
}
.yayaw-gantt-canvas {
  position: relative;
}
.yayaw-gantt-header {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--yayaw-background);
}
.yayaw-gantt-heading {
  align-items: flex-end !important;
  padding-bottom: 0.5rem;
  color: var(--yayaw-muted-foreground);
  font-weight: 500;
}
.yayaw-gantt-month,
.yayaw-gantt-date {
  position: absolute;
  border-bottom: 1px solid var(--yayaw-border);
  color: var(--yayaw-muted-foreground);
}
.yayaw-gantt-month {
  top: 0;
  overflow: hidden;
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-gantt-date {
  top: 24px;
  display: flex;
  height: 40px;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  padding-bottom: 0.25rem;
  font-size: 11px;
  gap: 2px;
}
.yayaw-gantt-date.today {
  color: var(--yayaw-danger);
  font-weight: 600;
}
.yayaw-gantt-date.today .yayaw-gantt-day {
  display: flex;
  width: 1.25rem;
  height: 1.25rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--yayaw-danger);
  color: var(--yayaw-background);
}
.yayaw-gantt-weekday {
  opacity: 0.7;
}
.yayaw-gantt-row {
  position: absolute;
  right: 0;
  left: 0;
  border-bottom: 1px solid var(--yayaw-border);
}
.yayaw-gantt-row.summary {
  background: color-mix(in srgb, var(--yayaw-muted) 25%, transparent);
}
.yayaw-gantt-label {
  position: sticky;
  left: 0;
  z-index: 1;
  display: flex;
  height: 100%;
  min-width: 0;
  align-items: center;
  border-right: 1px solid var(--yayaw-border);
  background: var(--yayaw-background);
  gap: 0.25rem;
  padding-right: 0.5rem;
}
.yayaw-gantt-label > * {
  min-width: 0;
}
.yayaw-gantt-spacer,
.yayaw-gantt-toggle {
  flex: none;
  width: 1.25rem;
  height: 1.25rem;
}
.yayaw-gantt-select,
.yayaw-gantt-kind {
  flex: none;
}
.yayaw-gantt-kind {
  color: var(--yayaw-muted-foreground);
}
.yayaw-gantt-title {
  overflow: hidden;
  flex: 1;
  border: 0;
  background: none;
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-gantt-title:hover {
  text-decoration: underline;
}
.yayaw-gantt-track {
  position: absolute;
  top: 0;
  bottom: 0;
  background-image: linear-gradient(
    to right,
    var(--yayaw-border) 0 1px,
    transparent 1px
  );
}
.yayaw-gantt-off {
  position: absolute;
  top: 0;
  bottom: 0;
  background: color-mix(in srgb, var(--yayaw-muted) 45%, transparent);
}
.yayaw-gantt-bar {
  position: absolute;
  top: 6px;
  bottom: 6px;
  border: 1px solid color-mix(in srgb, var(--yayaw-primary) 25%, transparent);
  border-radius: calc(var(--yayaw-radius) - 2px);
  background: color-mix(in srgb, var(--yayaw-primary) 15%, transparent);
}
.yayaw-gantt-bar.summary {
  border-color: var(--yayaw-border);
  background: var(--yayaw-muted);
}
.yayaw-gantt-bar-body {
  display: flex;
  overflow: hidden;
  width: 100%;
  height: 100%;
  align-items: center;
  border: 0;
  background: none;
  color: inherit;
  cursor: grab;
  font: inherit;
  font-size: 0.75rem;
  font-weight: 500;
  padding-inline: 0.5rem;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-gantt-bar-body:active {
  cursor: grabbing;
}
.yayaw-gantt-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 0.5rem;
  border: 0;
  border-radius: 2px;
  background: color-mix(in srgb, var(--yayaw-primary) 40%, transparent);
  cursor: ew-resize;
  opacity: 0;
  transition: opacity 120ms;
}
.yayaw-gantt-handle.start {
  left: 0;
}
.yayaw-gantt-handle.end {
  right: 0;
}
.yayaw-gantt-bar:hover .yayaw-gantt-handle,
.yayaw-gantt-handle:focus-visible {
  opacity: 1;
}
@media (hover: none) {
  .yayaw-gantt-handle {
    opacity: 1;
  }
}
.yayaw-gantt-unscheduled {
  position: absolute;
  top: 50%;
  left: 0.5rem;
  color: var(--yayaw-muted-foreground);
  font-size: 0.75rem;
  font-style: italic;
  transform: translateY(-50%);
}
.yayaw-gantt-links {
  position: absolute;
  top: 0;
  left: 0;
  color: color-mix(in srgb, var(--yayaw-muted-foreground) 70%, transparent);
  pointer-events: none;
}
.yayaw-gantt-today {
  position: absolute;
  width: 1px;
  background: color-mix(in srgb, var(--yayaw-danger) 60%, transparent);
  pointer-events: none;
}
.yayaw-gantt-drag-layer {
  position: fixed;
  z-index: 50;
  cursor: grabbing;
  inset: 0;
}
.yayaw-list {
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius, 8px);
  background: var(--yayaw-background);
  overflow: hidden;
}
.yayaw-list-section + .yayaw-list-section {
  border-top: 1px solid var(--yayaw-border);
}
.yayaw-list ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.yayaw-list li + li {
  border-top: 1px solid var(--yayaw-border);
}
.yayaw-list li.selected {
  background: color-mix(in oklab, var(--yayaw-primary) 5%, transparent);
}
.yayaw-list-group {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px;
  background: color-mix(in oklab, var(--yayaw-muted) 30%, transparent);
}
.yayaw-list-group h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 500;
}
.yayaw-list-group-label {
  color: var(--yayaw-muted-foreground);
}
.yayaw-list-item {
  display: flex;
  align-items: center;
  gap: 12px;
  /* Lines follow the table density scale, like table rows. */
  min-height: var(--yayaw-density-height, 40px);
  padding: var(--yayaw-density-py, 6px)
    calc(var(--yayaw-density-px, 8px) + var(--spacing, 0.25rem));
  cursor: pointer;
}
.yayaw-list-item:hover {
  background: color-mix(in oklab, var(--yayaw-muted) 40%, transparent);
}
.yayaw-list-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
}
.yayaw-list-properties {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-list-properties > div {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
.yayaw-list-properties dd {
  margin: 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-list-handle {
  display: inline-flex;
  flex-shrink: 0;
  margin-left: -4px;
  padding: 4px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--yayaw-muted-foreground);
  cursor: grab;
  touch-action: none;
}
.yayaw-list-handle:hover {
  background: var(--yayaw-muted);
}
.yayaw-list-handle:active {
  cursor: grabbing;
}
.yayaw-list li.yayaw-list-dragging {
  opacity: 0.5;
}
.yayaw-list li.yayaw-list-target {
  box-shadow: inset 0 2px 0 0 var(--yayaw-primary);
}
.yayaw-list-title.yayaw-list-wrap {
  overflow: visible;
  white-space: normal;
  overflow-wrap: anywhere;
}
.yayaw-list-title.yayaw-list-title-start {
  flex: 0 1 auto;
}
.yayaw-list-properties[data-align="start"] {
  flex: 1;
  justify-content: flex-start;
}
.yayaw-number-bar {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: 100%;
}
.yayaw-number-bar-track {
  flex: 1;
  min-width: 32px;
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--yayaw-muted);
}
.yayaw-number-bar-track > span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--yayaw-primary);
}

/* Native grid checkboxes match the shared checkbox. */
.yayaw-data-grid input[type="checkbox"] {
  appearance: none;
  display: inline-grid;
  width: 16px;
  height: 16px;
  margin: 0;
  place-content: center;
  border: 1px solid var(--yayaw-input);
  border-radius: 4px;
  background: transparent;
  box-shadow: var(--yayaw-shadow-xs);
  vertical-align: middle;
  cursor: pointer;
}
.yayaw-data-grid input[type="checkbox"]:checked:not(:indeterminate) {
  border-color: var(--yayaw-primary);
  background: var(--yayaw-primary);
}
.yayaw-data-grid input[type="checkbox"]:checked::after,
.yayaw-data-grid input[type="checkbox"]:indeterminate::after {
  width: 8px;
  height: 4px;
  border: 1.5px solid var(--yayaw-primary-foreground);
  border-top: 0;
  border-right: 0;
  content: "";
  transform: translateY(-1px) rotate(-45deg);
}
/* Partial selection looks like the stock shadcn (Base UI) checkbox React uses. */
.yayaw-data-grid input[type="checkbox"]:indeterminate::after {
  border-color: var(--yayaw-foreground);
}
.yayaw-gallery-placeholder {
  display: grid;
  gap: 6px;
  place-items: center;
  font-weight: 500;
}
.yayaw-gallery-body .yayaw-card-header strong {
  font-weight: 500;
}
.yayaw-kanban-lane > header strong {
  font-size: 14px;
  font-weight: 500;
}
/* The gallery grid sits in a bordered panel, as in React. */
.yayaw-gallery-panel {
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  padding: 12px;
}
/* Selection column: 48px with a centered checkbox, as in React. */
.yayaw-data-grid :is(th, td):has(> input[type="checkbox"]) {
  width: 48px;
  min-width: 48px;
  text-align: center;
}
.yayaw-toolbar .yayaw-view-trigger {
  gap: 8px;
  padding-inline: 10px;
  font-size: 14px;
  font-weight: 500;
}
.yayaw-data-grid :is(th, td) > input[type="checkbox"] {
  display: grid;
  margin: 0 auto;
}
.yayaw-data-grid thead th:first-child:has(input[type="checkbox"]) {
  width: 48px;
  text-align: center;
}
.yayaw-data-grid thead th:first-child input[type="checkbox"] {
  display: grid;
  margin: 0 auto;
}
/* React's header checkbox sits 2px lower than row checkboxes. */
.yayaw-data-grid thead th:first-child input[type="checkbox"] {
  transform: translateY(2px);
}
/* Header labels are regular weight inside a medium cell, as in React. */
.yayaw-data-grid th .yayaw-column-sort {
  font-weight: 400;
}
/* shadcn's dark: variants: inputs, outline buttons and checkboxes take --input at 30%. */
.dark
:is(
  .yayaw-input,
  .yayaw-select,
  .yayaw-textarea,
  .yayaw-checkbox:not([data-state="checked"])
),
.dark .yayaw-data-grid input[type="checkbox"]:not(:checked),
.dark .yayaw-button-outline {
  border-color: var(--yayaw-input);
  background: color-mix(in oklab, var(--yayaw-input) 30%, transparent);
}
.yayaw-input::placeholder,
.yayaw-textarea::placeholder {
  color: var(--yayaw-muted-foreground);
  opacity: 1;
}
/* Cell text uses a 20px line, as Tailwind's text-sm in React cells. */
.yayaw-data-grid td,
.yayaw-data-grid th {
  line-height: 20px;
}
/* Connect rows: run now, or open the schedule with the clock. */
.yayaw-destination-row {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
.yayaw-destination-row > .yayaw-options-item {
  min-width: 0;
  flex: 1;
}
.yayaw-destination-row .yayaw-schedule-trigger {
  width: 32px;
  min-width: 32px;
  min-height: 32px;
  flex: none;
}
.yayaw-schedule-panel {
  padding: 12px;
}
.yayaw-schedule-loading {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
}
.yayaw-schedule-panel .yayaw-schedule-field .yayaw-input,
.yayaw-schedule-panel .yayaw-schedule-run {
  width: 100%;
}
.yayaw-schedule-summary {
  display: grid;
  gap: 4px;
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-muted);
  padding: 8px 12px;
  font-size: 14px;
}
.yayaw-schedule-summary p {
  margin: 0;
}
.yayaw-schedule-muted {
  color: var(--yayaw-muted-foreground);
}
.yayaw-schedule-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.yayaw-schedule-actions > .yayaw-button {
  flex: 1;
}
/* Connector screens: target, column mapping, records, send and result. */
.yayaw-connector-panel {
  padding: 12px;
}
.yayaw-setting-heading {
  margin: 4px 0 0;
  font-size: 14px;
  font-weight: 500;
}
.yayaw-card-settings .yayaw-setting-inline .yayaw-control-field {
  grid-template-columns: minmax(0, 2fr) minmax(0, 3fr);
  align-items: center;
  gap: 8px;
}
.yayaw-card-settings .yayaw-setting-inline .yayaw-control-field > label {
  overflow: hidden;
  color: var(--yayaw-foreground);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-connector-input {
  display: grid;
  gap: 6px;
}
.yayaw-connector-input > label {
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
}
.yayaw-connector-input-row {
  display: flex;
  gap: 8px;
}
.yayaw-connector-input-row .yayaw-input {
  min-width: 0;
  flex: 1;
}
.yayaw-connector-hint {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-connector-error {
  margin: 0;
  border: 1px solid color-mix(in oklab, var(--yayaw-danger) 40%, transparent);
  border-radius: var(--yayaw-radius);
  padding: 8px 12px;
  color: var(--yayaw-danger);
  font-size: 14px;
}
.yayaw-connector-send {
  width: 100%;
}
.yayaw-connector-result {
  display: grid;
  gap: 12px;
}
.yayaw-connector-summary {
  display: grid;
  gap: 4px;
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-muted);
  padding: 8px 12px;
  font-size: 14px;
}
.yayaw-connector-summary p {
  margin: 0;
}
.yayaw-connector-counts {
  font-weight: 500;
}
.yayaw-connector-failure {
  color: var(--yayaw-danger);
}
/* Target check, "Prepare …" confirmation, refresh and new targets. */
.yayaw-connector-target-tools {
  display: grid;
  gap: 4px;
}
.yayaw-connector-refresh {
  justify-self: start;
  height: 28px;
  padding: 0 8px;
  font-size: 13px;
}
.yayaw-connector-check,
.yayaw-connector-prepare,
.yayaw-connector-create {
  display: grid;
  gap: 8px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  padding: 8px 12px;
  font-size: 14px;
}
.yayaw-connector-prepare {
  border-color: color-mix(in oklab, oklch(0.769 0.188 70.08) 50%, transparent);
}
.yayaw-connector-check h3,
.yayaw-connector-check h4,
.yayaw-connector-check p,
.yayaw-connector-check ul,
.yayaw-connector-prepare p,
.yayaw-connector-prepare ul,
.yayaw-connector-create h3 {
  margin: 0;
}
.yayaw-connector-check h3 {
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  font-weight: 500;
}
.yayaw-connector-create h3 {
  font-size: 14px;
  font-weight: 500;
}
.yayaw-connector-check-group {
  display: grid;
  gap: 4px;
}
.yayaw-connector-check h4 {
  font-size: 12px;
  font-weight: 500;
}
.yayaw-connector-check h4[data-severity="blocking"] {
  color: var(--yayaw-danger);
}
.yayaw-connector-check h4[data-severity="fixable"] {
  color: oklch(0.555 0.163 48.998);
}
.yayaw-connector-check ul {
  display: grid;
  gap: 2px;
  padding: 0;
  font-size: 12px;
  list-style: none;
}
.yayaw-connector-prepare ul {
  display: grid;
  gap: 2px;
  padding-inline-start: 20px;
  font-size: 12px;
}
.yayaw-connector-check-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.yayaw-connector-check-actions .yayaw-button {
  height: 32px;
  font-size: 13px;
}
.yayaw-connector-prepared {
  display: flex;
  align-items: center;
  gap: 6px;
  color: oklch(0.527 0.154 150.069);
  font-size: 12px;
}
.yayaw-connector-hint.yayaw-connector-blocked {
  color: var(--yayaw-danger);
}
/* Sync preview: counts per side, notes and the first conflicts. */
.yayaw-sync-confirm {
  align-items: flex-start;
  border: 1px solid color-mix(in oklab, var(--yayaw-danger) 40%, transparent);
  border-radius: var(--yayaw-radius);
  padding: 8px 12px;
  line-height: 1.35;
}
.yayaw-sync-preview {
  display: grid;
  gap: 8px;
  min-width: 0;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  padding: 8px 12px;
  font-size: 14px;
}
.yayaw-sync-preview p,
.yayaw-sync-preview h3,
.yayaw-sync-preview dl,
.yayaw-sync-preview dd,
.yayaw-sync-preview ul {
  margin: 0;
}
.yayaw-sync-sides {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.yayaw-sync-side {
  display: grid;
  gap: 4px;
  min-width: 0;
}
.yayaw-sync-side h3 {
  overflow: hidden;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-sync-side dl {
  display: grid;
  gap: 2px;
}
.yayaw-sync-side dl > div {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.yayaw-sync-side dd {
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}
.yayaw-sync-side dd.yayaw-sync-zero {
  color: var(--yayaw-muted-foreground);
  font-weight: 400;
}
.yayaw-sync-note {
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-sync-warning {
  color: color-mix(
    in oklab,
    oklch(0.666 0.179 58.318) 75%,
    var(--yayaw-foreground)
  );
  font-size: 12px;
}
.yayaw-sync-conflicts {
  display: grid;
  gap: 6px;
}
.yayaw-sync-conflicts h3 {
  font-size: 12px;
  font-weight: 500;
}
.yayaw-sync-conflicts ul {
  display: grid;
  gap: 6px;
  padding: 0;
  list-style: none;
}
.yayaw-sync-conflicts li {
  display: grid;
  gap: 2px;
  border-radius: calc(var(--yayaw-radius) - 2px);
  background: color-mix(in oklab, var(--yayaw-muted) 60%, transparent);
  padding: 6px 8px;
  font-size: 12px;
}
.yayaw-sync-conflict-title {
  overflow: hidden;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-sync-value {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  font-weight: 500;
}
.yayaw-sync-value > span:last-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-sync-value.yayaw-sync-loser {
  color: var(--yayaw-muted-foreground);
  font-weight: 400;
  text-decoration: line-through;
}
/* Conflict rules set in code and the conflicts left to a person. */
.yayaw-connector-rules {
  display: grid;
  gap: 4px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  padding: 8px 12px;
  font-size: 12px;
}
.yayaw-connector-rules h3 {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  font-weight: 500;
}
.yayaw-connector-rules ul {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.yayaw-connector-rules p {
  margin: 0;
}
.yayaw-connector-conflicts-entry {
  justify-content: flex-start;
  width: 100%;
}
.yayaw-connector-conflicts-entry svg {
  color: oklch(0.666 0.179 58.318);
}
.yayaw-connector-conflicts {
  display: grid;
  gap: 12px;
}
.yayaw-connector-conflicts-head {
  display: grid;
  gap: 4px;
}
.yayaw-connector-conflicts-head h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 500;
}
.yayaw-connector-conflicts ul {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.yayaw-connector-conflicts li {
  display: grid;
  gap: 6px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  padding: 8px 12px;
  font-size: 12px;
}
.yayaw-connector-conflicts li .yayaw-sync-conflict-title {
  font-size: 14px;
}
.yayaw-connector-conflicts li .yayaw-button {
  height: 32px;
  font-size: 13px;
}
.yayaw-connector-conflict-actions {
  display: grid;
  gap: 8px;
}
.yayaw-connector-conflict-value {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}
.yayaw-connector-conflict-value > span:first-child {
  flex-shrink: 0;
  color: var(--yayaw-muted-foreground);
}
.yayaw-connector-conflict-value > span:last-child {
  overflow: hidden;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Column mapping: sample and conversion badge under each row, preview table. */
.yayaw-column-mapping {
  display: grid;
  gap: 12px;
  min-width: 0;
}
.yayaw-mapping-details {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  margin-top: -8px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-mapping-sample {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-mapping-badge {
  flex: none;
  border: 1px solid var(--yayaw-border);
  border-radius: calc(var(--yayaw-radius) - 2px);
  padding: 2px 6px;
  line-height: 1;
}
.yayaw-mapping-badge[data-invalid] {
  border-color: color-mix(in oklab, var(--yayaw-danger) 40%, transparent);
  color: var(--yayaw-danger);
}
.yayaw-mapping-preview {
  display: grid;
  gap: 6px;
  min-width: 0;
}
.yayaw-mapping-preview-scroll {
  max-height: 192px;
  overflow: auto;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
}
.yayaw-mapping-preview table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}
.yayaw-mapping-preview th {
  background: color-mix(in srgb, var(--yayaw-muted) 60%, transparent);
  font-weight: 500;
  text-align: left;
}
.yayaw-mapping-preview th,
.yayaw-mapping-preview td {
  max-width: 160px;
  overflow: hidden;
  padding: 4px 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-mapping-preview tbody tr {
  border-top: 1px solid var(--yayaw-border);
}
.yayaw-mapping-preview td.yayaw-mapping-invalid {
  background: color-mix(in oklab, var(--yayaw-danger) 10%, transparent);
  color: var(--yayaw-danger);
}
/* Data › Import: source, mapping, review, progress and result. */
.yayaw-import-panel {
  padding: 12px;
}
.yayaw-import-step {
  display: grid;
  gap: 12px;
  min-width: 0;
}
.yayaw-import-drop {
  display: grid;
  justify-items: center;
  gap: 8px;
  border: 1px dashed var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  padding: 20px 12px;
  cursor: pointer;
  font-size: 14px;
  text-align: center;
}
.yayaw-import-drop.yayaw-import-dragging {
  border-color: var(--yayaw-primary);
  background: var(--yayaw-muted);
}
.yayaw-import-choose {
  display: inline-flex;
  align-items: center;
  height: 32px;
  margin-top: 4px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  padding: 0 12px;
  font-weight: 500;
}
.yayaw-import-strong {
  font-weight: 500;
}
.yayaw-import-muted {
  color: var(--yayaw-muted-foreground);
}
.yayaw-import-small {
  font-size: 12px;
}
.yayaw-import-text {
  margin: 0;
  font-size: 14px;
}
.yayaw-import-paste {
  display: grid;
  gap: 6px;
}
.yayaw-import-paste > label {
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
}
.yayaw-import-paste > .yayaw-button {
  justify-self: end;
}
.yayaw-import-textarea {
  min-height: 80px;
  font-family: ui-monospace, monospace;
  font-size: 12px;
}
.yayaw-import-check {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  cursor: pointer;
  font-size: 14px;
}
.yayaw-schedule-actions > .yayaw-button.yayaw-import-run {
  flex-basis: 100%;
}
.yayaw-import-progress {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--yayaw-muted);
}
.yayaw-import-progress > div {
  height: 100%;
  background: var(--yayaw-primary);
  transition: width 150ms;
}

/* Form view and standalone form: the React form's card, fields and states. */
.yayaw-form-root,
.yayaw-form-root *,
.yayaw-form-view,
.yayaw-form-view *,
.yayaw-form-popover,
.yayaw-form-popover * {
  box-sizing: border-box;
}
.yayaw-form-root {
  display: grid;
  width: 100%;
  min-width: 0;
  max-width: 640px;
  margin: 0 auto;
  gap: 24px;
  border: 1px solid var(--yayaw-border);
  border-radius: calc(var(--yayaw-radius) + 6px);
  background: var(--yayaw-card);
  box-shadow: var(--yayaw-shadow-xs);
  color: var(--yayaw-foreground);
  padding: 24px 20px;
  font-size: 14px;
  line-height: 1.4;
}
.yayaw-form-intro {
  display: grid;
  gap: 6px;
  border-bottom: 1px solid var(--yayaw-border);
  padding-bottom: 20px;
}
.yayaw-form-title {
  margin: 0;
  font-size: 18px;
  line-height: 1.25;
  font-weight: 600;
  letter-spacing: -0.025em;
}
.yayaw-form-description {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  white-space: pre-line;
}
.yayaw-form-questions {
  display: grid;
  gap: 24px;
}
.yayaw-form-question {
  display: grid;
  min-width: 0;
  gap: 12px;
  margin: 0;
  padding: 0;
  border: 0;
}
/* Like shadcn's Field: an invalid question turns its label and text red. */
.yayaw-form-question[data-invalid] {
  color: var(--yayaw-danger);
}
.yayaw-form-question-header {
  display: grid;
  min-width: 0;
  gap: 4px;
}
.yayaw-form-label {
  display: flex;
  width: fit-content;
  align-items: center;
  gap: 8px;
  padding: 0;
  font-weight: 500;
  line-height: 1.375;
}
.yayaw-form-legend {
  margin-bottom: -8px;
}
.yayaw-form-required {
  color: var(--yayaw-danger);
}
.yayaw-form-help {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  line-height: 1.5;
}
.yayaw-form-error {
  margin: 0;
  color: var(--yayaw-danger);
}
.yayaw-form-question > .yayaw-input,
.yayaw-form-question > .yayaw-textarea,
.yayaw-form-question > .yayaw-select-trigger,
.yayaw-form-date-anchor,
.yayaw-form-date {
  width: 100%;
  min-width: 0;
}
.yayaw-form-question :is(.yayaw-input, .yayaw-textarea) {
  font-size: 14px;
}
.yayaw-form-root
  [aria-invalid="true"]:not(.yayaw-switch-root, .yayaw-questionnaire-item) {
  border-color: var(--yayaw-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--yayaw-danger) 20%, transparent);
}
.dark
  .yayaw-form-root
  [aria-invalid="true"]:not(.yayaw-switch-root, .yayaw-questionnaire-item) {
  border-color: color-mix(in srgb, var(--yayaw-danger) 50%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--yayaw-danger) 40%, transparent);
}
.yayaw-form-label .yayaw-form-required {
  margin-left: -4px;
}
.yayaw-form-number {
  font-variant-numeric: tabular-nums;
}
.yayaw-form-select {
  width: 100%;
  max-width: none;
  height: 36px;
  min-height: 36px;
  border-color: var(--yayaw-input);
  border-radius: var(--yayaw-radius);
  background: transparent;
  padding: 8px 8px 8px 10px;
  font-size: 14px;
}
.yayaw-form-select-value {
  display: flex;
  min-width: 0;
  align-items: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-select-value[data-placeholder] {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-root .yayaw-tag,
.yayaw-select-content .yayaw-tag {
  line-height: 16px;
}
.yayaw-form-date-anchor {
  display: block;
}
.yayaw-form-date {
  justify-content: flex-start;
  padding: 0 10px;
  font-size: 14px;
}
.yayaw-form-date-value {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-date-value[data-empty],
.yayaw-form-date-icon {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-date-icon {
  flex-shrink: 0;
}
.yayaw-form-switch-row {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid var(--yayaw-border);
  border-radius: calc(var(--yayaw-radius) + 2px);
  box-shadow: var(--yayaw-shadow-xs);
  padding: 12px;
}
.yayaw-form-choices {
  display: grid;
  gap: 8px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  padding: 12px;
}
.yayaw-form-choice {
  display: flex;
  min-height: 24px;
  align-items: center;
  gap: 8px;
}
.yayaw-form-choice-label {
  display: flex;
  min-width: 0;
  align-items: center;
  color: var(--yayaw-foreground);
  line-height: 1.375;
}
/* shadcn's Switch: 32 by 18px, 24 by 14px when small. */
.yayaw-switch-root {
  position: relative;
  display: inline-flex;
  width: 32px;
  height: 18.4px;
  flex-shrink: 0;
  align-items: center;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--yayaw-input);
  box-shadow: var(--yayaw-shadow-xs);
  padding: 0;
  cursor: pointer;
  transition: background-color 150ms;
}
.yayaw-switch-root[data-size="sm"] {
  width: 24px;
  height: 14px;
}
.yayaw-switch-root[data-state="checked"] {
  background: var(--yayaw-primary);
}
.yayaw-switch-root:focus-visible {
  outline: none;
  border-color: var(--yayaw-ring);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--yayaw-ring) 50%, transparent);
}
.yayaw-switch-root[data-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}
.yayaw-switch-thumb {
  display: block;
  width: 16px;
  height: 16px;
  border-radius: 999px;
  background: var(--yayaw-background);
  pointer-events: none;
  transition: transform 150ms;
}
.yayaw-switch-root[data-size="sm"] .yayaw-switch-thumb {
  width: 12px;
  height: 12px;
}
.yayaw-switch-thumb[data-state="checked"] {
  transform: translateX(calc(100% - 2px));
}
.dark .yayaw-switch-root[data-state="unchecked"] {
  background: color-mix(in oklab, var(--yayaw-input) 80%, transparent);
}
.dark .yayaw-switch-thumb[data-state="unchecked"] {
  background: var(--yayaw-foreground);
}
.dark .yayaw-switch-thumb[data-state="checked"] {
  background: var(--yayaw-primary-foreground);
}
.yayaw-form-message {
  margin: 0;
  border: 1px solid color-mix(in srgb, var(--yayaw-danger) 40%, transparent);
  border-radius: var(--yayaw-radius);
  background: color-mix(in srgb, var(--yayaw-danger) 5%, transparent);
  color: var(--yayaw-danger);
  padding: 8px 12px;
}
.dark .yayaw-form-message {
  background: color-mix(in srgb, var(--yayaw-danger) 10%, transparent);
}
.yayaw-form-submit-bar {
  display: flex;
  justify-content: flex-end;
  border-top: 1px solid var(--yayaw-border);
  padding-top: 20px;
}
.yayaw-form-action {
  width: 100%;
}
.yayaw-empty-root.yayaw-form-state {
  min-height: 0;
  gap: 20px;
  padding: 24px 0;
}
.yayaw-form-state-text {
  display: grid;
  gap: 8px;
}
.yayaw-form-view {
  display: grid;
  min-width: 0;
  gap: 12px;
  padding: 8px 0;
}
.yayaw-form-toolbar {
  display: flex;
  min-height: 32px;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.yayaw-form-share-trigger {
  min-height: 32px;
  height: 32px;
  gap: 8px;
  padding: 0 10px;
  font-size: 14px;
}
.yayaw-form-canvas {
  border-radius: calc(var(--yayaw-radius) + 2px);
  background: color-mix(in oklab, var(--yayaw-muted) 40%, transparent);
  padding: 24px 12px;
}
.dark .yayaw-form-canvas {
  background: color-mix(in oklab, var(--yayaw-muted) 20%, transparent);
}
.yayaw-form-share-panel {
  display: grid;
  gap: 16px;
  padding: 12px;
}
.yayaw-form-switch-setting {
  display: flex;
  min-width: 0;
  min-height: 32px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.yayaw-form-switch-text {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 2px;
}
.yayaw-form-switch-label {
  min-width: 0;
  font-size: 14px;
}
.yayaw-form-share-panel .yayaw-form-switch-label {
  font-weight: 500;
}
.yayaw-form-share-icon {
  display: inline-flex;
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-muted);
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-share-field {
  display: grid;
  gap: 6px;
}
.yayaw-form-share-link {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 4px;
}
.yayaw-form-share-link .yayaw-input {
  height: 32px;
  min-height: 32px;
  min-width: 0;
  flex: 1;
  padding: 4px 10px;
  font-size: 12px;
}
.yayaw-form-share-link .yayaw-icon-only {
  width: 32px;
  min-width: 32px;
  height: 32px;
  min-height: 32px;
  flex-shrink: 0;
  padding: 0;
  text-decoration: none;
}
.yayaw-form-share-update {
  display: grid;
  gap: 6px;
  border-top: 1px solid var(--yayaw-border);
  padding-top: 12px;
}
.yayaw-form-share-update .yayaw-button {
  width: 100%;
  min-height: 32px;
  height: 32px;
  padding: 0 10px;
}
.yayaw-form-settings {
  display: grid;
  min-width: 0;
}
.yayaw-form-settings-section,
.yayaw-form-settings-hidden {
  display: grid;
  min-width: 0;
  gap: 8px;
}
.yayaw-form-settings-hidden {
  gap: 4px;
}
.yayaw-form-setting {
  display: grid;
  min-width: 0;
  gap: 6px;
}
.yayaw-form-setting .yayaw-input,
.yayaw-form-setting .yayaw-textarea {
  width: 100%;
  font-size: 14px;
}
.yayaw-form-setting-label,
.yayaw-form-settings-note {
  margin: 0;
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-settings-note {
  font-size: 12px;
}
.yayaw-form-settings-questions {
  display: grid;
  gap: 2px;
  margin: 0 -4px;
  padding: 0;
  list-style: none;
}
.yayaw-form-settings-item {
  display: grid;
  border-radius: var(--yayaw-radius);
}
.yayaw-form-settings-item[data-editing] {
  background: color-mix(in oklab, var(--yayaw-muted) 60%, transparent);
}
.yayaw-form-settings-row {
  display: flex;
  min-width: 0;
  min-height: 36px;
  align-items: center;
  gap: 4px;
  padding: 0 4px;
}
.yayaw-form-settings-grip {
  flex-shrink: 0;
  color: var(--yayaw-muted-foreground);
  opacity: 0.6;
}
.yayaw-form-settings-grip[data-hidden] {
  visibility: hidden;
}
.yayaw-form-settings-name {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  padding: 4px 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-settings-name:not([data-asked]) {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-settings-row .yayaw-form-settings-action {
  width: 24px;
  min-width: 24px;
  height: 24px;
  min-height: 24px;
  padding: 0;
}
.yayaw-form-settings-expand svg {
  transition: transform 150ms;
}
.yayaw-form-settings-expand[aria-expanded="true"] svg {
  transform: rotate(180deg);
}
.yayaw-form-settings-ask {
  margin-left: 4px;
}
.yayaw-form-settings-details {
  display: grid;
  gap: 12px;
  margin: 0 4px 4px;
  border-radius: var(--yayaw-radius);
  background: color-mix(in oklab, var(--yayaw-muted) 50%, transparent);
  padding: 12px;
}
.yayaw-form-settings-reset {
  min-height: 32px;
}
/* Date picker: shadcn's Calendar in a popover. */
.yayaw-form-popover {
  z-index: 120;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--popover, var(--yayaw-background));
  box-shadow: 0 4px 12px rgb(0 0 0 / 0.12);
  color: var(--yayaw-foreground);
  font-size: 14px;
}
.yayaw-form-calendar {
  padding: 12px;
}
.yayaw-form-calendar-header {
  display: flex;
  height: 32px;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}
.yayaw-form-calendar-heading {
  font-weight: 500;
}
.yayaw-form-calendar .yayaw-form-calendar-nav {
  width: 32px;
  min-width: 32px;
  height: 32px;
  min-height: 32px;
  padding: 0;
}
.yayaw-form-calendar-grid {
  margin-top: 16px;
  border-collapse: collapse;
}
.yayaw-form-calendar-row {
  display: flex;
}
.yayaw-form-calendar-row + .yayaw-form-calendar-row {
  margin-top: 8px;
}
.yayaw-form-calendar-weekday {
  width: 32px;
  color: var(--yayaw-muted-foreground);
  font-size: 12.8px;
  font-weight: 400;
}
.yayaw-form-calendar-cell {
  padding: 0;
}
.yayaw-form-calendar-day {
  display: inline-flex;
  width: 32px;
  height: 32px;
  align-items: center;
  justify-content: center;
  border-radius: var(--yayaw-radius);
  cursor: pointer;
  outline: none;
}
.yayaw-form-calendar-day:hover,
.yayaw-form-calendar-day[data-today] {
  background: var(--yayaw-muted);
}
.yayaw-form-calendar-day[data-outside-view] {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-calendar-day[data-selected] {
  background: var(--yayaw-primary);
  color: var(--yayaw-primary-foreground);
}
.yayaw-form-calendar-day:focus-visible {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--yayaw-ring) 50%, transparent);
}
.yayaw-form-calendar-day[data-disabled] {
  opacity: 0.5;
  pointer-events: none;
}
.yayaw-form-calendar-footer {
  display: flex;
  justify-content: flex-end;
  border-top: 1px solid var(--yayaw-border);
  padding: 8px;
}
.yayaw-form-calendar-footer .yayaw-button {
  min-height: 32px;
  height: 32px;
  padding: 0 10px;
}
@media (min-width: 640px) {
  .yayaw-form-root {
    padding: 32px;
  }
  .yayaw-form-action {
    width: fit-content;
  }
  .yayaw-form-canvas {
    padding: 40px 24px;
  }
}
/* Phone drawers: 44px targets, as React's drawer; switches keep their size. */
.yayaw-toolbar-menu[data-compact="true"] .yayaw-switch-root {
  min-height: 0;
}
.yayaw-toolbar-menu[data-compact="true"]
  .yayaw-form-share-link
  :is(.yayaw-input, .yayaw-icon-only),
.yayaw-toolbar-menu[data-compact="true"]
  .yayaw-form-share-update
  .yayaw-button {
  height: 44px;
  min-height: 44px;
}
.yayaw-toolbar-menu[data-compact="true"]
  .yayaw-form-share-link
  .yayaw-icon-only {
  width: 44px;
  min-width: 44px;
}
.yayaw-form-settings-row .yayaw-form-settings-action {
  background: transparent;
}
.yayaw-form-settings-row .yayaw-form-settings-action:hover:not(:disabled) {
  background: var(--yayaw-muted);
}

/* Form sections (page layout): a titled group of the next questions. */
.yayaw-form-section-break {
  display: grid;
  gap: 4px;
  border-top: 1px solid var(--yayaw-border);
  padding-top: 20px;
}
.yayaw-form-questions > .yayaw-form-section-break:first-child {
  border-top: 0;
  padding-top: 0;
}
.yayaw-form-section-title {
  margin: 0;
  font-size: 16px;
  font-weight: 500;
}
.yayaw-form-section-rule {
  margin: 0;
  border: 0;
  border-top: 1px solid var(--yayaw-border);
}

/* Steps layout: the shadcn-vue Questionnaire with the React edition's look. */
.yayaw-questionnaire {
  min-width: 0;
}
.yayaw-questionnaire-item {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 20px;
  margin: 0;
  border: 0;
  padding: 0;
  outline: none;
}
.yayaw-questionnaire-item[hidden],
.yayaw-questionnaire-actions > [hidden] {
  display: none;
}
.yayaw-questionnaire-title {
  margin: 0;
  padding: 0;
  font-size: 16px;
  font-weight: 600;
  text-wrap: pretty;
}
.yayaw-questionnaire-description {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
  text-wrap: pretty;
}
.yayaw-form-step-description {
  margin-top: -12px;
  white-space: pre-line;
}
.yayaw-form-progress {
  display: grid;
  gap: 8px;
}
.yayaw-questionnaire-progress {
  width: fit-content;
  min-width: 14ch;
  min-height: 1lh;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.yayaw-form-progress-track {
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--yayaw-muted);
}
.yayaw-form-progress-bar {
  height: 100%;
  border-radius: 999px;
  background: var(--yayaw-primary);
  transition: width 300ms;
}
.yayaw-questionnaire-actions {
  display: grid;
  width: 100%;
  min-height: 36px;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 8px;
}
.yayaw-form-step-actions {
  border-top: 1px solid var(--yayaw-border);
  padding-top: 20px;
}
.yayaw-questionnaire-previous {
  grid-column: 1;
  grid-row: 1;
  justify-self: start;
}
.yayaw-questionnaire-skip {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
}
.yayaw-questionnaire-next,
.yayaw-questionnaire-submit {
  grid-column: 3;
  grid-row: 1;
  justify-self: end;
}
.yayaw-form-review {
  display: grid;
  gap: 12px;
  margin: 0;
}
.yayaw-form-review-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 2px 12px;
  border-bottom: 1px solid var(--yayaw-border);
  padding-bottom: 12px;
}
.yayaw-form-review-row:last-child {
  border-bottom: 0;
}
.yayaw-form-review-row dt {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-review-row dd {
  grid-column: 1;
  margin: 0;
  white-space: pre-line;
}
.yayaw-button.yayaw-form-review-change {
  grid-column: 2;
  grid-row: 1 / span 2;
  min-height: 32px;
  padding: 4px 10px;
}
@media (max-width: 639px) {
  .yayaw-questionnaire-actions .yayaw-button {
    min-height: 44px;
  }
}

/* Rule editor of the Form settings. */
.yayaw-form-rule-summary {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0 4px 4px 28px;
  list-style: none;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-form-rules {
  display: grid;
  gap: 8px;
}
.yayaw-form-rules-heading {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  font-weight: 500;
}
.yayaw-form-rules-status {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-form-rules-status.yayaw-rule-issue {
  color: var(--yayaw-danger);
}
.yayaw-form-rules-empty {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
}
.yayaw-rule {
  display: grid;
  min-width: 0;
  gap: 8px;
  border: 1px solid var(--yayaw-border);
  border-radius: calc(var(--yayaw-radius) + 2px);
  background: var(--yayaw-background);
  padding: 8px;
}
.yayaw-rule-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px;
}
/* Each condition is a card sized by its own width (container queries):
   stacked when narrow, comparison and value side by side from 18rem, all
   three in a row from 34rem. */
.yayaw-rule-condition {
  min-width: 0;
  container-type: inline-size;
}
.yayaw-rule-card {
  position: relative;
  display: grid;
  gap: 6px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  padding: 8px 36px 8px 8px;
}
.yayaw-rule-card > .yayaw-rule-remove {
  position: absolute;
  top: 12px;
  right: 6px;
}
.yayaw-rule-compare {
  display: grid;
  min-width: 0;
  gap: 6px;
}
.yayaw-rule-operator,
.yayaw-rule-value,
.yayaw-rule-date {
  display: block;
  min-width: 0;
}
.yayaw-rule-card > .yayaw-rule-issue {
  grid-column: 1 / -1;
}
@container (min-width: 18rem) {
  .yayaw-rule-compare {
    grid-template-columns: minmax(0, 9rem) minmax(0, 1fr);
  }
  .yayaw-rule-operator[data-alone] {
    grid-column: 1 / -1;
  }
}
@container (width < 34rem) {
  .yayaw-rule-operator[data-wide],
  .yayaw-rule-value[data-wide] {
    grid-column: 1 / -1;
  }
}
@container (min-width: 34rem) {
  .yayaw-rule-card {
    grid-template-columns: minmax(0, 1fr) minmax(0, 9rem) minmax(0, 1.25fr);
    align-items: start;
  }
  .yayaw-rule-compare {
    display: contents;
  }
  .yayaw-rule-operator[data-alone] {
    grid-column: span 2;
  }
}
.yayaw-rule-range {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
.yayaw-rule-choices {
  display: grid;
  min-width: 0;
  gap: 6px;
  margin: 0;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  padding: 8px;
}
.yayaw-rule-choice {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}
.yayaw-rule-choice .yayaw-tag,
.yayaw-rule-select .yayaw-tag {
  line-height: 16px;
}
.yayaw-rule-issue {
  margin: 0;
  color: var(--yayaw-danger);
  font-size: 12px;
}
.yayaw-rule-unit {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-input.yayaw-rule-input[data-number] {
  font-variant-numeric: tabular-nums;
}
.yayaw-rule-date .yayaw-form-date {
  height: 32px;
  min-height: 32px;
  background: var(--yayaw-background);
  font-size: 12px;
}
/* A nested group: an indented card with its own All/Any toggle. */
.yayaw-rule-group {
  display: grid;
  min-width: 0;
  gap: 6px;
  margin: 0 0 0 8px;
  border: 1px solid var(--yayaw-border);
  border-left: 2px solid
    color-mix(in oklab, var(--yayaw-primary) 40%, transparent);
  border-radius: var(--yayaw-radius);
  background: color-mix(in oklab, var(--yayaw-muted) 40%, transparent);
  padding: 8px;
}
.dark .yayaw-rule-group {
  background: color-mix(in oklab, var(--yayaw-muted) 20%, transparent);
}
.yayaw-rule-group-header {
  position: relative;
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  padding-right: 28px;
}
.yayaw-rule-group-title {
  font-size: 12px;
  font-weight: 500;
}
.yayaw-rule-group-header > .yayaw-rule-remove {
  position: absolute;
  top: 0;
  right: 0;
}
/* All/Any: a segmented control of two radios. */
.yayaw-rule-join {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  margin: 0;
  border: 0;
  padding: 0;
}
.yayaw-rule-join-legend {
  float: left;
  margin-right: 8px;
  padding: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-rule-join-options {
  display: inline-flex;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: color-mix(in oklab, var(--yayaw-muted) 60%, transparent);
  padding: 2px;
}
.yayaw-rule-join-option {
  position: relative;
  display: inline-flex;
  height: 24px;
  align-items: center;
  border-radius: calc(var(--yayaw-radius) - 2px);
  padding: 0 10px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  cursor: pointer;
  transition:
    background-color 150ms,
    color 150ms;
}
.yayaw-rule-join-option:has(input:checked) {
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.05);
}
.dark .yayaw-rule-join-option:has(input:checked) {
  background: color-mix(in oklab, var(--yayaw-input) 60%, transparent);
}
.yayaw-rule-join-option:has(input:focus-visible) {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--yayaw-ring) 50%, transparent);
}
.yayaw-rule-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.yayaw-button.yayaw-rule-add {
  width: fit-content;
  min-height: 24px;
  gap: 4px;
  padding: 2px 8px;
  font-size: 12px;
}
.yayaw-rule-select {
  min-width: 0;
}
.yayaw-rule-select .yayaw-rule-select-trigger,
.yayaw-input.yayaw-rule-input {
  width: 100%;
  min-width: 0;
  max-width: none;
  height: 32px;
  min-height: 32px;
  background: var(--yayaw-background);
  font-size: 12px;
}
.yayaw-rule [aria-invalid="true"] {
  border-color: var(--yayaw-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--yayaw-danger) 20%, transparent);
}
/* The form builder's anchor in the table, for its theme tokens. */
.yayaw-form-builder-anchor {
  display: contents;
}
.yayaw-button.yayaw-form-settings-add {
  width: fit-content;
  min-height: 32px;
  gap: 6px;
  padding: 4px 10px;
}
.yayaw-form-settings-section-row {
  margin-top: 4px;
  border-top: 1px solid var(--yayaw-border);
  padding-top: 4px;
}
.yayaw-form-settings-section-name {
  font-weight: 500;
}

/* Form languages, consents and hidden fields. */
.yayaw-form-languages {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.yayaw-form-language-set {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: 0;
  border: 0;
  padding: 0;
}
.yayaw-form-language-legend {
  float: left;
  margin-right: 4px;
  padding: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
}
.yayaw-form-language-options {
  display: inline-flex;
  flex-wrap: wrap;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: color-mix(in oklab, var(--yayaw-muted) 60%, transparent);
  padding: 2px;
}
.yayaw-form-language {
  position: relative;
  display: inline-flex;
  height: 28px;
  align-items: center;
  border-radius: calc(var(--yayaw-radius) - 2px);
  padding: 0 10px;
  color: var(--yayaw-muted-foreground);
  font-size: 14px;
  cursor: pointer;
  transition:
    background-color 150ms,
    color 150ms;
}
.yayaw-form-language:has(input:checked) {
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.05);
}
.dark .yayaw-form-language:has(input:checked) {
  background: color-mix(in oklab, var(--yayaw-input) 60%, transparent);
}
.yayaw-form-language:has(input:focus-visible) {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--yayaw-ring) 50%, transparent);
}
.yayaw-form-language-add {
  width: 176px;
  max-width: 100%;
}
.yayaw-form-settings-languages {
  display: grid;
  min-width: 0;
  gap: 6px;
}
.yayaw-form-setting-head {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 8px;
}
.yayaw-form-missing {
  border-radius: calc(var(--yayaw-radius) - 4px);
  background: color-mix(in oklab, oklch(0.769 0.188 70.08) 12%, transparent);
  padding: 2px 6px;
  color: color-mix(
    in oklab,
    oklch(0.555 0.163 48.998) 85%,
    var(--yayaw-foreground)
  );
  font-size: 12px;
}
.dark .yayaw-form-missing {
  color: oklch(0.828 0.189 84.429);
}
.yayaw-form-missing-line {
  margin: 0;
  padding: 0 4px 4px 28px;
}
.yayaw-form-settings-kind {
  font-weight: 500;
}
.yayaw-form-settings-preview {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-hidden-name {
  padding-left: 4px;
}
.yayaw-form-option-labels {
  display: grid;
  min-width: 0;
  gap: 8px;
  margin: 0;
  border: 0;
  padding: 0;
}
.yayaw-form-option-labels > legend {
  margin-bottom: 4px;
  padding: 0;
}
.yayaw-form-settings-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.yayaw-form-consent {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: 12px;
  border: 1px solid var(--yayaw-border);
  border-radius: calc(var(--yayaw-radius) + 2px);
  box-shadow: var(--yayaw-shadow-xs);
  padding: 12px;
}
.yayaw-form-consent-box {
  margin-top: 2px;
}
.yayaw-form-consent-label {
  min-width: 0;
  line-height: 1.375;
}
.yayaw-form-consent-label .yayaw-form-required {
  margin-left: 2px;
}
.yayaw-form-consent-link {
  color: var(--yayaw-foreground);
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 4px;
}
.yayaw-form-consent-link:hover {
  color: var(--yayaw-primary);
}
.yayaw-form-toolbar-end {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}
.yayaw-form-edit-trigger {
  min-height: 32px;
  height: 32px;
  gap: 8px;
  padding: 0 10px;
  font-size: 14px;
}
.yayaw-form-share-trigger.yayaw-icon-only {
  width: 32px;
  padding: 0;
}
.yayaw-form-share-note {
  margin: 0;
  border-radius: var(--yayaw-radius);
  background: color-mix(in oklab, oklch(0.769 0.188 70.08) 10%, transparent);
  padding: 8px 10px;
  color: oklch(0.473 0.137 46.201);
  font-size: 14px;
}
.dark .yayaw-form-share-note {
  color: oklch(0.879 0.169 91.605);
}

/* View → Form settings: a summary and "Edit form". */
.yayaw-form-summary {
  display: grid;
  min-width: 0;
  gap: 4px;
}
.yayaw-form-summary p {
  margin: 0;
  font-size: 14px;
}
.yayaw-form-summary-title {
  overflow: hidden;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-summary-line {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-settings[data-form-settings] {
  gap: 12px;
}
.yayaw-button.yayaw-form-settings-edit {
  width: 100%;
  gap: 8px;
}
.yayaw-form-settings[data-form-settings] > .yayaw-form-settings-add {
  width: 100%;
  justify-content: center;
}

/* The form builder: a near full-screen dialog, full screen with tabs on phones. */
.yayaw-form-builder-backdrop {
  position: fixed;
  z-index: 60;
  inset: 0;
  background: rgba(0, 0, 0, 0.1);
  -webkit-backdrop-filter: blur(var(--blur-xs, 4px));
  backdrop-filter: blur(var(--blur-xs, 4px));
}
.yayaw-form-builder,
.yayaw-form-builder *,
.yayaw-form-builder-confirm,
.yayaw-form-builder-confirm * {
  box-sizing: border-box;
}
.yayaw-form-builder {
  position: fixed;
  z-index: 61;
  inset: 16px;
  display: flex;
  min-width: 0;
  flex-direction: column;
  overflow: hidden;
  border-radius: 12px;
  background: var(--yayaw-background);
  color: var(--yayaw-foreground);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--yayaw-foreground) 10%, transparent),
    0 10px 15px -3px rgb(0 0 0 / 0.1);
  font-size: 14px;
  line-height: 1.4;
  outline: none;
}
.yayaw-form-builder[data-compact] {
  inset: 0;
  border-radius: 0;
  box-shadow: none;
}
.yayaw-form-builder-bar {
  display: flex;
  min-height: 56px;
  flex: none;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 16px;
  border-bottom: 1px solid var(--yayaw-border);
  padding: 8px 16px;
}
.yayaw-form-builder[data-compact] .yayaw-form-builder-bar {
  padding: 8px 12px;
}
.yayaw-form-builder-heading {
  min-width: 0;
  flex: 1 1 160px;
}
.yayaw-form-builder-title {
  overflow: hidden;
  margin: 0;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-builder-subtitle {
  overflow: hidden;
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-builder-layout {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  margin: 0;
  border: 0;
  padding: 0;
}
.yayaw-form-builder-layout .yayaw-form-language {
  white-space: nowrap;
}
.yayaw-form-builder-bar-end {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}
.yayaw-form-builder-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  white-space: nowrap;
}
.yayaw-form-builder-status-dot,
.yayaw-form-builder-missing-dot {
  display: block;
  width: 8px;
  height: 8px;
  flex: none;
  border-radius: 999px;
  background: oklch(0.769 0.188 70.08);
}
.yayaw-form-builder-missing-dot {
  width: 6px;
  height: 6px;
}
.yayaw-button.yayaw-form-builder-settings,
.yayaw-button.yayaw-form-builder-save,
.yayaw-button.yayaw-form-builder-add,
.yayaw-button.yayaw-form-builder-remove,
.yayaw-button.yayaw-form-builder-ask {
  min-height: 32px;
  height: 32px;
  gap: 6px;
  padding: 0 10px;
  font-size: 14px;
}
.yayaw-button.yayaw-form-builder-close,
.yayaw-form-builder-actions .yayaw-button.yayaw-icon-only {
  width: 32px;
  min-width: 32px;
  min-height: 32px;
  height: 32px;
  padding: 0;
}
.yayaw-button.yayaw-form-builder-ask {
  width: fit-content;
}
.yayaw-form-builder-panes {
  display: grid;
  min-height: 0;
  flex: 1;
  grid-template-columns: minmax(14rem, 17rem) minmax(0, 1fr) minmax(
      19rem,
      23rem
    );
  grid-template-rows: minmax(0, 1fr);
}
@media (min-width: 1280px) {
  .yayaw-form-builder-panes {
    grid-template-columns: 18rem minmax(0, 1fr) 25rem;
  }
}
.yayaw-form-builder-pane {
  display: flex;
  min-height: 0;
  min-width: 0;
  flex-direction: column;
}
.yayaw-form-builder-pane-start {
  border-right: 1px solid var(--yayaw-border);
}
.yayaw-form-builder-pane-end {
  border-left: 1px solid var(--yayaw-border);
}
.yayaw-form-builder-outline,
.yayaw-form-builder-preview,
.yayaw-form-builder-properties {
  display: flex;
  min-height: 0;
  min-width: 0;
  flex: 1;
  flex-direction: column;
}
.yayaw-form-builder-pane-header {
  display: flex;
  min-height: 48px;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-bottom: 1px solid var(--yayaw-border);
  padding: 8px 12px;
}
.yayaw-form-builder-properties-header {
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  gap: 0;
  padding: 8px 16px;
}
.yayaw-form-builder-pane-title {
  overflow: hidden;
  margin: 0;
  font-size: 14px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-builder-scroll {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.yayaw-form-builder-outline .yayaw-form-builder-scroll {
  padding: 8px;
}
.yayaw-form-builder-entry {
  display: flex;
  width: 100%;
  min-width: 0;
  min-height: 32px;
  flex: 1;
  align-items: center;
  gap: 8px;
  border: 0;
  border-radius: var(--yayaw-radius);
  background: transparent;
  padding: 4px 8px;
  color: inherit;
  font: inherit;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
  transition: background-color 150ms;
}
.yayaw-form-builder-entry:hover {
  background: var(--yayaw-muted);
}
.yayaw-form-builder-entry[aria-current="true"] {
  background: color-mix(
    in oklab,
    var(--yayaw-muted) 100%,
    var(--yayaw-foreground) 4%
  );
}
.yayaw-form-builder-entry:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--yayaw-ring) 50%, transparent);
}
.yayaw-form-builder-form-entry {
  min-height: 36px;
  font-weight: 500;
}
.yayaw-form-builder-entry-icon,
.yayaw-form-builder-mark-icon {
  flex: none;
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-builder-entry-name {
  overflow: hidden;
  min-width: 0;
  flex: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-builder-row[data-kind="section"] .yayaw-form-builder-entry {
  font-weight: 500;
}
.yayaw-form-builder-row[data-kind="column"] .yayaw-form-builder-entry {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-builder-marks {
  display: flex;
  min-width: 0;
  flex-shrink: 1;
  align-items: center;
  gap: 6px;
}
.yayaw-form-builder-marks:empty {
  display: none;
}
.yayaw-form-builder-required {
  color: var(--yayaw-danger);
}
.yayaw-form-builder-detail {
  overflow: hidden;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-form-builder-group {
  display: grid;
  gap: 4px;
}
.yayaw-form-builder-group-title {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 12px 8px 0;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  font-weight: 500;
}
.yayaw-form-builder-count {
  font-variant-numeric: tabular-nums;
  font-weight: 400;
}
.yayaw-form-builder-note {
  margin: 0;
  padding: 0 8px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
}
.yayaw-form-builder-scroll > .yayaw-form-builder-note {
  padding-top: 12px;
}
.yayaw-form-builder-list {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.yayaw-form-builder-row {
  position: relative;
  display: flex;
  min-width: 0;
  align-items: center;
  border-radius: var(--yayaw-radius);
}
.yayaw-form-builder-row[data-kind="section"] {
  margin-top: 8px;
}
.yayaw-form-builder-row[data-kind="section"]:first-child {
  margin-top: 0;
}
.yayaw-form-builder-row[data-dragging] {
  opacity: 0.5;
}
.yayaw-form-builder-row[data-drop]::after {
  position: absolute;
  right: 4px;
  left: 4px;
  height: 2px;
  border-radius: 999px;
  background: var(--yayaw-primary);
  content: "";
}
.yayaw-form-builder-row[data-drop="before"]::after {
  top: -1px;
}
.yayaw-form-builder-row[data-drop="after"]::after {
  bottom: -1px;
}
.yayaw-form-builder-grip,
.yayaw-form-builder-grip-space {
  display: flex;
  width: 20px;
  height: 32px;
  flex: none;
  align-items: center;
  justify-content: center;
}
.yayaw-form-builder-grip {
  color: color-mix(in oklab, var(--yayaw-muted-foreground) 60%, transparent);
  cursor: grab;
  touch-action: none;
}
.yayaw-form-builder-grip:hover {
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-builder-grip:active {
  cursor: grabbing;
}
.yayaw-form-builder-menu {
  width: 256px;
}
.yayaw-form-builder-menu-label {
  padding: 6px 8px;
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  font-weight: 500;
}
.yayaw-form-builder-preview {
  background: color-mix(in oklab, var(--yayaw-muted) 40%, transparent);
}
.dark .yayaw-form-builder-preview {
  background: color-mix(in oklab, var(--yayaw-muted) 20%, transparent);
}
.yayaw-form-builder-preview-header {
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 4px 12px;
  background: var(--yayaw-background);
  padding: 8px 16px;
}
.yayaw-form-builder-closed {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}
.yayaw-form-builder-preview-body {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 20px 12px;
}
@media (min-width: 640px) {
  .yayaw-form-builder-preview-body {
    padding: 32px 24px;
  }
}
.yayaw-form-builder-preview-inner {
  display: grid;
  width: 100%;
  max-width: 640px;
  gap: 12px;
  margin: 0 auto;
}
.yayaw-form-builder-preview-body [data-builder-selected] {
  border-radius: 6px;
  outline: 2px solid color-mix(in oklab, var(--yayaw-primary) 60%, transparent);
  outline-offset: 4px;
}
.yayaw-form-builder-properties-body {
  display: grid;
  min-width: 0;
  gap: 16px;
  padding: 16px;
}
.yayaw-form-builder-section {
  display: grid;
  min-width: 0;
  gap: 12px;
}
.yayaw-form-builder-section-title {
  margin: 0;
  font-size: 14px;
  font-weight: 500;
}
.yayaw-form-builder-rules {
  display: grid;
  min-width: 0;
  gap: 8px;
}
.yayaw-form-builder-rules .yayaw-form-rule-summary {
  padding: 0;
}
.yayaw-form-builder-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  border-top: 1px solid var(--yayaw-border);
  padding-top: 16px;
}
.yayaw-button.yayaw-form-builder-remove {
  margin-left: auto;
  color: var(--yayaw-danger);
}
.yayaw-form-builder-reset {
  display: grid;
  justify-items: start;
  gap: 6px;
  border-top: 1px solid var(--yayaw-border);
  padding-top: 16px;
}
.yayaw-form-builder-tabs {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
}
.yayaw-form-builder-tab-list {
  display: flex;
  height: 44px;
  flex: none;
  border-bottom: 1px solid var(--yayaw-border);
  padding: 0 8px;
}
.yayaw-form-builder-tab {
  position: relative;
  flex: 1;
  border: 0;
  background: transparent;
  color: var(--yayaw-muted-foreground);
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
}
.yayaw-form-builder-tab[data-state="active"] {
  color: var(--yayaw-foreground);
}
.yayaw-form-builder-tab[data-state="active"]::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  background: var(--yayaw-foreground);
  content: "";
}
.yayaw-form-builder-tab:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px
    color-mix(in srgb, var(--yayaw-ring) 50%, transparent);
}
.yayaw-form-builder-tab-panel {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
}
.yayaw-form-builder-tab-panel[hidden] {
  display: none;
}
.yayaw-form-builder[data-compact] .yayaw-form-builder-entry {
  min-height: 40px;
}
.yayaw-form-builder-confirm-backdrop {
  position: fixed;
  z-index: 80;
  inset: 0;
  background: rgba(0, 0, 0, 0.1);
}
.yayaw-form-builder-confirm {
  position: fixed;
  z-index: 81;
  top: 50%;
  left: 50%;
  display: grid;
  width: min(440px, calc(100vw - 32px));
  gap: 12px;
  border-radius: 12px;
  background: var(--yayaw-background);
  padding: 24px;
  color: var(--yayaw-foreground);
  box-shadow:
    0 0 0 1px color-mix(in oklab, var(--yayaw-foreground) 10%, transparent),
    0 10px 15px -3px rgb(0 0 0 / 0.1);
  font-size: 14px;
  line-height: 1.4;
  transform: translate(-50%, -50%);
}
.yayaw-form-builder-confirm-title {
  margin: 0;
  font-size: 18px;
  font-weight: 500;
}
.yayaw-form-builder-confirm-description {
  margin: 0;
  color: var(--yayaw-muted-foreground);
}
.yayaw-form-builder-confirm-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
}
.yayaw-button.yayaw-form-builder-discard {
  background: color-mix(in oklab, var(--yayaw-danger) 10%, transparent);
  color: var(--yayaw-danger);
}
.yayaw-button.yayaw-form-builder-discard:hover:not(:disabled) {
  background: color-mix(in oklab, var(--yayaw-danger) 20%, transparent);
}
.dark .yayaw-button.yayaw-form-builder-discard {
