/** Framework-independent adapters. Also copied into the standalone Vue registry. */
import { calendarDay } from "./date-filter-days";
import {
  formatLocation,
  locationValueError,
  matchesLocationFilter,
} from "./location-model";
import {
  type ColumnValueFormat,
  formatColumnValue,
  formatDateValue,
  parseDateValue,
