export const useYayawTable = <TData extends RowData>(
  options: Omit<TableOptions<YayawTableFeatures, TData>, "features">
) => {
  Object.defineProperty(options, "features", {
    configurable: true,
    enumerable: true,
    value: yayawTableFeatures,
