  /** Replaces the locale's decimal separator. */
  decimalSeparator?: string;
  prefix?: string;
  suffix?: string;
  signDisplay?: "always" | "auto" | "exceptZero" | "never";
  /** `"parentheses"` shows negatives as (1,234.00), as in accounting. */
  negative?: "minus" | "parentheses";
  /** Percent input: `"fraction"` (0.25 = 25%, default) or `"whole"` (25 = 25%). */
  percentBase?: "fraction" | "whole";
  /** Render a progress bar beside the value, filled against `max`. */
  display?: "bar" | "number";
  /** Full-bar value; defaults to 1 for fraction percents and 100 otherwise. */
  max?: number;
}

export type NumberFormatConfig = ColumnNumberFormat | NumberFormatPreset;

const PRESET_SEPARATORS: Record<
  Exclude<NumberFormatPreset, "locale">,
  { thousandsSeparator: string; decimalSeparator: string; decimals: number }
> = {
  space: { thousandsSeparator: " ", decimalSeparator: ".", decimals: 2 },
  dot: { thousandsSeparator: ".", decimalSeparator: ",", decimals: 2 },
  comma: { thousandsSeparator: ",", decimalSeparator: ".", decimals: 2 },
};

/**
 * Presets become explicit options; objects pass through. The `"locale"`
 * preset keeps its historical two decimals at most.
 */
export function resolveNumberFormat(
  config: NumberFormatConfig | undefined
): ColumnNumberFormat {
  if (config === undefined) {
    return {};
  }
  if (config === "locale") {
    return { maximumFractionDigits: 2 };
  }
  return typeof config === "string" ? PRESET_SEPARATORS[config] : config;
}

function numberStyle(options: ColumnNumberFormat): Intl.NumberFormatOptions {
  const style = options.style ?? (options.currency ? "currency" : "decimal");
  if (style === "compact") {
    return { notation: "compact" };
  }
  if (style === "currency") {
    return {
      style,
      currency: options.currency ?? "USD",
      currencyDisplay: options.currencyDisplay,
    };
  }
  if (style === "unit") {
    return { style, unit: options.unit, unitDisplay: options.unitDisplay };
  }
  return { style };
}

function fractionDigits(options: ColumnNumberFormat): Intl.NumberFormatOptions {
  const fixed = options.decimals ?? options.decimalPlaces;
  if (fixed !== undefined) {
    return { minimumFractionDigits: fixed, maximumFractionDigits: fixed };
  }
  return {
    minimumFractionDigits: options.minimumFractionDigits,
    maximumFractionDigits: options.maximumFractionDigits,
  };
}

/** The value Intl receives: whole percents are divided by 100. */
function intlValue(value: number, options: ColumnNumberFormat): number {
  return options.style === "percent" && options.percentBase === "whole"
    ? value / 100
    : value;
}

export function formatNumberValue(
  value: unknown,
  config?: NumberFormatConfig,
  fallbackLocale?: string
): string {
  if (value === null || value === undefined || value === "") {
    return "—";
  }
  const numeric = typeof value === "number" ? value : Number(value);
  if (!Number.isFinite(numeric)) {
    return String(value);
  }
  const options = resolveNumberFormat(config);
  const parentheses = options.negative === "parentheses" && numeric < 0;
  const formatter = new Intl.NumberFormat(options.locale ?? fallbackLocale, {
    ...numberStyle(options),
    ...fractionDigits(options),
    signDisplay: parentheses ? "never" : options.signDisplay,
    useGrouping: options.thousandsSeparator !== "none",
  });
  const text = formatter
    .formatToParts(intlValue(parentheses ? -numeric : numeric, options))
    .map((part) => {
      if (part.type === "group" && options.thousandsSeparator !== undefined) {
        return options.thousandsSeparator === "none"
          ? ""
          : options.thousandsSeparator;
      }
      if (part.type === "decimal" && options.decimalSeparator !== undefined) {
        return options.decimalSeparator;
      }
      return part.value;
    })
    .join("");
  const affixed = `${options.prefix ?? ""}${text}${options.suffix ?? ""}`;
  return parentheses ? `(${affixed})` : affixed;
}

/** Fill ratio from 0 to 1 for the `display: "bar"` rendering. */
export function numberBarRatio(
  value: unknown,
  config?: NumberFormatConfig
): number | undefined {
  const options = resolveNumberFormat(config);
  const numeric = typeof value === "number" ? value : Number(value);
  if (options.display !== "bar" || !Number.isFinite(numeric)) {
    return;
  }
  const fraction =
    options.style === "percent" && options.percentBase !== "whole";
  const max = options.max ?? (fraction ? 1 : 100);
  return max > 0 ? Math.min(1, Math.max(0, numeric / max)) : 0;
}

/** Every date preset understood by both editions. */
export const DATE_DISPLAY_PRESETS = [
  "localized-short",
  "localized-medium",
  "localized-long",
  "month-name-long",
  "month-year",
  "dmy-numeric",
  "dmy-short",
  "mdy-numeric",
  "mdy-short",
  "iso-date",
  "iso",
  "date",
  "short",
  "long",
  "dateTime",
  "time",
  "relative",
] as const;

export type DateDisplayPreset = (typeof DATE_DISPLAY_PRESETS)[number];

export interface ColumnDateFormat {
  preset?: DateDisplayPreset;
  /** date-fns pattern such as `"dd MMM yyyy"`; wins over the preset. */
  pattern?: string;
  locale?: string;
  /**
   * IANA zone such as `"Europe/Paris"`, for presets and patterns alike.
   * Date-only values are calendar days and never shift.
   */
  timeZone?: string;
  /** Force a 12- or 24-hour clock where a time is shown. */
  hour12?: boolean;
  /** Reference instant for `"relative"`, mainly for tests. */
  now?: Date;
}

const DATE_ONLY = /^\d{4}-\d{2}-\d{2}$/;

/** Date-only strings are calendar days in local time; other values are instants. */
export function parseDateValue(value: unknown): Date | undefined {
  if (value === null || value === undefined || value === "") {
    return;
  }
  let date: Date;
  if (value instanceof Date) {
    date = value;
  } else if (typeof value === "string") {
    date = DATE_ONLY.test(value)
      ? new Date(`${value}T00:00:00`)
      : parseISO(value);
    if (!isValid(date)) {
      // Formats the browser accepted before, such as "2026/09/05".
      date = new Date(value);
    }
  } else {
    date = new Date(value as number);
  }
  return isValid(date) ? date : undefined;
}

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 31_536_000],
  ["month", 2_592_000],
  ["week", 604_800],
  ["day", 86_400],
  ["hour", 3600],
  ["minute", 60],
  ["second", 1],
];

function relative(date: Date, locale: string | undefined, now: Date): string {
  const seconds = (date.getTime() - now.getTime()) / 1000;
  const [unit, size] = RELATIVE_UNITS.find(
    ([, length]) => Math.abs(seconds) >= length
  ) ??
    RELATIVE_UNITS.at(-1) ?? ["second", 1];
  return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(
    Math.round(seconds / size),
    unit
  );
}

const INTL_PRESETS: Partial<
  Record<DateDisplayPreset, Intl.DateTimeFormatOptions>
> = {
  "localized-short": { dateStyle: "short" },
  short: { dateStyle: "short" },
  "localized-medium": { dateStyle: "medium" },
  date: { dateStyle: "medium" },
  "localized-long": { dateStyle: "long" },
  long: { dateStyle: "full" },
  "month-name-long": { day: "2-digit", month: "long", year: "numeric" },
  "month-year": { month: "long", year: "numeric" },
  dateTime: { dateStyle: "medium", timeStyle: "short" },
  time: { timeStyle: "short" },
};

function numericParts(date: Date, timeZone?: string) {
  const parts = new Intl.DateTimeFormat("en-US", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    timeZone,
  }).formatToParts(date);
  const get = (type: string) =>
    parts.find((part) => part.type === type)?.value ?? "";
  return { day: get("day"), month: get("month"), year: get("year") };
}

function numericPreset(
  preset: DateDisplayPreset,
  date: Date,
  timeZone?: string
): string | undefined {
  const { day, month, year } = numericParts(date, timeZone);
  const short = year.slice(-2);
  switch (preset) {
    case "dmy-numeric":
      return `${day}/${month}/${year}`;
    case "dmy-short":
      return `${day}/${month}/${short}`;
    case "mdy-numeric":
      return `${month}/${day}/${year}`;
    case "mdy-short":
      return `${month}/${day}/${short}`;
    case "iso-date":
      return `${year}-${month}-${day}`;
    default:
      return;
  }
}

const KNOWN_TIME_ZONES = new Map<string, boolean>();

/** The zone when Intl knows it; an unknown zone shows local time. */
function knownTimeZone(timeZone: string | undefined): string | undefined {
  if (!timeZone) {
    return;
  }
  let known = KNOWN_TIME_ZONES.get(timeZone);
  if (known === undefined) {
    try {
      new Intl.DateTimeFormat("en-US", { timeZone }).format(0);
      known = true;
    } catch {
      known = false;
    }
    KNOWN_TIME_ZONES.set(timeZone, known);
  }
  return known ? timeZone : undefined;
}

/** A date-only string is a calendar day: no time zone moves it. */
function isCalendarDay(value: unknown): boolean {
  return typeof value === "string" && DATE_ONLY.test(value);
}

/**
 * The wall-clock time of an instant in `timeZone`, as a local Date, so a
 * date-fns pattern prints the zone's day and hour.
 */
function wallClock(date: Date, timeZone: string): Date {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
  }).formatToParts(date);
  const part = (type: Intl.DateTimeFormatPartTypes) =>
    Number(parts.find((item) => item.type === type)?.value ?? 0);
  const local = new Date(date.getTime());
  local.setFullYear(part("year"), part("month") - 1, part("day"));
  local.setHours(
    part("hour"),
    part("minute"),
    part("second"),
    date.getMilliseconds()
  );
  return local;
}

function formatWithPattern(
  date: Date,
  pattern: string,
  timeZone: string | undefined
): string | undefined {
  try {
    return formatPattern(timeZone ? wallClock(date, timeZone) : date, pattern);
  } catch {
    // A pattern date-fns rejects falls back to the preset.
    return;
  }
}

/**
 * A date as its column shows it: the pattern wins over the preset, and
 * `timeZone` applies to both. Date-only values are calendar days that no
 * zone shifts.
 */
export function formatDateValue(
  value: unknown,
  options: ColumnDateFormat = {}
): string {
  if (value === null || value === undefined || value === "") {
    return "—";
  }
  const date = parseDateValue(value);
  if (!date) {
    return String(value);
  }
  const timeZone = isCalendarDay(value)
    ? undefined
    : knownTimeZone(options.timeZone);
  const patterned = options.pattern
    ? formatWithPattern(date, options.pattern, timeZone)
    : undefined;
  if (patterned !== undefined) {
    return patterned;
  }
  const preset = options.preset ?? "localized-short";
  if (preset === "iso") {
    return date.toISOString();
  }
  if (preset === "relative") {
    return relative(date, options.locale, options.now ?? new Date());
  }
  const numeric = numericPreset(preset, date, timeZone);
  if (numeric) {
    return numeric;
  }
  return new Intl.DateTimeFormat(options.locale, {
    ...(INTL_PRESETS[preset] ?? INTL_PRESETS["localized-short"]),
    hour12: options.hour12,
    timeZone,
  }).format(date);
}

/**
 * The format settings a column declares. React and Vue column definitions
 * both fit, so every surface formats a field from the same declaration.
 */
export interface ColumnValueFormat {
  type?: string;
  numberFormat?: NumberFormatConfig;
  dateDisplayPreset?: DateDisplayPreset;
  dateFormat?: string;
  timeZone?: string;
  hour12?: boolean;
}

/**
 * A column's date options: its pattern, else its preset, else the table's
 * default preset; its time zone and clock apply to each.
 */
export function columnDateFormat(
  column: ColumnValueFormat | undefined,
  locale?: string,
  fallbackPreset?: DateDisplayPreset
): ColumnDateFormat {
  return {
    preset: column?.dateDisplayPreset ?? fallbackPreset,
    pattern: column?.dateFormat || undefined,
    locale,
    timeZone: column?.timeZone,
    hour12: column?.hour12,
  };
}

/** date-fns tokens, literals and quoted text, as date-fns reads a pattern. */
const PATTERN_TOKENS =
  /[yYQqMLwIdDecihHKkms]o|(\w)\1*|''|'(?:''|[^'])+(?:'|$)|./g;
const DATE_TOKEN = /^[GyYRuQqMLwIdDEeciP]/;
const TIME_TOKEN = /^[aAbBhHKkmsSXxOztTp]/;

/**
 * The date part of a date-fns pattern, for values that are days (chart
 * buckets, filter dates): `"dd/MM/yyyy HH:mm"` gives `"dd/MM/yyyy"`.
 */
export function datePartOfPattern(pattern: string): string | undefined {
  const tokens = pattern.match(PATTERN_TOKENS) ?? [];
  const dated = tokens.map((token) => DATE_TOKEN.test(token));
  const first = dated.indexOf(true);
  const last = dated.lastIndexOf(true);
  if (first < 0) {
    return;
  }
  return tokens
    .slice(first, last + 1)
    .filter((token) => !TIME_TOKEN.test(token))
    .join("");
}

/** Presets that show a day without a time. */
const DAY_PRESETS = new Set<DateDisplayPreset>([
  "localized-short",
  "localized-medium",
  "localized-long",
  "month-name-long",
  "dmy-numeric",
  "dmy-short",
  "mdy-numeric",
  "mdy-short",
  "iso-date",
  "date",
  "short",
  "long",
]);

/**
 * How a column shows a calendar day (a chart day, a filter date): the date
 * part of its pattern or preset, never a time, and no zone shift.
 */
export function columnDayFormat(
  column: ColumnValueFormat | undefined,
  locale?: string,
  fallbackPreset?: DateDisplayPreset
): ColumnDateFormat {
  const preset = column?.dateDisplayPreset ?? fallbackPreset;
  let dayPreset: DateDisplayPreset = "localized-medium";
  if (preset && DAY_PRESETS.has(preset)) {
    dayPreset = preset;
  } else if (preset === "iso") {
    dayPreset = "iso-date";
  }
  return {
    preset: dayPreset,
    pattern: column?.dateFormat
      ? datePartOfPattern(column.dateFormat)
      : undefined,
    locale,
  };
}

/** A calendar day (`YYYY-MM-DD` or a local Date) in its column's day format. */
export function formatColumnDay(
  value: unknown,
  column: ColumnValueFormat | undefined,
  locale?: string,
  fallbackPreset?: DateDisplayPreset
): string {
  return formatDateValue(
    value,
    columnDayFormat(column, locale, fallbackPreset)
  );
}

/** A number in its column's format and the table locale. */
export function formatColumnNumber(
  value: unknown,
  column: ColumnValueFormat | undefined,
  locale?: string
): string {
  return formatNumberValue(value, column?.numberFormat, locale);
}

/** A date in its column's pattern or preset, time zone and clock. */
export function formatColumnDate(
  value: unknown,
  column: ColumnValueFormat | undefined,
  locale?: string,
  fallbackPreset?: DateDisplayPreset
): string {
  return formatDateValue(
    value,
    columnDateFormat(column, locale, fallbackPreset)
  );
}

/** Calculations whose result is a value of the column: same unit, same format. */
const VALUE_CALCULATIONS = new Set([
  "sum",
  "average",
  "median",
  "min",
  "max",
  "range",
]);

/**
 * A footer, group or widget calculation as people read it. Sums, averages,
 * medians, extremes and ranges keep the column's number format; a date
 * column's earliest and latest values keep its date format and its range
 * reads in days. Counts stay plain whole numbers and `percent_*` shares
 * (0–100) plain percents, in the table locale.
 */
export function formatColumnCalculation(
  value: unknown,
  calculation: string,
  column: ColumnValueFormat | undefined,
  locale?: string,
  fallbackPreset?: DateDisplayPreset
): string {
  if (value === null || value === undefined || value === "") {
    return "—";
  }
  const numeric = typeof value === "number" ? value : Number(value);
  if (calculation.startsWith("percent_")) {
    return Number.isFinite(numeric)
      ? new Intl.NumberFormat(locale, {
          style: "percent",
          maximumFractionDigits: 0,
        }).format(numeric / 100)
      : String(value);
  }
  if (!VALUE_CALCULATIONS.has(calculation)) {
    return Number.isFinite(numeric)
      ? new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(
          numeric
        )
      : String(value);
  }
  if (column?.type === "date") {
    if (calculation !== "range") {
      return formatColumnDate(value, column, locale, fallbackPreset);
    }
    return Number.isFinite(numeric)
      ? new Intl.NumberFormat(locale, {
          style: "unit",
          unit: "day",
          unitDisplay: "narrow",
          maximumFractionDigits: 0,
        }).format(numeric)
      : String(value);
  }
  return formatColumnNumber(value, column, locale);
}

/**
 * Number and date values in their column's format; `undefined` for the other
 * types, whose text (option labels, places, links) each surface owns.
 */
export function formatColumnValue(
  value: unknown,
  column: ColumnValueFormat | undefined,
  locale?: string,
  fallbackPreset?: DateDisplayPreset
): string | undefined {
  if (column?.type === "number") {
    return formatColumnNumber(value, column, locale);
  }
  if (column?.type === "date") {
    return formatColumnDate(value, column, locale, fallbackPreset);
  }
  return;
}

/**
 * Whether a card property has nothing to show (null, blank text, empty list);
 * compact board cards leave such properties out in both editions.
 */
export function isBlankCardValue(value: unknown): boolean {
  if (value === null || value === undefined) {
    return true;
  }
  if (typeof value === "string") {
    return value.trim() === "";
  }
  return Array.isArray(value) && value.length === 0;
}

/**
 * Saved-view settings (a saved view's `config`, without its identity) as a
 * dashboard embeds them (`widget.view`) and as hosts receive them from
 * browsers or AI tools. `sanitizeViewConfig` is strict and server-safe:
 * unknown keys are stripped, sizes capped, every value type-checked before a
 * display mode's normalizer reads it, and hostile JSON never throws. Pure and
 * shared by the React and Vue editions (synced to Vue).
 */
// biome-ignore-all assist/source/organizeImports: the React copy reads the planning engine from its parent folder, the Vue copy from beside it; both keep this order.
import { normalizeGanttView } from "./planning/engine";
import type { TableGanttViewConfig } from "./planning/types";
import {
  GENERIC_MODE_CONFIG_KEYS,
  type GenericModeViewConfigs,
  isTableDisplayMode,
  normalizeModeConfig,
  type TableDisplayMode,
} from "./display-modes";
import {
  type GalleryViewState,
  normalizeGalleryViewConfig,
} from "./gallery-view-state";
import { isTableDensity, type TableDensity } from "./table-contracts";

// JSON ---------------------------------------------------------------------------

/** A JSON object. */
export interface ViewJsonObject {
  [key: string]: ViewJson;
}

/** A JSON value. */
export type ViewJson =
  | string
  | number
  | boolean
  | null
  | ViewJson[]
  | ViewJsonObject;

type Row = Record<string, unknown>;

const isRecord = (value: unknown): value is Row =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;

/** A JSON path: `base.key`, `base["odd key"]` or `base[3]`. */
export function jsonPath(base: string, key: string | number): string {
  if (typeof key === "number") {
    return `${base}[${key}]`;
  }
  if (!IDENTIFIER.test(key)) {
    return `${base}[${JSON.stringify(key)}]`;
  }
  return base ? `${base}.${key}` : key;
}

/** What a value is, for messages: a short quoted text, or its type. */
export function describeValue(value: unknown): string {
  if (typeof value === "string") {
    return JSON.stringify(value.length > 40 ? `${value.slice(0, 40)}…` : value);
  }
  if (Array.isArray(value)) {
    return "a list";
  }
  return value === null ? "null" : typeof value;
}

/** Keys never copied: they could reach an object's prototype. */
export const UNSAFE_JSON_KEYS: ReadonlySet<string> = new Set([
  "__proto__",
  "constructor",
  "prototype",
]);

export interface JsonCopyOptions {
  /** Deepest nesting kept; deeper values are left out. */
  depth: number;
  /** Characters of JSON the copy may take; copying stops beyond. */
  size: number;
  /** Items kept per list; the others are left out. */
  items?: number;
  /** Characters kept per text; longer texts are cut. */
  text?: number;
}

export interface JsonCopyIssue {
  code: "invalidValue" | "truncated";
  path: string;
  message: string;
}

export interface JsonCopy {
  value?: ViewJson;
  issues: JsonCopyIssue[];
  /** The value was larger than `size`: the copy is incomplete. */
  oversize: boolean;
}

interface CopyState {
  options: JsonCopyOptions;
  issues: JsonCopyIssue[];
  size: number;
  oversize: boolean;
}

const MAX_COPY_ISSUES = 50;

function copyIssue(
  state: CopyState,
  code: JsonCopyIssue["code"],
  path: string,
  message: string
) {
  if (state.issues.length < MAX_COPY_ISSUES) {
    state.issues.push({ code, path, message });
  }
}

/** Counts `size` characters; false once the copy is too large. */
function charge(state: CopyState, size: number): boolean {
  state.size += size;
  if (state.size > state.options.size) {
    state.oversize = true;
  }
  return !state.oversize;
}

function copyText(value: string, path: string, state: CopyState) {
  const max = state.options.text;
  const text =
    max !== undefined && value.length > max ? value.slice(0, max) : value;
  if (text !== value) {
    copyIssue(state, "truncated", path, `Texts are cut at ${max} characters.`);
  }
  return charge(state, text.length + 2) ? text : undefined;
}

function copyPrimitive(
  value: unknown,
  path: string,
  state: CopyState
): ViewJson | undefined {
  if (typeof value === "string") {
    return copyText(value, path, state);
  }
  if (typeof value === "boolean") {
    return charge(state, 5) ? value : undefined;
  }
  if (typeof value === "number" && Number.isFinite(value)) {
    return charge(state, String(value).length) ? value : undefined;
  }
  if (value !== undefined) {
    copyIssue(
      state,
      "invalidValue",
      path,
      `${describeValue(value)} is not JSON and was left out.`
    );
  }
  return;
}

function copyList(
  value: unknown[],
  depth: number,
  path: string,
  state: CopyState
): ViewJson[] {
  const max = state.options.items ?? value.length;
  if (value.length > max) {
    copyIssue(state, "truncated", path, `Lists keep their first ${max} items.`);
  }
  const list: ViewJson[] = [];
  for (const [index, item] of value.slice(0, max).entries()) {
    const copied = copyNode(item, depth, jsonPath(path, index), state);
    if (state.oversize) {
      break;
    }
    if (copied !== undefined) {
      list.push(copied);
    }
  }
  return list;
}

function copyObject(
  value: Row,
  depth: number,
  path: string,
  state: CopyState
): ViewJsonObject {
  const object: ViewJsonObject = {};
  const keys = Object.keys(value);
  const max = state.options.items ?? keys.length;
  if (keys.length > max) {
    copyIssue(
      state,
      "truncated",
      path,
      `Objects keep their first ${max} keys.`
    );
  }
  for (const key of keys.slice(0, max)) {
    const keyPath = jsonPath(path, key);
    if (UNSAFE_JSON_KEYS.has(key)) {
      copyIssue(state, "invalidValue", keyPath, `"${key}" is not allowed.`);
      continue;
    }
    const copied = copyNode(value[key], depth, keyPath, state);
    if (state.oversize || !charge(state, key.length + 3)) {
      break;
    }
    if (copied !== undefined) {
      object[key] = copied;
    }
  }
  return object;
}

function copyNode(
  value: unknown,
  depth: number,
  path: string,
  state: CopyState
): ViewJson | undefined {
  if (state.oversize) {
    return;
  }
  if (value === null) {
    return charge(state, 4) ? null : undefined;
  }
  if (typeof value !== "object") {
    return copyPrimitive(value, path, state);
  }
  if (depth <= 0) {
    copyIssue(
      state,
      "truncated",
      path,
      "Values nested this deep are left out."
    );
    return;
  }
  if (Array.isArray(value)) {
    return charge(state, 2)
      ? copyList(value, depth - 1, path, state)
      : undefined;
  }
  if (value instanceof Date) {
    const time = value.getTime();
    return Number.isFinite(time)
      ? copyText(value.toISOString(), path, state)
      : undefined;
  }
  return charge(state, 2)
    ? copyObject(value as Row, depth - 1, path, state)
    : undefined;
}

/**
 * A deep copy of JSON data. Keys that could reach a prototype (`__proto__`,
 * `constructor`, `prototype`), functions, symbols, non-finite numbers and
 * values nested deeper than `depth` are left out, lists and texts are capped,
 * and copying stops at `size` characters of JSON. Never throws.
 */
export function copyJson(
  value: unknown,
  options: JsonCopyOptions,
  path = ""
): JsonCopy {
  const state: CopyState = { options, issues: [], size: 0, oversize: false };
  try {
    const copied = copyNode(value, options.depth, path, state);
    return {
      ...(copied === undefined || state.oversize ? {} : { value: copied }),
      issues: state.issues,
      oversize: state.oversize,
    };
  } catch {
    // Throwing getters and proxies are unreadable, not fatal.
    copyIssue(state, "invalidValue", path, "This value could not be read.");
    return { issues: state.issues, oversize: state.oversize };
  }
}

// Contract -------------------------------------------------------------------------

/** Filter operators a saved view may use: every operator of both editions. */
export const VIEW_FILTER_OPERATORS = [
  "contains",
  "notContains",
  "equals",
  "notEquals",
  "startsWith",
  "endsWith",
  "isEmpty",
  "isNotEmpty",
  "greaterThan",
  "greaterThanOrEqual",
  "lessThan",
  "lessThanOrEqual",
  "between",
  "before",
  "after",
  "is",
  "isNot",
  "isAnyOf",
  "isNoneOf",
  "in",
  "notIn",
  "containsAll",
  "containsNone",
  "isTrue",
  "isFalse",
  "withinDistance",
  "withinBounds",
] as const;

export type ViewFilterOperator = (typeof VIEW_FILTER_OPERATORS)[number];

const OPERATORS: ReadonlySet<string> = new Set(VIEW_FILTER_OPERATORS);

export interface ViewSort {
  id: string;
  desc: boolean;
}

export interface ViewColumnFilter {
  id: string;
  value: ViewJson;
}

/** An advanced filter rule. A view matching any rule marks each with `joinOperator: "or"`. */
export interface ViewFilterRule {
  id: string;
  columnId: string;
  operator: ViewFilterOperator;
  type?: string;
  values?: ViewJson;
  isActive: boolean;
  joinOperator?: "or";
  label?: string;
  createdAt?: string;
  updatedAt?: string;
}

export interface ViewKanbanSettings {
  titleColumn?: string;
  cardColumnIds?: string[];
  showCardLabels?: boolean;
}

export interface ViewColumnPinning {
  left: string[];
  right: string[];
}

/** Saved-view settings, sanitized: what `initialView.config` and saved views take. */
export interface ViewConfig extends GenericModeViewConfigs {
  displayMode?: TableDisplayMode;
  density?: TableDensity;
  footerCalculationsVisible?: boolean;
  globalSearch?: string;
  sorting?: ViewSort[];
  columnFilters?: ViewColumnFilter[];
  advancedFilters?: ViewFilterRule[];
  columnOrder?: string[];
  columnVisibility?: Record<string, boolean>;
  columnSizing?: Record<string, number>;
  columnPinning?: ViewColumnPinning;
  grouping?: string[];
  pageSize?: number;
  kanban?: ViewKanbanSettings;
  gallery?: GalleryViewState;
  gantt?: TableGanttViewConfig;
}

export interface ViewConfigLimits {
  /** Sort rules, column filters and filter rules, each. */
  rules: number;
  /** Column ids in one list: order, visibility, widths, pinning, grouping, card properties. */
  columns: number;
  /** Values of one filter rule or column filter. */
  values: number;
  /** Characters of one text: column ids, the search, filter values. */
  text: number;
  /** Nesting kept in display mode settings. */
  depth: number;
  /** Largest page size. */
  pageSize: number;
  /** Characters of JSON the settings of one display mode may take. */
  modeSettings: number;
}

export const VIEW_CONFIG_LIMITS: Readonly<ViewConfigLimits> = {
  rules: 50,
  columns: 200,
  values: 100,
  text: 500,
  depth: 16,
  pageSize: 500,
  modeSettings: 65_536,
};

export type ViewConfigIssueCode = "invalidValue" | "truncated" | "unknownKey";

export interface ViewConfigIssue {
  code: ViewConfigIssueCode;
  message: string;
  /** Errors lost something the settings asked for; warnings only dropped unknown keys. */
  severity: "error" | "warning";
  /** JSON path inside the settings (`sorting[0].id`); empty for the settings themselves. */
  path: string;
}

export interface SanitizedViewConfig {
  config: ViewConfig;
  issues: ViewConfigIssue[];
}

const SEVERITY: Record<ViewConfigIssueCode, "error" | "warning"> = {
  invalidValue: "error",
  truncated: "error",
  unknownKey: "warning",
};
const MAX_ISSUES = 100;
/** Items kept per list inside display mode settings (form questions, stages…). */
const MODE_ITEMS = 1000;
/** Nesting of filter values: lists of ranges at most. */
const VALUE_DEPTH = 3;
const DATE_TEXT = 64;
const RULE_TYPE = /^[A-Za-z][\w-]{0,39}$/;

interface Context {
  limits: ViewConfigLimits;
  issues: ViewConfigIssue[];
  add: (code: ViewConfigIssueCode, path: string, message: string) => void;
}

/** Positive whole limits override the defaults; anything else is ignored. */
function resolveLimits(limits: Partial<ViewConfigLimits>): ViewConfigLimits {
  const resolved = { ...VIEW_CONFIG_LIMITS };
  for (const key of Object.keys(resolved) as (keyof ViewConfigLimits)[]) {
    const value = limits[key];
    if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
      resolved[key] = Math.floor(value);
    }
  }
  return resolved;
}

function createContext(limits: Partial<ViewConfigLimits>): Context {
  const issues: ViewConfigIssue[] = [];
  return {
    limits: resolveLimits(limits),
    issues,
    add: (code, path, message) => {
      if (issues.length < MAX_ISSUES) {
        issues.push({ code, message, severity: SEVERITY[code], path });
      } else if (issues.length === MAX_ISSUES) {
        issues.push({
          code: "truncated",
          message: `More problems were found; only the first ${MAX_ISSUES} are listed.`,
          severity: "error",
          path: "",
        });
      }
    },
  };
}

// Values ----------------------------------------------------------------------------

function unknownKeys(
  value: Row,
  known: ReadonlySet<string>,
  path: string,
  context: Context
) {
  for (const key of Object.keys(value)) {
    if (!known.has(key)) {
      context.add(
        "unknownKey",
        jsonPath(path, key),
        `"${key}" is not a setting here and was removed.`
      );
    }
  }
}

/** A trimmed text, cut at the text limit; undefined when empty or not a text. */
function textOf(
  value: unknown,
  path: string,
  context: Context,
  max = context.limits.text
): string | undefined {
  if (value === undefined) {
    return;
  }
  if (typeof value !== "string") {
    context.add(
      "invalidValue",
      path,
      `Expected a text, got ${describeValue(value)}.`
    );
    return;
  }
  const text = value.trim();
  if (text.length > max) {
    context.add("truncated", path, `Texts are cut at ${max} characters.`);
    return text.slice(0, max);
  }
  return text || undefined;
}

/** A text that must be there: `message` explains a missing one. */
function requiredText(
  value: unknown,
  path: string,
  context: Context,
  message: string
): string | undefined {
  const text = textOf(value, path, context);
  if (!text && (value === undefined || typeof value === "string")) {
    context.add("invalidValue", path, message);
  }
  return text;
}

/** The list, or undefined (with an issue) when the value is not one; long lists are cut. */
function listOf(
  value: unknown,
  path: string,
  context: Context,
  max: number
): unknown[] | undefined {
  if (!Array.isArray(value)) {
    context.add(
      "invalidValue",
      path,
      `Expected a list, got ${describeValue(value)}.`
    );
    return;
  }
  if (value.length > max) {
    context.add("truncated", path, `Only the first ${max} items are kept.`);
    return value.slice(0, max);
  }
  return value;
}

function booleanOf(
  value: unknown,
  path: string,
  context: Context
): boolean | undefined {
  if (typeof value === "boolean") {
    return value;
  }
  context.add(
    "invalidValue",
    path,
    `Expected true or false, got ${describeValue(value)}.`
  );
  return;
}

/** Column ids: texts, each once. */
function columnIds(
  value: unknown,
  path: string,
  context: Context
): string[] | undefined {
  const items = listOf(value, path, context, context.limits.columns);
  if (!items) {
    return;
  }
  const ids: string[] = [];
  for (const [index, item] of items.entries()) {
    const itemPath = jsonPath(path, index);
    const id = textOf(item, itemPath, context);
    if (id && ids.includes(id)) {
      context.add("invalidValue", itemPath, `Column "${id}" appears twice.`);
    } else if (id) {
      ids.push(id);
    }
  }
  return ids;
}

/** A filter's value: JSON, lists capped, texts cut. */
function filterValue(
  value: unknown,
  path: string,
  context: Context
): ViewJson | undefined {
  const { text, values } = context.limits;
  const copy = copyJson(
    value,
    { depth: VALUE_DEPTH, items: values, text, size: (text + 3) * values },
    path
  );
  for (const issue of copy.issues) {
    context.add(issue.code, issue.path, issue.message);
  }
  if (copy.oversize) {
    context.add("truncated", path, "This filter value is too large.");
  }
  return copy.value;
}

// Fields ----------------------------------------------------------------------------

type FieldSanitizer = (
  value: unknown,
  path: string,
  context: Context,
  key: string
) => unknown;

const sanitizeDisplayMode: FieldSanitizer = (value, path, context) => {
  if (isTableDisplayMode(value)) {
    return value;
  }
  context.add(
    "invalidValue",
    path,
    `Unknown display mode ${describeValue(value)}.`
  );
  return;
};

const sanitizeDensity: FieldSanitizer = (value, path, context) => {
  if (isTableDensity(value)) {
    return value;
  }
  context.add("invalidValue", path, `Unknown density ${describeValue(value)}.`);
  return;
};

const sanitizeBoolean: FieldSanitizer = (value, path, context) =>
  booleanOf(value, path, context);

const sanitizeText: FieldSanitizer = (value, path, context) =>
  textOf(value, path, context);

const sanitizePageSize: FieldSanitizer = (value, path, context) => {
  const size = typeof value === "string" ? Number(value) : value;
  if (typeof size !== "number" || !Number.isFinite(size) || size < 1) {
    context.add(
      "invalidValue",
      path,
      `Page sizes are whole numbers from 1, got ${describeValue(value)}.`
    );
    return;
  }
  const max = context.limits.pageSize;
  if (size > max) {
    context.add("truncated", path, `Page sizes are at most ${max}.`);
    return max;
  }
  return Math.trunc(size);
};

const SORT_KEYS: ReadonlySet<string> = new Set(["id", "desc"]);

function sortOf(
  item: unknown,
  path: string,
  context: Context
): ViewSort | undefined {
  if (!isRecord(item)) {
    context.add("invalidValue", path, "Sort rules are `{ id, desc }` objects.");
    return;
  }
  unknownKeys(item, SORT_KEYS, path, context);
  const id = requiredText(
    item.id,
    jsonPath(path, "id"),
    context,
    "Sort rules need a column id."
  );
  if (!id) {
    return;
  }
  if (item.desc !== undefined && typeof item.desc !== "boolean") {
    context.add(
      "invalidValue",
      jsonPath(path, "desc"),
      "`desc` is true (descending) or false."
    );
    return;
  }
  return { id, desc: item.desc === true };
}

const sanitizeSorting: FieldSanitizer = (value, path, context) => {
  const items = listOf(value, path, context, context.limits.rules);
  const sorts: ViewSort[] = [];
  for (const [index, item] of (items ?? []).entries()) {
    const itemPath = jsonPath(path, index);
    const sort = sortOf(item, itemPath, context);
    if (sort && sorts.some((other) => other.id === sort.id)) {
      context.add(
        "invalidValue",
        itemPath,
        `Column "${sort.id}" is sorted twice.`
      );
    } else if (sort) {
      sorts.push(sort);
    }
  }
  return sorts.length ? sorts : undefined;
};

const COLUMN_FILTER_KEYS: ReadonlySet<string> = new Set(["id", "value"]);

function columnFilterOf(
  item: unknown,
  path: string,
  context: Context
): ViewColumnFilter | undefined {
  if (!isRecord(item)) {
    context.add(
      "invalidValue",
      path,
      "Column filters are `{ id, value }` objects."
    );
    return;
  }
  unknownKeys(item, COLUMN_FILTER_KEYS, path, context);
  const id = requiredText(
    item.id,
    jsonPath(path, "id"),
    context,
    "Column filters need a column id."
  );
  const value = filterValue(item.value, jsonPath(path, "value"), context);
  if (value === undefined && item.value === undefined) {
    context.add(
      "invalidValue",
      jsonPath(path, "value"),
      "Column filters need a value."
    );
  }
  return id && value !== undefined ? { id, value } : undefined;
}

const sanitizeColumnFilters: FieldSanitizer = (value, path, context) => {
  const items = listOf(value, path, context, context.limits.rules);
  const filters: ViewColumnFilter[] = [];
  for (const [index, item] of (items ?? []).entries()) {
    const itemPath = jsonPath(path, index);
    const filter = columnFilterOf(item, itemPath, context);
    if (filter && filters.some((other) => other.id === filter.id)) {
      context.add(
        "invalidValue",
        itemPath,
        `Column "${filter.id}" is filtered twice.`
      );
    } else if (filter) {
      filters.push(filter);
    }
  }
  return filters.length ? filters : undefined;
};

const RULE_KEYS: ReadonlySet<string> = new Set([
  "id",
  "columnId",
  "operator",
  "type",
  "values",
  "isActive",
  "joinOperator",
  "label",
  "createdAt",
  "updatedAt",
]);

function ruleStamp(
  value: unknown,
  path: string,
  context: Context
): string | undefined {
  if (value instanceof Date && Number.isFinite(value.getTime())) {
    return value.toISOString();
  }
  if (typeof value === "number" && Number.isFinite(value)) {
    return new Date(value).toISOString();
  }
  return textOf(value, path, context, DATE_TEXT);
}

/** A rule's optional parts: type, values, label, stamps and its join. */
function ruleDetails(
  item: Row,
  path: string,
  context: Context
): Partial<ViewFilterRule> {
  const details: Partial<ViewFilterRule> = {};
  if (item.type !== undefined) {
    if (typeof item.type === "string" && RULE_TYPE.test(item.type)) {
      details.type = item.type;
    } else {
      context.add(
        "invalidValue",
        jsonPath(path, "type"),
        `Unknown rule type ${describeValue(item.type)}.`
      );
    }
  }
  if (item.values !== undefined) {
    const values = filterValue(item.values, jsonPath(path, "values"), context);
    if (values !== undefined) {
      details.values = values;
    }
  }
  const label = textOf(item.label, jsonPath(path, "label"), context);
  const createdAt = ruleStamp(
    item.createdAt,
    jsonPath(path, "createdAt"),
    context
  );
  const updatedAt = ruleStamp(
    item.updatedAt,
    jsonPath(path, "updatedAt"),
    context
  );
  if (label) {
    details.label = label;
  }
  if (createdAt) {
    details.createdAt = createdAt;
  }
  if (updatedAt) {
    details.updatedAt = updatedAt;
  }
  if (item.joinOperator === "or") {
    details.joinOperator = "or";
  } else if (item.joinOperator !== undefined && item.joinOperator !== "and") {
    context.add(
      "invalidValue",
      jsonPath(path, "joinOperator"),
      '`joinOperator` is "and" or "or".'
    );
  }
  return details;
}

function ruleOf(
  item: unknown,
  path: string,
  context: Context,
  index: number
): ViewFilterRule | undefined {
  if (!isRecord(item)) {
    context.add("invalidValue", path, "Filter rules are objects.");
    return;
  }
  unknownKeys(item, RULE_KEYS, path, context);
  const columnId = requiredText(
    item.columnId,
    jsonPath(path, "columnId"),
    context,
    "Filter rules need a column id."
  );
  if (!columnId) {
    return;
  }
  if (!(typeof item.operator === "string" && OPERATORS.has(item.operator))) {
    context.add(
      "invalidValue",
      jsonPath(path, "operator"),
      `Unknown filter operator ${describeValue(item.operator)}.`
    );
    return;
  }
  const isActive =
    item.isActive === undefined
      ? true
      : booleanOf(item.isActive, jsonPath(path, "isActive"), context);
  return {
    id: textOf(item.id, jsonPath(path, "id"), context) ?? `rule-${index + 1}`,
    columnId,
    operator: item.operator as ViewFilterOperator,
    isActive: isActive !== false,
    ...ruleDetails(item, path, context),
  };
}

const ENVELOPE_KEYS: ReadonlySet<string> = new Set(["filters", "joinOperator"]);

/** Rules as React stores them: one list, each marked `joinOperator: "or"` when any may match. */
const sanitizeAdvancedFilters: FieldSanitizer = (value, path, context) => {
  let list = value;
  let listPath = path;
  let anyOf = false;
  if (isRecord(value)) {
    // The Vue envelope: `{ filters, joinOperator }`.
    unknownKeys(value, ENVELOPE_KEYS, path, context);
    anyOf = value.joinOperator === "or";
    list = value.filters ?? [];
    listPath = jsonPath(path, "filters");
  }
  const items = listOf(list, listPath, context, context.limits.rules);
  const rules: ViewFilterRule[] = [];
  for (const [index, item] of (items ?? []).entries()) {
    const rule = ruleOf(item, jsonPath(listPath, index), context, index);
    if (rule) {
      rules.push(rule);
    }
  }
  if (!rules.length) {
    return;
  }
  anyOf ||= rules[0]?.joinOperator === "or";
  return rules.map(({ joinOperator: _join, ...rule }) =>
    anyOf ? { ...rule, joinOperator: "or" } : rule
  );
};

const sanitizeColumnList: FieldSanitizer = (value, path, context) => {
  const ids = columnIds(value, path, context);
  return ids?.length ? ids : undefined;
};

/** Entries of a column map, capped; keys are column ids. */
function columnEntries(
  value: unknown,
  path: string,
  context: Context
): [string, unknown, string][] {
  if (!isRecord(value)) {
    context.add(
      "invalidValue",
      path,
      `Expected an object, got ${describeValue(value)}.`
    );
    return [];
  }
  const keys = Object.keys(value);
  const max = context.limits.columns;
  if (keys.length > max) {
    context.add("truncated", path, `Only the first ${max} columns are kept.`);
  }
  const entries: [string, unknown, string][] = [];
  for (const key of keys.slice(0, max)) {
    const keyPath = jsonPath(path, key);
    const id = key.trim();
    if (!id || id.length > context.limits.text || UNSAFE_JSON_KEYS.has(id)) {
      context.add(
        "invalidValue",
        keyPath,
        `${describeValue(key)} is not a column id.`
      );
    } else {
      entries.push([id, value[key], keyPath]);
    }
  }
  return entries;
}

const sanitizeVisibility: FieldSanitizer = (value, path, context) => {
  const visibility: Record<string, boolean> = {};
  for (const [id, shown, keyPath] of columnEntries(value, path, context)) {
    const flag = booleanOf(shown, keyPath, context);
    if (flag !== undefined) {
      visibility[id] = flag;
    }
  }
  return Object.keys(visibility).length ? visibility : undefined;
};

const sanitizeSizing: FieldSanitizer = (value, path, context) => {
  const sizing: Record<string, number> = {};
  for (const [id, width, keyPath] of columnEntries(value, path, context)) {
    if (typeof width === "number" && Number.isFinite(width) && width > 0) {
      sizing[id] = Math.round(width);
    } else {
      context.add(
        "invalidValue",
        keyPath,
        "Column widths are positive numbers."
      );
    }
  }
  return Object.keys(sizing).length ? sizing : undefined;
};

const PINNING_KEYS: ReadonlySet<string> = new Set(["left", "right"]);

const sanitizePinning: FieldSanitizer = (value, path, context) => {
  if (!isRecord(value)) {
    context.add(
      "invalidValue",
      path,
      "Pinned columns are `{ left, right }` lists."
    );
    return;
  }
  unknownKeys(value, PINNING_KEYS, path, context);
  const side = (key: "left" | "right") =>
    value[key] === undefined
      ? []
      : (columnIds(value[key], jsonPath(path, key), context) ?? []);
  const left = side("left");
  const right = side("right");
  return left.length || right.length ? { left, right } : undefined;
};

// Display mode settings -------------------------------------------------------------

/** Kanban settings; `groupBy` (legacy) moves to the shared `grouping`. */
function normalizeKanbanSettings(
  value: unknown
): ViewKanbanSettings | undefined {
  if (!isRecord(value)) {
    return;
  }
  const settings: ViewKanbanSettings = {};
  const title =
    typeof value.titleColumn === "string" ? value.titleColumn.trim() : "";
  if (title) {
    settings.titleColumn = title;
  }
  if (Array.isArray(value.cardColumnIds)) {
    settings.cardColumnIds = value.cardColumnIds
      .filter((item): item is string => typeof item === "string")
      .map((item) => item.trim())
      .filter(Boolean);
  }
  if (typeof value.showCardLabels === "boolean") {
    settings.showCardLabels = value.showCardLabels;
  }
  return Object.keys(settings).length ? settings : undefined;
}

/** The gallery normalizer trims its column ids: they must be texts first. */
function normalizeGallerySettings(
  value: unknown
): GalleryViewState | undefined {
  if (!isRecord(value)) {
    return;
  }
  const typed: Row = { ...value };
  for (const key of ["imageColumn", "titleColumn"]) {
    if (typed[key] !== undefined && typeof typed[key] !== "string") {
      Reflect.deleteProperty(typed, key);
    }
  }
  return normalizeGalleryViewConfig(typed as GalleryViewState);
}

function normalizeGanttSettings(
  value: unknown
): TableGanttViewConfig | undefined {
  const gantt = normalizeGanttView(value);
  return Object.keys(gantt).length ? gantt : undefined;
}

type ModeNormalizer = (value: unknown) => object | undefined;

const MODE_NORMALIZERS: Readonly<Record<string, ModeNormalizer>> = {
  kanban: normalizeKanbanSettings,
  gallery: normalizeGallerySettings,
  gantt: normalizeGanttSettings,
  ...Object.fromEntries(
    GENERIC_MODE_CONFIG_KEYS.map((key): [string, ModeNormalizer] => [
      key,
      (value) => normalizeModeConfig(key, value),
    ])
  ),
};

/**
 * The settings each display mode keeps, so a dropped setting reads as an
 * invalid value (an error) and anything else as an unknown key (a warning).
 */
export const VIEW_MODE_SETTING_KEYS: Readonly<
  Record<string, readonly string[]>
> = {
  list: [
    "titleColumn",
    "cardColumnIds",
    "showCardLabels",
    "wrap",
    "showActions",
    "propertyAlign",
    "maxProperties",
    "mobileMaxProperties",
  ],
  kanban: ["titleColumn", "cardColumnIds", "showCardLabels"],
  gallery: [
    "imageColumn",
    "titleColumn",
    "cardColumnIds",
    "aspectRatio",
    "imageFit",
    "cardSize",
    "previewSize",
    "showCardLabels",
  ],
  filetree: [
    "parentColumn",
