/** Reports the settings a mode's normalizer left out. */
function reportDropped(
  key: string,
  input: ViewJsonObject,
  kept: object | undefined,
  path: string,
  context: Context
) {
  const known = VIEW_MODE_SETTING_KEYS[key] ?? [];
  for (const setting of Object.keys(input)) {
    if (kept && Object.hasOwn(kept, setting)) {
      continue;
    }
    const settingPath = jsonPath(path, setting);
    if (known.includes(setting)) {
      context.add(
        "invalidValue",
        settingPath,
        `${describeValue(input[setting])} is not a valid ${key} "${setting}".`
      );
    } else {
      context.add(
        "unknownKey",
        settingPath,
        `"${setting}" is not a ${key} setting and was removed.`
      );
    }
  }
}

const sanitizeModeSettings: FieldSanitizer = (value, path, context, key) => {
  const normalize = Object.hasOwn(MODE_NORMALIZERS, key)
    ? MODE_NORMALIZERS[key]
    : undefined;
  if (!(normalize && isRecord(value))) {
    context.add("invalidValue", path, `The ${key} settings are an object.`);
    return;
  }
  const source: Row = { ...value };
  if (key === "kanban") {
    // Moved to `grouping` by `sanitizeViewConfig`.
    Reflect.deleteProperty(source, "groupBy");
  }
  const copy = copyJson(
    source,
    {
      depth: context.limits.depth,
      size: context.limits.modeSettings,
      items: MODE_ITEMS,
    },
    path
  );
  for (const issue of copy.issues) {
    context.add(issue.code, issue.path, issue.message);
  }
  if (copy.oversize || !isRecord(copy.value)) {
    context.add(
      "truncated",
      path,
      `The ${key} settings are larger than ${context.limits.modeSettings} characters and were removed.`
    );
    return;
  }
  let kept: object | undefined;
  try {
    kept = normalize(copy.value);
  } catch {
    context.add("invalidValue", path, `The ${key} settings could not be read.`);
    return;
  }
  reportDropped(key, copy.value, kept, path, context);
  return kept;
};

// Settings --------------------------------------------------------------------------

const FIELDS: Readonly<Record<string, FieldSanitizer>> = {
  displayMode: sanitizeDisplayMode,
  density: sanitizeDensity,
  footerCalculationsVisible: sanitizeBoolean,
  globalSearch: sanitizeText,
  pageSize: sanitizePageSize,
  sorting: sanitizeSorting,
  columnFilters: sanitizeColumnFilters,
  advancedFilters: sanitizeAdvancedFilters,
  columnOrder: sanitizeColumnList,
  grouping: sanitizeColumnList,
  columnVisibility: sanitizeVisibility,
  columnSizing: sanitizeSizing,
  columnPinning: sanitizePinning,
  ...Object.fromEntries(
    Object.keys(MODE_NORMALIZERS).map((key): [string, FieldSanitizer] => [
      key,
      sanitizeModeSettings,
    ])
  ),
};

/** The keys saved-view settings may have, in the order they are read. */
export const VIEW_CONFIG_KEYS: readonly string[] = Object.keys(FIELDS);

/** Historical Vue names, read when the canonical name is absent. */
const ALIASES: Readonly<Record<string, string>> = {
  search: "globalSearch",
  filters: "columnFilters",
  pinning: "columnPinning",
};

/** A legacy Kanban `groupBy`, as the shared grouping. */
function legacyGrouping(
  kanban: unknown,
  context: Context
): string[] | undefined {
  if (!(isRecord(kanban) && kanban.groupBy !== undefined)) {
    return;
  }
  const column = textOf(kanban.groupBy, "kanban.groupBy", context);
  return column ? [column] : undefined;
}

/**
 * The canonical name of a key and its sanitizer; `false` for a historical
 * name whose canonical one is also there (the canonical one wins).
 */
function fieldOf(
  key: string,
  input: Row
): { name: string; field?: FieldSanitizer } | false {
  const alias = Object.hasOwn(ALIASES, key) ? ALIASES[key] : undefined;
  if (alias && Object.hasOwn(input, alias)) {
    return false;
  }
  const name = alias ?? key;
  return {
    name,
    field: Object.hasOwn(FIELDS, name) ? FIELDS[name] : undefined,
  };
}

function sanitize(input: unknown, context: Context): ViewConfig {
  if (!isRecord(input)) {
    context.add(
      "invalidValue",
      "",
      `View settings are an object, got ${describeValue(input)}.`
    );
    return {};
  }
  const config: Row = {};
  for (const key of Object.keys(input)) {
    const found = fieldOf(key, input);
    if (!found) {
      continue;
    }
    if (!found.field) {
      context.add(
        "unknownKey",
        jsonPath("", key),
        `"${key}" is not a view setting and was removed.`
      );
      continue;
    }
    const value = found.field(
      input[key],
      jsonPath("", key),
      context,
      found.name
    );
    if (value !== undefined) {
      config[found.name] = value;
    }
  }
  if (config.grouping === undefined) {
    const grouping = legacyGrouping(input.kanban, context);
    if (grouping) {
      config.grouping = grouping;
    }
  }
  return config as ViewConfig;
}

/**
 * Saved-view settings, strictly sanitized: unknown keys (at every level) are
 * removed, lists and texts capped (`limits`, see `VIEW_CONFIG_LIMITS`), each
 * value type-checked before its display mode's normalizer reads it, and
 * historical Vue names (`search`, `filters`, `pinning`, Kanban `groupBy`)
 * read as the canonical ones. Never throws: unreadable input gives `{}`.
 * Issues carry JSON paths inside the settings; errors lost something the
 * settings asked for, warnings only removed unknown keys.
 */
export function sanitizeViewConfig(
  input: unknown,
  limits: Partial<ViewConfigLimits> = {}
): SanitizedViewConfig {
  const context = createContext(limits);
  try {
    return { config: sanitize(input, context), issues: context.issues };
  } catch {
    // Throwing getters and proxies are unreadable, not fatal.
    context.add("invalidValue", "", "The view settings could not be read.");
    return { config: {}, issues: context.issues };
  }
}

/** Columns every table adds itself (row selection, row actions): not part of a view. */
const SYSTEM_COLUMNS: ReadonlySet<string> = new Set(["select", "actions"]);

const withoutSystemColumns = (ids: readonly string[]): string[] =>
  ids.filter((id) => !SYSTEM_COLUMNS.has(id));

const withoutSystemEntries = <T>(
  map: Record<string, T>
): Record<string, T> | undefined => {
  const kept = Object.entries(map).filter(([id]) => !SYSTEM_COLUMNS.has(id));
  return kept.length ? Object.fromEntries(kept) : undefined;
};

/** The column layout of a view without the table's own columns. */
function dataColumnsOnly(config: ViewConfig): ViewConfig {
  const { columnOrder, columnPinning, columnSizing, columnVisibility } = config;
  const order = columnOrder ? withoutSystemColumns(columnOrder) : [];
  const left = withoutSystemColumns(columnPinning?.left ?? []);
  const right = withoutSystemColumns(columnPinning?.right ?? []);
  const visibility = columnVisibility && withoutSystemEntries(columnVisibility);
  const sizing = columnSizing && withoutSystemEntries(columnSizing);
  const {
    columnOrder: _order,
    columnPinning: _pinning,
    columnSizing: _sizing,
    columnVisibility: _visibility,
    ...rest
  } = config;
  return {
    ...rest,
    ...(order.length ? { columnOrder: order } : {}),
    ...(left.length || right.length ? { columnPinning: { left, right } } : {}),
    ...(sizing ? { columnSizing: sizing } : {}),
    ...(visibility ? { columnVisibility: visibility } : {}),
  };
}

/**
 * The settings a table reports for the view it shows (React
 * `onViewConfigChange`, Vue `view-config-change`, `getViewConfig()` in
 * toolbar actions): `sanitizeViewConfig`'s shape, without the table's own
 * columns (`select`, `actions`) and the display mode settings that hold
 * nothing, so both editions report the same object for the same view.
 */
export function canonicalViewConfig(input: unknown): ViewConfig {
  const config: Row = { ...dataColumnsOnly(sanitizeViewConfig(input).config) };
  const canonical: Row = {};
  // Keys in one order whatever the input's, so equal views give equal JSON.
  for (const key of Object.keys(FIELDS)) {
    const value = config[key];
    const empty = isRecord(value) && Object.keys(value).length === 0;
    if (value !== undefined && !empty) {
      canonical[key] = value;
    }
  }
  return canonical as ViewConfig;
}

import { normalizeDateFilterRule } from "./date-filter-days";
import {
  DISPLAY_MODE_CONFIG_KEYS,
  DISPLAY_MODES,
  resolveDisplayModes,
  type TableDisplayMode,
} from "./display-modes";
import {
  normalizeFilterEnvelope,
  normalizeViewAliases,
} from "./table-contracts";

/** These capabilities describe presentation, before catalogue permissions apply. */
export function getViewModeCapabilities(mode: TableDisplayMode) {
  const definition = DISPLAY_MODES[mode] ?? DISPLAY_MODES.table;
  return {
    ...definition.capabilities,
    kanban: mode === "kanban",
    gallery: mode === "gallery",
    gantt: mode === "gantt",
    maxGroups: definition.maxGroups,
  } as const;
}

/**
 * Gantt needs a planning graph the way Kanban needs a grouping column: offering the
 * mode without one only leads to an empty view, so it is withheld until it can render.
 */
export function availableDisplayModes(
  displayModes: readonly unknown[] | undefined,
  context: { planning: boolean; renderers?: readonly string[] }
): TableDisplayMode[] {
  return resolveDisplayModes(displayModes, context);
}

const VIEW_SETTING_KEYS = [
  ...DISPLAY_MODE_CONFIG_KEYS,
  "advancedFilters",
  "columnFilters",
  "columnOrder",
  "columnPinning",
  "columnSizing",
  "columnVisibility",
  "density",
  "displayMode",
  "footerCalculationsVisible",
  "globalSearch",
  "grouping",
  "pageSize",
  "sorting",
];

function canonicalValue(value: unknown, field?: string): unknown {
  if (value instanceof Date) {
    return value.toJSON() ?? undefined;
  }
  if (Array.isArray(value)) {
    return value.length || field === "cardColumnIds"
      ? value.map((item) => canonicalValue(item))
      : undefined;
  }
  if (value !== null && typeof value === "object") {
    const result: Record<string, unknown> = {};
    for (const key of Object.keys(value).sort()) {
      const normalized = canonicalValue(
        (value as Record<string, unknown>)[key],
        key
      );
      if (normalized !== undefined) {
        result[key] = normalized;
      }
    }
    return Object.keys(result).length ? result : undefined;
  }
  return value === null || (value === "" && field !== "imageColumn")
    ? undefined
    : value;
}

/** Compare saved settings, excluding transient selection, pages and UI state. */
export function areViewSettingsEqual(left: object, right: object): boolean {
  const normalize = (input: object) => {
    const aliases = normalizeViewAliases(input);
    const settings: Record<string, unknown> = {};
    for (const key of VIEW_SETTING_KEYS) {
      settings[key] = aliases[key];
    }
    // Selection and action columns are positioned by the table, including in legacy views.
    if (Array.isArray(settings.columnOrder)) {
      settings.columnOrder = settings.columnOrder.filter(
        (id) => id !== "select" && id !== "actions"
      );
    }
    // Filter identities and edit timestamps do not change the saved query's
    // meaning, nor does an older view's instant for the day it names.
    settings.advancedFilters = normalizeFilterEnvelope(
      aliases.advancedFilters
    ).filters.map(
      ({
        id: _id,
        label: _label,
        createdAt: _createdAt,
        updatedAt: _updatedAt,
        ...filter
      }) => ({
        ...normalizeDateFilterRule(filter),
        joinOperator: filter.joinOperator === "or" ? "or" : undefined,
      })
    );
    // An explicit visible column has the same meaning as an absent override.
    if (
      settings.columnVisibility &&
      typeof settings.columnVisibility === "object"
    ) {
      settings.columnVisibility = Object.fromEntries(
        Object.entries(settings.columnVisibility).filter(
          ([, visible]) => visible === false
        )
      );
    }
    return canonicalValue(settings);
  };
  return JSON.stringify(normalize(left)) === JSON.stringify(normalize(right));
}

export interface PageSharingEnvironment {
  share?: (data: { url: string }) => Promise<void>;
  clipboard?: { writeText: (text: string) => Promise<void> };
}

export type PageShareResult = "shared" | "copied" | "cancelled";

/** Sharing a URL never grants access or changes a saved view's organization scope. */
export async function sharePageUrl(
  url: string,
  native: boolean,
  environment: PageSharingEnvironment = navigator
): Promise<PageShareResult> {
  if (native && typeof environment.share === "function") {
    try {
      await environment.share({ url });
      return "shared";
    } catch (error) {
      if (error instanceof Error && error.name === "AbortError") {
        return "cancelled";
      }
      if (!environment.clipboard?.writeText) {
        throw error;
      }
    }
  }
  if (!environment.clipboard?.writeText) {
    throw new Error("Link sharing is unavailable in this browser.");
  }
  await environment.clipboard.writeText(url);
  return "copied";
}

/**
 * The user's order of saved views, shared by the React and Vue editions. It
 * applies to the view tabs, the "More views" list and the view menu; the view
 * menu moves the current view one step at a time.
 *
 * System views and the default view (`isDefault`, such as a screen's default)
 * keep their place first, in their list order. The user orders the others.
 * Views the order does not name (new ones) come last, in their list order.
 *
 * Server-safe: a host may sort its `list` answer with `orderViews` too.
 */

/** What the order reads from a saved view. */
export interface OrderableView {
  id: string;
  isDefault?: boolean;
  isSystem?: boolean;
}

/** `previous` moves a view left (tabs) or up (lists), `next` right or down. */
export type ViewMoveDirection = "previous" | "next";

/** Where the current view can move; see `viewMoves`. */
export interface ViewMoves {
  previous: boolean;
  next: boolean;
}

/** The table context the order belongs to, as for the favorite. */
export interface ViewOrderContext {
  tableId: string;
  tableType?: string;
}

/** Storage the order falls back to without `actions.views.setOrder`. */
export interface ViewOrderStorage {
  getItem: (key: string) => null | string;
  setItem: (key: string, value: string) => void;
}

/** Whether the user orders this view: system and default views keep their place. */
export function isOrderableView(view: OrderableView): boolean {
  return !(view.isSystem === true || view.isDefault === true);
}

/** View ids from an order, a stored value or a host answer; `undefined` otherwise. */
export function parseViewOrder(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) {
    return;
  }
  const ids = value.filter((id): id is string => typeof id === "string");
  return [...new Set(ids)];
}

/** The views in the user's order (see the module comment). */
export function orderViews<T extends OrderableView>(
  views: readonly T[],
  order?: readonly string[] | null
): T[] {
  const fixed = views.filter((view) => !isOrderableView(view));
  const orderable = views.filter(isOrderableView);
  const position = new Map<string, number>();
  for (const id of order ?? []) {
    if (!position.has(id)) {
      position.set(id, position.size);
    }
  }
  const named = orderable
    .filter((view) => position.has(view.id))
    .sort(
      (left, right) =>
        (position.get(left.id) ?? 0) - (position.get(right.id) ?? 0)
    );
  const unnamed = orderable.filter((view) => !position.has(view.id));
  return [...fixed, ...named, ...unnamed];
}

/** Ids of the views the user orders, first to last: what `setOrder` receives. */
export function orderableViewIds(views: readonly OrderableView[]): string[] {
  return views.filter(isOrderableView).map((view) => view.id);
}

/**
 * Where a view can move among `views` (in the user's order): `undefined` when
 * it keeps its place, is not listed or has no other view to swap with.
 */
export function viewMoves(
  views: readonly OrderableView[],
  id: string | null | undefined
): ViewMoves | undefined {
  const ids = orderableViewIds(views);
  const index = id ? ids.indexOf(id) : -1;
  if (index < 0 || ids.length < 2) {
    return;
  }
  return { previous: index > 0, next: index < ids.length - 1 };
}

/**
 * The order after moving a view one step (the `viewIds` for `setOrder`), or
 * `undefined` when it cannot move that way.
 */
export function moveViewInOrder(
  views: readonly OrderableView[],
  id: string,
  direction: ViewMoveDirection
): string[] | undefined {
  const moves = viewMoves(views, id);
  if (!moves?.[direction]) {
    return;
  }
  const ids = orderableViewIds(views);
  const index = ids.indexOf(id);
  ids.splice(index, 1);
  ids.splice(direction === "previous" ? index - 1 : index + 1, 0, id);
  return ids;
}

/**
 * A view's place as people see it, counting the table's default view (always
 * the first tab and the first entry of the view menu) before the saved views.
 */
export function viewPosition(
  views: readonly OrderableView[],
  id: string
): { position: number; count: number } | undefined {
  const index = views.findIndex((view) => view.id === id);
  return index < 0
    ? undefined
    : { position: index + 2, count: views.length + 1 };
}

/** The move announcement: `{name}`, `{position}` and `{count}` in `template`. */
export function formatViewMove(
  template: string,
  values: { name: string; position: number; count: number }
): string {
  return template
    .replaceAll("{name}", () => values.name)
    .replaceAll("{position}", String(values.position))
    .replaceAll("{count}", String(values.count));
}

/**
 * The order a view `list` answers with: its `order` field, else the order of
 * the views it lists when the host keeps the order (`hostKeepsOrder`).
 */
export function listedViewOrder(
  answer: unknown,
  hostKeepsOrder: boolean
): string[] | undefined {
  const record =
    answer !== null && typeof answer === "object" && !Array.isArray(answer)
      ? (answer as { data?: unknown; order?: unknown })
      : undefined;
  const order = parseViewOrder(record?.order);
  if (order || !hostKeepsOrder) {
    return order;
  }
  const views = Array.isArray(answer) ? answer : record?.data;
  return Array.isArray(views)
    ? parseViewOrder(
        views.map((view: unknown) =>
          view !== null && typeof view === "object"
            ? (view as { id?: unknown }).id
            : undefined
        )
      )
    : undefined;
}

/** localStorage key of the order without `setOrder`: per table type and table id, like the favorite. */
export function getTableViewOrderStorageKey(context: ViewOrderContext): string {
  return `yayaw-table-view-order:${JSON.stringify([context.tableType ?? "", context.tableId])}`;
}

/** The order stored for a table, `undefined` when none or unreadable. */
export function readStoredViewOrder(
  storage: ViewOrderStorage | undefined,
  context: ViewOrderContext
): string[] | undefined {
  try {
    const raw = storage?.getItem(getTableViewOrderStorageKey(context));
    return raw ? parseViewOrder(JSON.parse(raw)) : undefined;
  } catch {
    return;
  }
}

/** Stores a table's order; `false` when the storage refuses it. */
export function storeViewOrder(
  storage: ViewOrderStorage | undefined,
  context: ViewOrderContext,
  viewIds: readonly string[]
): boolean {
  if (!storage) {
    return false;
  }
  try {
    storage.setItem(
      getTableViewOrderStorageKey(context),
      JSON.stringify([...viewIds])
    );
    return true;
  } catch {
    return false;
  }
}

/**
 * View tabs shared by the React and Vue editions: which saved views show as
 * tabs and which move to the "More" menu.
 */

export interface ViewTabsSettings {
  /** Tabs shown before the rest move to the "More" menu (default 4). */
  maxVisible?: number;
}

/** `table.viewTabs`: `false` keeps the view menu only. */
export type ViewTabsConfig = boolean | ViewTabsSettings;

export const DEFAULT_VIEW_TABS_MAX_VISIBLE = 4;

/** Resolved tab settings, or `undefined` when tabs are turned off. */
export function resolveViewTabs(
  config: ViewTabsConfig | undefined
): Required<ViewTabsSettings> | undefined {
  if (config === false) {
    return;
  }
  const requested = typeof config === "object" ? config.maxVisible : undefined;
  const maxVisible =
    typeof requested === "number" &&
    Number.isInteger(requested) &&
    requested > 0
      ? requested
      : DEFAULT_VIEW_TABS_MAX_VISIBLE;
  return { maxVisible };
}

/**
 * Split views into visible tabs and the overflow menu, keeping their order.
 * The active view always stays visible, in place of the last visible tab.
 */
export function splitViewTabs<TView extends { id: string }>(
  views: readonly TView[],
  activeId: string | null | undefined,
  maxVisible: number
): { visible: TView[]; overflow: TView[] } {
  if (views.length <= maxVisible) {
    return { visible: [...views], overflow: [] };
  }
  const visible = views.slice(0, maxVisible);
  const active = views.find((view) => view.id === activeId);
  if (active && !visible.includes(active)) {
    visible[visible.length - 1] = active;
  }
  return {
    visible,
    overflow: views.filter((view) => !visible.includes(view)),
  };
}
